const isGatewayMain = typeof process !== 'undefined' && process.argv[1] != null && (process.argv[1].endsWith('gateway.ts') || process.argv[1].endsWith('gateway.js'))  // #2996 P0c: true only when this module is the process entrypoint (prod `bun .../gateway.js`; under vitest argv[1] is the runner → false; mirrors streaming-report.ts). Every module-load side effect below is guarded by it; the boot sequence is the guarded startGateway() at the bottom, so an import() fires nothing.

// ─── Stderr logging ───────────────────────────────────────────────────────
// Install the line-stamper FIRST so it wraps closest to the original
// stderr.write. plugin-logger's file mirror then sees the timestamped text.
// Kill switch: SWITCHROOM_LOG_TIMESTAMPS=0 disables.
installStderrTimestamps()
installPluginLogger()

// ─── Telemetry ────────────────────────────────────────────────────────────
// Catch uncaught exceptions + unhandled rejections and forward them to
// PostHog Error Tracking before the process dies. Mirrors the CLI's
// install (src/cli/index.ts), so gateway + CLI errors land in the same
// dashboard tagged `source: 'gateway'` vs `source: 'cli'`.
// #2996 P0e: global error handlers + the analytics-flush `beforeExit` listener
// are boot process-wiring, not import-time state. installGlobalErrorHandlers
// registers an `uncaughtException` handler that calls `process.exit(1)`, so
// leaving it ungated would make exit reachable from a bare `import(gateway.ts)`.
// Gate on isGatewayMain: registered verbatim (same order, same position) on the
// prod boot path; a no-op under a vitest import.
if (isGatewayMain) {
  installPosthogErrorHandlers()
  // Flush analytics on graceful shutdown so the last batch isn't lost.
  // The signal handlers themselves remain owned by other modules — we
  // piggyback by emitting a `beforeExit` listener which fires after
  // SIGTERM/SIGINT have run their handlers and the event loop is empty.
  process.on('beforeExit', () => {
    void shutdownAnalytics()
  })
}

// ─── Env + state dir ──────────────────────────────────────────────────────
const STATE_DIR = process.env.TELEGRAM_STATE_DIR ?? join(homedir(), '.claude', 'channels', 'telegram')
const permCardStore = createPermissionCardStore(STATE_DIR)
// #3084 follow-up — the blocked-approval surface. A SHARED top-level directory
// (compose binds host `~/.switchroom/blocked-approvals` here), not per-agent
// state: switchroom-web reads every agent's record from one place, and the
// records are 0644 so its uid-1000 process can actually read them. The agent's
// own telegram state is 0600 and is NOT web-readable.
// If the mount is missing (a container predating the volume), the write lands
// inside the container and the hold still works — only the off-Telegram
// SURFACE is lost. The record is best-effort by construction; it must never be
// able to fail the hold back into an auto-deny.
const BLOCKED_APPROVALS_DIR =
  process.env.SWITCHROOM_BLOCKED_APPROVALS_DIR ?? '/state/blocked-approvals'
// The canonical "which agent am I" identity (profiles/_base/start.sh.hbs:430).
const AGENT_NAME = process.env.SWITCHROOM_AGENT_NAME ?? 'agent'
const blockedApprovalStore = createBlockedApprovalStore(
  BLOCKED_APPROVALS_DIR,
  AGENT_NAME,
  // Fallback: the agent's OWN state dir, which the scaffold chowns to the agent
  // uid, so a write there always succeeds. Guarantees the record can never be
  // silently lost when the shared dir isn't writable by this agent's uid.
  resolveAgentStateDir(),
)

/**
 * Rewrite the blocked-approval surface from the LIVE pending state.
 *
 * A reconcile, not a delete — deliberately. The store holds one record per
 * agent, but an agent can hold SEVERAL permissions at once: Claude Code issues
 * parallel tool calls, each hitting `canUseTool`, and
 * `cancelPendingPermissionsForHalt` iterates multiple pendings. A naive
 * `clear()` on any single resolution would delete the file while ANOTHER
 * request was still held, blinding the operator to a real, live block.
 *
 * So derive the record from whatever is still held. Oldest block wins — it has
 * been waiting longest. Nothing held → clear.
 *
 * Also called at BOOT. `pendingPermissions` is in-memory and empty on a fresh
 * process, so this clears any record orphaned by a restart mid-hold — otherwise
 * the dashboard would show a permanently blocked agent forever. Nothing can
 * legitimately be held across a restart: the bridge re-sends unresolved requests
 * on IPC reconnect (`bridge/permission-ledger.ts`), which re-raises them and
 * re-marks them if the channel is still shut.
 */
function reconcileBlockedApprovals(): void {
  // Selection (oldest hold wins; null ⇒ nothing held) is the pure, unit-tested
  // `selectOldestHeld` in approval-hold.ts — keep policy out of gateway.ts.
  const oldest = selectOldestHeld(pendingPermissions)
  if (oldest == null) {
    blockedApprovalStore.clear()
    return
  }
  blockedApprovalStore.write({
    agent: AGENT_NAME,
    requestId: oldest.requestId,
    toolName: oldest.pend.tool_name,
    // NOT bare naturalAction(): for Bash/Glob/Grep/WebFetch/mcp__* it
    // interpolates the RAW tool input, and this file is world-readable.
    action: safeActionForRecord(naturalAction, oldest.pend.tool_name, oldest.pend.input_preview),
    blockedSince: oldest.pend.startedAt,
    undeliverableSince: oldest.mark.since,
    retryableAt: oldest.mark.retryableAt,
    reason: oldest.mark.reason,
  })
}
// Durable store for the four AGENT-INITIATED approval-card families
// (vault_request_access / vault_request_save / request_secret /
// mental_model_propose). Persists card METADATA only — never any secret value
// (see pending-card-store.ts secrets-hygiene note). Restored at boot so a
// post-restart tap on a still-valid card works like a pre-restart tap, and
// swept in the pendingStateReaper so an unanswered card wakes the parked agent
// on TTL instead of leaving it parked forever.
const pendingCardStore = createPendingCardStore(STATE_DIR)
// #2862 — missed-approvals re-offer. Persisted list of approvals that
// TTL-expired while the operator was away; a digest card is posted on the
// operator's next activity. Kill switch: SWITCHROOM_MISSED_APPROVAL_REOFFER=0.
const missedApprovalsStore = createMissedApprovalsStore(STATE_DIR)
const MISSED_APPROVAL_REOFFER_ENABLED =
  process.env.SWITCHROOM_MISSED_APPROVAL_REOFFER !== '0'
// #2973 pt.2 — durable retry queue for "🔁 Always allow" persists that
// fail for a retryable reason (stale config view, rate limit, transient
// hostd error). Drained at boot (below) and on a periodic timer so a
// gateway restart mid-persist never loses the retry.
const alwaysAllowPersistQueue = createAlwaysAllowPersistQueue(STATE_DIR)

/** Read a hostd `error_envelope`'s structured `retry_after` fix (if
 * present) as a millisecond delay from now. Returns undefined for any
 * other fix kind / missing envelope / unparsable timestamp — callers
 * fall back to plain exponential backoff in that case. */
function extractRetryAfterMs(resp: HostdResponse): number | undefined {
  const fix = resp.error_envelope?.fix
  if (fix == null || fix.kind !== 'retry_after') return undefined
  const at = Date.parse(fix.retry_at)
  if (Number.isNaN(at)) return undefined
  return Math.max(0, at - Date.now())
}

/**
 * Build a FRESH dependency set for `drainAlwaysAllowPersistQueue` — a new
 * factory call per drain pass, not a cached singleton, so every attempt
 * re-reads config from disk (the #2973 stale-container-side-view failure
 * class is fixed by never reusing a snapshot across retries).
 */
function alwaysAllowDrainDeps(): AlwaysAllowDrainDeps {
  return {
    readConfigText: () => {
      const cfgPath = process.env.SWITCHROOM_CONFIG ?? SWITCHROOM_CONFIG ?? findSwitchroomConfigFile()
      return readFileSync(cfgPath, 'utf8')
    },
    resolveAllowList: (_configText, agentName) => {
      const cfg = loadSwitchroomConfig()
      const rawAgent = cfg.agents?.[agentName]
      if (!rawAgent) return []
      const resolved = resolveAgentConfig(cfg.defaults, cfg.profiles, rawAgent)
      return (resolved as { tools?: { allow?: string[] } }).tools?.allow ?? []
    },
    isRulePersisted,
    synthesizeDiff: (agentName, rule, configText) =>
      synthesizeAllowRuleDiff({ agentName, rule, configText }),
    dispatchConfigEdit: async (entry, unifiedDiff) => {
      const req: HostdRequest = {
        v: 1,
        op: 'config_propose_edit',
        request_id: hostdRequestId('gw-always-allow-retry'),
        args: {
          unified_diff: unifiedDiff,
          reason: `Operator 'always allow' retry: ${entry.agentName} can ${entry.grantPhrase}`,
          target_path: '/state/config/switchroom.yaml',
        },
      }
      const resp = await tryHostdDispatch(entry.agentName, req, 720_000)
      if (resp === 'not-configured') {
        return { ok: false as const, error: 'hostd not-configured (retry queue requires host_control.enabled)' }
      }
      if (resp.result === 'completed') return { ok: true as const }
      return {
        ok: false as const,
        error: resp.error ?? `hostd ${resp.result}`,
        retryAfterMs: extractRetryAfterMs(resp),
      }
    },
    // #2973 pt.3 — loud terminal failure. A card edit doesn't ping the
    // operator (the original permission card was already edited to the
    // "saving durably in background…" interim state); this posts a NEW
    // message instead, via the same operator-event broadcast every other
    // fleet alert uses.
    notifyTerminalFailure: (entry, reason) => {
      emitGatewayOperatorEvent({
        kind: 'always-allow-persist-failed',
        agent: entry.agentName,
        detail: `"${entry.grantPhrase}" (rule \`${entry.rule}\`) — ${reason}`,
        suggestedActions: [],
        firstSeenAt: new Date(),
      })
    },
    log: (line) => process.stderr.write(line),
  }
}

/** ~10 min between periodic drain passes — frequent enough that a
 * retryable failure (rate limit, transient hostd hiccup) resolves within
 * a reasonable window, infrequent enough to never look like polling. */
const ALWAYS_ALLOW_DRAIN_INTERVAL_MS = 10 * 60_000

/**
 * Boot drain (picks up anything a prior gateway process queued right
 * before a restart — success criterion: "restarting the gateway mid-
 * persist does not lose the queued entry") + a periodic timer thereafter.
 * Called once at gateway startup. Every pass is independently
 * fault-tolerant — `drainAlwaysAllowPersistQueue` never throws.
 */
function scheduleAlwaysAllowPersistDrain(): void {
  void drainAlwaysAllowPersistQueue(alwaysAllowPersistQueue, alwaysAllowDrainDeps()).catch((err) => {
    process.stderr.write(
      `telegram gateway: always-allow-persist-queue boot drain failed: ${(err as Error).message}\n`,
    )
  })
  const timer = setInterval(() => {
    void drainAlwaysAllowPersistQueue(alwaysAllowPersistQueue, alwaysAllowDrainDeps()).catch((err) => {
      process.stderr.write(
        `telegram gateway: always-allow-persist-queue periodic drain failed: ${(err as Error).message}\n`,
      )
    })
  }, ALWAYS_ALLOW_DRAIN_INTERVAL_MS)
  timer.unref?.()
}
const ACCESS_FILE = join(STATE_DIR, 'access.json')
const APPROVED_DIR = join(STATE_DIR, 'approved')
const ENV_FILE = join(STATE_DIR, '.env')
const INBOX_DIR = join(STATE_DIR, 'inbox')
// person_id name resolution (docs/configuration.md). Sibling to
// access.json but a COMPLETELY SEPARATE, purely config-derived file —
// scaffold regenerates it on every reconcile via writeFileSyncIfChanged,
// the gateway never mutates it, and (unlike access.json) it is read
// exactly ONCE at boot into PERSON_DIRECTORY below — no hot-reload.
const PEOPLE_FILE = join(STATE_DIR, 'people.json')

/**
 * Trigger a restart of the agent + gateway pair.
 *
 * Branches on `SWITCHROOM_RUNTIME`:
 *   - `docker`: send `SIGTERM` to PID 1 (tini) after a brief delay so
 *     in-flight IPC responses flush. tini propagates the signal to its
 *     children (claude → start.sh → us), the whole tree exits cleanly,
 *     the container exits, and docker compose's `restart: unless-stopped`
 *     policy recreates it. This covers BOTH the agent process and the
 *     gateway plugin (we're a child of claude inside the same container).
 *     `targetAgent` is informational only here — we can't restart a
 *     different agent's container from inside our own (no docker.sock).
 *   - else (v0.6 legacy non-docker path, scheduled for removal in
 *     Phase 3 of the host-control daemon rollout — see
 *     `reference/rfcs/host-control-daemon.md`): detached `systemctl --user
 *     restart` of the two units. This branch is never reached on
 *     v0.7+ docker installs (the `isDocker` guard above takes the
 *     docker branch); only callable on legacy systemd hosts that
 *     ran the gateway as a user unit. Don't add new dependencies
 *     on this path.
 *
 * `targetAgent` defaults to `SWITCHROOM_AGENT_NAME`; pass a different
 * value only for the inline restart-button callback handler. Under
 * docker, a `targetAgent !== SWITCHROOM_AGENT_NAME` request returns
 * false (and logs) so the caller can surface a "not supported" message.
 */
function triggerSelfRestart(
  targetAgent: string,
  reason: string,
  delayMs = 300,
): boolean {
  const isDocker = process.env.SWITCHROOM_RUNTIME === 'docker'
  const selfAgent = process.env.SWITCHROOM_AGENT_NAME
  if (isDocker) {
    if (selfAgent && targetAgent !== selfAgent) {
      process.stderr.write(
        `telegram gateway: cross-agent restart not supported under docker (target=${targetAgent}, self=${selfAgent}, reason=${reason})\n`,
      )
      return false
    }
    // Session-scoped /model (reference/rfcs/session-model-stickiness.md §0.1):
    // a `.session-model` carrier is consume-once — start.sh applies it on the
    // apply-relaunch and deletes it, so no boot needs a keep/revert intent. A
    // switchroom-managed bounce simply reverts to the configured default.
    process.stderr.write(
      `telegram gateway: restart-via-SIGTERM-PID1 agent=${targetAgent} reason=${reason} (docker)\n`,
    )
    setTimeout(() => {
      try { process.kill(1, 'SIGTERM') } catch (err) {
        process.stderr.write(`telegram gateway: SIGTERM PID 1 failed: ${err}\n`)
      }
    }, delayMs).unref()
    return true
  }
  // Legacy systemd path.
  process.stderr.write(
    `telegram gateway: restart-via-systemctl agent=${targetAgent} reason=${reason}\n`,
  )
  try {
    spawn(
      'sh',
      [
        '-c',
        `sleep ${(delayMs / 1000).toFixed(2)} && systemctl --user restart switchroom-${targetAgent}.service switchroom-${targetAgent}-gateway.service`,
      ],
      { detached: true, stdio: 'ignore' },
    ).unref()
    return true
  } catch (err) {
    process.stderr.write(`telegram gateway: restart spawn failed for ${targetAgent}: ${err}\n`)
    return false
  }
}

// Cached lazily — the claude CLI binary doesn't change inside a running
// gateway process; on `switchroom update` the gateway restarts, refreshing this.
let cachedClaudeCliVersion: string | null | undefined = undefined
function getClaudeCliVersion(): string | null {
  if (cachedClaudeCliVersion !== undefined) return cachedClaudeCliVersion
  try {
    const out = execSync('claude --version 2>/dev/null', {
      encoding: 'utf-8',
      stdio: ['ignore', 'pipe', 'ignore'],
      timeout: 5000,
    }).trim()
    const m = out.match(/^(\S+)/)
    cachedClaudeCliVersion = m ? m[1] : (out || null)
  } catch {
    cachedClaudeCliVersion = null
  }
  return cachedClaudeCliVersion
}

function formatBootVersion(): string {
  return composeBootVersionString({
    version: VERSION,
    commitSha: COMMIT_SHA,
    commitDate: COMMIT_DATE,
    latestPr: LATEST_PR,
    commitsAheadOfTag: COMMITS_AHEAD_OF_TAG,
    claudeCliVersion: getClaudeCliVersion(),
  })
}

try {
  chmodSync(ENV_FILE, 0o600)
  for (const line of readFileSync(ENV_FILE, 'utf8').split('\n')) {
    const m = line.match(/^(\w+)=(.*)$/)
    if (m && process.env[m[1]] === undefined) process.env[m[1]] = m[2]
  }
} catch (err) {
  // ENOENT is the expected "no .env yet" path and not worth logging.
  // Anything else (permission denied, truncated, IO error) should surface
  // so a misconfigured install isn't silently missing env vars.
  const code = (err as NodeJS.ErrnoException)?.code
  if (code !== 'ENOENT') {
    process.stderr.write(
      `telegram gateway: warning — failed to load ${ENV_FILE}: ${(err as Error).message}\n`,
    )
  }
}

