export type Access = {
  dmPolicy: 'pairing' | 'allowlist' | 'disabled'
  allowFrom: string[]
  groups: Record<string, GroupPolicy>
  pending: Record<string, PendingEntry>
  mentionPatterns?: string[]
  ackReaction?: string
  replyToMode?: 'off' | 'first' | 'all'
  textChunkLimit?: number
  chunkMode?: 'length' | 'newline'
  parseMode?: 'html' | 'markdownv2' | 'text'
  disableLinkPreview?: boolean
  coalescingGapMs?: number
  /** Cooldown window (ms) for the litellm-local 429 notice — the debounced
   *  "fleet token limiter engaged" message (litellm-local-notice.ts). Default
   *  15 min when unset/invalid (parseLitellmNoticeWindowMs). Projected from
   *  channels.telegram.litellm_notice.window_ms by scaffold. */
  litellmNoticeWindowMs?: number
  /** A2: max media attachments folded into one coalesced turn. Default 10
   *  (a full Telegram album / forwarded burst arrives as one turn). Set 1 to
   *  restore single-attachment behaviour. Projected from
   *  channels.telegram.coalesce.max_attachments by scaffold. */
  coalesceMaxAttachments?: number
  /** Problem B: when true (the default), a `!` interrupt that lands
   *  mid-tool-call is deferred until the in-flight tool finishes (bounded by
   *  interruptMaxWaitMs) before SIGINT + resume. Set false to fire
   *  synchronously. Projected from channels.telegram.interrupt.safe_boundary. */
  interruptSafeBoundary?: boolean
  /** Upper bound (ms) to wait for a safe boundary before firing a deferred
   *  interrupt anyway. Default 8000. Projected from
   *  channels.telegram.interrupt.max_wait_ms. */
  interruptMaxWaitMs?: number
  statusReactions?: boolean
  historyEnabled?: boolean
  historyRetentionDays?: number
  /** Per-agent sticker aliases for the `send_sticker` MCP tool (#576).
   *  Operator declares a name → file_id map under telegram.stickers
   *  in switchroom.yaml; reconcile writes the resolved map into
   *  access.json so the gateway has it without re-reading config. */
  stickers?: Record<string, string>
  /** Voice-in transcription config (#578 spike). When `enabled` is
   *  true and provider is 'openai', inbound voice/audio messages are
   *  downloaded and transcribed via Whisper, then surface as the
   *  user's inbound text. The provider API key is a `vault:` reference
   *  (`api_key`, default `vault:openai/api-key`) resolved through the
   *  vault broker at use-time — never read from a plaintext file. Off by
   *  default. */
  voice_in?: {
    enabled?: boolean
    provider?: 'openai'
    language?: string
    api_key?: string
  }
  /** Outbound spoken replies via TTS (PR-C2). When enabled, the agent's
   *  text reply is synthesized into an OGG/Opus voice note and sent
   *  alongside (or instead of) the text, per `reply_mode`. The 'kokoro'
   *  engine uses the local voice sidecar (POST /tts) and is only active
   *  when the host voice verdict is local (SWITCHROOM_VOICE_ENGINE ===
   *  'local'); 'openai' is an honest-exception cloud path gated on an
   *  `api_key` vault ref. Voice is best-effort and fully non-fatal — any
   *  TTS error falls back to the text reply. ONE voice note per response:
   *  the reply is speech-normalized (markdown/symbols stripped) and, for the
   *  kokoro sidecar, sent in a SINGLE /tts call that returns one concatenated
   *  file. Off by default. */
  voice_out?: {
    enabled?: boolean
    engine?: 'kokoro' | 'openai'
    voice?: string
    reply_mode?: 'voice+text' | 'voice-only' | 'on-demand'
    /** Kokoro-engine playback speed. Clamped to 0.5–2.0; defaults to 1.1
     *  when voice_out is enabled but speed is unset (the fleet default —
     *  slightly brisker than neutral). Ignored by the OpenAI path. */
    speed?: number
    /** OpenAI-engine only: per-voice-note chunk size (default 600) used to
     *  split a long reply across sequential notes, since OpenAI's TTS input
     *  has a hard cap. Ignored by the kokoro path, which sends the whole
     *  reply in one call (the sidecar owns length + concatenation). */
    max_chars?: number
    api_key?: string
  }
  /** Telegraph long-reply publishing (#579). When enabled, replies
   *  above `threshold` chars publish to Telegraph and the agent's
   *  reply becomes a single message linking to the Telegraph URL
   *  (rendered via Telegram's native Instant View). Off by default. */
  telegraph?: {
    enabled?: boolean
    threshold?: number
    short_name?: string
    author_name?: string
  }
  /** Auto-confirm "✅ You chose: X" annotation on inline_keyboard taps
   *  (#789). When enabled, tapping an agent-emitted single-use button
   *  annotates the source message body so the chat surface is
   *  self-documenting. Off by default; only honored when parseMode is the
   *  default 'html'. Projected from
   *  channels.telegram.button_choice_confirmation by scaffold. */
  button_choice_confirmation?: {
    enabled?: boolean
    format?: string
    timezone?: 'gateway' | 'utc'
  }
}

// Rich-message wire cap (#2669): the rich path allows 32768 UTF-8 chars.
const MAX_CHUNK_LIMIT = RICH_MESSAGE_MAX_CHARS
const MAX_ATTACHMENT_BYTES = 50 * 1024 * 1024

function assertSendable(f: string): void {
  // Reject non-absolute paths to prevent relative path traversal
  if (!f.startsWith('/')) {
    throw new Error(`refusing to send file with relative path: ${f}`)
  }
  let real: string, stateReal: string
  try {
    real = realpathSync(f)
    stateReal = realpathSync(STATE_DIR)
  } catch {
    // Fail closed: if we can't resolve the real path (broken symlink, no
    // permission, etc.), refuse to send. The old behavior silently allowed
    // the file through on resolution failure.
    throw new Error(`refusing to send file — cannot resolve real path: ${f}`)
  }
  // Block sending any channel state files (access.json, .env, history.db, etc.)
  // except files in the inbox directory (which are user-downloaded attachments).
  const inbox = join(stateReal, 'inbox')
  if (real.startsWith(stateReal + sep) && !real.startsWith(inbox + sep)) {
    throw new Error(`refusing to send channel state: ${f}`)
  }
  // Block known sensitive paths
  const SENSITIVE_PREFIXES = ['/proc/', '/sys/']
  const SENSITIVE_EXACT = ['/etc/shadow', '/etc/gshadow']
  for (const prefix of SENSITIVE_PREFIXES) {
    if (real.startsWith(prefix)) {
      throw new Error(`refusing to send system file: ${f}`)
    }
  }
  for (const exact of SENSITIVE_EXACT) {
    if (real === exact) {
      throw new Error(`refusing to send system file: ${f}`)
    }
  }
}

// Access/allowlist file layer (access.json + people.json). Extracted to
// ./access-store.ts (switchroom#4248) to relieve the gateway line-ratchet;
// behavior is byte-identical. The factory runs the static-mode BOOT_ACCESS
// snapshot eagerly at THIS point in startup — same timing as the inline
// version — so the frozen-allowlist semantics are unchanged.
const { loadAccess, readPeopleFile, assertAllowedChat, saveAccess, pruneExpired } =
  createAccessStore({
    accessFile: ACCESS_FILE,
    peopleFile: PEOPLE_FILE,
    stateDir: STATE_DIR,
    isStatic: STATIC,
  })

/**
 * Boot-time-only person-name directory (see resolve-person.ts module doc).
 * Populated exactly once by the boot-validation block in the startup IIFE
 * below, then never reassigned or re-read from disk again for the life of
 * this process — a config change requires an agent restart.
 */
let PERSON_DIRECTORY: PersonDirectory = { byTelegramKey: {} }

// ─── History ──────────────────────────────────────────────────────────────
const HISTORY_ACCESS = loadAccess()
const HISTORY_ENABLED = HISTORY_ACCESS.historyEnabled !== false
if (isGatewayMain && HISTORY_ENABLED) {  // #2996 P0c: gated — initHistory opens bun:sqlite
  try {
    initHistory(STATE_DIR, HISTORY_ACCESS.historyRetentionDays ?? 30)
    process.stderr.write(`telegram gateway: history capture enabled at ${join(STATE_DIR, 'history.db')}\n`)
  } catch (err) {
    process.stderr.write(`telegram gateway: history init failed (${(err as Error).message}) — capture disabled\n`)
  }
}

// ─── Turn-tracking registry + honest-restart-resume ────────────────────────
// On boot, open the per-agent registry.db and reap any turn that never got an
// ended_at — those were killed mid-flight (operator restart, SIGKILL, OOM,
// hard reboot). The reaper CLASSIFIES each orphan from the on-disk
// turn-active marker's age:
//   - marker older than the hang-watchdog window → 'timeout' (the turn
//     stalled with no tool progress; report it, don't blindly resume).
//   - otherwise → 'restart' (a clean interrupt; resume it).
// Then, if the LATEST turn was interrupted, we build a synthetic resume /
// report inbound and (further down, once the inbound spool exists) inject it
// so the agent wakes on its own and either picks the work back up or tells
// the user why it stopped — no human nudge required.
//
// The classifier MUST read the marker before the boot-cleanup sweep removes
// it (the sweep runs much later, in the bridge-registration path). This block
// runs at module top, so the marker is still present here.
let turnsDb: ReturnType<typeof openTurnsDb> | null = null
// Stashed here; pushed to the spool once it's constructed below. The spool's
// turn_key-keyed dedup makes a re-stash across multiple restarts a no-op.
let bootResumeInbound: { agent: string; msg: InboundMessage } | null = null
// Crash-survival redelivery candidate, captured during the boot-resume block
// (module init, BEFORE the Telegram client connects) and consumed by
// `maybeRedeliverUndeliveredAnswer` in the one-time-setup block AFTER
// `bot.api.getMe()` succeeds — so the framed recovered-answer send is sequenced
// after the client is ready, never fired mid module-init. `null` when there is
// no interrupted turn to consider.
let pendingRedelivery: { turn: Turn; maxAgeMs: number } | null = null
// #3038 cross-boot damper: consecutive bridge-dead escalations by PRIOR
// boots (the consumed marker's `count`; 0 when no fresh marker). Set in
// the boot block below, consumed by the watchdog constructor further down.
let bridgeDeadPriorStreak = 0
if (isGatewayMain) try {  // #2996 P0c: gated — opens bun:sqlite + writes .pending-turn.env
  // STATE_DIR is `<agentDir>/telegram` in production. openTurnsDb expects
  // the parent (agent dir) and joins `telegram/registry.db` itself.
  const agentDir = STATE_DIR.endsWith('/telegram')
    ? STATE_DIR.slice(0, -'/telegram'.length)
    : STATE_DIR
  turnsDb = openTurnsDb(agentDir)
  // Apply subagents schema in the same DB. openTurnsDb only applies the turns
  // schema; subagents lives alongside in registry.db. Idempotent — safe on
  // pre-existing DBs (handles the jsonl_agent_id column migration).
  applySubagentsSchema(turnsDb)

  // Read the turn-active marker (the in-flight turn the watchdog tracks)
  // BEFORE classifying — its mtime is "ms since last tool progress" and its
  // payload carries the in-flight turn_key.
  let markerTurnKey: string | null = null
  let markerAgeMs: number | null = null
  try {
    const markerPath = join(STATE_DIR, TURN_ACTIVE_MARKER_FILE)
    if (existsSync(markerPath)) {
      const st = statSync(markerPath)
      markerAgeMs = Date.now() - st.mtimeMs
      try {
        const payload = JSON.parse(readFileSync(markerPath, 'utf8')) as { turnKey?: unknown }
        if (typeof payload.turnKey === 'string' && payload.turnKey.length > 0) {
          markerTurnKey = payload.turnKey
        }
      } catch { /* unreadable/torn marker — age alone still classifies */ }
    }
  } catch { /* stat failure — treat as no marker (plain restart) */ }

  // TURN_HANG_SECS is the watchdog's hang threshold (default 300s); the
  // classifier uses the same signal so "would the watchdog have killed it"
  // is answered identically whether or not the watchdog is live (it's
  // disabled under Docker, but the staleness judgement still holds).
  const hangSecs = Number(process.env.TURN_HANG_SECS)
  const hangThresholdMs = (Number.isFinite(hangSecs) && hangSecs > 0 ? hangSecs : 300) * 1000
  const reasonSnapshot =
    markerAgeMs != null ? JSON.stringify({ idleMs: Math.round(markerAgeMs) }) : null

  const { reaped, timeoutTurnKey } = markOrphanedWithTimeoutClassification(turnsDb, {
    markerTurnKey,
    markerAgeMs,
    hangThresholdMs,
    reasonSnapshot,
  })
  if (reaped > 0) {
    process.stderr.write(
      `telegram gateway: turn-registry boot-reaper stamped ${reaped} orphaned turn(s)` +
      `${timeoutTurnKey ? ` (turnKey=${timeoutTurnKey} as 'timeout', markerAgeMs=${markerAgeMs})` : " as 'restart'"}\n`,
    )
  } else {
    process.stderr.write(`telegram gateway: turn-registry initialized at ${join(agentDir, 'telegram', 'registry.db')}\n`)
  }

  // #3038 — bridge-dead escalation marker. If the PREVIOUS gateway bounced
  // this container because the MCP bridge died (see bridge-dead-watchdog.ts),
  // it left a marker so THIS boot's resume inbound can state the real cause
  // instead of implying an operator restart or a watchdog timeout. Consumed
  // (always cleared) whether or not a turn was in flight.
  const bridgeDeadMarker = consumeBridgeDeadEscalationMarker(
    join(STATE_DIR, 'bridge-dead-escalation.json'),
  )
  if (bridgeDeadMarker != null) {
    bridgeDeadPriorStreak = bridgeDeadMarker.count ?? 1
    process.stderr.write(
      `telegram gateway: boot: prior restart was a bridge-dead escalation (reason=${bridgeDeadMarker.reason}` +
      `, consecutive=${bridgeDeadPriorStreak}` +
      `${bridgeDeadMarker.crashTail ? `, crashTail=${bridgeDeadMarker.crashTail}` : ''})\n`,
    )
  }
  const bridgeDeadRestartCause = bridgeDeadMarker != null
    ? {
        reason: bridgeDeadMarker.reason,
        note:
          'The framework itself triggered this restart: your Telegram MCP bridge process had died ' +
          '(chat tools were unavailable — you could not send replies), so the container was bounced ' +
          'to restore the chat surface. This was NOT an operator-initiated restart and NOT a hang-watchdog kill.',
      }
    : undefined

  // Build the boot resume/report inbound for the LATEST turn if it was
  // interrupted. selectResumeBuilder owns the resume-vs-report policy.
  const pending = findLatestTurnIfInterrupted(turnsDb)
  const selfAgent = process.env.SWITCHROOM_AGENT_NAME ?? ''
  if (pending != null && selfAgent) {
    // Boot-resume policy (2026-07, superseding #2585). The block only runs
    // when `pending` exists — i.e. there IS genuinely in-flight work. The
    // product decision is that a DELIBERATE restart must not silently drop
    // that work: `session_continuity.boot_resume` (SWITCHROOM_BOOT_RESUME,
    // default 'in-flight') resumes it even after a clean shutdown. #2585's
    // quota-saving posture survives only as the opt-in 'never' mode — and
    // even then we deliver a passive REPORT, never silence, because the user
    // must always be told when in-flight work stopped.
    //
    // NOTE: GATEWAY_CLEAN_SHUTDOWN_MARKER_PATH is defined lower in this file
    // (module-init order); we compute the path inline here using the same
    // formula so we can read it at boot-resume time.
    // SWITCHROOM_BOOT_RESUME_ALWAYS=1 remains a back-compat escape hatch that
    // forces unconditional resume regardless of mode.
    const bootResumeMarkerPath =
      process.env.SWITCHROOM_GATEWAY_CLEAN_SHUTDOWN_MARKER ?? join(STATE_DIR, 'clean-shutdown.json')
    const bootResumeCleanMarker = readCleanShutdownMarker(bootResumeMarkerPath)
    const bootResumeForceAlways = process.env.SWITCHROOM_BOOT_RESUME_ALWAYS === '1'
    const bootResumeMode = parseBootResumeMode(process.env.SWITCHROOM_BOOT_RESUME)
    const bootResumeSuppressed = shouldSuppressBootResume(bootResumeCleanMarker, Date.now(), {
      forceAlways: bootResumeForceAlways,
      mode: bootResumeMode,
    })

    // 3h staleness failsafe (operator spec, 2026-06-03): never AUTO-resume
    // interrupted work older than RESUME_MAX_AGE_MS — selectResumeBuilder
    // downgrades a stale 'resume' to the passive 'report'. Env override
    // SWITCHROOM_RESUME_MAX_AGE_MS (ms); set very high to disable.
    const RESUME_MAX_AGE_MS = (() => {
      const v = Number(process.env.SWITCHROOM_RESUME_MAX_AGE_MS)
      return Number.isFinite(v) && v > 0 ? v : 10_800_000 // 3h
    })()

    // Decide the inbound kind (pure — see decideBootResumeKind). Precedence:
    //   1. loop-guard  → 'defer-loop'       (never a second resume of a resume)
    //   2. suppressed  → 'defer-suppressed' (boot_resume: never; notice, not silence)
    //   3. otherwise   → selectResumeBuilder (resume | report | none)
    const bootResumeKind = decideBootResumeKind({
      pending,
      suppressed: bootResumeSuppressed,
      ageMs: Math.max(0, Date.now() - pending.started_at),
      maxAgeMs: RESUME_MAX_AGE_MS,
    })

    // Crash-survival redelivery (deterministic, zero-token): capture THIS
    // interrupted turn as a redelivery candidate. The actual re-project + framed
    // send happens later, AFTER the Telegram client connects (see
    // `maybeRedeliverUndeliveredAnswer`, fired from the one-time-setup block).
    // Gated on the same `pending` as the resume synthetic but a SEPARATE concern:
    // resume re-runs the model on unfinished work; redelivery just re-sends the
    // finished answer the model already produced and the crash swallowed.
    //
    // MUTUAL EXCLUSION with resume (double-send guard): redelivery is captured
    // ONLY when this turn will NOT be re-run by the resume path — i.e.
    // `bootResumeKind !== 'resume'`. When the kind IS 'resume', the model re-runs
    // the interrupted work and emits a FRESH answer that supersedes the recovered
    // draft; redelivering as well would send the same answer twice (once framed
    // "Recovered from an interrupted turn:", once fresh). The other kinds do NOT
    // auto-re-answer, so redelivery is the correct (and only) send there:
    //   - 'report'          (watchdog-timeout): synthetic only ASKS retry — no auto re-answer
    //   - 'defer-suppressed' (boot_resume: never): no synthetic re-run at all
    //   - 'defer-loop'       (resume-of-a-resume guard): no re-run
    //   - 'none'             (nothing queued): redelivery is the sole recovery
    // This gate is deterministic in code, not prompt-dependent.
    //
    // Eligibility floor: only a turn with a durably-stamped `session_id` (pinned
    // live via the session-event path) qualifies — without it we cannot resolve
    // the EXACT transcript, and a most-recent-mtime heuristic could shadow a
    // fresh boot session's file. The mutual-exclusion-with-resume rule and this
    // floor live together in the pure `decideRedeliverCapture` predicate.
    const redeliverCapture = decideRedeliverCapture({
      willBeResumed: bootResumeKind === 'resume',
      hasSessionId: Boolean(pending.session_id),
    })
    if (redeliverCapture.capture) {
      pendingRedelivery = { turn: pending, maxAgeMs: RESUME_MAX_AGE_MS }
    } else if (redeliverCapture.skipReason === 'will-be-resumed') {
      process.stderr.write(
        `telegram gateway: crash-redelivery suppressed — interrupted turnKey=${pending.turn_key} will be ` +
        `RESUMED (bootResumeKind=resume); the fresh re-answer supersedes the recovered draft (no double-send)\n`,
      )
    } else {
      process.stderr.write(
        `telegram gateway: crash-redelivery skipped — interrupted turnKey=${pending.turn_key} has no ` +
        `pinned session_id (pre-feature turn or no session event seen); cannot resolve exact transcript\n`,
      )
    }

    // Sub-agents that were still in flight (running / stalled — non-terminal)
    // when the turn was killed. Read HERE, at module top, BEFORE the
    // subagent-watcher's boot scan + reaper run: the watcher never deletes
    // these rows (it only flips running→stalled and marks files historical
    // in-memory), and this accessor already includes 'stalled', so the data
    // survives either ordering — but reading pre-watcher keeps it simplest.
    // Threaded into ALL the builders below (resume, watchdog report, and the
    // deferred report) so the session gets an explicit killed-workers block —
    // it must not declare the task done on ghost workers, and even a
    // suppressed/loop-guarded resume must still NAME the deaths.
    let interruptedSubagents: InterruptedSubagent[] = []
    try {
      interruptedSubagents = listNonTerminalSubagentsForTurn(turnsDb, pending.turn_key).map(
        (s) => ({ agentType: s.agent_type, description: s.description, status: s.status }),
      )
    } catch (err) {
      process.stderr.write(
        `telegram gateway: boot-resume subagent lookup failed (${(err as Error).message}) — continuing without worker list\n`,
      )
    }

    if (bootResumeKind === 'resume') {
      bootResumeInbound = {
        agent: selfAgent,
        msg: buildResumeInterruptedInbound({
          turn: pending,
          subagents: interruptedSubagents,
          restartCause: bridgeDeadRestartCause,
        }),
      }
    } else if (bootResumeKind === 'report') {
      // idleMs: this boot's measured marker age if it just classified this
      // turn; otherwise recover it from the persisted interrupt_reason (a
      // later boot, marker already swept); else fall back to total runtime.
      let idleMs = pending.turn_key === timeoutTurnKey && markerAgeMs != null ? markerAgeMs : null
      if (idleMs == null && pending.interrupt_reason) {
        try {
          const parsed = JSON.parse(pending.interrupt_reason) as { idleMs?: unknown }
          if (typeof parsed.idleMs === 'number' && Number.isFinite(parsed.idleMs)) idleMs = parsed.idleMs
        } catch { /* malformed snapshot — fall through */ }
      }
      if (idleMs == null) idleMs = Math.max(0, Date.now() - pending.started_at)
      bootResumeInbound = {
        agent: selfAgent,
        msg: buildResumeWatchdogReportInbound({
          turn: pending,
          idleMs,
          subagents: interruptedSubagents,
          restartCause: bridgeDeadRestartCause,
        }),
      }
    } else if (bootResumeKind === 'defer-loop' || bootResumeKind === 'defer-suppressed') {
      // Passive deferred-report: work was in flight but we decline to
      // auto-resume (loop-guard, or boot_resume:never). Silence is never
      // acceptable here — tell the user what was in flight and ask.
      bootResumeInbound = {
        agent: selfAgent,
        msg: buildResumeDeferredReportInbound({
          turn: pending,
          reason: bootResumeKind === 'defer-loop' ? 'loop-guard' : 'clean-restart-suppressed',
          subagents: interruptedSubagents,
          restartCause: bridgeDeadRestartCause,
        }),
      }
    }

    if (bootResumeKind === 'defer-suppressed') {
      process.stderr.write(
        `telegram gateway: boot-resume suppressed (clean shutdown` +
        `${bootResumeCleanMarker?.reason ? ` reason=${JSON.stringify(bootResumeCleanMarker.reason)}` : ''}` +
        `, mode=${bootResumeMode}) — passive report delivered for turnKey=${pending.turn_key}\n`,
      )
    } else if (bootResumeKind === 'defer-loop') {
      process.stderr.write(
        `telegram gateway: boot-resume loop-guard tripped (interrupted turn was itself a resume) ` +
        `— passive report delivered instead of re-resuming turnKey=${pending.turn_key}\n`,
      )
    }
    if (bootResumeInbound != null) {
      process.stderr.write(
        `telegram gateway: boot-resume queued kind=${bootResumeKind} mode=${bootResumeMode} ` +
        `turnKey=${pending.turn_key} endedVia=${pending.ended_via ?? 'open'} chat=${pending.chat_id}\n`,
      )
    }
  }

  // #3038 review finding 2 — idle-case honesty. When the previous boot was
  // a bridge-dead escalation but NO turn was interrupted (idle agent, dead
  // bridge), the consumed marker's cause would otherwise reach stderr only:
  // the agent and the user never learn why the container bounced. Surface
  // it once, via the same boot-inbound channel the resume path uses, routed
  // to the agent's default/owner chat.
  if (bridgeDeadMarker != null && bootResumeInbound == null && selfAgent) {
    const idleNoticeChat = (() => {
      try {
        return loadAccess().allowFrom[0] ?? null
      } catch {
        return null
      }
    })()
    if (idleNoticeChat != null) {
      bootResumeInbound = {
        agent: selfAgent,
        msg: buildBridgeDeadIdleNoticeInbound({
          chatId: String(idleNoticeChat),
          marker: bridgeDeadMarker,
        }),
      }
      process.stderr.write(
        `telegram gateway: boot: bridge-dead idle notice queued chat=${idleNoticeChat} (no turn was in flight)\n`,
      )
    } else {
      process.stderr.write(
        `telegram gateway: boot: bridge-dead idle notice skipped — no allowFrom chat to surface it in\n`,
      )
    }
  }

  // Diagnostic env file (one-shot, sourced by start.sh) — kept for the
  // wake-audit context. The injected inbound above is the real wake signal;
  // these vars are passive context only. Extracted to pending-turn-env.ts
  // (atomic tmp+rename writer; never throws).
  writePendingTurnEnv(agentDir, pending)
} catch (err) {
  process.stderr.write(`telegram gateway: turn-registry init failed (${(err as Error).message}) — turn tracking disabled\n`)
  turnsDb = null
}

/**
 * Resolve the chat/thread a background sub-agent was dispatched from, so
 * its live worker card + handback route back to the originating
 * conversation (group / forum topic) instead of the operator DM.
 *
 * Walks jsonl_agent_id → `subagents.parent_turn_key` →
 * `turns.chat_id`/`thread_id`. Returns null on any miss so the caller
 * keeps its existing `allowFrom[0]` DM fallback — best-effort, never
 * throws out of the worker-card hot path. This restores the chat context
 * the pinned-card fleet used to carry before it was removed in #1122
 * (progressDriver is permanently null, so the old fleet lookup always
 * yielded the DM for a Task dispatched from a group/topic).
 */
function resolveSubagentOriginChat(
  agentId: string,
): { chatId: string; threadId?: number } | null {
  if (turnsDb == null) return null
  // Transitive walk (jsonl stem → parent_turn_key chain → turns row) —
  // extracted to subagent-origin-surface.ts so the resolution precedence is
  // unit-testable against a real registry DB. Null on any miss; the callers
  // keep their fallback ladders (now with the recent-turn floor).
  return resolveSubagentOriginChatDb(turnsDb, agentId)
}

/**
 * Recent-turn routing floor (msg-6897 misroute fix): the newest turn AT OR
 * BEFORE the worker's dispatch time — where the operator dispatched it from.
 * Used ONLY after origin resolution has missed; bounded by the dispatch time
 * so a later turn in an unrelated (possibly shared) chat can never capture
 * the worker's surface. Null-safe (no pre-dispatch turn → owner-DM fallback).
 */
function recentTurnFallbackChat(agentId: string): { chatId: string; threadId?: number } | null {
  if (turnsDb == null) return null
  return resolveRecentTurnFallbackChat(turnsDb, agentId)
}

/**
 * Tracks worker-feed agents whose owner-DM fallback has already been
 * logged, so `resolveWorkerFeedChat` emits the routing-decision line once
 * per agent instead of every watcher tick (~1/s). Capped FIFO at 256 — a
 * late duplicate log is harmless (one extra stderr line), and the cap keeps
 * the set bounded across a long gateway lifetime even if origin resolution
 * is persistently broken fleet-wide (history disabled → every nested worker
 * hits the fallback). A gateway restart clears it.
 */
const WORKER_FEED_FALLBACK_LOG_CAP = 256
/**
 * Margin added to the watcher's in-flight terminal cap to form the worker-feed
 * backstop TTL (`staleWorkerTtlMs`). The feed reaps a row only once it has been
 * silent for cap + this margin — comfortably past the watcher's own terminal-
 * transition latency, so the backstop can only ever bite a genuinely ghosted
 * slot, never a live-but-quiet worker. 5 min.
 */
const WORKER_FEED_STALE_TTL_MARGIN_MS = 5 * 60_000
/**
 * Multiple of the watcher's in-flight terminal cap used to derive the worker-
 * feed ABSOLUTE row-lifetime cap (`absoluteRowLifetimeCapMs`). Unlike the
 * silence-keyed `staleWorkerTtlMs` backstop, the absolute cap is anchored to a
 * row's immutable creation time, so it reaps an immortal card even when the row
 * keeps receiving `update()` cues that reset `lastUpdateAt` every heartbeat
 * (the Carrie 5h zombie-pin leak, re-edited 3000+ times, that the silence sweep
 * could never match). At the 45-min default cap this yields a 3-hour absolute
 * ceiling — comfortably above any legitimate single worker's lifetime, so it
 * can only ever bite a genuine leak, while bounding a ghost card well UNDER the
 * ~5h symptom Ken hit (the initial 8x/6h was too loose). Derived from the same
 * base as `staleWorkerTtlMs` — the watcher's effective in-flight terminal cap
 * (`resolveInflightTerminalCapMs()`: the `SWITCHROOM_SUBAGENT_INFLIGHT_TERMINAL_
 * CAP_MS` env override, else the 45-min default) — never a bare magic number, so
 * it tracks the env-level terminal-cap override in lockstep with the silence
 * backstop. (Both this and `staleWorkerTtlMs` call `resolveInflightTerminalCapMs()`
 * with NO arg, matching the watcher's OWN effective value here: the gateway does
 * not pass a config-file `inflightTerminalCapMs` to `startSubagentWatcher`, so
 * there is no config-file override to thread through — env + default is the
 * complete override surface on this path.)
 */
const WORKER_FEED_ABSOLUTE_ROW_LIFETIME_CAP_MULTIPLE = 4
/**
 * ABSOLUTE reused-group-MESSAGE lifetime cap (invisible-worker-cards fix,
 * 2026-07-15). Bounds how long the shared worker-feed message is reused before
 * it is force-rotated to a fresh message, re-establishing the pin surface so a
 * card whose pin was lost out-of-band (and whose in-memory claim went stale)
 * cannot stay scroll-buried indefinitely. Conservative default 60 min; env
 * `SWITCHROOM_WORKER_FEED_GROUP_MESSAGE_LIFETIME_CAP_MS` overrides for tuning.
 */
const WORKER_FEED_GROUP_MESSAGE_LIFETIME_CAP_MS = (() => {
  const v = Number(process.env.SWITCHROOM_WORKER_FEED_GROUP_MESSAGE_LIFETIME_CAP_MS)
  return Number.isFinite(v) && v > 0 ? v : 60 * 60_000
})()
const workerFeedOwnerDmFallbackLogged = new Set<string>()

// Once-per-agent owner-DM-fallback routing line (bounded FIFO set). Shared by
// `resolveWorkerFeedChat` and the origin-defer paint path so both log alike.
function noteWorkerFeedOwnerDmFallback(agentId: string): void {
  if (workerFeedOwnerDmFallbackLogged.has(agentId)) return
  workerFeedOwnerDmFallbackLogged.add(agentId)
  if (workerFeedOwnerDmFallbackLogged.size > WORKER_FEED_FALLBACK_LOG_CAP) {
    const oldest = workerFeedOwnerDmFallbackLogged.values().next().value
    if (oldest != null) workerFeedOwnerDmFallbackLogged.delete(oldest)
  }
  process.stderr.write(
    `telegram gateway: worker-feed origin unresolved agent=${agentId} — routing card to owner DM\n`,
  )
}

// Per-agent consecutive origin-race deferrals (rationale in
// `decideWorkerFeedOriginDefer`, worker-feed-dispatch.ts). Bounds the wait for
// the `jsonl_agent_id` backfill; deleted on link, card-exists, and finish/drop
// so the map stays bounded.
const workerFeedOriginDeferrals = new Map<string, number>()
// Watcher ticks ~1/s and the backfill retries ~every 3s, so ~10 ticks is a
// comfortable ceiling on the race window before painting anyway.
const WORKER_FEED_ORIGIN_DEFER_MAX = 10

/**
 * Resolve a worker-feed destination chat with a guaranteed last resort
 * (universal-liveness: "any active work has a card" — the owner DM is the
 * durable floor, "wrong chat" beats "no card"). The ladder itself
 * (origin → fleet → recent-turn → owner DM) lives in
 * `resolveWorkerSurfaceChat` (subagent-origin-surface.ts) — the ONE tested
 * implementation, shared with the handback/progress deciders below so the
 * precedence cannot diverge per call site again; this wrapper adds only the
 * gateway's audit logs.
 */
function resolveWorkerFeedChat(
  agentId: string,
  fleetChatId: string,
): { chatId: string; threadId?: number } {
  const dest = resolveWorkerSurfaceChat(turnsDb, agentId, {
    fleetChatId,
    ownerDm: loadAccess().allowFrom[0] ?? '',
  })
  if (dest.via === 'recent-turn') noteWorkerRecentTurnFloor(agentId, dest)
  if (dest.via === 'owner-dm') noteWorkerFeedOwnerDmFallback(agentId)
  return { chatId: dest.chatId, ...(dest.threadId != null ? { threadId: dest.threadId } : {}) }
}

// ─── Periodic history reaper (#1073) ──────────────────────────────────────
// The init-time prune in history.ts only touched the `messages` table.
// `subagents` and `turns` in registry.db grew unbounded — every Agent()
// call and every turn added a row that never expired. The SQLite WAL
// also grew without bound because no path issued a checkpoint.
//
// Strategy:
//   1. At boot, prune both registry tables on the same window as
//      messages (catch-up for long-stopped agents waking up to stale
//      data). Plus a one-shot WAL checkpoint on history.db.
//   2. Every 6h thereafter, re-run the registry reaper + history WAL
//      checkpoint. The window is intentionally coarse — a daily-ish
//      cadence keeps the WAL bounded without thrashing IO on a quiet
//      agent.
//
// Retention selection — same resolveRegistryRetentionDays helper used
// at boot and on every tick, so an operator can change env or
// access.json and the next tick picks it up.
const REGISTRY_REAPER_INTERVAL_MS = 6 * 60 * 60 * 1000
function runHistoryReaperNow(reason: 'boot' | 'periodic'): void {
  const retentionDays = resolveRegistryRetentionDays(HISTORY_ACCESS.historyRetentionDays)
  // Registry reaper: subagents + turns + WAL checkpoint on registry.db.
  if (turnsDb != null) {
    try {
      const result = runRegistryReaper(turnsDb, { retentionDays })
      process.stderr.write(
        `telegram gateway: registry-reaper (${reason}) retentionDays=${retentionDays}`
        + ` subagents.deleted=${result.subagents.deleted} (${result.subagents.batches} batches)`
        + ` turns.deleted=${result.turns.deleted} (${result.turns.batches} batches)`
        + ` wal.checkpoint=${result.walCheckpointed ? 'ok' : 'busy'}\n`,
      )
    } catch (err) {
      process.stderr.write(`telegram gateway: registry-reaper (${reason}) failed: ${(err as Error).message}\n`)
    }
  }
  // History DB extension: on boot, extend the messages init-prune to
  // cover the case where the existing one-shot prune in initHistory()
  // ran with a stale retention value (or didn't run at all on an old
  // DB). On periodic ticks, also prune messages so a multi-month
  // session doesn't slowly outgrow its window. We deliberately reuse
  // the messages-table retention from access.json (`historyRetentionDays`,
  // defaulting to 30) here — the new HISTORY_RETENTION_DAYS env applies
  // to registry tables only, per the issue scope. Messages retention
  // policy is unchanged.
  if (HISTORY_ENABLED) {
    try {
      const messagesRetentionDays = HISTORY_ACCESS.historyRetentionDays ?? 30
      const deleted = pruneMessagesOlderThanDays(messagesRetentionDays)
      const walOk = checkpointHistoryWal()
      if (deleted > 0 || reason === 'boot') {
        process.stderr.write(
          `telegram gateway: history-reaper (${reason}) messagesRetentionDays=${messagesRetentionDays}`
          + ` messages.deleted=${deleted} wal.checkpoint=${walOk ? 'ok' : 'busy'}\n`,
        )
      }
    } catch (err) {
      process.stderr.write(`telegram gateway: history-reaper (${reason}) failed: ${(err as Error).message}\n`)
    }
  }
}
// Run once at boot to catch up long-stopped agents. (#2996 P0c: gated.)
if (isGatewayMain) runHistoryReaperNow('boot')
// Then every 6h. unref() so the interval doesn't keep the process alive
// past shutdown.
if (isGatewayMain && !STATIC) {
  setInterval(() => runHistoryReaperNow('periodic'), REGISTRY_REAPER_INTERVAL_MS).unref()
}

// ─── Approval polling ─────────────────────────────────────────────────────
function checkApprovals(): void {
  let files: string[]
  try { files = readdirSync(APPROVED_DIR) } catch { return }
  for (const senderId of files) {
    const file = join(APPROVED_DIR, senderId)
    // allow-raw-bot-api: Paired! sendMessage to DM senderId; no thread_id, cannot trigger THREAD_NOT_FOUND
    void bot.api.sendMessage(senderId, "Paired! Say hi to Claude.").then(
      () => rmSync(file, { force: true }),
      err => {
        process.stderr.write(`telegram gateway: failed to send approval confirm: ${err}\n`)
        rmSync(file, { force: true })
      },
    )
  }
}
if (isGatewayMain && !STATIC) setInterval(attachBootBeacon(STATE_DIR, checkApprovals), 5000).unref() // beacon rides this EXISTING tick — boot-beacon.ts
// Gateway liveness heartbeat — touches `<STATE_DIR>/gateway-heartbeat` while
// the gateway lives so the silent-end Stop hook's single-writer election can
// confirm the gateway is alive (and WILL run its turn_end delivery) before
// electing to allow a turn to end without re-prompting. Allowing into a dead
// gateway would drop the answer — the one outcome worse than a duplicate. See
// gateway/gateway-heartbeat.ts + hooks/silent-end-scan.mjs.
if (isGatewayMain && !STATIC) startGatewayHeartbeat(STATE_DIR)
// Idle auto-clear: check wall-clock idle every minute; maybeIdleClear no-ops
// when disabled ('0s'), mid-turn, or already cleared this idle period. The
// `let` state + maybeIdleClear are hoisted/initialized before this fires.
const IDLE_CLEAR_CHECK_MS = Number(process.env.SWITCHROOM_IDLE_CLEAR_CHECK_MS ?? 60_000)
if (isGatewayMain && !STATIC && IDLE_CLEAR_CHECK_MS > 0) setInterval(maybeIdleClear, IDLE_CLEAR_CHECK_MS).unref()

// ─── Thread / status / stream state ───────────────────────────────────────
const chatThreadMap = new Map<string, number>()
const activeStatusReactions = new Map<string, StatusReactionController>()
const activeReactionMsgIds = new Map<string, { chatId: string; messageId: number }>()
// Component 5 (queued-status UX). When a cross-topic inbound buffers behind
// an in-flight turn in another topic, we post ONE self-updating status into
// the buffered message's OWN topic ("Queued — replying in <other topic>
// first" → "On it — replying now" → deleted when the answer lands). Keyed
// by chatKey(chat_id, bufferedThread). Delete-on-answer: never a dangling
// placeholder. Reaped on answer (executeReply/stream), on turn-flush, and
// in purgeReactionTracking cleanup so an abnormal turn-end can't strand it.
// #2995: threadId is null for DM cards — the mid-flight busy-ack extends
// this lifecycle to DMs and same-topic surfaces (the original component-5
// card was cross-topic only).
const queuedStatusMsgIds = new Map<string, { chatId: string; threadId: number | null; messageId: number }>()
// #2995 mid-flight busy-ack dedupe: statusKeys that already got a busy-ack
// card during the CURRENT turn — at most one card per turn per chat/topic
// even after the card itself is reaped. The ending turn's key is deleted in
// purgeReactionTracking (per-key, not a global clear — a purge for topic A
// must not reset topic B's dedupe).
const busyAckPostedKeys = new Set<string>()
// #2995 deferred re-check: a ping that arrives while the blocking step is
// still YOUNG (< threshold) must not be silently forgotten — the step may
// run for minutes more (the original #2995 silence). One timer per key,
// armed for (threshold − stepAge); it re-evaluates live state when it
// fires and is cancelled by purgeReactionTracking when the turn ends.
const busyAckRecheckTimers = new Map<string, ReturnType<typeof setTimeout>>()
// Reactions whose terminal 👍 is deferred because a background sub-agent
// worker was still running when the parent's `turn_end` fired. Painting 👍
// then would read as "done / nothing happening" while the worker keeps
// going. The controller is `hold()`-frozen on a working glyph; the entry
// is promoted to 👍 by `deferredDoneReactions.promote()` (wired to the
// watcher's `onFinish`) when the last worker completes. See
// `reaction-defer.ts` for the promote/purge interaction the unit tests pin.
const deferredDoneReactions = new DeferredDoneReactions<StatusReactionController>({
  countRunningWorkers: () => countRunningWorkers(),
  getActive: (key) => activeStatusReactions.get(key),
  purge: (key) => purgeReactionTracking(key),
})

// #546 — outbound content-dedup window. PR #599 introduced the read
// sites (`outboundDedup.check` / `.record` in executeReply and
// turn-flush) but the declaration was lost in a merge somewhere — every reply
// path threw `outboundDedup is not defined` at runtime, blocking ALL outbound
// from the agent. Restore the module-level singleton here.
const outboundDedup = new OutboundDedupCache()
// 2026-07 duplicate-reply fix — turnId-keyed supersede. When a turn-flush
// (answer-ready quiescence OR the turn-end backstop) posts the model's terminal
// text and the model's REAL `reply` for the SAME turn lands later, the reply
// SUPERSEDES the flushed message (delete + canonical resend) instead of shipping
// a second message. Keyed on the per-turn `turnId` nonce, NOT on text — so it
// catches the containment case the exact-text `outboundDedup` misses (a
// `narration\n\nanswer` flush never equals the clean `answer`-only reply).
// #4173/#4175 — window bounds (env kill-switch + rationale) live in
// reply-owner-wiring.ts so this ctor and the owner-tier candidates share them.
const flushedTurnSupersede = new FlushedTurnSupersedeRegistry({
  openCapMs: SUPERSEDE_OPEN_CAP_MS,
  completedGraceMs: SUPERSEDE_GRACE_MS,
})
// #3276 — the turn-flush backstop's per-turn delivery latch + per-chunk
// idempotency ledger. The latch (keyed on `turnId`) is the deterministic
// arbiter of backstop-vs-reply; the chunk ledger lets a retry after a partial
// send resume at the first unsent chunk instead of re-sending chunk 0.
const backstopDeliveryLedger = new BackstopDeliveryLedger()
// #3276 finding-1 — bounded in-turn retries for the backstop send before it
// gives up and records `send_failed` (leaving the obligation open for the
// liveness floor). Resumes mid-chunk each attempt, so chunk 0 is never
// re-sent. Env-tunable for ops; default 3.
const BACKSTOP_DELIVERY_MAX_ATTEMPTS = (() => {
  const raw = Number(process.env.SWITCHROOM_BACKSTOP_DELIVERY_MAX_ATTEMPTS)
  return Number.isFinite(raw) && raw >= 1 ? Math.floor(raw) : 3
})()

/**
 * #3276 — the ONE delivery primitive the turn-flush backstop uses to put a
 * flushed answer into the chat. It routes through `sendReplyChunks` — the SAME
 * battle-tested send core `executeReply` uses (THREAD_NOT_FOUND fallback,
 * length re-split, parse-reject plaintext fallback) — and returns the REAL
 * fresh chat message ids.
 *
 * Deliberately NOT card-coupled: it never edits the progress card, so a
 * "delivery" can never be a card mutation that the marker-sweep GC's ~60-90s
 * later. The card is unpinned/collapsed by the caller as a purely cosmetic
 * follow-up (guard 4). `previewMessageId` is always null here.
 *
 * Idempotent (guard 6): each chunk is sent under `backstopDeliveryLedger`. A
 * chunk that already landed for this `turnId` is skipped, and a pending marker
 * is written before every wire call, so a retry after a partial send or a lost
 * ack resumes at the first unsent chunk and never re-sends chunk 0.
 *
 * `text` must already be fully normalized/redacted/scrubbed by the caller (the
 * turn-flush branch runs the exact reply-parity pipeline before calling this).
 */
async function deliverAnswer(args: {
  chatId: string
  threadId: number | undefined
  text: string
  turnId: string
  cardMessageId: number | null
  /** S4 (fable red-team 2026-07-17) — the inbound message this turn answers
   *  (`turn.sourceMessageId`). When present, the FIRST chunk is sent as a
   *  native quote-reply so the flushed answer anchors to the user's question,
   *  matching `executeReply`'s default. `allow_sending_without_reply` keeps
   *  the send alive if the user deleted their message. Null for synthesized
   *  turns (cron/handback) — those send bare, as before. */
  replyToMessageId: number | null
  /** #3282 captured-answer RESUME (see captured-answer-resume.ts): re-deliver the SAME byte-identical chunks + pre-hydrate the ledger (unsent tail only; a landed chunk is re-probed, never re-sent). */
  resume?: { snapshot: CapturedDeliverySnapshot; hydrate: (ledger: BackstopDeliveryLedger, turnId: string) => void }
  /** Duplicate-message race fix — forwarded to `runBackstopDelivery` as `onAckClaim` (claims the nonce at send-ack, before the read-back probe; see backstop-delivery.ts). */ onAckClaim?: (sentIds: number[]) => void }): Promise<{ sentIds: number[]; chunkCount: number; delivered: boolean; exhausted: boolean; landedUnconfirmed: number }> {
  const { chatId, turnId } = args
  // Spacers into `\n\n` gaps then split (as executeReply); a resume re-delivers the EXACT captured chunks (byte-stable, no re-split).
  const chunks = args.resume
    ? args.resume.snapshot.chunks
    : splitMarkdownChunks(addParagraphSpacers(args.text), RICH_MESSAGE_MAX_CHARS)

  const deps: ReplyChunkSendDeps = {
    sendRich: (opts, body, tid) =>
      robustApiCall(
        // allow-raw-bot-api: deliverAnswer chunk-loop adapter — sendRichMessage routed through robustApiCall; THREAD_NOT_FOUND handled by sendReplyChunks' fallback ladder
        () => bot.api.sendRichMessage(chatId, body as never, opts as never),
        { threadId: tid, chat_id: chatId, priorityClass: 'critical' },
      ),
    sendLiteral: (opts, txt, tid) =>
      robustApiCall(
        // allow-raw-bot-api: deliverAnswer chunk-loop adapter — literal sendMessage routed through robustApiCall; THREAD_NOT_FOUND handled by sendReplyChunks
        () => bot.api.sendMessage(chatId, txt, opts as never),
        { threadId: tid, chat_id: chatId, priorityClass: 'critical' },
      ),
    // allow-raw-bot-api: literal last-resort fallback (parse-reject / length re-split); wrapping would re-enter the policy that just rejected the payload
    sendLiteralRaw: (opts, txt) => bot.api.sendMessage(chatId, txt, opts as never),
    // allow-raw-bot-api: rich length-error re-split last resort; wrapping would re-enter the chunk-loop classification on an already-classified length failure
    sendRichRaw: (opts, body) => bot.api.sendRichMessage(chatId, body as never, opts as never),
    editPreview: (mid, body, opts, tid) =>
      robustApiCall(
        // allow-raw-bot-api: preview edit-in-place routed through robustApiCall; thread fallback handled by sendReplyChunks
        () => bot.api.editMessageText(chatId, mid, body as never, opts as never),
        { threadId: tid, chat_id: chatId, priorityClass: 'critical', messageId: mid, editPayload: body },
      ),
    richMessage,
    logOutbound,
    // deliverAnswer never sets a previewMessageId, so this is never invoked;
    // provide a best-effort delete for interface completeness.
    deleteStalePreview: async (id: number): Promise<void> => {
      await swallowingApiCall(
        () => bot.api.deleteMessage(chatId, id),
        { chat_id: chatId, verb: 'deliverAnswer.deleteStalePreview' },
      )
    },
    stderr: (s: string) => { process.stderr.write(s) },
  }

  // Send ONE chunk via the shared `sendReplyChunks` core. `liveThreadId`
  // threads the THREAD_NOT_FOUND fallback decision across chunks. Returns the
  // landed message id(s) (a length-resplit chunk may land >1); throws on an
  // unrecoverable send failure so the retry orchestrator can resume.
  let liveThreadId = args.threadId
  const sendChunk = async (chunkIndex: number, text: string): Promise<number[]> => {
    const chunkIds: number[] = []
    // S4 — quote-anchor the FIRST chunk only (chunkIndex is the OVERALL chunk
    // index across the retry orchestrator; each sendReplyChunks call here
    // carries exactly one chunk, so the inner index is always 0). Mirrors
    // executeReply's first-chunk-only default. The ledger resumes retries at
    // the first UNSENT chunk, so chunk 0 keeps its anchor across retries.
    const anchor =
      chunkIndex === 0 && args.replyToMessageId != null
        ? { reply_parameters: { message_id: args.replyToMessageId, allow_sending_without_reply: true } }
        : {}
    const res = await sendReplyChunks(deps, {
      chatId,
      chunks: [text],
      literalText: false,
      suppressText: false,
      threadId: liveThreadId,
      previewMessageId: null,
      sentIds: chunkIds,
      buildSendOpts: (_i, _isLast, tid) => ({
        ...anchor,
        ...(tid != null ? { message_thread_id: tid } : {}),
        link_preview_options: { is_disabled: true },
      }),
      buildPreviewEditOpts: () => ({}),
    })
    liveThreadId = res.threadId
    return chunkIds
  }

  // #3278 read-back confirmation. A returned message_id proves Telegram
  // ACCEPTED a send, not that the message is VISIBLE — a server-side
  // accept-then-silently-discard (flood/anti-spam) returns a fresh id yet the
  // user sees nothing. `createBackstopReadBack` re-confirms each landed chunk
  // via a no-op editMessageText before it counts as delivered; it is paced
  // COSMETIC through the send gate (sheds under a flood window → ambiguous,
  // never a re-send) and scoped to this RARE backstop path — the hot reply-tool
  // path issues ZERO probes (#3278 §1.3/§1.5).
  const readBack = createBackstopReadBack({
    // allow-raw-bot-api: #3278 read-back probe — no-op editMessageText, paced by the injected sendGate.gate (cosmetic) and classified by classifyReadBackError; a gate shed / any throw → ambiguous (never re-send)
    editMessageText: (mid, body, apiOpts) => bot.api.editMessageText(chatId, mid, body as never, apiOpts as never),
    gate: (fn, opts) => sendGate.gate(fn, opts),
    isShed: isSendGateShed,
    richMessage,
    chatId,
    threadId: args.threadId,
  })

  // #3282 — a resume pre-hydrates the ledger (confirmed chunks never re-sent).
  if (args.resume) args.resume.hydrate(backstopDeliveryLedger, turnId)

  // Bounded in-turn retry (finding-1 fix): resumes at the first unsent chunk on
  // each attempt via the ledger, so chunk 0 is delivered exactly once even
  // across retries. `delivered`/`exhausted` tell the caller whether the answer
  // actually reached the chat — the caller leaves the delivery obligation OPEN
  // on terminal failure so the liveness floor re-presents it.
  const result = await runBackstopDelivery(
    backstopDeliveryLedger,
    turnId,
    chunks,
    args.resume ? null : args.cardMessageId,
    {
      sendChunk,
      readBack, onAckClaim: args.onAckClaim,
      recordOutbound: HISTORY_ENABLED
        ? (messageIds, texts) => {
            try {
              recordOutbound({
                chat_id: chatId,
                thread_id: args.threadId ?? null,
                message_ids: messageIds,
                texts,
              })
            } catch { /* best-effort */ }
          }
        : undefined,
      stderr: (s: string) => { process.stderr.write(s) },
    },
    BACKSTOP_DELIVERY_MAX_ATTEMPTS,
  )
  // #3282 — on a PARTIAL first-delivery, persist the per-chunk snapshot onto the still-OPEN obligation so the represent resumes the tail (not a regeneration).
  if (!args.resume && !result.delivered && OBLIGATION_LEDGER_ENABLED)
    obligationLedger.noteCapturedDelivery(turnId, buildCapturedDeliverySnapshot(backstopDeliveryLedger, turnId, chunks))
  return {
    sentIds: result.sentIds,
    chunkCount: result.chunkCount,
    delivered: result.delivered,
    exhausted: result.exhausted,
    landedUnconfirmed: result.landedUnconfirmedIds.length, // #3702 — the caller stamps this on the turn record
  }
}

/**
 * Per-chat cache of `available_reactions` from `getChat`. Populated lazily —
 * the FIRST message in a chat creates a controller without the filter (null
 * = "try all whitelisted variants"); a fire-and-forget probe populates the
 * cache for subsequent messages. Closes #542: when a chat restricts
 * reactions (common in supergroups), Telegram silently rejects intermediate
 * emoji like 🤔 / 👨‍💻 / ⚡ with 400 REACTION_INVALID, the controller's
 * catch logs and continues, and only 👍 lands. With this cache wired in,
 * StatusReactionController.resolveEmoji() falls through to a permitted
 * variant instead of letting the call fail silently.
 *
 * `null` means "no filter / first probe in flight". `Set<string>` means
 * "Telegram returned the explicit list". Empty Set means the chat allows
 * NO reactions (rare; controller's last-resort branch will return null
 * and emits become no-ops, which is correct).
 */
const chatAvailableReactions = new Map<string, Set<string> | null>()
const chatProbesInFlight = new Set<string>()
const activeTurnStartedAt = new Map<string, number>()
// #2996 P1: the legacy PR3b `claudeBusyKeys` set + its #2787 orphan reaper
// were deleted here — the delivery machine (single activeTurn + TTL tick,
// structurally immune to per-key orphan dangles) is the sole turn-in-flight
// authority now. Fleet gates read `isMachineInTurn()` via
// turnInFlightForGate(); per-key reads (status-query metric, wedge
// detection, etc.) keep reading activeTurnStartedAt because they want the
// receipt timestamp.

/**
 * #2527 observability: count emoji transitions per status-reaction controller
 * so `turn_no_reply_warn` can report how many reaction changes happened while
 * producing zero text. Keyed by statusKey(chatId, threadId); cleared in
 * purgeReactionTracking alongside the controller itself.
 */
const reactionTransitionCounts = new Map<string, number>()

/**
 * #2527 observability: tracks which (chatId:threadId) keys have already emitted
 * a `turn_reply_timing` event this turn so we only fire it on the FIRST text
 * reply. Cleared in purgeReactionTracking at turn-end alongside the controller.
 */
const firstTextReplyLogged = new Set<string>()

/**
 * Helper: canonical chat key for an inbound about to be handed to claude —
 * the key the delivery-confirm tracker matches `enqueue` acks against.
 * Pulls the thread id from the top-level field if present, otherwise falls
 * back to meta.message_thread_id (cron and vault-synthetic inbounds put it
 * there). chatKey canonicalises null/undefined/0 to `_` so callers don't
 * need to think about it. (#2996 P1: this replaced the deleted
 * `markClaudeBusyForInbound` twin — same key derivation, no busy-set
 * side effect; the delivery machine owns the turn-in-flight fact.)
 */
function chatKeyForInbound(m: {
  chatId: string
  threadId?: number
  meta?: Record<string, string>
}): string {
  let tid: number | null = m.threadId ?? null
  if (tid == null && m.meta?.message_thread_id != null) {
    const n = Number(m.meta.message_thread_id)
    if (Number.isFinite(n)) tid = n
  }
  return chatKey(m.chatId, tid)
}

// ─── Reliable inbound delivery: deliver-until-acked (the marko drop-wedge) ─
// A delivered inbound is ACKED only by the `enqueue` session-event (claude
// actually started the turn) — NOT by sendToAgent returning true. Until
// acked, the message stays queued; if it didn't land within the timeout it
// stranded in claude's composer, so we re-deliver it. Re-deliver forever
// until acked — never drop (vs the old fire-and-forget that the 300s
// silence-poke swallowed). Kill switch: SWITCHROOM_INBOUND_DELIVERY_CONFIRM=0
// → legacy fire-and-forget. See inbound-delivery-confirm.ts.
const DELIVERY_CONFIRM_ENABLED = process.env.SWITCHROOM_INBOUND_DELIVERY_CONFIRM !== '0'
// How long to wait for claude's `enqueue` ack before treating a delivery as
// stranded and re-delivering. Generous by default — claude acks within ~1s of
// a clean delivery, so 15s won't false-positive on a healthy turn. Tunable
// (env) for tests/forensics; a too-low value re-delivers healthy slow turns
// (duplicate turn), which is why the default is comfortably above ack latency.
const _deliveryTimeoutRaw = process.env.SWITCHROOM_INBOUND_DELIVERY_TIMEOUT_MS
const _deliveryTimeoutParsed =
  _deliveryTimeoutRaw != null && _deliveryTimeoutRaw !== '' ? Number(_deliveryTimeoutRaw) : 15_000
// Clamp to a positive, finite value: a negative / zero / NaN env override would
// make the sweep treat every tracked entry as stranded and re-deliver every
// cycle forever (a self-inflicted re-delivery loop). To disable the feature,
// use SWITCHROOM_INBOUND_DELIVERY_CONFIRM=0, not a degenerate timeout.
const DELIVERY_CONFIRM_TIMEOUT_MS =
  Number.isFinite(_deliveryTimeoutParsed) && _deliveryTimeoutParsed > 0 ? _deliveryTimeoutParsed : 15_000
const DELIVERY_CONFIRM_SWEEP_MS = 5_000
const deliveryQueue = createDeliveryQueue<InboundMessage>()

// ─── Deterministic delivery-obligation ledger (systems-analysis PR2) ──────────
// An inbound is an OBLIGATION (keyed origin_turn_id) that is OPEN at receipt and
// CLOSED only by an observable substantive reply resolving to that origin —
// never the model's words. An open obligation that survives a turn boundary is
// re-presented (bounded) until it closes, so a message the model read but never
// answered (the marko 715 drop) cannot be silently lost. ADDITIVE + flagged: it
// runs ALONGSIDE the existing acks/spool/buffer (PR3 retires the redundant
// pieces). DEFAULT ON (graduated from canary 2026-06-04 after the hang-fix
// (#2152, total-proof), the escalate-grace (#2156, kills the fuzz-found
// over-escalation), and interrupt-cancel (#2157) — proven on marko (supergroup)
// + test-harness for days with 0 false cards). Kill switch:
// SWITCHROOM_OBLIGATION_LEDGER=0 → every hook below is a no-op → zero change.
const OBLIGATION_LEDGER_ENABLED = process.env.SWITCHROOM_OBLIGATION_LEDGER !== '0'
const OBLIGATION_REPRESENT_MAX = 2
// Minimum reply length (chars) the duplicate-represent guard (#2472/#2474) treats
// as "the user was answered". DECOUPLED from the escalate branch's 200-char proxy:
// for the represent guard ANY genuine assistant reply — even a terse "Yes — done."
// — satisfies the obligation, so suppressing the duplicate re-ask must not require
// 200 chars. Default 1 (any non-empty real reply; empty/whitespace rows are
// clamped out inside hasOutboundDeliveredSince). Override via env for tuning. Safe
// because only recordOutbound writes role='assistant' rows — progress-card edits
// and typing indicators are never counted.
const OBLIGATION_REPRESENT_GUARD_MIN_REPLY_CHARS = (() => {
  const raw = process.env.SWITCHROOM_OBLIGATION_REPRESENT_GUARD_MIN_REPLY_CHARS
  const n = raw != null ? Number.parseInt(raw, 10) : NaN
  return Number.isFinite(n) && n >= 1 ? n : 1
})()
const OBLIGATION_SWEEP_MS = 5_000
// Bound on escalation SEND attempts. The escalation now closes only AFTER a
// successful send (a transient failure stays OPEN and retries next sweep), so a
// PERMANENTLY-undeliverable nudge (dead/renumbered topic → Telegram 400 even
// after thread-fallback, blocked bot) would loop forever — and, with the
// durable snapshot, re-enter that loop on every boot. After this many failed
// attempts the gateway closes best-effort (loud log): the user is genuinely
// unreachable, so a bounded give-up beats an infinite/poison loop.
const OBLIGATION_ESCALATE_MAX = 3
// Deadline for a single escalation send. grammy/fetch impose NO request timeout,
// and the in-flight guard (obligationEscalateInFlight) is cleared only in the
// send's `.finally` — which never runs if the send hangs. Without a bound, one
// stalled send leaks the in-flight flag forever and the obligation is stuck OPEN
// (never re-escalated, never closed) — the sole liveness hole a total proof
// found. Racing the send against this deadline makes the wait bounded BY
// CONSTRUCTION (see with-deadline.ts): the chain always settles, `.finally`
// always clears the flag, and a hang becomes a bounded reject that feeds the
// bounded escalate ladder to a terminal. 45s comfortably exceeds robustApiCall's
// 3-attempt network backoff so a legitimate slow send isn't cut short.
const OBLIGATION_ESCALATE_SEND_DEADLINE_MS = 45_000
// Escalate-grace window. A slow / background-worker / multi-segment turn ends
// (the in-flight gate clears) BEFORE its trailing answer's reply lands, and the
// 5s sweep would re-present/escalate in that gap — a false "⚠️ I may have missed
// this" on a message that's actively being answered (fuzz-confirmed on v0.14.62:
// ~14% of marko's no-reply turn-ends had the answer in flight). An obligation
// whose handling turn ended < this ago is skipped by decideAtIdle, giving the
// trailing answer's close a beat to fire. Bounded: each re-present is itself a
// turn that re-stamps once, representCount is capped → the ladder still
// terminates. 45s > the observed "answer lands within ~60s, usually <40s" gap.
// Kill switch: SWITCHROOM_OBLIGATION_ESCALATE_GRACE_MS=0 → pre-grace behaviour.
const OBLIGATION_ESCALATE_GRACE_MS = (() => {
  const raw = process.env.SWITCHROOM_OBLIGATION_ESCALATE_GRACE_MS
  if (raw == null || raw === '') return 45_000
  const n = Number(raw)
  return Number.isFinite(n) && n >= 0 ? n : 45_000
})()

// Background-work escalate-grace ceiling. The 45s grace above is far too short
// for extended-autonomous sub-agent work: an agent that ack-firsts ("on it")
// then delegates to a background worker OR an orphaned foreground sub-agent ends
// its FOREGROUND turn in seconds, but the real answer lands minutes later. The
// turn-in-flight machine (turn already ended) doesn't see that work, so the
// sweep would re-present/escalate a false "⚠️ I may have missed this — re-send"
// while the agent is genuinely researching (the gymbro liven-research case,
// 2026-06-10). While `agentHasInFlightBackgroundWork()` holds, an open
// obligation younger than THIS ceiling (from openedAt) is skipped. Bounded BY
// CONSTRUCTION — a hard wall-clock ceiling, so even a stuck/leaked worker can't
// suppress escalation forever; the obligation FSM still terminates. This also
// preserves the represent budget across a restart that kills the work: with the
// false represents suppressed, the hydrated obligation re-presents (resumes the
// research) instead of prematurely escalating. Kill switch: =0 → pre-fix
// behaviour (no background-work grace).
const OBLIGATION_BACKGROUND_WORK_GRACE_MS = (() => {
  const raw = process.env.SWITCHROOM_OBLIGATION_BACKGROUND_WORK_GRACE_MS
  if (raw == null || raw === '') return 20 * 60_000 // 20 min — generous for real research, still bounded
  const n = Number(raw)
  return Number.isFinite(n) && n >= 0 ? n : 20 * 60_000
})()
// Per-represent grace window. After a re-present fires, the obligation is
// ineligible for the next represent/escalate until at least this many ms have
// elapsed since markRepresented. Without this the 5s sweep can fire again
// before the re-presented turn even reaches the agent, burning the represent
// budget and producing back-to-back re-presents or a premature escalation.
// Default 120s — generous enough for a turn to start + deliver an answer;
// small enough not to delay genuine unanswered re-presents.
// Kill switch: SWITCHROOM_OBLIGATION_REPRESENT_GRACE_MS=0 → no per-represent grace.
const OBLIGATION_REPRESENT_GRACE_MS = (() => {
  const raw = process.env.SWITCHROOM_OBLIGATION_REPRESENT_GRACE_MS
  if (raw == null || raw === '') return 120_000
  const n = Number(raw)
  return Number.isFinite(n) && n >= 0 ? n : 120_000
})()
// Marker-freshness window for the orphaned-foreground signal. The turn-active
// marker is touched on every foreground tool_use and on foreground sub-agent
// JSONL growth, so an mtime younger than this means a sub-agent is touching it
// RIGHT NOW; older ⇒ the work stopped (or the marker leaked) ⇒ not active.
// Comfortably exceeds the sub-agent poll cadence so it doesn't flap.
const TURN_ACTIVE_MARKER_FRESH_MS = 90_000

// ─── Mid-turn auto-classify (steer-vs-queue), SHADOW mode ─────────────────────
// Today a no-prefix mid-turn message always QUEUES. autoClassifyMidTurnInbound
// (auto-classify-mid-turn.ts) is the basis for a smarter default using
// topic-vs-active-turn + reply-recency. Phase 1 ships SHADOW-ONLY: when this
// flag is on we COMPUTE + LOG what we'd decide (decision/reason/same_topic/
// ms_since_out) but the behaviour is UNCHANGED (still queue) — to gather the
// real-world distribution (how often mid-turn messages are same-topic
// continuations vs cross-topic, and the recency spread) before any action flips
// on. DEFAULT ON fleet-wide (data-gathering: zero behaviour change — only logs +
// a bounded recency map). This is a TEMPORARY default; when auto-steer ships it
// supersedes shadow. Kill switch: SWITCHROOM_AUTOCLASSIFY_MIDTURN_SHADOW=0.
const AUTOCLASSIFY_MIDTURN_SHADOW = process.env.SWITCHROOM_AUTOCLASSIFY_MIDTURN_SHADOW !== '0'
// Per-(chat,thread) wall-clock ms of the agent's LAST visible output — the
// recency clock the classifier uses (NOT turn age: a long actively-narrating
// worker turn must not read "stale"). Stamped beside signalTracker.noteOutbound.
// LRU-bounded so a long-lived gateway with many topics can't grow unboundedly.
const lastAgentOutputAt = new Map<string, number>()
const LAST_OUTPUT_MAX_KEYS = 512
function noteAgentOutputAt(key: string, ts: number): void {
  lastAgentOutputAt.delete(key) // re-insert → most-recently-used at the tail
  lastAgentOutputAt.set(key, ts)
  if (lastAgentOutputAt.size > LAST_OUTPUT_MAX_KEYS) {
    const oldest = lastAgentOutputAt.keys().next().value
    if (oldest !== undefined) lastAgentOutputAt.delete(oldest)
  }
}
// Durable snapshot of the open obligation set on the persistent per-agent
// volume (STATE_DIR = /state/agent/telegram in prod). Closes the restart hole:
// the in-memory ledger alone empties on restart and the spool's boot-replay
// bypasses handleInbound (where obligations OPEN), so a delivered-but-unanswered
// message used to lose its obligation across a restart. onChange persists every
// mutation; boot hydrate (below) restores OPEN/ESCALATING with representCount +
// escalateAttempts intact. STATIC mode (no runtime) and flag-off both skip disk.
const OBLIGATION_STORE_PATH = join(STATE_DIR, 'obligations.json')
const obligationStoreFs = {
  readFileSync: (p: string) => readFileSync(p, 'utf8'),
  writeFileSync: (p: string, d: string) => writeFileSync(p, d),
  renameSync: (a: string, b: string) => renameSync(a, b),
  existsSync: (p: string) => existsSync(p),
  fsyncFileSync: fsyncPathSync, fsyncDirSync: fsyncPathSync, unlinkSync,
}
const obligationLedger = new ObligationLedger(OBLIGATION_REPRESENT_MAX, {
  onChange:
    STATIC || !OBLIGATION_LEDGER_ENABLED
      ? undefined
      : (snapshot) => persistObligations(OBLIGATION_STORE_PATH, obligationStoreFs, snapshot),
})
if (isGatewayMain && !STATIC && OBLIGATION_LEDGER_ENABLED) {
  // Restart-durability: re-open obligations that were OPEN/ESCALATING when the
  // gateway last ran. The very next idle sweep re-presents or re-escalates them.
  const restored = loadObligations(OBLIGATION_STORE_PATH, obligationStoreFs)
  if (restored.length > 0) {
    obligationLedger.hydrate(restored)
    process.stderr.write(
      `telegram gateway: obligation-ledger hydrated ${restored.length} open obligation(s) from ${OBLIGATION_STORE_PATH}\n`,
    )
  }
} else if (isGatewayMain) removeUnmaintainedSnapshot(OBLIGATION_STORE_PATH, obligationStoreFs, `static=${STATIC} enabled=${OBLIGATION_LEDGER_ENABLED}`) // #4146: persistence is off, so a leftover snapshot must not read as "nobody is waiting" to the W1-d audience classifier (logic in obligation-store.ts)
// Origin ids with an escalation send IN FLIGHT — prevents the 5s sweep from
// firing a second concurrent send for the same obligation while the first is
// still awaiting (an escalation that takes >5s, or repeated failures).
const obligationEscalateInFlight = new Set<string>()

// #3282 — captured-answer resume driver (orchestration in the extracted module).
const capturedResume = createCapturedResumeDispatcher({
  deliverAnswer: (a) => deliverAnswer(a), obligationLedger, backstopDeliveryLedger,
  flushedTurnSupersede, historyEnabled: HISTORY_ENABLED,
})

// ─── Serialize-until-replied (multitopic reply-routing) ───────────────────
// Component 1 (deliver-before-drain gate). A buffered cross-topic inbound
// drains ONLY after the just-ended turn delivered its reply to its own
// thread — see `serialize-drain-gate.ts` for the full rationale (the
// Brevo→Meta wrong-topic bug). Kill switch off (=0) → legacy behaviour:
// drain on the bare turn-end signal.
const SERIALIZE_UNTIL_REPLIED_ENABLED =
  process.env.SWITCHROOM_SERIALIZE_UNTIL_REPLIED !== '0'
// #2917 rapid-fire per-chat FIFO note (#2996 P1): the legacy live-read +
// synchronous busy-key reservation (`SWITCHROOM_SERIALIZE_INBOUND_DELIVERY`)
// was deleted with the claudeBusyKeys set — under the delivery machine the
// inbound event advances the machine SYNCHRONOUSLY at the emit (idle→
// in_turn), so the machine itself is the pre-await reservation and a
// concurrent same-chat inbound observes it at its own receipt snapshot.
// Component 2 (bounded no-reply escape hatch). A turn that legitimately
// ends with NO reply (handback ack, NO_REPLY marker, silent-end) sets
// finalAnswerDelivered=false and would block the serialize gate forever.
// When such a turn ends with a buffered inbound waiting, arm a short
// bounded timer that force-drains regardless. The 300s silence-poke
// unwedge fallback remains the long-stop. Tunable for tests/forensics;
// clamped to a positive finite value (a degenerate override would either
// drain instantly — defeating serialization — or, if negative, be
// rejected). To disable the serialize feature entirely use
// SWITCHROOM_SERIALIZE_UNTIL_REPLIED=0, not a degenerate timeout.
const _noReplyDrainRaw = process.env.SWITCHROOM_SERIALIZE_NOREPLY_DRAIN_MS
const _noReplyDrainParsed =
  _noReplyDrainRaw != null && _noReplyDrainRaw !== '' ? Number(_noReplyDrainRaw) : 2_500
const SERIALIZE_NOREPLY_DRAIN_MS =
  Number.isFinite(_noReplyDrainParsed) && _noReplyDrainParsed > 0 ? _noReplyDrainParsed : 2_500
// Component 3 (turn-origin reply routing). Resolve an answer's thread from
// the turn that OWNS the reply (matched by origin_turn_id), not the live
// currentTurn if it has flipped. Kill switch off (=0) → legacy turn-pinned
// behaviour (#1664: thread from the live currentTurn capture).
const TURN_ORIGIN_ROUTING_ENABLED =
  process.env.SWITCHROOM_TURN_ORIGIN_ROUTING !== '0'
// Framework-owned origin recovery (2026-06-05 determinism pass). The origin
// signal that survives a currentTurn flip (tier 2) travels through the MODEL
// (it echoes `origin_turn_id`). When the model OMITS it, routing falls to the
// live turn — the wrong topic if currentTurn flipped (HOLE a). The model rarely
// passes `reply_to` explicitly, but WHEN it quotes a specific earlier message
// that message_id is a FRAMEWORK-owned anchor: reverse-index it to the turn
// that owns it and recover the origin without the model echo. Strictly
// additive — it only fires when the echo is absent AND a quote is present, and
// resolves to the ACTUAL origin turn (never the live successor), so it cannot
// mask a misroute. Kill switch off (=0) → echo-only origin (today's behaviour).
const FRAMEWORK_ORIGIN_ROUTING_ENABLED =
  process.env.SWITCHROOM_FRAMEWORK_ORIGIN_ROUTING !== '0'
// Reply-topic framework authority (2026-06-08 determinism pass). The topic an
// ANSWER lands in is owned by the TURN it answers (origin → live), NOT the
// model's `message_thread_id`. The model's explicit thread is demoted to a
// last resort (consulted only when there is no origin AND no live turn). Closes
// the model-chosen-topic override that sent a General-topic question's answer
// into the CRM topic (marko) — the model could redirect any reply. Kill switch
// off (=0) → legacy explicit-first precedence (the model's thread wins).
const REPLY_TOPIC_AUTHORITY_ENABLED =
  process.env.SWITCHROOM_REPLY_TOPIC_AUTHORITY !== '0'
// Component 4 (per-turn topic framing). Add a one-line directive to the
// channel meta + bridge instructions telling the model to answer ONLY the
// current message's topic. Kill switch off (=0) → no framing field.
const TOPIC_FRAMING_ENABLED =
  process.env.SWITCHROOM_TOPIC_FRAMING !== '0'
// Component 5 (queued-status UX). Post a self-updating "Queued — replying
// in <other topic> first" status into a cross-topic buffered message's own
// topic, then edit→delete it as the turn progresses. Kill switch off (=0)
// → no placeholder (the 👀 ack reaction still fires). Delete-on-answer.
const QUEUED_STATUS_UX_ENABLED =
  process.env.SWITCHROOM_QUEUED_STATUS_UX !== '0'
// #2995 mid-flight busy ack. When a mid-turn inbound is buffered (or lands
// as a steer) while the running turn sits inside ONE long tool call (step
// age past the threshold in busy-ack.ts), post a silent deterministic
// "⏳ Queued — currently inside `<tool>` …" card into the inbound's own
// chat/topic — model-free, zero tokens. Reuses the queuedStatusMsgIds
// edit/delete lifecycle (delete-on-answer, reap on abnormal turn-end),
// extending it to DMs and same-topic surfaces. At most one card per turn
// per chat/topic. Kill switch off (=0) → legacy silence (👀 only).
const MIDFLIGHT_BUSY_ACK_ENABLED =
  process.env.SWITCHROOM_MIDFLIGHT_BUSY_ACK !== '0'
// Feed-reopen-after-ack. When a tool label arrives for a turn already
// marked finalAnswerDelivered, the model is still WORKING — so the earlier
// "final" reply was an interim ACK (an ack-first reply pings or runs ≥200
// chars, both of which isFinalAnswerReply classifies as final). Re-open the
// live activity feed for the post-ack work instead of dropping the label.
// Kill switch off (=0) → legacy behaviour: the label is dropped and the
// post-ack feed stays dark. See `feed-reopen-gate.ts` for the rationale and
// the finalAnswerDelivered-consumer interactions.
const FEED_REOPEN_AFTER_ACK_ENABLED =
  process.env.SWITCHROOM_FEED_REOPEN_AFTER_ACK !== '0'
// Feed-reopen-after-SUBSTANTIVE. Distinct from the ack kill switch above: a
// turn that delivered a real answer EARLY and then kept doing tool work had
// its feed go dark for the rest of the turn. Lets the feed RE-OPEN after >=2
// post-answer labels WITHOUT clearing finalAnswerDelivered. Off (=0) → legacy.
// See `feed-reopen-gate.ts` for the full rationale.
const FEED_REOPEN_AFTER_SUBSTANTIVE_ENABLED =
  process.env.SWITCHROOM_FEED_REOPEN_AFTER_SUBSTANTIVE !== '0'

// Activity-feed heartbeat (PR1). The feed is pull-only — it only re-renders on
// a tool_label event, so a long single step that emits no new label leaves the
// feed frozen on "→ doing X" for tens of seconds (the marko ~26s freeze). The
// heartbeat re-renders the live feed every FEED_HEARTBEAT_TICK_MS with a
// climbing " · Ns" elapsed on the in-progress line, but only once the current
// step has run >= FEED_HEARTBEAT_MIN_STALE_MS (so a normally-advancing feed is
// untouched). Kill switch: SWITCHROOM_FEED_HEARTBEAT=0. Default on.
const FEED_HEARTBEAT_ENABLED = process.env.SWITCHROOM_FEED_HEARTBEAT !== '0'
const FEED_HEARTBEAT_TICK_MS = 6_000
const FEED_HEARTBEAT_MIN_STALE_MS = 6_000
// Liveness-driven feed open. The activity feed is otherwise TOOL-driven — it
// opens only when a tool emits a non-null label. A turn dominated by thinking
// or by suppressed-by-design tools (typing / memory recall / reply) emits no
// label, so the feed never opens and a long turn reads as pure silence until
// the 300s silence-poke (the #680 dark-turn). When a turn has been alive >=
// FEED_LIVENESS_OPEN_MS with no feed yet, open a minimal "Working…" feed so the
// user always has a live indicator; the first real tool label edits it with
// real content.
//
// Two callers reach the SAME open path (`openLivenessFeedIfDue`):
//   1. an enqueue-time one-shot timer (`scheduleEarlyLivenessOpen`) fires at
//      `FEED_LIVENESS_OPEN_MS` after turn start — this is the early-open that
//      kills the dead-air gap (narration emitted before the first tool now
//      surfaces ~`FEED_LIVENESS_OPEN_MS` after enqueue, not after a 6 s
//      heartbeat phase + the old 12 s threshold);
//   2. the 6 s heartbeat tick, which maintains/climbs the card and is the
//      backstop if the one-shot ever missed (e.g. a clock skew).
// The threshold dropped from 12 s → ~1.2 s so the "something is happening"
// signal lands within a second or two of the inbound, matching the JTBD
// `know-what-my-agent-is-doing` p95 ≤ ~1 s ambient-ack bar. Kill switch:
// SWITCHROOM_FEED_LIVENESS_OPEN=0. Default on.
const FEED_LIVENESS_OPEN_ENABLED = process.env.SWITCHROOM_FEED_LIVENESS_OPEN !== '0'
const FEED_LIVENESS_OPEN_MS = (() => {
  const raw = process.env.SWITCHROOM_FEED_LIVENESS_OPEN_MS
  const n = raw ? Number(raw) : NaN
  return Number.isFinite(n) && n > 0 ? n : 1_200
})()

// Post-answer background-agent liveness STALENESS CAP (Fix 2 / #2587 supersede,
// concern 3). The `feedHeartbeatTick` post-answer branch re-renders a "background
// agent still working" card every FEED_HEARTBEAT_TICK_MS while the sub-agent
// watcher keeps advancing `turn.subagentActivityAt`. Without a cap that card kept
// emitting `state:'running'` with an ever-climbing `elapsed` FOREVER — even after
// the worker's `onFinish` froze the timestamp — because (unlike the pre-answer
// path's `FEED_LIVENESS_OPEN_MS` recency cap) the post-answer branch had no
// staleness bound. This cap mirrors that pre-answer pattern: once the worker's
// last advance is older than the cap, the heartbeat stops re-rendering and the
// card freezes at its last state. Parsed via the same pure `parsePostAnswerLivenessMs`
// helper (positive int or 0); `|| 30_000` supplies a default-ON 30s cap, so an
// unset env keeps the cap active. Override with SWITCHROOM_POST_ANSWER_LIVENESS_STALE_MS.
const POST_ANSWER_LIVENESS_STALE_MS = parsePostAnswerLivenessMs(
  process.env.SWITCHROOM_POST_ANSWER_LIVENESS_STALE_MS,
) || 30_000

// Live-feed step suffixes render via `formatStepSuffix` (tool-activity-summary):
// the CURRENT step's own elapsed, shown only past STEP_TIMER_MIN_MS (10 s).

/**
 * Authoritative "is a turn in flight?" for every fleet-wide gate. The
 * delivery state machine's single-`activeTurn` global state is the sole
 * authority (#2794 cutover, kill switch + legacy `claudeBusyKeys` shadow
 * deleted in #2996 P1) — unlike a per-delivery key set it cannot
 * accumulate orphan keys and wedge the gate "in-flight forever" (the
 * gymbro/clerk 5-min dangle, 2026-05-28).
 *
 * NOT for the inbound-receipt gate: that must snapshot the
 * machine state BEFORE the inbound event advances it, or a fresh-turn
 * message self-blocks. See the snapshot at the inbound handler.
 */
function turnInFlightForGate(): boolean {
  // Include pendingPermissions in the "turn busy" signal (#2841): after the
  // first interim reply, `releaseTurnBufferGate` clears the machine turn
  // even though a permission card is still outstanding and claude is still
  // blocked mid-turn waiting for the tap verdict. A new inbound that arrives
  // in this window would see turnInFlightAtReceipt=false and deliver directly,
  // landing while claude's bridge is suspended in the permission-notification
  // handler — displacing the approval and orphaning the pending brevo/MCP call.
  // Keeping the gate closed for as long as there is an outstanding approval
  // card prevents that race. The gate reopens when the card is tapped or times
  // out (pendingPermissions.delete in finalizeCallback / TTL sweep).
  //
  // #3084 follow-up — ONE case now has no timeout valve: an approval HELD
  // because its card could not be DELIVERED (a Telegram flood ban) never
  // expires, by design. The leash may not fabricate a verdict for an ask no
  // human ever saw, so the entry — and therefore this gate — persists until a
  // human answers. An agent can consequently buffer normal inbound for the
  // duration of a channel outage. That is the intended trade: a buffered
  // message is recoverable, a silently auto-denied approval is not. The escape
  // hatches are unaffected — /allow, /deny and /pending are grammy command
  // handlers and do not sit behind this gate — and the block is surfaced
  // off-Telegram in blocked-approvals/<agent>.json.
  const hasPendingApproval = pendingPermissions.size > 0
  // The shared inbound gate stays STRICT: unconditionally busy whenever an
  // approval card is outstanding (#2841 — a new inbound in that window would
  // displace the approval context and orphan the pending MCP call). Only the
  // machine-in-turn leg is factored out (`turnInFlightMachineOnly`); the
  // `|| hasPendingApproval` composition here is what preserves the contract.
  return turnInFlightMachineOnly() || hasPendingApproval
}

/**
 * The machine-in-turn portion of the gate WITHOUT the `pendingPermissions`
 * hold — "claude is actively producing a turn right now", ignoring an
 * outstanding approval card. `turnInFlightForGate()` = this OR a pending
 * approval, so the shared inbound-hold contract (#2841) is unchanged.
 *
 * Factored out so the `/model` & `/effort` busy decision can read THIS
 * machine-only leg (plus a TTL-bounded approval check in
 * `resolveModelEffortBusy`) — a wedged / undeliverable approval that "never
 * expires by design" (#3084) must not hold their switch queued forever on an
 * idle session (#3262), even though it correctly holds the general inbound gate.
 */
function turnInFlightMachineOnly(): boolean {
  // The machine is the sole authority (#2996 P1): the legacy claudeBusyKeys
  // read, the kill-switch branch, and the gate-parity drift canary were
  // deleted once the #3012 cutover baked — see gate-parity-probe.ts history
  // for the bake-era drift classification.
  return isMachineInTurn()
}

/**
 * Age (ms) of the live turn for the phantom-turn cross-check (#3262): the
 * turn-active liveness marker's mtime age (touched on every foreground
 * tool_use AND on sub-agent JSONL growth, so a genuinely long turn keeps it
 * small), falling back to `now - turn.startedAt` when the marker is absent
 * (e.g. already swept). Null when no turn atom is set. A large age on a
 * non-null atom is the dangling-atom signal.
 */
function liveTurnAgeMs(now: number): number | null {
  if (currentTurn === null) return null
  return effectiveTurnAgeMs(readTurnActiveMarkerAgeMs(STATE_DIR, now), currentTurn.startedAt, now)
}

/** Age (ms) of the OLDEST outstanding pending approval, or null when none. */
function oldestPendingApprovalAgeMs(now: number): number | null {
  let oldest: number | null = null
  for (const p of pendingPermissions.values()) {
    const age = now - p.startedAt
    if (oldest === null || age > oldest) oldest = age
  }
  return oldest
}

/**
 * Resolve the apply-vs-queue busy signals for a `/model` or `/effort` command,
 * sweeping a stale (dangling) turn atom and discounting a wedged (undeliverable)
 * approval hold — both bounded by the SAME `TURN_ACTIVE_HARD_TTL_MS` ceiling the
 * marker sweep uses (#3262). A genuinely in-flight turn (fresh marker) and a
 * recent pending approval still read busy, so the #3017/#3039 apply-or-queue
 * contract and #3177/#3180 are preserved. Clears the dangling atom as a side
 * effect so the phantom can't re-block the next command.
 */
function resolveModelEffortBusy(now = Date.now()): { currentTurnActive: boolean; turnInFlight: boolean } {
  const turnAgeMs = liveTurnAgeMs(now)
  const resolved = resolveStaleAwareBusy({
    currentTurnActive: currentTurn !== null,
    turnAgeMs,
    machineInTurn: turnInFlightMachineOnly(),
    oldestPendingApprovalAgeMs: oldestPendingApprovalAgeMs(now),
    hardTtlMs: TURN_ACTIVE_HARD_TTL_MS,
  })
  if (resolved.clearStaleTurn && currentTurn !== null) {
    const ageSec = Math.round((turnAgeMs ?? 0) / 1000)
    process.stderr.write(
      `telegram gateway: [phantomturn] cleared stale currentTurn atom age=${ageSec}s ` +
      `ttl=${Math.round(TURN_ACTIVE_HARD_TTL_MS / 1000)}s for /model|/effort busy-check agent=${getMyAgentName()}\n`,
    )
    // Single-tenant / sequential-CLI invariant: the singleton `currentTurn` IS
    // the only live turn, and a stale atom is a ghost (its `turn_end` never
    // fired) — clearing every entry is equivalent to clearing it, matching the
    // bridge-died "every entry is a ghost" semantics.
    // PR-E (M1): under the v2 funnel this is the named 'phantom-ttl-clear'
    // reason — atom-clear ONLY (no purge / obligation close / drain).
    if (TURN_END_FUNNEL_V2) turnEndFunnel().endTurn('phantom-ttl-clear')
    else clearAllCurrentTurns()
  }
  return { currentTurnActive: resolved.currentTurnActive, turnInFlight: resolved.turnInFlight }
}

/**
 * Deliver a synthetic "resume" inbound — the wake-up the gateway sends
 * after an operator approves/denies a vault grant, provides/declines a
 * requested secret, or completes/fails/discards a vault save — turn-gated
 * exactly like a real Telegram inbound.
 *
 * THE BUG (clerk `hotdoc/credentials`, 2026-06-13): these synthetics did a
 * raw `ipcServer.sendToAgent` and buffered ONLY on `delivered=false`
 * (bridge disconnected). But approvals routinely land WHILE the agent's
 * grant-requesting turn is still finishing — the socket write succeeds
 * (`delivered=true`) yet claude is mid-turn, so the channel notification
 * is typed into its TUI composer and stranded by the turn-completion race
 * (#1556, the lawgpt wedge). `delivered=true` → the buffer never rescued
 * it → the agent sat idle until the operator manually poked it. Observed:
 * injection 179ms BEFORE turn_end, then 2 minutes of silence.
 *
 * Fix: route through the SAME `decideInboundDelivery` gate the Telegram
 * `handleInbound` path uses. Mid-turn → `buffer-until-idle` (the
 * turn-complete hook `releaseTurnBufferGate → drainBufferedIfAllowed`,
 * plus the idle-drain timer, flush it the instant claude goes idle, where
 * it lands cleanly as a fresh turn). Idle → deliver now; buffer on a
 * genuine delivery miss exactly as before. Unlike the cron `inject_inbound`
 * path (deliberately ungated — at-least-once replay), a one-shot resume
 * synthetic must never strand, so it IS gated.
 *
 * Returns true iff delivered to the bridge now (false = buffered/held;
 * the caller's forensic log records this as `delivered=false`, which now
 * means "held mid-turn OR bridge-down" — both are "will flush when idle",
 * never "dropped").
 */
function deliverResumeSyntheticOrBuffer(agent: string, inbound: InboundMessage): boolean {
  const decision = decideInboundDelivery({
    turnInFlight: turnInFlightForGate(),
    isSteering: false,
    isInterrupt: false,
  })
  if (decision === 'buffer-until-idle') {
    pendingInboundBuffer.push(agent, inbound)
    return false
  }
  const delivered = ipcServer.sendToAgent(agent, inbound)
  if (!delivered) pendingInboundBuffer.push(agent, inbound)
  return delivered
}

/** Outcome of routing an agent-authored button tap through the turn-safe
 *  delivery machinery. `buffered-mid-turn` and `delivered` both mean "the tap
 *  will be actioned" (the mid-turn case flushes on turn-complete); only
 *  `buffered-bridge-offline` needs the user-facing "agent is restarting" notice. */
type ButtonTapDeliveryOutcome = 'delivered' | 'buffered-mid-turn' | 'buffered-bridge-offline'

/**
 * Deliver an agent-authored inline-keyboard button tap (`agent:` callback_data)
 * through the SAME turn-safe machinery as a normal Telegram inbound, instead of
 * the old raw `sendToAgent` + buffer-only-on-bridge-miss.
 *
 * THE BUG (#271 button path, verified 2026-07): the `agent:` callback handler
 * delivered the synthesized tap inbound with a bare `ipcServer.sendToAgent`,
 * marked busy, and buffered ONLY when the bridge was offline. It never ran the
 * #1556 turn gate — so a tap landing WHILE a turn is in flight fired the MCP
 * channel notification mid-turn, typed into the CLI composer, and stranded there
 * (the lawgpt/marko wedge). It also skipped the pre-send composer clear and the
 * deliver-until-acked tracking, so a stranded tap was never sweep-redelivered.
 *
 * Fix: reuse the resume-synthetic turn gate (mid-turn → `buffer-until-idle`, the
 * turn-complete hook + idle-drain flush it the instant claude goes idle), the
 * pre-send composer clear, and the delivery-confirm tracking — exactly like the
 * `handleInbound` fresh-turn path. A button tap carries no `meta.source` and a
 * non-empty body, so `shouldTrackDelivery` enrols it; we additionally require a
 * real `meta.message_id` so the `enqueue` ack has something to match (else the
 * never-drop sweep would storm). The tap UX is unchanged — the ack toast, the
 * single-use keyboard strip, and the bridge-offline spool + restart notice all
 * stay at the call site; only delivery timing/safety changes.
 */
async function deliverButtonTapInbound(
  agent: string,
  inbound: InboundMessage,
): Promise<ButtonTapDeliveryOutcome> {
  // #1556 turn gate — same authoritative "is a turn in flight?" read the
  // resume-synthetic path uses. Mid-turn → hold in the pending-inbound buffer;
  // the turn-complete hook + idle-drain timer flush it when claude goes idle,
  // where it lands cleanly as a fresh turn instead of stranding in the composer.
  const { decision } = reserveInboundDelivery({
    turnInFlight: turnInFlightForGate(),
    isSteering: false,
    isInterrupt: false,
  })
  if (decision === 'buffer-until-idle') {
    pendingInboundBuffer.push(agent, inbound)
    return 'buffered-mid-turn'
  }
  // Pre-send composer clear (the marko wedge) — wipe stale typed-ahead / ghost
  // text so the channel notification lands at a clean line and auto-submits.
  // Soft-fail by contract: a clear failure must NEVER block delivery.
  if (agent) {
    try {
      const { clearAgentComposer } = await import('../../src/agents/tmux.js')
      const cleared = clearAgentComposer({ agentName: agent })
      if ('error' in cleared) {
        process.stderr.write(
          `telegram gateway: button-tap pre-send composer-clear soft-failed agent=${agent}: ${cleared.error} — delivering anyway\n`,
        )
      }
    } catch (err) {
      process.stderr.write(
        `telegram gateway: button-tap pre-send composer-clear threw agent=${agent}: ${(err as Error).message} — delivering anyway\n`,
      )
    }
  }
  const delivered = ipcServer.sendToAgent(agent, inbound)
  if (delivered) {
    const busyKey = chatKeyForInbound(inbound)
    // Track until claude acks via `enqueue` so the deliver-until-acked sweep
    // re-delivers a tap stranded in the composer. Only when we have a real
    // message_id to match the ack against — otherwise the never-drop loop storms.
    if (
      DELIVERY_CONFIRM_ENABLED &&
      inbound.meta?.message_id != null &&
      inbound.meta.message_id !== '' &&
      shouldTrackDelivery({
        isSteering: false,
        isInterrupt: false,
        hasSource: inbound.meta?.source != null,
        effectiveText: inbound.text,
      })
    ) {
      trackDelivery(deliveryQueue, busyKey, inbound, Date.now(), String(inbound.messageId))
    }
    return 'delivered'
  }
  // Bridge offline: spool the tap so it replays on reconnect — same
  // behaviour as before this fix.
  pendingInboundBuffer.push(agent, inbound)
  return 'buffered-bridge-offline'
}

const pendingRestarts = new Map<string, number>()  // agentName -> timestamp when restart was requested

// Deterministic ack-queue-apply-confirm for /model + /effort issued mid-turn
// (#3017). One slot per kind (model|effort): same-kind last-write-wins,
// cross-kind coexist (#3018 finding 2). Enqueued at the busy gates (typed
// and menu), drained at the SAME model-idle gate as pendingRestarts (turn
// complete + the reaper cap), which then EDITS the ack card into the
// confirmation. See pending-session-command.ts for the contract.
const pendingSessionCommand = createPendingSessionCommandSlots()
// Bounded drain-cap for a queued /model|/effort command whose session never
// cleanly idles — mirrors PENDING_RESTART_DRAIN_CAP_MS. After this, force the
// apply-or-report so the ack card never dangles unresolved — but ONLY while
// no turn is in flight (#3018 finding 1; see drainCapDecision).
const PENDING_CMD_DRAIN_CAP_MS = 60_000

// ─── Proactive context compaction (session.max_context_tokens) ──────────
//
// Opt-in: when the resolved agent config sets session.max_context_tokens,
// we fire `/compact` once the live context-window occupancy of the latest
// assistant turn reaches that many tokens. Evaluated ONLY at the
// model-idle gate inside purgeReactionTracking (activeTurnStartedAt.size
// === 0) — never mid-turn — mirroring the pendingRestarts drain. The
// `/compact` verb is allowlisted in src/agents/inject.ts and runs via the
// tmux send-keys path (the only path that actually executes the slash
// command; inject_inbound would deliver it as literal text).
//
// `lastSessionActiveFile` is the session-tail's tracked currentFile,
// forwarded by the bridge on every session_event — we read occupancy from
// exactly that file (never an independent findActiveSessionFile re-scan).
let lastSessionActiveFile: string | null = null
// Crash-survival redelivery (#session-id pin): the last turn_key whose
// `session_id` we durably stamped, so the hot session-event path stamps once
// per turn instead of issuing a guarded UPDATE on every event.
let lastSessionStampedTurnKey: string | null = null
// Anti-spam state machine lives in ./proactive-compact (pure, unit
// tested). `compactDispatching` is a synchronous re-entrancy guard for
// the async tmux send — purgeReactionTracking can run several times per
// turn and we must not double-dispatch before the first send settles.
let compactState: CompactState = initialCompactState()
let compactDispatching = false

// User-facing proactive-compaction notification (single Telegram card
// edited START → FINISH; transition selection is pure in
// ./compact-notify). Session reset/rotation stays silent — not here.
// The wall-clock timer is owned HERE (not the pure helper): an idle
// agent produces no idle evaluations, so a card that never gets a
// re-arm edge must be resolved by a real timer, independent of the
// eval loop, or it would dangle forever.
const COMPACT_CARD_TIMEOUT_MS = 15 * 60 * 1000
interface OutstandingCompactCard {
  chatId: string
  threadId: number | undefined
  messageId: number
  occAtStart: number
  capAtStart: number
  timer: ReturnType<typeof setTimeout>
}
let compactNotifyState: CompactNotifyState = idleCompactNotifyState()
let outstandingCompactCard: OutstandingCompactCard | null = null
const activeDraftStreams = new Map<string, DraftStreamHandle>()
const suppressPtyPreview = new Set<string>()
const lastPtyPreviewByChat = new Map<string, string>()
const progressUpdateLastSent = new Map<string, number>()
const progressUpdateTurnCount = new Map<string, number>()

// Pre-allocated placeholder drafts (issue #416) and the associated
// heartbeat / phase enrichment were removed in #553 PR 5. Real-text +
// 👀 status reaction (#568) + sendChatAction('typing') indicator
// (#585) replace the visual gap that the placeholder used to fill.
// recall.py's update_placeholder IPC calls now no-op cleanly because
// the gateway no longer registers an onUpdatePlaceholder handler.

/**
 * Per-turn singletons consolidated into one atom (#1067).
 *
 * Pre-#1067, this was 13 module-level `let`s (currentSessionChatId,
 * currentTurnStartedAt, currentSessionThreadId, currentTurnReplyCalled,
 * currentTurnCapturedText, orphanedReplyTimeoutId, currentTurnRegistryKey,
 * currentTurnLastAssistantMsgId, currentTurnLastAssistantDone,
 * currentTurnToolCallCount, activeAnswerStream, currentTurnIsDm,
 * currentTurnGatewayReceiveAt). Every async session-event handler read
 * those singletons directly — so a handler that captured a value,
 * awaited, and resumed could see the next turn's state instead of its
 * own. Concretely: tool_use for chat A could route its visible effect
 * (status reaction, progress card mutation, answer-stream update) to
 * chat B if an `enqueue` for B landed during the handler's await.
 *
 * The fix: a single mutable atom that `enqueue` swaps wholesale and
 * `turn_end` nulls. Every handler captures `const turn = currentTurn`
 * at entry — closures and async continuations use that snapshot for
 * the rest of the handler, so a mid-handler enqueue can't reattribute.
 *
 * Field-name mapping (old → new):
 *   currentSessionChatId            → turn.sessionChatId
 *   currentSessionThreadId          → turn.sessionThreadId
 *   currentTurnStartedAt            → turn.startedAt
 *   currentTurnGatewayReceiveAt     → turn.gatewayReceiveAt
 *   currentTurnReplyCalled          → turn.replyCalled
 *   currentTurnCapturedText         → turn.capturedText
 *   orphanedReplyTimeoutId          → turn.orphanedReplyTimeoutId
 *   currentTurnRegistryKey          → turn.registryKey
 *   currentTurnLastAssistantMsgId   → turn.lastAssistantMsgId
 *   currentTurnLastAssistantDone    → turn.lastAssistantDone
 *   currentTurnToolCallCount        → turn.toolCallCount
 *   activeAnswerStream              → turn.answerStream
 *   currentTurnIsDm                 → turn.isDm
 */
export type CurrentTurn = {
  sessionChatId: string
  sessionThreadId: number | undefined
  // Inbound message id this turn answers. Anchors the activity feed's
  // native reply-quote (reply_parameters) so the user's question renders
  // as a quoted header on the feed message. Null for synthesized turns
  // (cron/handback) that have no originating inbound message.
  sourceMessageId: number | null
  startedAt: number
  gatewayReceiveAt: number
  // #2527 — the single turn-provenance discriminator, stamped once at
  // enqueue from the channel envelope `source`. `user` (a human is waiting:
  // never-silent guarantee + mid-turn floor), `system` (cron/scheduled:
  // silence is legitimate). The gateway never builds a turn atom for a
  // sub-agent, so `sub-agent` never appears here. Read by the mid-turn floor
  // eligibility and the role-aware terminal reaction gate. Replaces the
  // scattered `chatType`/`chatId==null`/`source==='cron'` predicates.
  role: LoopRole
  // PR1 (cross-turn stale-card guard, design `docs/message-emission-determinism.md`
  // §9 lever 4 / race C/D). Present ONLY when this turn is a cross-turn SYNTHETIC
  // surface whose card OPEN must be gated against an answer already delivered in
  // an EARLIER turn — i.e. an `obligation_represent` re-delivery (and the
  // liveness/heartbeat timer firing on it). `sinceMs` is the obligation's
  // `openedAt` — the moment the obligation was RAISED — so the card-OPEN gate
  // asks `hasOutboundDeliveredSince(chat, openedAt)`: did a substantive answer
  // already land since then? Stamped at the turn ctor from a pending marker that
  // `obligationSweep` writes when it pushes the represent inbound (see
  // `pendingCrossTurnGate`). `undefined` for a normal foreground turn → the
  // cross-turn lever-4 gate is inert there (the foreground turn's own card is
  // governed only by the per-turn `finalAnswerEverDelivered` latch, lever 1).
  crossTurnGate?: { sinceMs: number }
  replyCalled: boolean
  // #1664 — whether the model has delivered its *final answer* this turn
  // (as opposed to only an interim ack). `replyCalled` flips on the first
  // reply / stream_reply tool_use and stays true for the rest of the turn,
  // so it cannot tell "ack only" from "ack + real answer". This flag is the
  // finer signal the silent-end re-prompt needs: it is set only when a reply
  // actually lands AND `isFinalAnswerReply` (final-answer-detect.ts)
  // classifies it as the final answer — notification-bearing, or long
  // enough to be substantive, or a stream_reply done=true — OR when the
  // turn-flush safety net legitimately emits the model's terminal text. A
  // turn that ends with this still `false` triggers the silent-end re-prompt
  // even though `replyCalled` is true — the #1664 case where the real answer
  // ended up as plain transcript text rendered into an ephemeral draft.
  finalAnswerDelivered: boolean
  // PR B (send-honesty). The REAL fate of a backstop (turn-flush) send,
  // stamped only AFTER the async send resolves inside the IIFE — success →
  // 'delivered', throw/partial → 'failed', reply-tool-already-sent
  // short-circuit → 'suppressed'. `emitTurnRecord` derives the recorded
  // status from THIS (via `computeTurnStatus`) rather than the speculative
  // `finalAnswerDelivered` flag, so a flood-dropped answer is logged
  // `send_failed` instead of a false `complete`. Undefined on the synchronous
  // turn-end paths (reply-tool tail, silent-marker, genuine no-reply), where
  // the legacy `finalAnswerDelivered` reading still applies unchanged.
  deliveryOutcome?: DeliveryOutcome
  landedUnconfirmed?: number // #3702 — landed ids no read-back corroborated; emitted as `landed_unconfirmed` (rationale: turn-record-status.ts)
  // Feed-reopen-after-ack refinement — whether the reply that set
  // `finalAnswerDelivered` was a *substantive* final answer (stream
  // `done`, or ≥200 chars) as opposed to a short pinging interim ACK.
  // Set via `isSubstantiveFinalReply` at every site that sets
  // `finalAnswerDelivered = true`. The tool_label handler re-opens the
  // live activity feed ONLY when `finalAnswerDelivered && !finalAnswer-
  // Substantive` (the prior "final" was an ack). After a genuine final
  // answer this stays true, so routine post-answer housekeeping (memory
  // write / TodoWrite / Bash — non-surface tools that reach the handler)
  // does NOT reopen and does NOT reset `finalAnswerDelivered`, which would
  // otherwise spuriously trip the silent-end re-prompt → duplicate answer.
  // Reset to false on every fresh-turn enqueue alongside
  // `finalAnswerDelivered`.
  finalAnswerSubstantive: boolean
  // Post-SUBSTANTIVE feed-reopen counter — incremented on each tool label that
  // arrives while `finalAnswerDelivered && finalAnswerSubstantive` (a real
  // answer landed early, model still working). At `SUBSTANTIVE_REOPEN_MIN_LABELS`
  // (>=2) the tool_label handler reopens the feed (see `feed-reopen-gate.ts`).
  // Reset to 0 on every fresh-turn enqueue.
  postSubstantiveToolLabelCount: number
  // Post-SUBSTANTIVE feed-reopen lever-1 lift latch. Set true by the tool_label
  // handler when the long-turn reopen fires (>=2 post-answer labels). The drain
  // reads it as `mayOpenActivityCard`'s `postAnswerMainActivity` so the fresh
  // card may OPEN below the already-delivered reply despite the sticky lever-1
  // latch. Sticky for the rest of the turn; reset to false on fresh-turn enqueue.
  postAnswerMainActivity: boolean
  // Sticky "a substantive final answer has been delivered this turn" latch
  // (design `docs/message-emission-determinism.md` §9 preamble / R0). Distinct
  // from the MUTABLE `finalAnswerDelivered`, which the ack-reopen path clears
  // mid-turn (`feed-reopen-gate.ts:157`) so an "On it…" ack keeps a live feed
  // (#2141). Ordering gates (the no-OPEN-after-final card gate, lever 1) MUST
  // key on this sticky latch, not the mutable flag — keying on the mutable flag
  // is a no-op on exactly the ack-first turn where the reorder originates. Set
  // true ONLY at the points that set `finalAnswerDelivered = true` AND only when
  // the reply is `isSubstantiveFinalReply`; NEVER cleared by reopen. Reset to
  // false ONLY at turn start, mirroring `activityEverOpened`'s sticky-true
  // contract.
  finalAnswerEverDelivered: boolean
  // 2026-07 double-reply-on-DM fix (Part 2 — race backstop), SOURCE-TAGGED
  // since #3426. Set to 'flush' SYNCHRONOUSLY at turn-flush FIRE time (before
  // the ~500 ms async send and before `flushedTurnSupersede.record`) and at
  // supersede-record consumption (the resurrection window); set to 'reply'
  // when a substantive `reply` sends. It persists on the ended turn in
  // `recentTurnsById`, so a LATE reply landing in the flush's post-fire
  // pre-record race window (where `flushedTurnSupersede` finds no record to
  // delete yet) resolves this turn via the unified owner resolver, sees the
  // 'flush' latch already set, and suppresses itself — closing the residual
  // window Part 1's supersede cannot reach. The 'reply' tag deliberately does
  // NOT suppress a late reply (#3426): a substantive interim ack followed by
  // an async sub-agent handback (which lands with NO live gateway turn and
  // resolves this ended turn as owner via the latest-ended tier) must deliver,
  // not silently drop. Scoped to the substantive floor so an interim sub-floor
  // ack NEITHER sets nor trips it. Reset false at turn start.
  answerDelivered: AnswerDeliveredLatch
  // #3429 — the text the turn-flush backstop delivered (or is mid-delivering)
  // as this turn's answer. Stamped SYNCHRONOUSLY alongside the 'flush' latch
  // arm (stream-render fire site; outbound-send-path supersede-consumption
  // resurrection site) and cleared wherever that latch is reset. Lets the
  // late-reply suppression discriminate BY CONTENT between the flushed answer
  // landing again (suppress — the flush race) and a genuinely new async
  // handback attributed to this flush-delivered ended turn (deliver fresh —
  // suppressing/editing it is the #3429 silent client-side drop), including in
  // the post-fire pre-record window where no supersede record exists yet.
  // Null when no flush armed this turn. Reset null at turn start.
  flushedAnswerText: string | null
  // 2026-07 double-reply-on-DM fix (F2 — recency bound). Wall-clock ms the turn
  // ENDED (stamped once by `endCurrentTurnAtomic`), or null while still live.
  // The `latest-ended` supersede tier carries DESTRUCTIVE authority (it drives
  // message deletion), so `resolveReplyOwnerTurn` only honours a latest-ended
  // turn whose `endedAt` is non-null (#3725 — the registry is populated at turn
  // START, so the tail entry may still be RUNNING) AND within the
  // turn-completion window (#4173) — otherwise a late reply belonging to an
  // OLDER turn could resolve its owner to a NEWER turn at the registry tail and
  // delete that turn's legit answer. The unbounded ROUTING use
  // (`endedOnly: false`) is unaffected: it only picks a topic to deliver into
  // and deletes nothing.
  endedAt: number | null
  // #4173 — the turn-completion signal: ms the SESSION's real stop was
  // observed, or null while the window is OPEN (a flush-ended turn still
  // composing). Stamped in turn-end.ts / closed by stream-render's hooks;
  // full three-phase model in flushed-turn-supersede.ts.
  realEndObservedAt: number | null
  // #1675 (over-ping safety net): wall-clock ms of the first reply
  // this turn that landed with `disable_notification: false` (a real
  // device ping). The conversational-pacing contract
  // (`reference/rfcs/conversational-pacing.md` beat 5) says EXACTLY ONE
  // ping per turn — the final answer. When the model violates that
  // (sends a substantive answer pinged + a wrap-up "Delivered…" or
  // meta-narration also pinged), subsequent reply calls with
  // `disable_notification: false` are auto-downgraded to silent by
  // the framework. Null until the first ping lands. Reset on every
  // fresh-turn enqueue.
  firstPingAt: number | null
  // Notification ownership (R8 / PR-2 — design `docs/message-emission-
  // determinism.md` §over-ping). Whether the send that CLAIMED this turn's
  // ping slot (`firstPingAt`) was itself a *substantive* final answer
  // (`isSubstantiveFinalReply`) as opposed to a short interim ACK. The
  // over-ping safety net keys on this so a substantive answer pinging AFTER
  // an ack already pinged is UPGRADED (let through, owns the slot) rather
  // than silenced — otherwise "the reply is last but the phone never buzzed
  // for the answer." Set ATOMICALLY with `firstPingAt` (same synchronous
  // block, no await between) on a claim/upgrade so a racing second reply
  // reads a consistent pair. Init false; reset to false on every fresh-turn
  // enqueue alongside `firstPingAt`.
  firstPingWasSubstantive: boolean
  // #1677 silent-reply auto-edit. The first silent reply of a turn
  // captures `silentAnchorMessageId` + `silentAnchorText`; subsequent
  // silent replies in the SAME turn editMessageText that anchor
  // (appending with paragraph-break separator). Net visual: one
  // growing silent bubble instead of N stacked silent bubbles.
  // Cleared by turn-atom replacement on enqueue. See
  // `telegram-plugin/silent-reply-anchor.ts` for the pure
  // `decideSilentReplyAnchor` predicate.
  silentAnchorMessageId: number | null
  silentAnchorText: string
  capturedText: string[]
  // #3237 — per-block structural provenance, pushed in LOCKSTEP with
  // `capturedText` at the `case 'text'` accumulation site (stream-render.ts).
  // `capturedBlockMeta[i] === true` ⇒ a tool_use followed `capturedText[i]` in
  // its assistant message (`!ev.lastInMessage`), i.e. the model drafted then
  // acted — the deterministic narration signal the flush strip uses to avoid
  // truncating a real answer that merely opens with "Let me explain…".
  capturedBlockMeta: boolean[]
  orphanedReplyTimeoutId: ReturnType<typeof setTimeout> | null
  // PR A — answer-ready quiescence flush timer. Armed in `case 'text'` once the
  // turn has a genuine composed terminal answer and is quiescent; fires a
  // positive `answer-ready-quiescence` synthetic turn_end after the ~1 s
  // debounce so the answer is delivered deterministically instead of waiting on
  // the unreliable turn_duration signal or the ~150 s orphaned-reply backstop.
  // Cleared on any tool activity, on `endCurrentTurnAtomic`, and re-armed on
  // each subsequent text chunk (the debounce).
  answerReadyFlushTimeoutId: ReturnType<typeof setTimeout> | null
  // Per-turn liveness tracker for the orphaned-reply backstop. Owns
  // `lastStreamEventAt` (stamped on ANY genuine stream event so a model
  // reasoning pause keeps the turn "recently streaming" and re-arms the fuse
  // instead of firing) and the rearm counter (bounded by
  // ORPHANED_REPLY_MAX_REARMS so a genuinely wedged single tool that never
  // streams still surfaces after the cap). The counter is zeroed on every
  // genuine stream event, so the cap only bites CONSECUTIVE silent expiries.
  // Fresh instance per enqueue (below). See context-exhaustion.ts.
  liveness: LivenessTracker
  // Component 3 (turn-origin reply routing). A stable per-turn identity,
  // `${registryKey-or-chatKey}#${startedAt}`, assigned when the turn
  // starts and stamped into the inbound meta (`origin_turn_id`) so a reply
  // can be matched back to the turn that OWNS it — even after `currentTurn`
  // has flipped to a successor. Recently-ended turns are retained in
  // `recentTurnsById` so a late reply (the Brevo answer landing 42s after
  // turn-end, when currentTurn already points at Meta) routes to its
  // origin thread instead of the live (wrong) turn's thread.
  turnId: string
  registryKey: string | null
  // Component 2 (bounded no-reply escape hatch). When a turn ends with
  // finalAnswerDelivered=false AND a buffered cross-topic inbound is
  // waiting, this timer force-drains after SERIALIZE_NOREPLY_DRAIN_MS so
  // the queue can never wedge on a legitimately silent turn. Armed in
  // `endCurrentTurnAtomic`, cleared if the turn delivers first.
  noReplyDrainTimer: ReturnType<typeof setTimeout> | null
  // Last assistant outbound message id for the current turn — populated
  // on reply / stream_reply emit, captured into recordTurnEnd. Stage 4
  // reads this on resume to thread-jump back to the in-flight conversation.
  lastAssistantMsgId: string | null
  // Whether the current turn produced a stream_reply with done=true. The
  // resume protocol uses this to decide "did the previous turn actually
  // finish a reply, or was it interrupted before commit?".
  lastAssistantDone: boolean
  // Live model in use for THIS turn, sourced from the main transcript's
  // `message.model` (the exact resolved model per API call) via the session-tail
  // `model` event — never from config or launch-time state. Updated on change;
  // undefined until the turn's first assistant line lands. Rendered onto the
  // activity/liveness card header's metrics line (e.g. "2m · 14 tools · opus 4.8")
  // and preferred by /status's buildAgentMetadata over the in-memory override.
  currentModel?: string
  // Phase 1 of #332: count of tool_use events in the current turn, for
  // the tool_call_count column in the turns registry.
  toolCallCount: number
  // Count of tool_label events that passed the isTelegramSurfaceTool guard
  // this turn — the deterministic, surface-tool-excluded step count used by
  // the `✓ N steps` activity-feed total and the `tools=` lifecycle log.
  // Incremented in `case 'tool_label':` AFTER the surface-tool guard so
  // reply/stream_reply/edit_message/react are never counted. send_typing and
  // sync_retain are suppressed at the hook (computeLabel returns null) and
  // never arrive as tool_label events — excluded automatically.
  labeledToolCount: number
  // Running total of the PARENT agent's OWN token usage this turn, summed from
  // the main-tier session-tail `usage` events (input + output + cache_creation
  // per assistant message, via sumUsageTokens; cache_read is excluded —
  // replayed cached context, not new work). Rendered on the
  // 🤖 turn-activity card's metrics line (`… · N tok · model`). This is the
  // parent alone — sub-agent tokens are NOT folded in here (they report on
  // their own worker-feed rows; summing them would double-count). 0 until the
  // turn's first assistant line carries a usage block.
  totalTokens: number
  // Dedup guard for `totalTokens`: Claude Code persists one logical assistant
  // message as MULTIPLE JSONL lines sharing one `message.id`, each stamped with
  // the SAME `usage` block. We fold a given `message.id` exactly once (same
  // idempotency as the sub-agent watcher's `seenUsageMessageIds`). A null/absent
  // messageId is un-dedupable and always counted.
  seenUsageMessageIds: Set<string>
  // Tool-activity summary — mirrors Claude Code's native chat-UI
  // rendering ("Ran 5 commands, read a file"). Counters are
  // incremented in `case 'tool_use'`; `activityMessageId` holds the
  // Telegram message id we send/edit so a single message accumulates
  // the summary in place. Stops updating once `replyCalled` flips —
  // the model's own reply lands below the summary as the actual
  // content.
  //
  // Parallel-tool-use coalescing (PR #1926 review): modern Claude
  // emits multiple tool_uses in a tight synchronous loop (e.g. 3
  // parallel Reads). Without coalescing, each would see
  // `activityMessageId == null` and fire its own sendMessage,
  // producing N messages instead of one editable summary. Pattern
  // mirrors `telegram-plugin/answer-stream.ts`:
  //   - `activityInFlight` — promise that resolves when the current
  //     send/edit settles. While set, NEW tool_uses just update
  //     `activityState` and `activityPendingRender` and return.
  //   - When the in-flight resolves, it picks the latest
  //     `activityPendingRender`, fires the next send/edit, and
  //     repeats until the pending matches the last-sent.
  // Result: at most one Telegram call in flight at a time; the
  // final state always lands.
  activityMessageId: number | null
  activityInFlight: Promise<void> | null
  activityPendingRender: string | null
  activityLastSentRender: string | null
  // Status-surface observability. `activityEverOpened` is sticky-true once the
  // feed posts its first message — unlike `activityMessageId`, it is NOT nulled
  // by `clearActivitySummary`, so the turn-end DEGRADED check can tell "feed
  // never opened" (the resume-400 signature) from "feed finalized + cleared".
  // `activityDrainFailures` counts real activity-feed send/edit failures this
  // turn (429s + "message is not modified" excluded). Both reset per turn.
  activityEverOpened: boolean
  activityDrainFailures: number
  // Wall-clock anchor for the newest in-progress feed step — set each time a
  // tool_label re-renders the feed. The heartbeat (`feedHeartbeatTick`) reads
  // it to show a climbing " · Ns" elapsed on the live line so a long single
  // step that emits no new label doesn't read as frozen (the feed is otherwise
  // pull-only). undefined until the first label of the turn renders.
  lastToolLabelAt?: number
  // Fix 2 (post-answer background-agent liveness): wall-clock timestamp last
  // updated by the sub-agent/workflow watcher's onProgress callback whenever
  // it surfaces a NEW sub-agent step AFTER this turn's substantive answer was
  // delivered. Written INDEPENDENTLY of the tool_label path so the drop-guard
  // (`shouldReopenFeedAfterAck` / `finalAnswerSubstantive`) cannot gate it.
  // `feedHeartbeatTick` reads THIS (not `lastToolLabelAt`, which is frozen by
  // the drop-guard) to drive the post-answer liveness card — the core fix for
  // #2587's inert state. undefined until the first post-answer watcher advance.
  subagentActivityAt?: number
  // Sticky wall-clock timestamp when finalAnswerEverDelivered first latched
  // true this turn. Allows the heartbeat to distinguish "tool label arrived
  // before the answer" (lastToolLabelAt ≤ finalAnswerDeliveredAt, inert) from
  // "sub-agent active after the answer" (subagentActivityAt >
  // finalAnswerDeliveredAt, liveness card warranted). undefined until the
  // first substantive final answer of the turn.
  finalAnswerDeliveredAt?: number
  // Accumulating friendly-action feed for this turn. Each non-surface
  // tool_label appends a line via `appendActivityLabel`; the feed renders
  // (via `renderActivityFeed`) as a capped chronological list into the
  // in-place edited activity message and clears on reply. Reset per turn.
  mirrorLines: string[]
  // Narrative-dedup gate state (JSONL-text-narrative primitive). A `text` block
  // is parked for ONE lookahead step so the next event (a tool_use or turn_end)
  // can decide draft-then-send (SUPPRESS, it duplicates the reply) vs
  // working-narration (SHOW it as a transient mirrorLines step). The pure park /
  // timer / retract state machine lives in `narrative-flush.ts`; this controller
  // is the per-turn instance, wired with the SHOW effect (`showNarrativeStep`),
  // the RETRACT effect (splice the timer-painted line out of `mirrorLines`), and
  // a real `unref`'d `setTimeout` scheduler for the ~`PENDING_NARRATIVE_FLUSH_MS`
  // early paint. Reset per turn. Invariant `chat-is-the-single-source-of-truth`:
  // a SHOWN narrative renders through the SAME appendActivityLabel→renderStepFeed
  // path as a tool step — transient, clipped, rolling-window, never a persisted
  // parallel mirror.
  narrativeGate: NarrativeFlushController
  // Most-recently-seen reply/stream_reply `input.text` for this turn — the
  // ACTUAL delivered answer surface. Set wherever a REPLY_TOOL tool_use is
  // handled in the reducer. `flushPendingNarrativeAtTurnEnd` compares a
  // trailing narrative block against THIS (not capturedText.join(''), which
  // can mis-suppress when the model emits the same short string twice in a
  // turn). Empty string until the turn delivers a reply. Reset per turn.
  lastReplyText: string
  // Model A — foreground sub-agent nesting. A foreground sub-agent (Task/Agent
  // with no run_in_background) runs INSIDE this turn while the parent blocks at
  // the Task tool, so its live steps nest under the parent's activity feed
  // rather than a separate message. Keyed by jsonl agent id; value = the
  // sub-agent's accumulated narrative lines (oldest→newest, deduped + capped).
  // Background workers are NOT here — they get the standalone worker feed.
  foregroundSubAgents: Map<string, string[]>
  // Issue #195 — answer-lane streaming. Lazily created on the first text
  // event of a turn (once enough text has accumulated, the stream itself
  // gates on minInitialChars). Materialized and cleared at turn_end.
  answerStream: AnswerStreamHandle | null
  isDm: boolean
  // PR-4a (message-emission-determinism, `emission-authority.ts`). The
  // per-foreground-turn emission-authority façade the foreground-lane card/ping
  // emission call sites route through. Constructed ONCE per turn in the ctor
  // with the chat/thread key passed in explicitly (the PR-4e seam). Per-turn
  // only — a fresh `CurrentTurn` literal gets a fresh façade, so it never
  // persists across turns. Optional in the type so the bounded recently-ended
  // registry's older entries (and any hand-built test turn) tolerate its
  // absence; `emissionAuthorityFor` lazily backfills one when missing.
  emissionAuthority?: EmissionAuthority
  readonly originChannel: 'telegram' | 'buzz'; readonly buzzCoords?: { channelId: string; eventId: string; threadRoot: string } } // Buzz Phase 2a/2b: origin provenance stamped ONCE at the turn ctor via parseChannelOrigin(ev.rawContent) (channel-route.ts); buzzCoords present IFF originChannel==='buzz'. `readonly` enforces single-writer immutability (MINOR-2) — no `.originChannel=`/`.buzzCoords=` reassignment compiles. Types inlined + brace merged to hold gateway.ts at its zero-headroom ratchet (switchroom#2996); structurally identical to channel-route.ts Channel/BuzzCoords (type-identity asserted in channel-route.ts, MINOR-3).

// PR-4e — the singleton `currentTurn` is RETAINED as (a) the flag-OFF store and
// (b) the flag-ON "most-recent-set" MIRROR. Every GLOBAL-liveness read in this
// file (`isBusy`, the `if (currentTurn != null) return` poke guards, the
// orphaned-reply guard, the synchronous-to-live-turn `const turn = currentTurn`
// captures) keeps reading this variable, so under the sequential-CLI invariant
// (the most-recently-set turn IS the live turn) those reads stay byte-identical.
// The per-topic isolation lives in `currentTurnMap.byKey`: a LATE async event
// captured for topic A resolves A's authority by ITS OWN key even after the live
// turn flipped to topic B (see current-turn-map.ts). Under the flag OFF the map
// is never written and this is exactly the old singleton.
let currentTurn: CurrentTurn | null = null
const currentTurnMap = new CurrentTurnMap<CurrentTurn>()
// Freshness-aware /status session-model source. Two writers: the session-tail
// `model` event (each assistant line's `message.model` — ground truth for the
// last API call, survives between turns) and the #2982 /model override (set
// the instant a switch is confirmed — the ONLY truthful source in the
// idle-after-switch window, before the next assistant line lands). Every write
// is seq-stamped and `resolve()` prefers the NEWER observation, so neither
// source can go stale behind the other (session-model-source.ts, pinned by
// tests/session-model-source.test.ts). buildAgentMetadata reads resolve();
// the /model command paths write via setOverride. The comparator arms the
// #3427 requested-vs-served tripwire (handler registered at boot rehydration).
const sessionModelSource = createSessionModelSource({ servedMatchesRequested: servedModelMatchesRequested })
// Captures the most-recently-started turn's sessionChatId. Unlike currentTurn,
// this is NOT cleared by the silence poke (firePoke/clearTurnStarted). It lets
// the Bug B fallback in executeReply route to the correct chat even when the
// model calls reply AFTER the silence poke has nulled currentTurn (Bug D).
// Safe in single-tenant gateways: the fallback only fires when the raw chat_id
// fails the allowlist, and this value was itself validated at inbound receipt.
let lastActiveTurnChatId: string | undefined

/**
 * Set the live turn for `key`. Flag-branches in ONE place (inside the map):
 * flag-OFF assigns the singleton only; flag-ON sets the per-topic entry AND
 * updates the most-recent mirror. We keep the module-scope `currentTurn`
 * variable in lock-step with the map's mirror so the 140 unchanged global reads
 * see the same value.
 */
function setCurrentTurn(turn: CurrentTurn, key: string): void {
  currentTurnMap.set(turn, key)
  currentTurn = currentTurnMap.get() // mirror most-recent-set (== `turn`)
  lastActiveTurnChatId = turn.sessionChatId
}

/**
 * End (delete) the live turn for `key`, iff `key` still maps to `turn`. Routes
 * the clear through the keyed accessor (leak-close-at-origin) and re-syncs the
 * module-scope mirror to the map's mirror.
 */
function endCurrentTurnForKey(turn: CurrentTurn, key: string): boolean {
  const ended = currentTurnMap.endTurnForKey(turn, key)
  currentTurn = currentTurnMap.get() // re-sync mirror (null iff it pointed at turn)
  return ended
}

/**
 * Clear the ENTIRE per-topic store + mirror (disconnect-flush / bridge-died:
 * every entry is a ghost).
 */
function clearAllCurrentTurns(): void {
  currentTurnMap.clearAll()
  currentTurn = null
}

/**
 * Is `turn` still the live turn FOR ITS OWN topic? Flag-OFF: `currentTurn ===
 * turn` (the ambient check, verbatim). Flag-ON: `byKey.get(turn'sKey) === turn`,
 * so a B-flip never falsifies A's own liveness. The callsites keep the literal
 * `currentTurn === turn` in source (the silence-liveness-wiring oracle) by
 * inlining the flag-OFF branch and delegating the flag-ON branch here.
 */
function turnLiveForItsTopic(turn: CurrentTurn): boolean {
  return currentTurnMap.isLiveForKey(
    turn,
    statusKey(turn.sessionChatId, turn.sessionThreadId),
  )
}

/**
 * Accessor for a turn's per-foreground-turn emission-authority façade (PR-4a).
 * Returns the façade constructed at the turn ctor; lazily backfills one (keyed
 * on the turn's chat/thread) for any turn that predates the field or was built
 * outside the ctor. Per-turn: the memoized instance lives on the turn object,
 * so it is discarded with the turn and never persists across turns.
 */
function emissionAuthorityFor(turn: CurrentTurn): EmissionAuthority {
  if (turn.emissionAuthority == null) {
    turn.emissionAuthority = new EmissionAuthority(
      statusKey(turn.sessionChatId, turn.sessionThreadId),
    )
  }
  // PR-4b — CENTRALIZE the OPEN-gate wiring here, the single accessor every
  // routed call site already funnels through, so all 6 `openOrEditCard(...)`
  // sites stay byte-identical `(producer, apply)`. The façade reads the LIVE
  // turn view (a thunk — the card id / latch / tool-count mutate during the
  // turn) + the injected history deps from this one place, not per-call.
  // Idempotent; harmless under the flag OFF (the disabled branch never reads
  // it). The turn IS a structural `FeedOpenGateView`.
  turn.emissionAuthority.wireFeedOpenGate(() => turn, feedOpenGateDeps())
  return turn.emissionAuthority
}

/**
 * The injected history dependencies the PR-4b OPEN gate needs (the real
 * `hasOutboundDeliveredSince` predicate + `HISTORY_ENABLED` + the substantive
 * `FINAL_ANSWER_MIN_CHARS` floor). Centralized so both the façade's enabled
 * branch AND the drain's own (now-redundant) inline gate consume the SAME deps
 * via the SAME pure helpers — flag-ON and flag-OFF cannot diverge. Keeps
 * `feed-open-gate.ts` sqlite-free (it never imports `history.js`).
 */
function feedOpenGateDeps(): FeedOpenGateDeps {
  return {
    hasOutboundDeliveredSince,
    historyEnabled: HISTORY_ENABLED,
    finalAnswerMinChars: FINAL_ANSWER_MIN_CHARS,
  }
}

/**
 * The deliver-before-drain inputs the PR-4d card-drain gate threads into the
 * façade's pure `mayDrainCardNow`. Centralized so the card-drain helper sources
 * the SAME `turnInFlightForGate()` + kill-switch the buffer-drain gate uses.
 *
 * `endingTurnFinalAnswerDelivered` is FIXED to `null` for the card path (§5
 * modeling decision): the live foreground card single-flight is governed by
 * `turn.activityInFlight` (via `mayDrain`), NOT by an ending turn's delivery
 * state — so `mayDrainBufferedInbound` degenerates to `!turnInFlight` and a
 * synthetic represent turn (finalAnswerDelivered=false) can never wedge the card.
 */
function cardDrainGateCtx(): CardDrainGateCtx {
  return {
    turnInFlight: turnInFlightForGate(),
    endingTurnFinalAnswerDelivered: null,
    enabled: SERIALIZE_UNTIL_REPLIED_ENABLED,
  }
}

/**
 * PR-4d centralized card-drain gate (Option A). The 6 foreground card-drain
 * sites pass their EXISTING single-flight-guarded block (the `mayDrain` guard +
 * the `openOrEditCard(producer, …)` thunk that assigns `turn.activityInFlight =
 * drainActivitySummary(…)`) in VERBATIM as `run`, so those load-bearing literals
 * stay byte-identical (the wiring oracles still see them).
 *
 *  - **Flag OFF (default):** runs the guarded block directly — NO `chatLock`
 *    wrapper, byte-equivalent to base.
 *  - **Flag ON:** acquires `chatLock` AROUND the deliver-before-drain decision
 *    (`mayDrainCardNow`) + the synchronous block, unifying the card path with
 *    the #2137 serialization gate. The lock spans ONLY the gate decision + the
 *    synchronous `openOrEditCard` kick-off inside `run` (which only ASSIGNS
 *    `turn.activityInFlight = drainActivitySummary(...)`; the async send is NOT
 *    awaited inside the lock). The lock is released before any drain
 *    `await sendMessage` suspends, so a card OPEN never holds `chatLock` across
 *    the gate's release — a synthetic represent turn can never wedge the gate,
 *    and `mayDrain` stays callable lock-free.
 *
 * LOCK ORDERING (no-deadlock invariant): `chatLock` is acquired EXCLUSIVELY
 * here, around the gate; never the reverse. `mayDrainCardNow` is a pure read.
 */
function cardDrainGate(turn: CurrentTurn, ea: EmissionAuthority, run: () => void): void {
  if (EMISSION_AUTHORITY_ENABLED) {
    void chatLock.run(
      statusKey(turn.sessionChatId, turn.sessionThreadId),
      async () => {
        if (ea.mayDrainCardNow(turn, cardDrainGateCtx())) run()
      },
    )
    return
  }
  run()
}

// Component 3 (turn-origin reply routing). Recently-ended turns retained
// by `turnId` so a LATE reply (the Brevo answer landing ~42s after
// turn-end, after `currentTurn` has flipped to the Meta turn) can still
// resolve its ORIGIN turn's thread instead of the live successor's. Bug:
// `executeReply` captured `const turn = currentTurn` at entry and, when
// the model omitted message_thread_id, routed to `turn.sessionThreadId`
// — the flipped turn's thread. Pinning by origin turnId closes that.
// Bounded LRU (insertion-ordered Map) so it can't grow unbounded across
// a long-lived supergroup session.
const RECENT_TURNS_MAX = 32
const recentTurnsById = new Map<string, CurrentTurn>()
// Framework-owned origin recovery: reverse-index from an inbound's source
// message_id to the turnId that owns it, so a reply that QUOTES a specific
// message (args.reply_to) resolves its origin turn deterministically — a
// real message_id the framework stamped, never a model-asserted thread.
// Evicted in lock-step with recentTurnsById so it can't outgrow it.
const recentTurnIdBySourceMessageId = new Map<number, string>()

// fix/backstop-duplicate-reply — per-chat/thread marker of the most recent
// gateway-synthesized `subagent_handback` enqueue (logic in
// subagent-handback-marker.ts; extracted per the gateway anti-inflation ratchet).
// The record is thread-resolved (retains the originating topic), but the
// content-gate READ is CHAT-WIDE (dup-audit MUST-FIX 2): the latest-ended owner
// tier is chat-wide, so a thread-specific gate read was steerable by the reply's
// own `message_thread_id` → silent edit-over. `lastAtInChat` makes the gate
// un-steerable (any in-window handback in the chat keeps the content gate).
const subagentHandbackMarker = new SubagentHandbackMarker()
const getLastSubagentHandbackAt = (chatId: string): number | null =>
  subagentHandbackMarker.lastAtInChat(chatId)

function rememberRecentTurn(turn: CurrentTurn): void {
  recentTurnsById.set(turn.turnId, turn)
  if (turn.sourceMessageId != null) {
    recentTurnIdBySourceMessageId.set(turn.sourceMessageId, turn.turnId)
  }
  while (recentTurnsById.size > RECENT_TURNS_MAX) {
    const oldest = recentTurnsById.keys().next().value
    if (oldest === undefined) break
    const evicted = recentTurnsById.get(oldest)
    recentTurnsById.delete(oldest)
    // Drop the reverse-index entry for the evicted turn (only when it still
    // points at THIS turn — a newer turn may have reused the same message id).
    if (evicted?.sourceMessageId != null &&
        recentTurnIdBySourceMessageId.get(evicted.sourceMessageId) === oldest) {
      recentTurnIdBySourceMessageId.delete(evicted.sourceMessageId)
    }
  }
}

/**
 * Framework-owned origin recovery (kill switch SWITCHROOM_FRAMEWORK_ORIGIN_ROUTING).
 * Resolve the turn that owns a reply from the message_id it QUOTES (args.reply_to),
 * via the source-message reverse index. Returns null when disabled, when reply_to
 * is absent/non-numeric, or when no turn owns that message id (evicted / unknown).
 * Deterministic: a real framework-stamped message_id → its turn, with no model
 * thread assertion and no dependence on the live currentTurn.
 *
 * SCOPED to `chatId`: Telegram numbers message ids PER CHAT, so the same numeric
 * id exists in a DM and a supergroup. The reverse index is keyed by id alone, so
 * the resolved turn MUST be confirmed to belong to this reply's chat — otherwise
 * a reply quoting its own id could inherit another chat's thread (a cross-chat
 * leak). On a chat mismatch we return null (decline to recover → fall through to
 * the live-turn behaviour), never a wrong-chat thread.
 */
function findTurnByQuotedMessageId(chatId: string, replyTo: unknown): CurrentTurn | null {
  if (!FRAMEWORK_ORIGIN_ROUTING_ENABLED) return null
  if (replyTo == null) return null
  const mid = Number(replyTo)
  if (!Number.isFinite(mid)) return null
  const owner = recentTurnIdBySourceMessageId.get(mid)
  if (owner == null) return null
  const turn = recentTurnsById.get(owner) ?? null
  if (turn == null || turn.sessionChatId !== chatId) return null
  return turn
}
// Component 3 — the stable per-turn identity. Extracted to `derive-turn-id.ts`
// (#3268) so the enqueue seam and the handback round-trip test share ONE
// function. Re-exported into scope under the original name so every existing
// callsite is unchanged.

/**
 * Component 3 — resolve the turn that OWNS a reply by its `origin_turn_id`
 * (the meta field the model echoes back from the channel tag). Checks the
 * live turn first, then the recently-ended registry. Returns null when the
 * id is absent or unknown (a model that didn't echo it, or a turn evicted
 * from the bounded registry) — callers then fall back to the existing
 * turn-pinned / chatThreadMap precedence.
 */
function findTurnByOriginId(originTurnId: string | null | undefined): CurrentTurn | null {
  if (originTurnId == null || originTurnId === '') return null
  // PR-4e — resolve the LIVE turn by ITS OWN topic key under the flag. The
  // turnId encodes the key: `deriveTurnId` builds `${chatKey}#${messageId}`, so
  // the substring before `#` IS the statusKey. Flag-ON does an O(1)
  // `byKey.get(key)` and matches on turnId — so a reply whose origin turn is
  // STILL live for topic A resolves A even after the singleton mirror flipped to
  // B. Flag-OFF keeps the singleton check, verbatim. The recentTurnsById
  // registry fallback is UNCHANGED in both branches.
  if (EMISSION_AUTHORITY_ENABLED) {
    const hashIdx = originTurnId.indexOf('#')
    if (hashIdx > 0) {
      const live = currentTurnMap.get(originTurnId.slice(0, hashIdx))
      if (live != null && live.turnId === originTurnId) return live
    }
  } else if (currentTurn != null && currentTurn.turnId === originTurnId) {
    return currentTurn
  }
  return recentTurnsById.get(originTurnId) ?? null
}

// Late-reply topic recovery (2026-06-05 marko triage). Default ON; kill switch
// SWITCHROOM_LATE_REPLY_TOPIC_RECOVERY=0 restores the legacy behaviour (a late
// reply with no echoed origin and no live turn defaults to General).
const LATE_REPLY_TOPIC_RECOVERY_ENABLED =
  process.env.SWITCHROOM_LATE_REPLY_TOPIC_RECOVERY !== '0'

/**
 * The most recent turn for a chat from the bounded recent-turn registry — the
 * deterministic fallback for a LATE answer reply when the model echoed no
 * `origin_turn_id` and `currentTurn` has already cleared. Returns null when the
 * chat has no matching turn (so the caller keeps the legacy result). NB: this is
 * the chat's own most-recent TURN, not the `chatThreadMap` last-seen-any-message
 * heuristic that caused the wrong-topic bug. `endedOnly` selects the consumer's
 * semantics — routing takes the tail entry even when that turn is still RUNNING;
 * the destructive `latest-ended` owner tier takes only a genuinely ENDED turn,
 * because the registry is populated at turn START (#3725; see the module).
 */
function findLatestTurnForChat(chatId: string, opts: { endedOnly: boolean }): CurrentTurn | null {
  return latestTurnForChat(recentTurnsById.values(), chatId, opts)
}

/** 2026-07 double-reply-on-DM fix (Part 1) — thin wrapper over the extracted
 *  composition (`reply-owner-wiring.ts`, which also carries the #4173
 *  turn-completion-window bounds). Kept here only to bind the gateway's
 *  stateful lookups. */
function resolveReplyOwnerTurn(
  liveTurn: CurrentTurn | null,
  chatId: string,
  args: Record<string, unknown>,
): { turn: CurrentTurn | null; tier: ReplyOwnerTier; candidates: ReplyOwnerCandidates } {
  return resolveReplyOwnerTurnWith(
    { findTurnByOriginId, findTurnByQuotedMessageId, findLatestTurnForChat, now: Date.now },
    liveTurn,
    chatId,
    args,
  )
}

/**
 * Resolve the answer-reply thread AND emit `reply-route` telemetry. The
 * 2026-06-05 triage showed reply routing was the blind spot: `reply: invoked`
 * logged only chat + char count, so a late reply landing in the wrong topic was
 * invisible without hand-correlating raw tg-post threads against turn-lifecycle
 * timestamps. This wrapper logs, per reply: which precedence tier won (`via`),
 * the resolved thread, the origin turn + its thread, and whether the reply was
 * late (turn already ended). `via=recovered` marks a late reply this fix saved
 * from General; `via=quoted` marks an origin recovered from the framework-owned
 * quoted message_id (no model echo); `UNROUTED` flags a supergroup reply that
 * resolved to no topic with NO owner turn to attribute it to (genuinely lost).
 * `MISROUTE_RISK` flags the irreducible determinism residual: a no-echo,
 * no-quote reply that fell to the LIVE turn while a DIFFERENT topic recently had
 * a turn — the framework cannot tell which topic the bare reply answers, so the
 * routing MIGHT be wrong (HOLE a). It is observability only (the reply still
 * routes to the live turn) — it makes the one case that is genuinely
 * model-dependent visible instead of silently mis-routed. A General-topic turn
 * legitimately has no thread, so its replies are NOT UNROUTED-flagged.
 *
 * `originVia` distinguishes how the origin turn was resolved: 'echo' (model
 * echoed origin_turn_id), 'quoted' (framework recovered it from args.reply_to),
 * or null (no origin turn). It only affects the `via` label, never the routing.
 */
function resolveAnswerThreadWithLog(
  chatId: string,
  explicitThreadId: number | undefined,
  originTurn: CurrentTurn | null,
  originVia: 'echo' | 'quoted' | null,
  liveTurn: CurrentTurn | null,
  surface: 'reply' | 'stream_reply',
): number | undefined {
  // Recover ONLY for a genuinely LATE reply — no live turn at all. Gating on
  // `liveTurn?.sessionThreadId == null` (the original) also fired for a
  // threadless DM that still had a live turn, marking every DM reply
  // `via=recovered`/RECOVERED in the telemetry (routing result unchanged —
  // DM → undefined — but it drowned the real supergroup recoveries the marker
  // exists to surface). `liveTurn == null` is the precise late-reply condition.
  const recovered =
    LATE_REPLY_TOPIC_RECOVERY_ENABLED &&
    explicitThreadId == null &&
    originTurn == null &&
    liveTurn == null
      ? findLatestTurnForChat(chatId, { endedOnly: false })
      : null
  const threadId = resolveAnswerThreadId({
    explicitThreadId,
    originResolved: originTurn != null,
    originThreadId: originTurn?.sessionThreadId,
    liveThreadId: liveTurn?.sessionThreadId,
    liveTurnPresent: liveTurn != null,
    lastEndedResolvedForChat: recovered != null,
    lastEndedThreadIdForChat: recovered?.sessionThreadId,
    frameworkTopicAuthority: REPLY_TOPIC_AUTHORITY_ENABLED,
  })
  // `via` reflects the ACTIVE precedence so telemetry matches routing.
  const via = REPLY_TOPIC_AUTHORITY_ENABLED
    ? (originTurn != null ? (originVia === 'quoted' ? 'quoted' : 'origin')
      : liveTurn != null ? 'live'
      : explicitThreadId != null ? 'explicit'
      : recovered != null ? 'recovered'
      : 'none')
    : (explicitThreadId != null ? 'explicit'
      : originTurn != null ? (originVia === 'quoted' ? 'quoted' : 'origin')
      : liveTurn?.sessionThreadId != null ? 'live'
      : recovered != null ? 'recovered'
      : 'none')
  // Observability: the model passed an explicit topic but a framework anchor
  // (origin/live) overrode it. This is the deterministic correction that fixes
  // the General→CRM misroute; surface it so the model's topic-grabbing is
  // visible rather than silent.
  const explicitOverridden =
    REPLY_TOPIC_AUTHORITY_ENABLED &&
    explicitThreadId != null &&
    (originTurn != null || liveTurn != null) &&
    threadId !== explicitThreadId
  const ownerTurn = originTurn ?? recovered ?? liveTurn
  const isSupergroup = chatId.startsWith('-100')
  // UNROUTED = a supergroup reply that resolved to NO topic with NO owner turn
  // to attribute it to (genuinely lost). A General-topic turn legitimately has
  // no thread, so a reply owned by it resolving to `-` is CORRECT, not lost —
  // gate on `ownerTurn == null` so General replies don't false-alarm (found by
  // the multi-topic UAT stress, 2026-06-05).
  const unrouted = isSupergroup && threadId == null && ownerTurn == null
  // MISROUTE_RISK = the irreducible determinism residual (HOLE a). A no-echo,
  // no-quote reply fell to the LIVE turn (via=live), but a DIFFERENT topic
  // recently had a turn for this chat — so this bare reply MIGHT belong to that
  // other topic and we cannot tell without the model's echo. Observability only;
  // routing is unchanged. This is the one case framework state cannot
  // disambiguate, surfaced instead of silently mis-routed.
  const misrouteRisk =
    isSupergroup &&
    via === 'live' &&
    hasDifferentThreadedRecentTurn(chatId, liveTurn?.sessionThreadId)
  process.stderr.write(
    `telegram gateway: reply-route surface=${surface} chat=${chatId} ` +
      `resolved_thread=${threadId ?? '-'} via=${via} late=${liveTurn == null} ` +
      `originTurn=${ownerTurn?.turnId ?? '-'} origin_thread=${ownerTurn?.sessionThreadId ?? '-'}` +
      (via === 'recovered' ? ' RECOVERED' : '') +
      (via === 'quoted' ? ' QUOTED(framework-origin)' : '') +
      (unrouted ? ' UNROUTED(supergroup→no-topic)' : '') +
      (misrouteRisk ? ' MISROUTE_RISK(no-echo→live-successor)' : '') +
      (explicitOverridden
        ? ` EXPLICIT_OVERRIDDEN(model→${explicitThreadId},routed→${threadId ?? '-'})`
        : '') +
      '\n',
  )
  return threadId
}

/**
 * Determinism-residual detector (HOLE a observability). True when a DIFFERENT
 * forum topic recently had a turn for this chat than the live turn's thread —
 * i.e. a currentTurn flip plausibly happened, so a no-echo / no-quote reply
 * routed to the live turn MIGHT belong to the other topic. Scans the bounded
 * recently-ended registry; cheap (≤32 entries). Used only to ALARM, never to
 * route.
 */
function hasDifferentThreadedRecentTurn(
  chatId: string,
  liveThreadId: number | undefined,
): boolean {
  const live = liveThreadId ?? null
  for (const t of recentTurnsById.values()) {
    if (t.sessionChatId === chatId && (t.sessionThreadId ?? null) !== live) return true
  }
  return false
}

// ─── Obligation open/close/cancel + idle sweep — extracted to obligation-wiring.ts
// (#2996 P8 PR-C2). The ledger INSTANCE, its durable store, `pendingCrossTurnGate`,
// `obligationEscalateInFlight`, the grace consts and the escalation nudge SEND
// (bot-api retry policy) all stay here — logic moved, state stays. Thin wrappers
// keep every callsite byte-identical; the sweep interval stays gateway-owned (P0c).

/** Live gateway deps for the extracted obligation wiring. */
function gatewayObligationWiringDeps() {
  return {
    OBLIGATION_LEDGER_ENABLED,
    HISTORY_ENABLED,
    OBLIGATION_BACKGROUND_WORK_GRACE_MS,
    OBLIGATION_ESCALATE_GRACE_MS,
    OBLIGATION_REPRESENT_GRACE_MS,
    OBLIGATION_REPRESENT_MAX,
    OBLIGATION_REPRESENT_GUARD_MIN_REPLY_CHARS,
    OBLIGATION_ESCALATE_MAX,
    OBLIGATION_ESCALATE_SEND_DEADLINE_MS,
    obligationLedger,
    obligationEscalateInFlight,
    pendingCrossTurnGate,
    pendingInboundBuffer,
    capturedResume,
    getCurrentTurn: (): CurrentTurn | null => currentTurn,
    turnInFlightForGate,
    agentHasInFlightBackgroundWork,
    hasOutboundDeliveredSince,
    findTurnByOriginId,
    bridgeAlive: (agent: string): boolean => ipcServer.getClient(agent)?.isAlive() === true,
    // The escalation nudge — the ONE bot-api touch, kept here behind the
    // gateway retry policy (new modules never call bot.api raw).
    sendEscalationNudge: (o: Obligation) =>
      retryWithThreadFallback(
        robustApiCall,
        (tid) =>
          bot.api.sendMessage(o.chatId, obligationEscalationText(o), {
            ...(tid != null ? { message_thread_id: tid } : {}),
          }),
        { threadId: o.threadId, chat_id: o.chatId, verb: 'obligation.escalate' },
      ),
  }
}
export type ObligationWiringDeps = ReturnType<typeof gatewayObligationWiringDeps>

let _obligationWiring: ReturnType<typeof createObligationWiring> | undefined
function obligationWiring(): ReturnType<typeof createObligationWiring> {
  return (_obligationWiring ??= createObligationWiring(gatewayObligationWiringDeps()))
}

function closeObligationOnSubstantiveReply(
  args: Record<string, unknown>,
  liveTurn: CurrentTurn | null | undefined,
  routedOriginTurn?: CurrentTurn | null,
): void {
  obligationWiring().closeObligationOnSubstantiveReply(args, liveTurn, routedOriginTurn)
}

function openObligationFromInbound(
  inboundMsg: InboundMessage,
  gate: { isSteering: boolean; isInterrupt: boolean; effectiveText: string },
): void {
  obligationWiring().openObligationFromInbound(inboundMsg, gate)
}

/**
 * Component 5 — post a "Queued — replying in another topic first" status
 * into a cross-topic buffered message's OWN topic. Fire-and-forget through
 * the swallowing wrapper (carries message_thread_id so it lands in the
 * right topic). Suppressed for DMs and same-topic queues by the CALLER.
 * Records the sent message id keyed by chatKey(chatId, bufferedThread) for
 * the later edit (Hook B) / delete (Hook C / reap).
 */
function postQueuedStatus(chatId: string, bufferedThread: number, inFlightThread: number | undefined): void {
  if (!QUEUED_STATUS_UX_ENABLED) return
  const key = statusKey(chatId, bufferedThread)
  // Idempotent: a second buffered message in the same topic re-uses the
  // existing placeholder (don't stack).
  if (queuedStatusMsgIds.has(key)) return
  const otherTopic = inFlightThread != null ? `another topic` : `another conversation`
  const text = `⏳ Queued — replying in ${otherTopic} first, then I'll get to this.`
  void (async () => {
    const sent = await swallowingApiCall(
      () =>
        // Queued-placeholder status, not the user's answer — silence the
        // open ping (BORDERLINE: it's a "your message is queued" notice;
        // see PR description).
        bot.api.sendMessage(chatId, text, { message_thread_id: bufferedThread, disable_notification: true }),
      { chat_id: chatId, verb: 'queued-status.post', threadId: bufferedThread },
    )
    const messageId = (sent as { message_id?: number } | undefined)?.message_id
    if (typeof messageId !== 'number') return
    // Re-check after the await: the turn may have already started and
    // edited/deleted via Hook B/C in the gap. If the key is now occupied
    // by a different placeholder, delete this orphan; otherwise record it.
    if (queuedStatusMsgIds.has(key)) {
      void swallowingApiCall(
        () => bot.api.deleteMessage(chatId, messageId),
        { chat_id: chatId, verb: 'queued-status.post-race-cleanup', threadId: bufferedThread },
      )
      return
    }
    queuedStatusMsgIds.set(key, { chatId, threadId: bufferedThread, messageId })
    // #3002: write through to the durable store so a gateway restart before the
    // in-process reap can still delete this orphaned card on boot.
    persistQueuedCard(key, chatId, bufferedThread, messageId)
  })()
}

/**
 * Component 5 (Hook B) — the buffered message's turn just STARTED. Edit the
 * queued placeholder in its topic to "On it — replying now." Best-effort.
 */
function promoteQueuedStatus(chatId: string, thread: number | undefined): void {
  if (!QUEUED_STATUS_UX_ENABLED) return
  // #2995: thread == null is a DM (or General-topic) card — the busy-ack
  // extended this lifecycle to DMs, so promote those too (statusKey keys
  // a null thread identically at post and promote time).
  const key = statusKey(chatId, thread)
  const entry = queuedStatusMsgIds.get(key)
  if (entry == null) return
  // editMessageText targets a specific message id, which already implies
  // its thread — grammy's typed signature has no message_thread_id (the
  // swallowingApiCall opts still carry threadId for the deleted-topic
  // fallback policy).
  void swallowingApiCall(
    () =>
      bot.api.editMessageText(chatId, entry.messageId, '✍️ On it — replying now.', {}),
    { chat_id: chatId, verb: 'queued-status.promote', ...(thread != null ? { threadId: thread } : {}) },
  )
}

/**
 * Component 5 (Hook C / reap) — the answer landed (or the turn ended
 * abnormally). Delete the queued placeholder and drop the map entry so the
 * topic shows the real answer, never a stale "Queued" line. Idempotent.
 */
function reapQueuedStatus(chatId: string, thread: number | undefined): void {
  const key = statusKey(chatId, thread ?? null)
  const entry = queuedStatusMsgIds.get(key)
  if (entry == null) return
  queuedStatusMsgIds.delete(key)
  // #3002: drop the durable row too, scoped to this exact message id (reap-race
  // guard) so a fresh live card under the same key keeps its own protection.
  clearQueuedCard(key, entry.messageId)
  void swallowingApiCall(
    () => bot.api.deleteMessage(chatId, entry.messageId),
    { chat_id: chatId, verb: 'queued-status.reap', ...(entry.threadId != null ? { threadId: entry.threadId } : {}) },
  )
}

/**
 * #2995 — mid-flight busy ack (decision + dispatch). Called when a mid-turn
 * inbound was buffered (`buffer-until-idle`) or delivered as a steer. If the
 * running turn is sitting inside one LONG tool step (see busy-ack.ts for the
 * threshold rationale), post a silent deterministic card into the inbound's
 * own chat/topic naming the blocking activity — so a quick question asked
 * behind a `--watch`-style blocking call doesn't read as ignored for
 * minutes. Model-free, zero tokens. The card is stored in
 * `queuedStatusMsgIds`, so it inherits the component-5 lifecycle: promoted
 * ("On it") when the buffered turn starts, deleted when the answer lands or
 * the turn ends. Dedupe is per turn per chat/topic via `busyAckPostedKeys`.
 */
function maybePostBusyAck(
  gateDecision: 'buffer-until-idle' | 'steer',
  chatId: string,
  threadId: number | undefined,
): void {
  if (!MIDFLIGHT_BUSY_ACK_ENABLED) return
  const key = statusKey(chatId, threadId)
  const inFlight = currentTurn
  const inFlightKey =
    inFlight != null ? statusKey(inFlight.sessionChatId, inFlight.sessionThreadId) : key
  const now = Date.now()
  const step = silencePoke.longestInFlightTool(inFlightKey, now)
  const midToolCall = toolFlightTracker.isMidToolCall()
  const stepAgeMs = step?.durationMs ?? null
  const alreadyAcked = queuedStatusMsgIds.has(key) || busyAckPostedKeys.has(key)
  const fire = shouldPostBusyAck({ gateDecision, midToolCall, stepAgeMs, alreadyAcked })
  if (!fire) {
    // Deferred re-check: the ONLY miss reason we re-arm for is a step that
    // is genuinely open but still young — it may run for minutes more, and
    // a one-shot evaluation would re-create the original #2995 silence. Arm
    // one timer for (threshold − stepAge); everything is re-read live at
    // fire time, and the timer is pinned to THIS turn (turnId guard) plus
    // cancelled outright by purgeReactionTracking when the turn ends.
    if (
      midToolCall &&
      !alreadyAcked &&
      stepAgeMs != null &&
      stepAgeMs < BUSY_ACK_STEP_AGE_THRESHOLD_MS &&
      !busyAckRecheckTimers.has(key)
    ) {
      const turnIdAtSchedule = inFlight?.turnId ?? null
      const delayMs = BUSY_ACK_STEP_AGE_THRESHOLD_MS - stepAgeMs + 250
      busyAckRecheckTimers.set(key, setTimeout(() => {
        busyAckRecheckTimers.delete(key)
        // The ping is only still waiting if the SAME turn is still running
        // (a new/ended turn means the buffered inbound is being handled —
        // a "Queued" card then would be a lie).
        if (turnIdAtSchedule == null || currentTurn?.turnId !== turnIdAtSchedule) return
        maybePostBusyAck(gateDecision, chatId, threadId)
      }, delayMs))
    }
    return
  }
  const pendingRecheck = busyAckRecheckTimers.get(key)
  if (pendingRecheck != null) {
    clearTimeout(pendingRecheck)
    busyAckRecheckTimers.delete(key)
  }
  busyAckPostedKeys.add(key)
  const text = formatBusyAckText({
    gateDecision,
    toolName: step?.name ?? null,
    toolLabel: step?.label ?? null,
  })
  process.stderr.write(
    `telegram gateway: mid-flight busy ack chat=${chatId} thread=${threadId ?? '-'} ` +
    `decision=${gateDecision} step=${step?.name ?? '-'} step_age_ms=${step?.durationMs ?? '-'}\n`,
  )
  postBusyAck(chatId, threadId, text)
}

/**
 * #2995 — send the busy-ack card. Mirrors `postQueuedStatus` (idempotent
 * key, silent send, post-race orphan cleanup) but is thread-OPTIONAL so it
 * covers DMs and same-topic queues — the surfaces the cross-topic queued
 * status deliberately suppressed. Shares `queuedStatusMsgIds`, so
 * promote/reap clean it up exactly like the queued-status placeholder.
 */
function postBusyAck(chatId: string, threadId: number | undefined, text: string): void {
  const key = statusKey(chatId, threadId)
  if (queuedStatusMsgIds.has(key)) return
  void (async () => {
    const sent = await swallowingApiCall(
      () =>
        // Deterministic busy-ack placeholder, not the user's answer —
        // silent by contract (no device ping for a status card).
        bot.api.sendMessage(chatId, text, {
          ...(threadId != null ? { message_thread_id: threadId } : {}),
          disable_notification: true,
        }),
      { chat_id: chatId, verb: 'busy-ack.post', ...(threadId != null ? { threadId } : {}) },
    )
    const messageId = (sent as { message_id?: number } | undefined)?.message_id
    if (typeof messageId !== 'number') return
    // Re-check after the await (same race pattern as postQueuedStatus):
    // if a placeholder landed for this key in the gap, delete this orphan.
    if (queuedStatusMsgIds.has(key)) {
      void swallowingApiCall(
        () => bot.api.deleteMessage(chatId, messageId),
        { chat_id: chatId, verb: 'busy-ack.post-race-cleanup', ...(threadId != null ? { threadId } : {}) },
      )
      return
    }
    queuedStatusMsgIds.set(key, { chatId, threadId: threadId ?? null, messageId })
    // #3002: write through to the durable store (see postQueuedStatus).
    persistQueuedCard(key, chatId, threadId ?? null, messageId)
  })()
}

// Problem B — deferred safe-boundary interrupt.
//
// `toolFlightTracker` mirrors the session-event stream to know whether a
// top-level tool call is open right now (an unsafe point to SIGINT). When the
// `interrupt.safe_boundary` flag is on and a `!` lands mid-tool-call, we don't
// fire the SIGINT — we stash the fully-built replacement inbound here and fire
// it (SIGINT + deliver) at the next clean boundary (tool_result drains the
// last open tool, or turn_end), or when the max-wait timer expires. Rapid
// repeated `!` while one is pending coalesce: the latest body replaces the
// stashed inbound, the original deadline is preserved (bounded wait).
const toolFlightTracker = new ToolFlightTracker()

interface PendingDeferredInterrupt {
  agentName: string
  inboundMsg: InboundMessage
  chatId: string
  msgId: number | null
  threadId: number | undefined
  registeredAt: number
  deadlineTimer: ReturnType<typeof setTimeout>
}
let pendingDeferredInterrupt: PendingDeferredInterrupt | null = null

/**
 * Fire a stashed deferred interrupt: SIGINT the (now safely-bounded) turn via
 * tmux, then deliver the replacement body as a fresh inbound — the same two
 * primitives the synchronous `!` path uses, just gated on a clean boundary.
 * Idempotent: nulls the slot and clears the timer before doing any work so a
 * boundary event and the timeout can't double-fire.
 */
function cancelInterruptedObligation(): void {
  obligationWiring().cancelInterruptedObligation()
}

async function fireDeferredInterrupt(reason: 'boundary' | 'timeout'): Promise<void> {
  const pending = pendingDeferredInterrupt
  if (pending == null) return
  pendingDeferredInterrupt = null
  clearTimeout(pending.deadlineTimer)

  const waitedMs = Date.now() - pending.registeredAt
  process.stderr.write(
    `telegram gateway: deferred-interrupt firing reason=${reason} agent=${pending.agentName} ` +
    `chat=${pending.chatId} waited_ms=${waitedMs} in_flight=${toolFlightTracker.inFlightCount()}\n`,
  )

  try {
    const { sendAgentInterrupt } = await import('../../src/agents/tmux.js')
    const r = sendAgentInterrupt({ agentName: pending.agentName })
    if ('ok' in r) {
      process.stderr.write(
        `telegram gateway: deferred-interrupt SIGINT delivered via tmux send-keys agent=${pending.agentName}\n`,
      )
    } else {
      process.stderr.write(
        `telegram gateway: deferred-interrupt SIGINT via tmux failed agent=${pending.agentName}: ${r.error}\n`,
      )
    }
  } catch (err) {
    process.stderr.write(`telegram gateway: deferred-interrupt SIGINT failed: ${(err as Error).message}\n`)
  }

  // The SIGINT just killed the in-flight turn — cancel its obligation so the
  // interrupted (user-redirected) question isn't re-presented/escalated later.
  cancelInterruptedObligation()

  // Deliver the replacement body as a fresh turn to the freshly-killed
  // bridge — same sendToAgent + buffer-on-miss primitive the synchronous
  // interrupt carve-out uses at the handleInbound delivery site.
  const delivered = ipcServer.sendToAgent(pending.agentName, pending.inboundMsg)
  if (!delivered) {
    pendingInboundBuffer.push(pending.agentName, pending.inboundMsg)
    process.stderr.write(
      `telegram gateway: deferred-interrupt body buffered (bridge miss) agent=${pending.agentName} chat=${pending.chatId}\n`,
    )
  }
}

// #3020 — halt-now (the operator kill switch: empty `!`, `/stop`, bare "stop").
//
// Unlike a `!` interrupt WITH a body (which stashes a replacement inbound in
// `pendingDeferredInterrupt` and re-delivers it), a halt has no replacement:
// the operator just wants the in-flight turn dead. Shared sequence:
//   1. Honor the safe-boundary deferral (same `decideInterruptTiming` +
//      max-wait config the `!` path uses) so we don't C-c mid-tool-call.
//   2. SIGINT via tmux send-keys (`sendAgentInterrupt`) — the same primitive
//      the `!` path fires.
//   3. Cancel the killed turn's obligation (the user explicitly cancelled it;
//      re-presenting it later would be wrong).
//   4. Deterministically release the turn's busy state. With no replacement
//      inbound there is no later event guaranteed to end the turn — an
//      interrupted claude turn may never emit `turn_end`, and leaning on the
//      busy-key reaper leaves the chat gated for minutes. Same primitives
//      the reply path uses (`endCurrentTurnAtomic` + `releaseTurnBufferGate`),
//      both idempotent, reaper stays as backstop. The obligation cancel in
//      step 3 runs FIRST so `endCurrentTurnAtomic`'s no-reply branch is a
//      ledger no-op instead of stamping a grace clock on a cancelled turn.
//
// The boundary wait is event-driven: `waitForSafeBoundary` parks a waiter
// that the session-event ingest kicks (`notifyHaltBoundaryWaiters`) whenever
// the tracker might have drained, with the configured max-wait as the bound.

const haltBoundaryWaiters = new Set<() => void>()

function notifyHaltBoundaryWaiters(): void {
  if (haltBoundaryWaiters.size === 0) return
  for (const check of [...haltBoundaryWaiters]) check()
}

function waitForSafeBoundary(maxWaitMs: number): Promise<'boundary' | 'timeout'> {
  if (!toolFlightTracker.isMidToolCall()) return Promise.resolve('boundary')
  return new Promise(resolve => {
    let done = false
    const finish = (reason: 'boundary' | 'timeout') => {
      if (done) return
      done = true
      clearTimeout(timer)
      haltBoundaryWaiters.delete(check)
      resolve(reason)
    }
    const timer = setTimeout(() => finish('timeout'), maxWaitMs)
    const check = () => {
      if (!toolFlightTracker.isMidToolCall()) finish('boundary')
    }
    haltBoundaryWaiters.add(check)
  })
}

// #3020 item 4 — a halted turn may be suspended INSIDE an MCP permission
// call with a live Approve/Deny card in chat. The card's pending entry keeps
// the buffer gate closed (`hasPendingApproval`), and a later Approve tap
// would dispatch a verdict into an idle session. Deny each pending request
// (unblocking the suspended call before/as the C-c lands) and edit its
// card(s) to a cancelled state with the keyboard stripped.
function cancelPendingPermissionsForHalt(origin: string): void {
  if (pendingPermissions.size === 0) return
  for (const [requestId, details] of pendingPermissions) {
    // halted-turn-verdict: the turn this card parked is being KILLED by the
    // operator — there is nothing to resume, so no resumeReactionAfterVerdict
    // / postPermissionResumeMessage pairing. The card edit ("⏹ Cancelled")
    // is the visible terminal state and the /stop reply is the operator ack.
    dispatchPermissionVerdict({
      type: 'permission',
      requestId,
      behavior: 'deny',
      message: 'Cancelled — the operator stopped this turn. Do not retry.',
    })
    void stripCancelledPermissionCards(details.card_text, details.cards)
    pendingPermissions.delete(requestId)
    permCardStore.remove(requestId)
    reconcileBlockedApprovals()
    process.stderr.write(
      `telegram gateway: halt-now cancelled pending permission origin=${origin} ` +
      `request=${requestId} tool=${details.tool_name}\n`,
    )
  }
}

async function stripCancelledPermissionCards(
  cardText: string,
  cards: PermissionCardRef[],
): Promise<void> {
  for (const edit of buildCancelledCardEdits(cardText, cards)) {
    await swallowingApiCall(
      // allow-raw-bot-api: routed through swallowingApiCall (retry policy); message-id-targeted edit (no thread to lose). Passing {} as opts (no reply_markup) strips the stale Allow/Deny keyboard atomically with the text edit.
      () => bot.api.editMessageText(edit.chatId, edit.messageId, richMessage(edit.text), {}),
      { chat_id: edit.chatId, verb: 'permission_halt.strip' },
    )
  }
}

async function executeHaltNow(origin: string): Promise<void> {
  const agentName = process.env.SWITCHROOM_AGENT_NAME
  if (!agentName) return
  // #3020 item 3 — snapshot the halt target at request entry. The boundary
  // wait below can park for seconds; if the targeted turn ends naturally in
  // that window and a NEW turn starts, firing the C-c would kill an innocent
  // turn the requester never saw. Identity is the currentTurn object itself
  // (registryKey included, for the log line).
  const haltTarget = currentTurn
  const haltTargetKey = haltTarget?.registryKey ?? null
  const access = loadAccess()
  const timing = decideInterruptTiming({
    safeBoundaryEnabled: resolveSafeBoundaryEnabled(access.interruptSafeBoundary),
    midToolCall: toolFlightTracker.isMidToolCall(),
  })
  const startedAt = Date.now()
  if (timing === 'defer') {
    const maxWaitMs = resolveInterruptMaxWaitMs(access.interruptMaxWaitMs)
    const reason = await waitForSafeBoundary(maxWaitMs)
    process.stderr.write(
      `telegram gateway: halt-now boundary-wait origin=${origin} reason=${reason} ` +
      `waited_ms=${Date.now() - startedAt} in_flight=${toolFlightTracker.inFlightCount()}\n`,
    )
  }
  // #3020 item 3 — wrong-turn kill guard: if the turn changed while we
  // waited (the target ended naturally; a new turn may already be running),
  // no-op the C-c AND the teardown — the requester's turn already ended and
  // the current busy/permission state belongs to someone else. This also
  // skips the benign-but-pointless idle-session C-c when target-ended → idle.
  if (currentTurn !== haltTarget) {
    process.stderr.write(
      `telegram gateway: halt-now skipped — turn changed during boundary wait ` +
      `origin=${origin} target_key=${haltTargetKey ?? 'none'} ` +
      `current_key=${currentTurn?.registryKey ?? 'none'}\n`,
    )
    return
  }
  try {
    // Same tmux-direct rationale as the `!` path: the gateway runs inside the
    // agent container, so PID-probing interruptAgent can't work — send-keys can.
    const { sendAgentInterrupt } = await import('../../src/agents/tmux.js')
    const r = sendAgentInterrupt({ agentName })
    if ('ok' in r) {
      process.stderr.write(
        `telegram gateway: halt-now SIGINT delivered via tmux send-keys origin=${origin} agent=${agentName}\n`,
      )
    } else {
      process.stderr.write(
        `telegram gateway: halt-now SIGINT via tmux failed origin=${origin} agent=${agentName}: ${r.error}\n`,
      )
    }
  } catch (err) {
    process.stderr.write(`telegram gateway: halt-now SIGINT failed origin=${origin}: ${(err as Error).message}\n`)
  }
  // The SIGINT just killed the in-flight turn — cancel its obligation so the
  // cancelled question isn't re-presented/escalated later. Must run before the
  // teardown below (it reads `currentTurn`).
  cancelInterruptedObligation()
  // Item 4 — deny + strip any Approve/Deny cards belonging to the halted
  // turn so the buffer gate (`hasPendingApproval`) opens and a later tap
  // can't dispatch into an idle session.
  cancelPendingPermissionsForHalt(origin)
  // Deterministic busy release (step 4 above).
  const turn = currentTurn
  if (turn != null) {
    // Stamp the registry row as a CLEAN end (`endedVia: 'stop'`). A killed
    // turn never emits the session `turn_end` event, so without this the row
    // stays open (`ended_at IS NULL`) and `findLatestTurnIfInterrupted` would
    // fire a resume_interrupted synthetic for it at the next boot — resuming
    // work the operator explicitly cancelled. 'stop' is the resume gate's
    // "ended cleanly" verdict, which is exactly what a deliberate cancel is.
    if (turnsDb != null && turn.registryKey != null) {
      const _turnKey = turn.registryKey
      try {
        recordTurnEnd(turnsDb, {
          turnKey: _turnKey,
          endedVia: 'stop' as const,
          lastAssistantMsgId: turn.lastAssistantMsgId,
          lastAssistantDone: turn.lastAssistantDone,
          toolCallCount: turn.toolCallCount,
        })
      } catch (err) {
        process.stderr.write(`telegram gateway: recordTurnEnd(halt) failed turnKey=${_turnKey}: ${(err as Error).message}\n`)
      }
    }
    const key = statusKey(turn.sessionChatId, turn.sessionThreadId)
    endCurrentTurnAtomic(turn)
    releaseTurnBufferGate(key, turn)
  }
  // #3020 item 5 — the busy release above may have opened the idle gate, and
  // no turn_end event follows a halt to trigger the usual idle-drain hook.
  // Kick the queued session-command drain now so a queued /model or /effort
  // applies promptly instead of waiting for the 60s reaper.
  if (!turnInFlightForGate()) void drainPendingSessionCommand()
}

// #549 fix — preamble suppression for the answer-stream path.
//
// Background: assistant text emitted before a tool_use is "preamble"
// (think-out-loud guidance about what's about to happen). The
// progress-card driver consumes preamble as a narrative row for the
// upcoming tool. Independently, the answer-stream path was sending the
// same text to chat as a standalone message — user saw it twice (#549).
//
// The buffering policy lives in `preamble-suppressor.ts` so it can be
// unit-tested without spinning the whole gateway. The suppressor's
// `emitAnswer` callback is what bridges back to `activeAnswerStream` —
// when text is promoted from "pending" to "answer text", we update the
// stream with the cumulative answer-only payload (excluding preamble).
const preambleSuppressor = new PreambleSuppressor({
  emitAnswer: (cumulative) => {
    // Re-reads currentTurn at call time on purpose: the suppressor is
    // long-lived and flushes can occur outside any session-event
    // handler's scope. If the turn has been cleared, the update is
    // dropped (no chat to send to, no stream to mutate).
    //
    // PR-4e — the module-scope suppressor carries NO per-topic key (it is a
    // single global instance reset/flushed per turn), so there is no key to
    // scope by here: the correct resolution under BOTH flag states is the
    // most-recent-set live turn — exactly the singleton mirror `currentTurn`.
    // The per-turn `reset()` / `flushNow()` / `dropNow()` lifecycle (driven from
    // the live turn's own handlers) keeps the suppressor aligned with whichever
    // topic is currently live, so the mirror read is byte-identical to base and
    // cannot leak A's answer text into B (a flush for A runs while A is still the
    // most-recent turn; once B flips, A's stream is already force-superseded).
    const stream = currentTurn?.answerStream ?? null
    if (stream != null) stream.update(cumulative)
  },
})

/**
 * Telegram chat-id convention: positive ids are private chats (DM with a
 * user; chat.id === user.id). Negative ids are groups, supergroups, or
 * channels. Used to pick the answer-stream transport without an extra
 * getChat round-trip.
 */
function isDmChatId(chatId: string | null | undefined): boolean {
  if (!chatId) return false
  const id = Number(chatId)
  return Number.isFinite(id) && id > 0
}

// Phase 1 of #332: extract the plain-text body from the channel XML wrapper
// produced by the Telegram MCP plugin. The wrapper looks like:
//   <channel source="telegram" chat_id="..." ...>user text here</channel>
// We strip the outer tag and return a ~200-char preview for the turns table.
const TURN_PREVIEW_MAX = 200
function extractUserPromptPreview(rawContent: string): string | null {
  const m = rawContent.match(/<channel[^>]*>([\s\S]*?)<\/channel>/)
  const body = m ? m[1].trim() : rawContent.trim()
  if (!body) return null
  return body.length > TURN_PREVIEW_MAX ? body.slice(0, TURN_PREVIEW_MAX) : body
}

const CONTEXT_EXHAUSTION_COOLDOWN_MS = 10 * 60 * 1000
let lastContextExhaustionWarningAt = 0

let pendingPtyPartial: string | null = null

// statusKey + streamKey are thin re-exports of the canonical chatKey()
// constructor (see telegram-plugin/gateway/chat-key.ts). chatKey()
// collapses 0/null/undefined thread IDs to the same token (`_`),
// closing the sibling-key class behind #1564 (where one site set the
// entry under `null → _` and another cleared under `0 → 0`, leaving
// activeTurnStartedAt non-empty forever).
function statusKey(chatId: string, threadId?: number | null): string {
  return chatKey(chatId, threadId)
}

function streamKey(chatId: string, threadId?: number | null): string {
  return chatKey(chatId, threadId)
}

// PR1 (cross-turn stale-card guard, design §9 lever 4 / race C/D).
// `obligationSweep` writes one entry here, keyed on the obligation's
// `originTurnId`, the instant it pushes an `obligation_represent` inbound —
// carrying the obligation's `openedAt` (when the obligation was RAISED). The
// represent inbound reuses the obligation's chat/thread/messageId, so the
// `enqueue` that spawns the synthetic represent turn reconstructs the SAME
// `deriveTurnId` value as the key. That represent turn — and ONLY that turn —
// consumes and clears it, stamping `turn.crossTurnGate = { sinceMs: openedAt }`.
// That turn's first card-OPEN then consults `hasOutboundDeliveredSince(chat,
// openedAt)` and is suppressed iff a SUBSTANTIVE answer already landed since the
// obligation was raised — so a "thinking…" card never narrates beneath an answer
// the user already received in the original turn. Keying on `originTurnId` (not
// chat/thread) means an unrelated later foreground turn on the same chat/thread
// derives a different turn id, finds no entry, and is never mis-gated — closing
// the residual cross-contamination window where a represent that was armed but
// never enqueued (degenerate bridge-death) left a stale chat/thread-keyed gate
// that the next foreground turn could wrongly consume. A normal foreground turn
// never has an entry here, so the gate stays scoped to the synthetic surface.
// The map holds at most one entry per obligation; re-arming the same obligation
// overwrites its own entry with the latest openedAt.
const pendingCrossTurnGate = new Map<string, { sinceMs: number }>()

// ─── Turn-END funnel — extracted to turn-end.ts (#2996 P8 PR-B) ───────────
// The funnel bodies (`endCurrentTurnAtomic`, `purgeReactionTracking`,
// `releaseTurnBufferGate`) and the drain chokepoint (`performBufferDrain`,
// `drainBufferedIfAllowed`, `armNoReplyDrainTimer`) moved VERBATIM to
// `turn-end.ts`, parameterised by `gatewayTurnEndDeps()` below (the
// stream-render deps-builder idiom: state stays here, logic moved). The thin
// function-declaration wrappers keep every callsite — stream-render deps,
// the halt path, disconnect-flush, the silence-poke framework fallback,
// executeReply's gate release, and the __inboundRouterTestSeam — byte-identical.
//
// M2 (design amendment): the purge tail's pending-restart drain
// (`pendingRestarts` → `triggerSelfRestart('turn-complete-pending-restart')`
// behind `!turnInFlightForGate()`) crosses in the deps EXPLICITLY — omitting
// it would leave a queued /restart never firing at turn-complete (pinned by
// harness case 8 in tests/turn-lifecycle-characterization.test.ts).

/** Live gateway deps for the extracted turn-end funnel. Stable consts /
 *  function-decls / store singletons, plus volatile GETTERS for the
 *  boot-assigned or per-turn-mutated handles (`currentTurn`, `inboundSpool`,
 *  `ipcServer`) — the P9 getter funnel (clusters B/D). Built lazily on the
 *  first turn end, long after boot wiring assigned the singletons. */
function gatewayTurnEndDeps() {
  return {
    SERIALIZE_UNTIL_REPLIED_ENABLED,
    SERIALIZE_NOREPLY_DRAIN_MS,
    OBLIGATION_LEDGER_ENABLED,
    getCurrentTurn: (): CurrentTurn | null => currentTurn,
    getInboundSpool: (): ReturnType<typeof createInboundSpool> | undefined => inboundSpool,
    sendToAgent: (agent: string, m: InboundMessage): boolean => ipcServer.sendToAgent(agent, m),
    turnInFlightForGate,
    turnLiveForItsTopic,
    endCurrentTurnForKey,
    clearAllCurrentTurns,
    statusKey,
    reapQueuedStatus,
    stopTurnTypingLoop,
    stopEarlyLivenessOpen,
    reconcileStatusPin,
    trackRedeliveredInbound,
    drainPendingSessionCommand,
    triggerSelfRestart,
    maybeProactiveCompact,
    snapshotContextOccupancy,
    emitTurnRecord,
    flushPendingUserFailureNotices,
    clearAnswerReadyFlushTimeout,
    shadowEmit,
    removeActiveReaction,
    resolveAgentDirFromEnv,
    activeStatusReactions,
    activeReactionMsgIds,
    activeTurnStartedAt,
    busyAckPostedKeys,
    busyAckRecheckTimers,
    reactionTransitionCounts,
    firstTextReplyLogged,
    pendingRestarts,
    pendingInboundBuffer,
    obligationLedger,
  }
}
export type TurnEndDeps = ReturnType<typeof gatewayTurnEndDeps>

// Lazy singleton: built on first use so the deps close over post-boot state
// (`pendingInboundBuffer` et al are declared later in this file; by the first
// real turn end everything is assigned). Function-declaration wrappers (never
// reassigned bindings) so by-name captures (stream-render deps, the
// deferredDoneReactions purge arrow) resolve at call time, as before.
// PR-E (#2996 P8) — deterministic kill switch for the endTurn(reason)
// consolidation. Default OFF during bake: the wrappers below run the PR-B code
// paths verbatim. =1 routes every wrapper (and the two ghost-clear callsites)
// through the single `endTurn` dispatcher — same code, one auditable entry
// point. Module-load const: flipping requires an agent restart (P7 F2).
const TURN_END_FUNNEL_V2 = process.env.SWITCHROOM_TURN_END_FUNNEL_V2 !== '0'  // default ON (canary-validated v0.18.33); escape hatch =0

let _turnEndFunnel: ReturnType<typeof createTurnEndFunnel> | undefined
function turnEndFunnel(): ReturnType<typeof createTurnEndFunnel> {
  return (_turnEndFunnel ??= createTurnEndFunnel(gatewayTurnEndDeps()))
}

function performBufferDrain(reason: string): void {
  turnEndFunnel().performBufferDrain(reason)
}

function drainBufferedIfAllowed(endingTurn: CurrentTurn | undefined, reason: string): void {
  turnEndFunnel().drainBufferedIfAllowed(endingTurn, reason)
}

function armNoReplyDrainTimer(turn: CurrentTurn): void {
  turnEndFunnel().armNoReplyDrainTimer(turn)
}

function purgeReactionTracking(key: string, endingTurn?: CurrentTurn): void {
  if (TURN_END_FUNNEL_V2) { turnEndFunnel().endTurn('fallback-purge', { key, endingTurn }); return }
  turnEndFunnel().purgeReactionTracking(key, endingTurn)
}

function releaseTurnBufferGate(key: string, endingTurn?: CurrentTurn): void {
  if (TURN_END_FUNNEL_V2) { turnEndFunnel().endTurn('reply-gate-release', { key, endingTurn }); return }
  turnEndFunnel().releaseTurnBufferGate(key, endingTurn)
}

function endCurrentTurnAtomic(
  turn: CurrentTurn,
  opts?: { deferRecord?: boolean; deferObligationClose?: boolean },
): number | null {
  if (TURN_END_FUNNEL_V2) return turnEndFunnel().endTurn('turn-end', { turn, opts }) ?? null
  return turnEndFunnel().endCurrentTurnAtomic(turn, opts)
}

