// Run all four agent-initiated approval-card expiry sweeps. Called from the
// pendingStateReaper (the authoritative 60s timer). Each family sweep is
// per-entry guarded via sweepExpiredEntries, so one throwing expiry (dead IPC
// socket, store IO error) can't skip the remaining entries or families.
function sweepExpiredApprovalCards(now: number): void {
  pendingVaultRequestAccesses.sweep(now)
  pendingVaultRequestSaves.sweep(now)
  pendingMentalModelProposes.sweep(now)
  sweepSecretRequests(now)
}

// Boot restore: repopulate the four in-memory approval-card maps from the
// durable store so a post-restart tap on a still-valid card resolves normally
// (approve → grant + synthetic; deny → denial synthetic) instead of hitting
// the "Card expired" tombstone. Entries already past their TTL are left for
// the reaper's next tick, which wakes the parked agent via the timeout path.
// vault_request_save entries restore WITHOUT their staged value (never
// persisted) and are flagged `restoredWithoutValue` so a Save tap degrades
// gracefully rather than writing an empty secret.
function restorePendingApprovalCards(): number {
  let restored = 0
  for (const e of pendingCardStore.loadAll()) {
    try {
      if (e.family === 'vault_request_access') {
        pendingVaultRequestAccesses.set(e.stageId, {
          agent: e.agent,
          chat_id: e.chatId,
          ...(e.cardMessageId != null ? { card_message_id: e.cardMessageId } : {}),
          ...(e.threadId != null ? { threadId: e.threadId } : {}),
          key: e.key,
          scope: e.scope,
          ...(e.reason != null ? { reason: e.reason } : {}),
          ttl_seconds: e.ttlSeconds,
          staged_at: e.stagedAt,
        })
        restored++
      } else if (e.family === 'vault_request_save') {
        pendingVaultRequestSaves.set(e.stageId, {
          agent: e.agent,
          chat_id: e.chatId,
          ...(e.cardMessageId != null ? { card_message_id: e.cardMessageId } : {}),
          ...(e.threadId != null ? { threadId: e.threadId } : {}),
          key: e.key,
          kind: e.kind,
          value: '', // never persisted — secrets hygiene
          ...(e.why != null ? { why: e.why } : {}),
          staged_at: e.stagedAt,
          restoredWithoutValue: true,
        })
        restored++
      } else if (e.family === 'request_secret') {
        pendingSecretRequests.set(e.stageId, {
          agent: e.agent,
          chat_id: e.chatId,
          ...(e.cardMessageId != null ? { card_message_id: e.cardMessageId } : {}),
          ...(e.threadId != null ? { threadId: e.threadId } : {}),
          key: e.key,
          ...(e.reason != null ? { reason: e.reason } : {}),
          staged_at: e.stagedAt,
        })
        restored++
      } else if (e.family === 'mental_model_propose') {
        pendingMentalModelProposes.set(e.stageId, {
          agent: e.agent,
          chat_id: e.chatId,
          ...(e.cardMessageId != null ? { card_message_id: e.cardMessageId } : {}),
          ...(e.threadId != null ? { threadId: e.threadId } : {}),
          spec: e.spec,
          ...(e.reason != null ? { reason: e.reason } : {}),
          staged_at: e.stagedAt,
        })
        restored++
      }
    } catch (err) {
      process.stderr.write(
        `telegram gateway: pending-card restore skipped a malformed entry: ${(err as Error).message}\n`,
      )
    }
  }
  if (restored > 0) {
    process.stderr.write(
      `telegram gateway: restored ${restored} pending approval card(s) from prior gateway session\n`,
    )
  }
  return restored
}

/**
 * Post the Approve/Deny card for `requestId` to every permission-card target.
 *
 * Extracted from `onPermissionRequest` (#3084 follow-up) so it has TWO callers:
 * the initial delivery, and the reaper's held-card re-delivery once a flood
 * window closes. Both paths must behave identically — same routing, same
 * thread-fallback, same landed-card bookkeeping, same hold-on-flood-wait — so
 * there is exactly one implementation of "post this card".
 *
 * Everything it needs is rebuilt from the pending entry, so a re-delivery an
 * hour later renders the same card the operator would have seen at T+0.
 */
function postPermissionCard(
  requestId: string,
  pend: NonNullable<ReturnType<typeof pendingPermissions.get>>,
): void {
  // Register the in-flight flag HERE, not at the call sites, so BOTH callers are
  // covered. The sweep used to add it itself, but the ipcServer initial-delivery
  // call site did not — so a reaper tick landing between window-close and a slow
  // in-flight INITIAL send settling could post a duplicate card. One registration
  // point, one release point (the `.finally` below / the sync-throw catch).
  heldCardsInFlight.add(requestId)

  // One increment per ATTEMPT, not per failing target. `targets` is N-wide and
  // every failing target runs the same `.catch` — incrementing there ratcheted
  // the backoff ladder N× faster than the documented 1m/2m/4m…30m. Compute the
  // attempt number once, up front; every failing target stamps the SAME value.
  const attemptFailures = (pend.redeliveryFailures ?? 0) + 1

  try {
  const text = pend.card_text
  const showAlways =
    resolveScopedAllowChoices(pend.tool_name, pend.input_preview) != null
  const keyboard = buildPermissionActionRow(requestId, showAlways)
  // Route the card to the SAME place the post-verdict resume message lands
  // (resolvePermissionCardTargets): the ORIGINATING chat+topic when there's an
  // active turn — so a supergroup agent's card appears IN the topic the
  // operator asked from (marko's "CRM (Brevo)"), not the operator DM — else the
  // configured operator DMs, thread-stripped. The old code iterated `allowFrom`
  // unconditionally, so a supergroup card could only ever reach operator DMs
  // (the topic chat id is never in `allowFrom`) (marko, 2026-06-03).
  const targets = resolvePermissionCardTargets()

  // ONE settle across ALL targets, not one per target (reviewer F1).
  //
  // The in-flight flag (guard iii) exists so the reaper can't re-post a card whose
  // previous post hasn't settled. `resolvePermissionCardTargets()` returns N
  // targets — it ends in `allowFrom.map(...)` — and on the RE-delivery path N>1 is
  // the COMMON case: re-delivery after a multi-hour ban is by construction past the
  // 30-min origin-recovery window, so it falls through to the operator-DM fan-out.
  // Clearing the flag per-target released it the moment the FIRST target settled
  // while others were still in flight, and the next tick re-posted to all of them —
  // a double delivery. Settle once, when every target is done.
  const sends = targets.map(({ chatId, threadId }) => {
    // The rich-markdown path pairs with formatPermissionCardBody (#1790) so its
    // bold/italic render. retryWithThreadFallback: if the topic was
    // deleted/recreated (stale thread id → 400 "message thread not found"),
    // re-send thread-less into the main chat so the card still ARRIVES rather
    // than vanishing.
    // allow-raw-bot-api: wrapped in retryWithThreadFallback (retry policy); topic-aware send
    return retryWithThreadFallback<{ message_id: number; message_thread_id?: number }>(
      robustApiCall,
      (tid) =>
        bot.api.sendRichMessage(chatId, richMessage(text), {
          reply_markup: keyboard,
          ...(tid != null ? { message_thread_id: tid } : {}),
        }),
      { threadId, chat_id: chatId, verb: 'permission_request' },
    ).then(sent => {
      // Record the live card's (chat, message) so the reaper can strip its inline
      // keyboard — a stale Approve button left tappable dispatches a verdict for a
      // dead request_id (Bug 2). The entry may already be gone (operator tapped
      // before this resolved); guard the lookup.
      const live = pendingPermissions.get(requestId)
      if (live && sent && typeof sent.message_id === 'number') {
        // #2787: record where the card ACTUALLY LANDED so the confirm sweep scopes
        // its re-delivery suspension to the real chat/topic. `sent.message_thread_id`
        // reflects reality in all three cases: topic success → tid, main-chat /
        // fallback → undefined.
        const landedThreadId = sent.message_thread_id ?? undefined
        live.cards.push({ chatId, messageId: sent.message_id, threadId: landedThreadId })
        // The card LANDED — the operator can see and tap it, so the block is over.
        // Drop the hold mark, reset the TTL clock, and reconcile the off-Telegram
        // surface — as ONE shared decision (`applyDeliveredHoldReset`, #3128) that
        // the outcome test's harness ALSO drives, so deleting the `startedAt` reset
        // turns the behavioural `(d2)` test red instead of only a fragile grep.
        // PR 3: the reset is load-bearing — the TTL measures how long the operator
        // had to answer, and until this moment they had nothing to answer.
        if (applyDeliveredHoldReset(live, Date.now())) {
          reconcileBlockedApprovals()
          process.stderr.write(
            `telegram gateway: permission-card RE-DELIVERED request=${requestId} ` +
            `tool=${live.tool_name} chat=${chatId} — the operator can answer now; ` +
            `TTL clock restarted (they had zero seconds while the channel was shut)\n`,
          )
        }
        permCardStore.add({
          requestId,
          chatId,
          messageId: sent.message_id,
          startedAt: live.startedAt,
          toolName: live.tool_name,
          cardText: live.card_text,
        })
      }
    }).catch(e => {
      process.stderr.write(`telegram gateway: permission_request send to ${chatId} failed: ${e}\n`)
      const live = pendingPermissions.get(requestId)
      if (live == null) return // operator already resolved it — nothing to hold

      // A card already landed on ANOTHER target, so the ask is NOT undeliverable —
      // the operator can see and tap it (reviewer F2). Marking it held here would be
      // a PERMANENT wedge: `selectHeldForRedelivery` skips entries that have cards,
      // so the mark could never be cleared, and PR 3's TTL freeze would then keep
      // the entry alive forever with the surface stuck on "blocked".
      if (live.cards.length > 0) return

      // The card did NOT land anywhere. Before this the error was logged and
      // dropped: the entry sat with `cards: []`, the operator saw nothing, and 60
      // minutes later the TTL sweep AUTO-DENIED an approval no human had ever been
      // shown. Now we hold it — but only for a TRANSIENT cause. `holdReasonFor`
      // decides; a permanent 400 (a card that will never format) still falls through
      // to the TTL, which PR 3 makes safe by giving the no-card timeout a
      // missed-approvals fallback.
      const reason = holdReasonFor(e)
      if (reason == null) return

      // Bound the RATE, never the RETRY. A held entry is re-selected every tick, so a
      // target that keeps failing would otherwise re-send every 60s forever — the
      // amplifier this series exists to avoid. Back off instead (1m, 2m, 4m … 30m).
      // We never STOP retrying: a terminal give-up would strand the card even after
      // the channel recovered, and because turnInFlightForGate() holds the inbound
      // gate while a permission is pending, that would silently buffer the operator's
      // messages forever. Escalate the surface, never the verdict — and never abandon
      // the card.
      const failures = attemptFailures
      live.redeliveryFailures = failures
      const now = Date.now()
      // A flood-wait carries Telegram's own window end; everything else backs off.
      const retryableAt = isFloodWaitActiveError(e) ? e.untilTs : now + heldRetryBackoffMs(failures)
      // `since` is set ONCE — it is when the block began, not when we last retried.
      live.undeliverable = { since: live.undeliverable?.since ?? now, retryableAt, reason }
      // Reconcile the shared surface SYNCHRONOUSLY, here in the failure handler — not
      // on the 60s reaper tick. The operator is locked out of Telegram; this record is
      // the only way they learn an agent is blocked, so it must be live in under a
      // second, not up to a minute.
      reconcileBlockedApprovals()
      process.stderr.write(
        `telegram gateway: permission-card HELD (undeliverable) request=${requestId} ` +
        `tool=${live.tool_name} reason=${reason} attempt=${failures} ` +
        `retryable_at=${new Date(retryableAt).toISOString()}` +
        ` — approval is held, NOT denied; re-delivering when the channel returns ` +
        `(backoff ${Math.round(heldRetryBackoffMs(failures) / 60000)}m)\n`,
      )
    })
  })

  // Settle ONCE, after every target. `allSettled` never rejects, so the flag is
  // always released — including when `targets` is empty (no active turn AND no
  // configured operator DM), in which case `sends` is [] and this resolves at once.
  void Promise.allSettled(sends).finally(() => {
    heldCardsInFlight.delete(requestId)
  })
  } catch (e) {
    // A SYNCHRONOUS throw (resolveScopedAllowChoices / buildPermissionActionRow /
    // resolvePermissionCardTargets) never reaches the `.finally` above — without
    // this catch the in-flight flag would leak and the request would never be
    // re-selected by the sweep. Release the flag, then rethrow so the caller
    // (the sweep's own try/catch, or the ipc handler) sees the failure.
    heldCardsInFlight.delete(requestId)
    throw e
  }
}

/**
 * Request ids whose card post is mid-flight — INITIAL delivery or re-delivery.
 * Guard (iii) against double-delivery: the 60s reaper must not re-post a card
 * whose previous post hasn't settled yet (a slow send would otherwise be
 * re-issued every tick). Registered at the top of postPermissionCard (so both
 * callers are covered) and cleared in its `.finally` — or its sync-throw catch.
 */
const heldCardsInFlight = new Set<string>()

/**
 * Re-deliver held permission cards once the flood window closes (#3084
 * follow-up, PR 2).
 *
 * The whole point of holding rather than auto-denying is that the ask comes
 * BACK. This is the half that brings it back.
 *
 * `selectHeldForRedelivery` owns the guards (window closed, held, no landed
 * card, not in flight, per-tick cap). `robustApiCall`'s own pre-call probe is a
 * further, independent short-circuit downstream — if the window re-opens
 * between selection and send, the send refuses itself and the entry is simply
 * re-marked with the longer window.
 *
 * The per-tick cap is the ban-safety property: a backlog of held cards must not
 * BURST the instant the window closes, because that burst is the one realistic
 * way this design could re-earn the ban it exists to survive. Deferred ids are
 * LOGGED, never silently dropped — they go out on the next tick.
 */
function sweepHeldPermissionCards(): void {
  const remaining = probeFloodWaitRemainingMs()
  const { send, deferred } = selectHeldForRedelivery(pendingPermissions.entries(), {
    floodRemainingMs: remaining,
    inFlight: heldCardsInFlight,
    now: Date.now(),
  })
  if (send.length === 0) return

  process.stderr.write(
    `telegram gateway: flood window closed — re-delivering ${send.length} held ` +
    `permission card(s)` +
    (deferred.length > 0
      ? `; ${deferred.length} deferred to the next tick by the per-tick cap ` +
        `(${deferred.join(', ')}) — deferred, NOT dropped`
      : '') + '\n',
  )
  for (const requestId of send) {
    const pend = pendingPermissions.get(requestId)
    if (pend == null) continue
    try {
      // postPermissionCard registers the in-flight flag itself (so the ipc
      // initial-delivery caller is covered too) and releases it once every
      // target settles — or on a sync throw, in its own catch.
      postPermissionCard(requestId, pend)
    } catch (e) {
      // A synchronous throw must not escape the setInterval callback (it would
      // kill the whole reaper tick, TTL sweep included). postPermissionCard has
      // already released the flag; delete again defensively so the entry is
      // re-selectable on the next tick, and log rather than rethrow.
      heldCardsInFlight.delete(requestId)
      process.stderr.write(
        `telegram gateway: held-card re-delivery for ${requestId} threw ` +
        `synchronously: ${e} — flag released, will retry on the next tick\n`,
      )
    }
  }
}

// 60-second sweep drops anything past its documented TTL.
const pendingStateReaper = isGatewayMain ? setInterval(() => {  // #2996 P0c gate
  const now = Date.now()
  // #3084 follow-up — bring held cards BACK the moment the channel reopens.
  // Runs before the TTL sweep below so a card that can be re-delivered on this
  // tick is re-delivered, not considered for expiry.
  sweepHeldPermissionCards()
  // OAuth-code state grouped first (pinned by secret-detect-oauth-code.test.ts).
  pendingReauthFlows.sweep(now)
  for (const [k, v] of pendingAuthAddFlows) {
    if (now - v.startedAt > REAUTH_INTERCEPT_TTL_MS) {
      cancelAccountAuthSession(v)
      pendingAuthAddFlows.delete(k)
    }
  }
  for (const [k, v] of awaitingAuthCodeAt) {
    if (now - v > AUTH_CODE_CONTEXT_TTL_MS) awaitingAuthCodeAt.delete(k)
  }
  // Loopback OAuth relay flows (issue #2582) — same TTL. Kill the waiting
  // CLI child so an abandoned consent never lingers with a bound listener.
  // Placed AFTER the OAuth-code cluster above, which secret-detect-oauth-
  // code.test.ts pins as contiguous within the first 800 chars of the
  // reaper (same precedent as the Microsoft connect sweep below). A flow
  // with a submit in flight is skipped (PR #3100 review finding 3): a paste
  // near the TTL boundary must not have its child killed mid-registration —
  // the submit path owns cleanup once `submitting` is set.
  for (const [k, v] of pendingLoopbackFlows) {
    if (v.submitting) continue
    if (now - v.startedAt > REAUTH_INTERCEPT_TTL_MS) {
      cancelLoopbackFlow(v)
      pendingLoopbackFlows.delete(k)
    }
  }
  // Microsoft connect flows self-expire at the device code's own expiry
  // (~15 min) — sweep past that + grace so an abandoned card doesn't pin
  // its key. Setting cancelled makes any still-running poll bail. Placed
  // AFTER the OAuth-code cluster above, which secret-detect-oauth-code.
  // test.ts pins as contiguous within the first 800 chars of the reaper.
  for (const [k, v] of pendingMicrosoftConnectFlows) {
    if (now - v.startedAt > v.device.expires_in * 1000 + 30_000) {
      v.cancelled = true
      pendingMicrosoftConnectFlows.delete(k)
    }
  }
  // Auth-refresh throttle entries decay quickly (5s window); sweep
  // anything older than 60s so abandoned snapshot messages don't pin
  // their key forever.
  for (const [k, v] of lastAuthRefreshAtMs) {
    if (now - v > 60_000) lastAuthRefreshAtMs.delete(k)
  }
  // /auth rm two-step confirm window — self-expires at `expiresAt`.
  for (const [k, v] of pendingAuthRmFlows) {
    if (now >= v.expiresAt) pendingAuthRmFlows.delete(k)
  }
  pendingVaultOps.sweep(now)
  // THE LEASH. The sweep — the guard AND the auto-deny it gates — now lives in
  // permission-ttl-sweep.ts, and the outcome test's harness drives that exact
  // function. It used to be an inline loop here while the harness kept a PRIVATE
  // copy of the guard, so deleting the real check left every behavioural assertion
  // GREEN and only a source-text grep noticed. A test that cannot fail is not a
  // test, and this is the test for `no-self-escalation`. One implementation, two
  // callers: there is no longer a gateway-side line whose deletion restores the
  // auto-deny without removing the sweep entirely.
  sweepPermissionTtl({
    entries: pendingPermissions,
    now,
    ttlForTool,
    onExpire: (k, v, ttl) => {
      // Don't just drop it: the claude turn is suspended INSIDE the MCP
      // permission call waiting for a verdict. A silent delete left it
      // wedged forever when the operator never tapped — permanent
      // silence, the exact symptom this series fixes. Auto-deny so the
      // call unblocks; claude then tells the user it couldn't get
      // permission (or takes a fallback). Routed through
      // dispatchPermissionVerdict so it's buffered+redelivered too if
      // the bridge is also offline at sweep time.
      // Carry a TIMEOUT reason to the model (claude renders it as "…the user
      // said: …") so it can tell a timeout from a real denial and not retry
      // the identical call — the duplicate-card loop this series closes.
      const timeoutMinutes = Math.round(ttl / 60000)
      dispatchPermissionVerdict({
        type: 'permission',
        requestId: k,
        behavior: 'deny',
        message: timeoutDenyMessage(timeoutMinutes),
      })
      // Strip the card's inline keyboard + mark it timed out (Bug 2 fix #1).
      // Before this, the reaper deleted the pending entry but left a LIVE
      // Approve button — a late operator tap then dispatched a verdict for an
      // already-resolved/dead request_id, which Claude Code ignores, so the
      // operator "approved" but work never continued. Stripping the keyboard
      // makes the timeout legible and removes the stale tappable button.
      void stripTimedOutPermissionCards(v.card_text, v.cards)
      // The auto-deny un-parks the suspended turn — flip 🙏 → working so
      // it doesn't sit on the awaiting glyph (or stall) after the timeout.
      resumeReactionAfterVerdict()
      postPermissionResumeMessage({
        behavior: 'deny',
        action: naturalAction(v.tool_name, v.input_preview),
        timeoutMinutes,
      })
      // Remember this (tool, input) timed out so an immediate identical retry
      // (while the operator is still absent) is short-circuited without a
      // second card. Cleared on operator activity.
      if (PERMISSION_NO_REPEAT_ENABLED) {
        permissionTimeoutSignatures.set(
          permissionSignature(v.tool_name, v.input_preview),
          now,
        )
      }
      // #2862 — record the miss so it can be re-offered when the operator
      // returns. Anchor to the card's own origin surface (where the operator
      // would have tapped), so the digest lands in the same topic — not a
      // fanned-out DM. Skip if the card was never posted anywhere.
      // The `cards[0]` hole (#3084 follow-up): this used to skip silently when the
      // card had never landed (`cards: []` → `origin === undefined`). That is
      // exactly the undeliverable case — so the request was auto-denied AND erased
      // from the only record that would have brought it back. The safety net had a
      // hole shaped exactly like the accident.
      //
      // Held entries no longer reach this code at all (the TTL freeze above skips
      // them), so this is belt-and-braces: ANY future path that times out a card
      // which never landed — including a PERMANENT 400, which holdReasonFor()
      // deliberately does not hold — still lands in the digest. Fall back to where
      // the card WOULD have gone.
      if (MISSED_APPROVAL_REOFFER_ENABLED) {
        const origin = v.cards[0] ?? resolvePermissionCardTargets()[0]
        if (origin != null) {
          missedApprovalsStore.add({
            requestId: k,
            toolName: v.tool_name,
            action: naturalAction(v.tool_name, v.input_preview),
            chatId: origin.chatId,
            threadId: origin.threadId ?? null,
            timedOutAt: now,
          })
        }
      }
      process.stderr.write(
        `telegram gateway: permission TTL expired — auto-deny request=${k} ` +
        `tool=${v.tool_name} (no operator response in ` +
        `${timeoutMinutes}m)\n`,
      )
      pendingPermissions.delete(k)
      permCardStore.remove(k)
      reconcileBlockedApprovals()
    },
  })
  // Drop no-repeat suppression entries past the safety-cap window (the primary
  // bound is the operator-activity reset; this just keeps the map from growing).
  for (const [sig, at] of permissionTimeoutSignatures) {
    if (now - at > PERMISSION_DUPLICATE_WINDOW_MS) permissionTimeoutSignatures.delete(sig)
  }
  vaultPassphraseCache.sweep(now)
  // Drop expired "⏱ 30 min" scoped grants. (Lookup already fails closed on
  // expiry; this just keeps the map from accumulating dead entries.) Persist
  // the removal so a restart between sweeps can't resurrect a swept grant —
  // only write when the sweep actually changed something (sweeps only remove).
  const scopedGrantsBefore = countScopedGrants(scopedGrants)
  sweepScopedGrants(scopedGrants, now)
  if (countScopedGrants(scopedGrants) !== scopedGrantsBefore) {
    scopedGrantStore.save(scopedGrants)
  }
  deferredSecrets.sweep(now)
  // Agent-initiated approval cards (vault_request_access / vault_request_save /
  // request_secret / mental_model_propose): expire past-TTL entries and WAKE
  // the parked agent (timeout synthetic + missed-approvals re-offer). This is
  // the authoritative timer — before this the only expiry path was a lazy
  // sweep on the NEXT stage, so an agent that ended its turn to wait on one of
  // these cards could sit parked forever if no further request ever staged.
  // try/catch matches the sibling sweepStaleTurnActiveMarker guard: an escaped
  // throw inside this setInterval callback would reach uncaughtException and
  // take the WHOLE gateway down (per-entry faults are already contained inside
  // sweepExpiredEntries/expirePendingCard; this is the outer belt).
  try {
    sweepExpiredApprovalCards(now)
  } catch (err) {
    process.stderr.write(
      `telegram gateway: approval-card expiry sweep failed: ${(err as Error).message}\n`,
    )
  }
  // #550: sweep a stale turn-active marker. Defence-in-depth for the
  // case where neither the turn_end arm nor onTurnComplete fired (SDK
  // killed before the JSONL turn_duration record, compaction window,
  // forceCompleteTurn silent no-op on torn-down card, etc). We use
  // currentTurnRegistryKey as the "is a turn in flight?" signal — when
  // null we sweep aggressively (>60s mtime), and we always sweep when
  // the marker is older than 10min regardless. Both bounds are well
  // under the watchdog's TURN_HANG_SECS=300s threshold for the in-
  // flight case but generous enough that real long-running tool calls
  // (which touch mtime on every tool_use) won't trip the idle path.
  //
  // Logging: include agent name + age + reason + payload so a marker
  // leak (or a real wedge) leaves enough breadcrumbs in journalctl to
  // diagnose without needing to inspect the file (which is gone after
  // the sweep). `journalctl -u switchroom-<agent>-gateway -g markersweep`
  // is the audit trail.
  try {
    sweepStaleTurnActiveMarker(STATE_DIR, {
      turnInFlight: currentTurn?.registryKey != null,
      idleSweepMs: TURN_ACTIVE_IDLE_SWEEP_MS,
      hardTtlMs: TURN_ACTIVE_HARD_TTL_MS,
      now,
      onRemove: ({ ageMs, reason, payload }) => {
        const agent = getMyAgentName()
        const ageSec = Math.round(ageMs / 1000)
        const turnInFlight = currentTurn?.registryKey != null
        const summary = summariseMarkerPayload(payload)
        process.stderr.write(
          `telegram gateway: [markersweep] removed agent=${agent} age=${ageSec}s reason=${reason} turn_in_flight=${turnInFlight} ${summary}\n`,
        )
      },
    })
  } catch { /* best-effort */ }
  // Drain cap: if a scheduled restart has been waiting >60s for a turn
  // to complete, force it through anyway (spec: 60s cap → SIGKILL fallback).
  //
  // Auto-fallback cooldown gate: if the persisted lockout shows we just
  // rotated this agent's slot inside the cooldown window, defer the
  // forced restart by another tick. This closes a churn window where a
  // 429-driven fallback already spawned a restart, and a parallel
  // schedule_restart IPC sat in pendingRestarts — without this gate the
  // drain cap would fire a SECOND restart 60s later. Bound: at most
  // FALLBACK_COOLDOWN_MS / 60s extra deferrals per pending restart.
  for (const [agentName, requestedAt] of pendingRestarts.entries()) {
    if (now - requestedAt > PENDING_RESTART_DRAIN_CAP_MS) {
      const waitedSec = Math.round((now - requestedAt) / 1000)
      const cooldownActive = isAutoFallbackCooldownActive(agentName, now)
      if (cooldownActive) {
        process.stderr.write(
          `telegram gateway: [restart-drain] deferred agent=${agentName} waited=${waitedSec}s reason=auto-fallback-cooldown-active\n`,
        )
        continue
      }
      process.stderr.write(
        `telegram gateway: [restart-drain] forcing agent=${agentName} waited=${waitedSec}s threshold=${Math.round(PENDING_RESTART_DRAIN_CAP_MS / 1000)}s\n`,
      )
      pendingRestarts.delete(agentName)
      triggerSelfRestart(agentName, 'restart-drain-cap-forced', 100)
    }
  }
  // Drain cap for queued /model|/effort commands (#3017): if the session
  // never cleanly idled, force the apply-or-report so the ack card never
  // dangles unresolved. drainPendingSessionCommand no-ops on an idle-gate race
  // (its own re-entrancy guard) and reports honestly when a restart is pending.
  // #3018 finding 1: NEVER force while a turn is genuinely in flight — a
  // forced mid-turn drain hits the typed model handler's busy gate (edits the
  // ack card into the old "try again" refusal, choice destroyed) and /effort
  // has no busy gate at all (would type into the live claude input). The cap
  // only rescues the missed-idle-gate case; mid-turn we keep waiting and the
  // idle gate drains at turn end.
  const queuedCmds = pendingSessionCommand.list()
  const cmdDecision = pendingCmdDrainCapDecision(
    queuedCmds,
    now,
    PENDING_CMD_DRAIN_CAP_MS,
    turnInFlightForGate(),
  )
  if (cmdDecision === 'defer-turn-in-flight') {
    process.stderr.write(
      `telegram gateway: [pending-cmd-drain] deferred reason=turn-in-flight queued=${queuedCmds.map(c => c.kind).join(',')}\n`,
    )
  } else if (cmdDecision === 'force') {
    const oldest = Math.min(...queuedCmds.map(c => c.requestedAt))
    process.stderr.write(
      `telegram gateway: [pending-cmd-drain] forcing queued=${queuedCmds.map(c => `${c.kind}:${c.targetLabel}`).join(',')} waited=${Math.round((now - oldest) / 1000)}s threshold=${Math.round(PENDING_CMD_DRAIN_CAP_MS / 1000)}s\n`,
    )
    void drainPendingSessionCommand()
  }
}, 60_000) : undefined
pendingStateReaper?.unref()

/**
 * Does a message look like a Claude setup-token browser code?
 *
 * The intercept path in the inbound-message handler uses this to decide
 * whether to treat a pending-reauth chat's next message as `/auth code`.
 * Return value drives whether the gateway hijacks the message or lets
 * it through to the agent bridge — false negatives are user-visible as
 * 'I pasted my code and nothing happened'.
 *
 * Format evolution:
 *   - Legacy:  opaque 20+ char alphanum+underscore+hyphen token
 *   - 2025+:   `sk-ant-...` API tokens emitted by setup-token
 *   - 2026+:   `<code>#<state>` format from the claude.com/cai
 *              authorize URL (see parseSetupTokenUrl regex). The `#`
 *              in the middle was the breakage surfaced 2026-04-22 —
 *              user's code starting with `tle0rm...#00EySj...` fell
 *              through because the character class missed `#`.
 *
 * Character class now includes `#` and `.` for future-proofing (dot
 * is common in JWT-style tokens). Length cap raised to 500 because
 * the new dual-section format is ~90+ chars and will likely grow.
 */
function looksLikeAuthCode(text: string): boolean {
  const trimmed = text.trim()
  if (!trimmed || /\s/.test(trimmed)) return false
  if (trimmed.startsWith('session_')) return true
  if (trimmed.startsWith('sk-ant-')) return true
  if (/^[A-Za-z0-9_.#-]{6,500}$/.test(trimmed)) return true
  return false
}

// ─── Coalescing ───────────────────────────────────────────────────────────
export type AttachmentMeta = {
  kind: string
  file_id: string
  size?: number
  mime?: string
  name?: string
}

// One attachment slot carried by a coalesced message — primary or extra.
type CoalesceAttachment = {
  downloadImage?: () => Promise<string | undefined>
  attachment?: AttachmentMeta
}

// CoalescePayload is what the InboundCoalescer carries per buffered message.
// `ctx` must be the *latest* message's context (latest message_id, etc.) so
// the merge function picks the last entry's ctx.
//
// Each inbound Telegram message carries at most one attachment, so an enqueued
// payload sets at most `downloadImage`/`attachment`. The merge collects every
// attachment-bearing entry in the window (up to coalesce.max_attachments): the
// first becomes the primary `downloadImage`/`attachment`, the rest ride along
// in `extraAttachments` (A2). When the cap is 1 (default), the
// handleInboundCoalesced guards still bypass a second attachment / album part
// to its own turn, so the single-attachment behaviour is byte-for-byte
// preserved.
type CoalescePayload = {
  text: string
  ctx: Context
  downloadImage?: () => Promise<string | undefined>
  attachment?: AttachmentMeta
  // Set only by `merge`: the 2nd..Nth attachments folded into this turn.
  extraAttachments?: CoalesceAttachment[]
  // Forwarded-message origin of THIS entry (parsed at enqueue time from
  // message.forward_origin). merged.ctx is the LAST entry's ctx, so a
  // coalesced burst would otherwise lose the earlier entries' origins —
  // each entry carries its own.
  forwardOrigin?: ForwardOriginInfo
  // Set only by `merge`: the distinct origins of the whole burst, arrival
  // order, deduped (a single-origin album collapses to one entry).
  forwardOrigins?: ForwardOriginInfo[]
}

// Count of attachment-bearing entries currently buffered per coalesce key.
// A new attachment for a key whose count has reached the per-agent cap
// (coalesce.max_attachments, default 10) bypasses coalescing (see
// handleInboundCoalesced) so no media is dropped past the cap. Cleared on
// flush (below) and on the synchronous bypass path.
const bufferedAttachmentKeys = new Map<string, number>()

function coalesceMaxAttachments(): number {
  return resolveCoalesceMaxAttachments(loadAccess().coalesceMaxAttachments)
}

const inboundCoalescer = createInboundCoalescer<CoalescePayload>({
  // Read per-call from the access file so an operator-tuned
  // channels.telegram.coalesce.window_ms (projected to coalescingGapMs by
  // scaffold) takes effect on the next message after apply+restart.
  //
  // Default lowered 1500 → 500 in #553 PR 3 to shrink the gateway-side
  // contribution to first-real-text latency.
  gapMs: () => loadAccess().coalescingGapMs ?? 500,
  merge: (entries) => {
    const last = entries[entries.length - 1]
    // Collect every attachment-bearing entry in arrival order. The first is
    // the primary (unsuffixed image_path/attachment_* meta); the remainder,
    // capped at max_attachments, become numbered extras. A [photo][text]
    // burst keeps its image even though the last entry is text-only.
    const { primary, extras } = splitCoalescedAttachments(
      entries,
      (e) => e.downloadImage != null || e.attachment != null,
      coalesceMaxAttachments(),
    )
    // Distinct forwarded-message origins across the burst, arrival order.
    // A forwarded album (one origin, N parts) collapses to a single entry
    // so the attrs are emitted once; a burst forwarded from two different
    // senders keeps both (numbered forwarded_from_2 siblings downstream).
    const forwardOrigins = dedupeForwardOrigins(entries.map((e) => e.forwardOrigin))
    return {
      // Drop empty texts (e.g. caption-less album parts) so the join doesn't
      // emit blank lines between attachments.
      text: entries.map((e) => e.text).filter((t) => t.length > 0).join('\n'),
      ctx: last.ctx,
      downloadImage: primary?.downloadImage,
      attachment: primary?.attachment,
      extraAttachments: extras.length > 0
        ? extras.map((e) => ({ downloadImage: e.downloadImage, attachment: e.attachment }))
        : undefined,
      forwardOrigins: forwardOrigins.length > 0 ? forwardOrigins : undefined,
    }
  },
  onFlush: (key, merged) => {
    bufferedAttachmentKeys.delete(key)
    void handleInbound(
      merged.ctx,
      merged.text,
      merged.downloadImage,
      merged.attachment,
      merged.extraAttachments,
      merged.forwardOrigins,
    )
  },
})

/**
 * Gateway-side emission for an OperatorEvent — the single point where:
 *   - per-agent per-kind cooldown is enforced
 *   - the event is recorded into the in-memory history (feeds /status)
 *   - the rendered card is broadcast to every chat in `access.allowFrom`
 *
 * Producers (the IPC `onOperatorEvent` handler, the boot-card crash
 * detector, the restart-watchdog) all funnel through here so the dedupe,
 * record, and post logic stays in one place.
 *
 * Each step is independently fault-tolerant — a failure to record
 * doesn't block the post; a bad send to one chat doesn't block siblings.
 */
function emitGatewayOperatorEvent(event: OperatorEvent): void {
  const { agent, kind } = event

  // #llm-error-surfacing FIX 2 (secret leak): the operator-event cards are sent
  // via a raw bot.api.sendRichMessage that BYPASSES the normal outbound redact
  // chokepoint (normalizeOutboundBody → redact, outbound-send-path.ts). The only
  // scrub the renderers apply is stripRawErrorBytes — a JSON-SHAPE scrub, NOT a
  // secret scrubber — so a bearer token / `sk-…` key / url-embedded credential
  // smuggled in an error `detail` would reach the operator card verbatim on the
  // credentials-expired / credit-exhausted / unknown-4xx paths. Redact the detail
  // ONCE here, up front, through the SAME redact() the reply path uses — and
  // crucially BEFORE renderOperatorEvent runs escapeMarkdown on it (redacting the
  // already-escaped text would let url-query-param secrets slip past url-redact,
  // exactly the order the outbound pipeline documents: redact before markdown).
  // Doing it at the top also scrubs the recorded operator-event history and the
  // 429 metrics — defense in depth, no secret survives in ANY downstream sink.
  event = { ...event, detail: redactOutboundText(event.detail, 'operator_event') }

  // transport-transient (mid-response stream abort — `server_error`/`api_error`
  // with no HTTP status): no broadcast card, no Reauth; record + deferred user
  // notice, burst escalates. Orchestration in user-failure-notices.ts.
  if (kind === 'transport-transient') {
    emitTransportTransientEvent(event, userFailureNoticeDeps())
    return
  }

  // ── 429 throttle tier (operator spec: "retry in place under 5 min, else
  // mark + failover, honest reset messaging") ────────────────────────────
  // A terminal TRANSIENT ACCOUNT-scoped 429 — kind `rate-limited` carrying
  // wording that affirms the account's own rate limit ("would exceed your
  // account's rate limit") — is decided BEFORE the per-kind cooldown gate:
  // every hit must reach the broker's mark-throttled escalation counter, and
  // the >threshold failover ACTION must fire, even when the user-facing card
  // is cooldown-suppressed (a calm 529 card two minutes earlier arms that
  // cooldown). Server-side transients (529 / "server is temporarily…") fall
  // through to the existing calm rate-limited card unchanged — an
  // account-scoped throttle would be the wrong action for a server-wide
  // condition.
  //
  // Classification is three-way (classify429Detail, throttle-tier.ts):
  // only `account-scoped` may enter the throttle tier. `litellm-local` —
  // the LiteLLM proxy's OWN tpm/rpm/router limiter tripping before the
  // request reached Anthropic — takes the calm path with NO broker mark and
  // NO failover: the condition is proxy-local and says nothing about the
  // account. Every rate-limited event ALSO emits one
  // `rate_limit_429_classified` runtime metric (PostHog + JSONL), fired
  // here — before the cooldown gate — so operators can correlate
  // account-scoped 429s with fleet TPM even when the card is suppressed.
  let throttleEscalation: ModelUnavailableDetection | null = null
  let escalationFired = false
  // True when decideRateLimitedSurface already consulted (and armed) the
  // shared per-kind card cooldown for this event — the gate below must not
  // re-consult it, or the arm from the first consult would self-suppress.
  let rateLimitedCooldownConsulted = false
  const rateLimit429Classification =
    kind === 'rate-limited' ? classify429Detail(event.detail) : null
  if (rateLimit429Classification != null && rateLimit429Classification !== 'account-scoped') {
    // litellm-local / generic-transient: the calm path. NO broker
    // mark-throttled, NO throttle-tier runner, NO failover — for a
    // proxy-local cap trip those would bench an account that was never
    // touched.
    emitRuntimeMetric(
      build429ClassifiedMetric({
        agent,
        detail: event.detail,
        classification: rateLimit429Classification,
        action: 'calm',
        now: Date.now(),
      }),
    )
    // Surface decision — extracted (decideRateLimitedSurface,
    // litellm-local-notice-wiring.ts) so the ordering contract with the
    // shared per-kind card cooldown is pinnable by tests: litellm-local
    // resolves BEFORE the gate (never arms `${agent}:rate-limited`, never
    // suppressed by a cooldown a recent 529/generic card armed);
    // generic-transient consults the gate exactly once HERE.
    const surface = decideRateLimitedSurface({
      classification: rateLimit429Classification,
      agent,
      shouldEmitCard: (a) => shouldEmitOperatorEvent(a, 'rate-limited'),
    })
    routeRateLimit429(rateLimit429Classification, throttleTierRunner, agent) // #failover-429-corroborate probe-only seam; boolean return is for test observability (throttle-tier-route-429.test.ts), intentionally discarded here — see docstring
    if (surface === 'litellm-local-notice') {
      process.stderr.write(
        `telegram gateway: 429 classified litellm-proxy-local agent=${agent} — ` +
          `calm path, no account attribution, no failover\n`,
      )
      // The dedicated debounced notice REPLACES the generic "🚦 Rate limited"
      // card for this classification only: one calm message naming the fleet
      // token limiter (LiteLLM tpm_limit/rpm_limit) instead of a card that
      // reads like an Anthropic account problem. Classification, quota-ledger,
      // and failover behavior are untouched (nothing fired above on this
      // branch). Record into history ONLY when a notice actually posted — a
      // suppressed low-stakes proxy throttle must not overwrite a more
      // important most-recent event (e.g. credentials-expired) in the
      // /status enrichment (operator-events-history keeps the most recent
      // event per agent).
      const outcome = litellmLocalNoticeRunner.onRateLimited('litellm-local', agent)
      if (outcome === 'sent') {
        try {
          recordOperatorEvent(event)
        } catch { /* history is best-effort */ }
      }
      return
    }
    if (surface === 'cooldown-suppressed') {
      process.stderr.write(
        `telegram gateway: operator-event suppressed (cooldown) agent=${agent} kind=${kind}\n`,
      )
      return
    }
    // 'generic-card' — the gate passed (and armed) above; fall through to
    // the existing calm rate-limited card without re-consulting it.
    rateLimitedCooldownConsulted = true
  }
  if (rateLimit429Classification === 'account-scoped') {
    const throttleDecision = decideThrottleTier({
      detail: event.detail,
      now: Date.now(),
      thresholdMs: throttleRetryInPlaceMaxMs(),
    })
    emitRuntimeMetric(
      build429ClassifiedMetric({
        agent,
        detail: event.detail,
        classification: 'account-scoped',
        // decideThrottleTier can't return 'none' for account-scoped wording;
        // map the two live actions onto the metric's vocabulary.
        action: throttleDecision.action === 'failover' ? 'failover' : 'throttle',
        now: Date.now(),
      }),
    )
    if (throttleDecision.action === 'throttle') {
      // Reset is near (≤ threshold) or unparseable (60s default): DO NOT
      // fail over. Record throttled_until broker-side, post ONE lightweight
      // notice (per-account + fleet-wide dedup), nudge a retry after the
      // reset. The runner owns the sequencing (throttle-tier-wiring.ts).
      process.stderr.write(
        `telegram gateway: throttle-tier staying-put agent=${agent} ` +
          `until=${new Date(throttleDecision.throttledUntilMs).toISOString()} ` +
          `parsedReset=${throttleDecision.resetParsed}\n`,
      )
      try {
        recordOperatorEvent(event)
      } catch { /* history is best-effort */ }
      void throttleTierRunner.fire(
        agent,
        throttleDecision.throttledUntilMs,
        throttleDecision.resetParsed,
      )
      return
    }
    if (throttleDecision.action === 'failover') {
      // Reset beyond the retry-in-place threshold: the account is benched
      // until then anyway, so escalate to the standard mark-exhausted +
      // fleet-failover machinery — honest 'rate_limited' wording, parsed
      // reset as the mark expiry. The ACTION fires HERE, before the
      // per-kind card cooldown below can swallow it (the fleetFallbackGate
      // provides the action-level dedup); only the card stays
      // cooldown-bounded. The 'rate-limit' trigger tells the dispatcher to
      // trust this terminal parsed-reset signal over the utilization probe
      // (a transient 429 negates the usage-limit reading, so utilization
      // typically looks healthy — the idempotency guard would self-cancel
      // the swap).
      const resetAt = new Date(throttleDecision.resetAtMs)
      throttleEscalation = { kind: 'rate_limited', resetAt, raw: event.detail }
      if (wouldFireFleetAutoFallback()) {
        escalationFired = true
        void fireFleetAutoFallback(
          agent,
          resolveExhaustUntil(resetAt.getTime()),
          resetAt,
          'rate-limit',
        )
      }
    }
  }

  if (!rateLimitedCooldownConsulted && !shouldEmitOperatorEvent(agent, kind)) {
    process.stderr.write(
      `telegram gateway: operator-event suppressed (cooldown) agent=${agent} kind=${kind}\n`,
    )
    return
  }

  try {
    recordOperatorEvent(event)
  } catch (err) {
    process.stderr.write(
      `telegram gateway: recordOperatorEvent failed agent=${agent} kind=${kind}: ${(err as Error).message}\n`,
    )
  }

  // Issue #394 Fix 2: when the failure is model-unavailable (quota out,
  // overloaded, or the network can't even reach Anthropic), suppress the
  // raw stderr/detail and post the actionable ⚠️ card instead. The card
  // points at the commands that move the needle (`/auth` Switch
  // primary picker, `/auth add`, `/usage`) so the user isn't left
  // staring at "You're out of extra usage · resets May 3, 11am" with
  // no idea what to do.
  //
  // Two routes match:
  //   - kind already classified as quota-exhausted / rate-limited / unknown-5xx
  //     by the upstream classifier
  //   - detail string contains one of the model-unavailable text patterns
  //     (covers raw stderr that slipped past structured classification)
  // Throttle-tier escalation (long-reset transient 429) takes precedence:
  // resolveModelUnavailableFromOperatorEvent deliberately returns null for a
  // bare rate-limited event, but this one is auto-fallback-eligible.
  const modelUnavailable = throttleEscalation ?? resolveModelUnavailableFromOperatorEvent(event)
  let renderedText: string
  let renderedKeyboard: ReturnType<typeof renderOperatorEvent>['keyboard'] | undefined
  // #3031 PR 3 — when the card promises an in-flight auto-failover, record
  // each per-chat send in the collapse registry so a SUCCESSFUL swap edits
  // the card (single evolving message) instead of sending a second one.
  let cardPromisedFallback = false
  if (modelUnavailable) {
    // Two questions, asked synchronously to avoid the "card promises
    // an announcement that never arrives" trap:
    //   1. Is this a kind that AUTO-fallback can address?
    //   2. Will the dispatcher actually fire (vs. dedup-drop)?
    // Card text branches on the AND. wouldFireFleetAutoFallback is a
    // pure read of the dedup state; calling fireFleetAutoFallback only
    // when both are true keeps the card honest.
    // Only a genuine quota / usage-limit hit is addressable by fleet
    // auto-fallback (swap to an account that still has runway). An
    // `overload` is transient Anthropic SERVER-side capacity pressure —
    // every account is equally affected, so failing over does nothing;
    // it just produces a self-cancelling "probed healthy / Stale event?"
    // loop on every 529. Overload is handled by Claude Code's own
    // internal retry, not by switching accounts.
    // 'rate_limited' is the throttle-tier escalation (transient 429 whose
    // reset exceeds the retry-in-place threshold) — same failover mechanics
    // as a quota wall, honest wording on the card. Its fire already happened
    // ABOVE the cooldown gate (escalationFired) so the action can't be
    // swallowed by the per-kind card cooldown; the card here only reports it.
    const isAutoKind =
      modelUnavailable.kind === 'quota_exhausted' ||
      modelUnavailable.kind === 'rate_limited'
    const willActuallyFire =
      throttleEscalation != null
        ? escalationFired
        : isAutoKind && wouldFireFleetAutoFallback()
    process.stderr.write(
      `telegram gateway: operator-event suppressing-raw-stderr-for-model-unavailable agent=${agent} kind=${kind} detected=${modelUnavailable.kind} autoKind=${isAutoKind} willFire=${willActuallyFire}\n`,
    )
    renderedText = formatModelUnavailableCard(modelUnavailable, agent, {
      autoFallbackInFlight: willActuallyFire,
    })
    renderedKeyboard = undefined
    cardPromisedFallback = willActuallyFire
    // Trigger fleet-wide auto-fallback. Pre-fix this branch only
    // rendered the card; the fallback machinery was unreachable from
    // here. We fire-and-forget so card delivery is never blocked on
    // broker / API latency. The fallback's own announcement is sent
    // separately with the causal-shape headline ("5-hour limit on
    // ken" instead of generic "quota exhausted") — see
    // auth-snapshot-format.ts → renderFallbackAnnouncement.
    //
    // Thread the parsed reset as markExhausted's `until` via the shared
    // resolveExhaustUntil floor. parseResetTime gives a finite epoch for
    // ROLLING wordings ("resets in 2h", "retry after 60s"); a WEEKLY wall
    // ("resets Jun 9, 5am") is UNPARSEABLE here → undefined → +7d floor.
    // Pre-fix this called fireFleetAutoFallback(agent) with no until, so a
    // weekly wall that surfaced as a 429 got markExhausted's ~5h default and
    // the broker re-mirrored the still-walled account onto the fleet after 5h.
    // Throttle-tier escalations (throttleEscalation != null) already fired
    // above the cooldown gate — don't double-fire here.
    if (willActuallyFire && throttleEscalation == null) {
      const untilMs = resolveExhaustUntil(modelUnavailable.resetAt?.getTime())
      // Thread the RAW parsed reset (distinct from the floor-applied untilMs)
      // so the fallback announcement can name it even when the live probe of
      // the old account fails — honest reset messaging on the enriched card.
      void fireFleetAutoFallback(agent, untilMs, modelUnavailable.resetAt)
    }
  } else if (kind === 'rate-limited' || kind === 'unknown-5xx') {
    // #llm-error-surfacing — surface #2 (the "🚦 Rate limited" operator card).
    // The transient rate-limit / overload family used to render the raw
    // synthetic-error `detail` (bytes and all) via renderOperatorEvent. Route
    // it through the humanized card instead: JSON-stripped coreText + reset in
    // LOCAL time. The ErrorPresenceGate is the cross-surface dedup authority —
    // the reply/done-card surfaces are already suppressed at the transcript
    // source (session-tail), so the operator card is the sole renderer and
    // wins the claim; a redundant burst within the collapse window is
    // suppressed here in addition to the existing 5-min per-kind cooldown.
    const parsed = parseLlmError(event.detail)
    const now = Date.now()
    if (decideErrorSurface(parsed, agent, { claim: true, now }) === 'suppress') {
      process.stderr.write(
        `telegram gateway: operator-event collapsed (error-presence-gate) agent=${agent} kind=${kind}\n`,
      )
      return
    }
    const tz = process.env.SWITCHROOM_TIMEZONE ?? process.env.TZ ?? 'UTC'
    // #llm-error-surfacing FIX 3 (crash guard): renderLlmErrorSafe wraps the
    // tz-formatting render — an invalid IANA `SWITCHROOM_TIMEZONE`/`TZ` throws a
    // RangeError out of Intl.DateTimeFormat (local-time.ts's "never throws" claim
    // does NOT hold for construction-time zone validation). Pre-fix this branch
    // had no guard, so a bad tz crashed the whole operator-event turn; now it
    // degrades to a minimal tz-free line. There are no action buttons on this
    // card (FIX 1) — the humanized text carries any recommendation inline.
    const r = renderLlmErrorSafe(parsed, agent, tz, new Date(now))
    renderedText = r.text
    renderedKeyboard = undefined
  } else {
    try {
      const r = renderOperatorEvent(event)
      renderedText = r.text
      renderedKeyboard = r.keyboard
    } catch (err) {
      process.stderr.write(
        `telegram gateway: renderOperatorEvent failed agent=${agent} kind=${kind}: ${(err as Error).message}\n`,
      )
      return
    }
  }

  const access = loadAccess()
  if (access.allowFrom.length === 0) {
    process.stderr.write(
      `telegram gateway: operator-event no-allowlist agent=${agent} kind=${kind} (recorded only)\n`,
    )
    return
  }

  // PR4b emitter sweep: supergroup-mode agents route operator-event
  // cards (boot crash, restart-watchdog, model-unavailable, etc.) into
  // the alerts/admin alias topic instead of chat-root. The
  // 'compact-watchdog' kind covers all system-initiated notifications
  // — alerts alias → default_topic_id fallback (see router contract).
  // Fleet-shared / DM agents see `undefined` → no `message_thread_id`
  // is added to the broadcast opts → behavior unchanged.
  const opEventTopic = resolveAgentOutboundTopic({ kind: 'compact-watchdog' })
  const opEventSupergroup = resolveAgentSupergroupChatId()

  process.stderr.write(
    `telegram gateway: operator-event posting agent=${agent} kind=${kind} to ${access.allowFrom.length} chat(s)` +
      (opEventTopic != null ? ` topic=${opEventTopic}` : '') + '\n',
  )
  // Ken's deterministic error-surfacing policy: an OPERATOR-ACTIONABLE fault
  // (credentials / credit / proxy-misconfig) must not reach non-operator users
  // as a raw or misleading card they can't act on. Split the audience — the
  // operator (allowlist head) gets the full card; every other allowlist chat
  // gets, at most, a brief plain-language "it's on our side" notice. Non-
  // actionable kinds keep their existing broadcast (all chats are operatorChats).
  const { operatorChats, userNoticeChats } = decideOperatorEventAudience(
    kind,
    access.allowFrom,
    access.allowFrom[0],
  )
  if (userNoticeChats.length > 0) {
    process.stderr.write(
      `telegram gateway: operator-event operator-only routing agent=${agent} kind=${kind} operatorChats=${operatorChats.length} userNoticeChats=${userNoticeChats.length}\n`,
    )
  }

  for (const chat_id of operatorChats) {
    // The resolved topic is valid ONLY in the agent's supergroup — attaching
    // it to an operator DM recipient yields 400 "message thread not found" and
    // the event silently fails to deliver (the marko #2096 class). Guard it:
    // DM recipients get a thread-less send; the supergroup owner gets the lane.
    const opEventThread = topicForRecipient({ recipientChatId: chat_id, resolvedTopic: opEventTopic, supergroupChatId: opEventSupergroup })
    // grammy's Other<...> opts type is generated and stricter than our
    // call shape; runtime accepts both. Cast through unknown.
    const opts = {
      ...(renderedKeyboard ? { reply_markup: renderedKeyboard } : {}),
      ...(opEventThread != null ? { message_thread_id: opEventThread } : {}),
    }
    // Comment-only context for the reader; the lint marker on the
    // very next line is what unlocks the raw bot.api call.
    // Opts now includes message_thread_id when supergroup mode is on.
    // allow-raw-bot-api: operator-event broadcast loop; topic-aware opts
    void bot.api.sendRichMessage(chat_id, richMessage(renderedText), opts as never)
      .then((sent: { message_id: number }) => {
        // #3031 PR 3 — remember the fallback-promising card so the swap
        // announcement can EDIT it (collapse) instead of sending anew.
        // Recorded only after the send resolves (we need the message_id);
        // the collapse path degrades to a plain send when no record exists.
        if (cardPromisedFallback) {
          modelUnavailableCardRegistry.record(String(chat_id), {
            messageId: sent.message_id,
            text: renderedText,
            atMs: Date.now(),
            promisedFallback: true,
          })
        }
      })
      .catch(e => {
        process.stderr.write(
          `telegram gateway: operator-event send to ${chat_id} failed agent=${agent} kind=${kind}: ${e}\n`,
        )
      })
  }

  // Non-operator users: only the plain-language failure notice, and ONLY when
  // the turn genuinely dies (userNoticeChats is empty for every non-actionable
  // kind — see decideOperatorEventAudience). #3293 review finding 1: an error
  // line is NOT proof of turn failure — the LiteLLM fallback can 401 while a
  // retry / another deployment still serves the turn, and sending "couldn't
  // complete that" for a turn that completed is a false failure report. So the
  // notice is never sent here: it is SCHEDULED on the pendingUserNoticeGate and
  // resolved at the turn-end funnel (endCurrentTurnAtomic) — dropped when the
  // turn delivered a reply (recovered), sent when it ended reply-less (died).
  // Un-resolved notices expire after PENDING_USER_NOTICE_TTL_MS (bias to
  // silence over a false failure claim). Operator cards above stay immediate.
  if (userNoticeChats.length > 0) {
    // #3294 — key the notice to the live turn's topic so under PR-4e keyed
    // liveness only THAT topic's turn end resolves it (full rationale on
    // `PendingUserNotice.key`). `undefined` (no live turn — the event is
    // agent-level, empty wire chatId) keeps the legacy agent-wide resolution.
    const noticeDeps = userFailureNoticeDeps()
    const noticeKey = noticeDeps.liveTurnKey()
    noticeDeps.scheduleUserNotice({ chatIds: userNoticeChats, agent, kind, key: noticeKey, atMs: Date.now() })
    process.stderr.write(
      `telegram gateway: operator-event user-notice deferred to turn-end agent=${agent} kind=${kind} chats=${userNoticeChats.length} topic=${noticeKey ?? '-'}\n`,
    )
  }
}

/**
 * Live gateway deps for the plain user-failure-notice subsystem
 * (`user-failure-notices.ts`): transport-transient handling AND the turn-end
 * flush share this one wiring. Every side effect is a closure over live state.
 */
function userFailureNoticeDeps(): UserFailureNoticeDeps {
  return {
    now: () => Date.now(),
    allowFrom: () => loadAccess().allowFrom,
    liveTurnKey: () => currentTurn != null ? statusKey(currentTurn.sessionChatId, currentTurn.sessionThreadId) : undefined,
    record: (e) => { try { recordOperatorEvent(e) } catch { /* history best-effort */ } },
    scheduleUserNotice: (i) => pendingUserNoticeGate.schedule({ ...i, text: renderUserFacingFailureNotice() }),
    resolveNotices: (delivered, key) => pendingUserNoticeGate.resolveTurnEnd(key, delivered),
    send: (chat_id, text, keyboard) => {
      const thread = topicForRecipient({ recipientChatId: chat_id, resolvedTopic: resolveAgentOutboundTopic({ kind: 'compact-watchdog' }), supergroupChatId: resolveAgentSupergroupChatId() })
      const opts = { ...(keyboard ? { reply_markup: keyboard } : {}), ...(thread != null ? { message_thread_id: thread } : {}) }
      // allow-raw-bot-api: user-failure-notice / transport escalation send; topic-aware opts
      void bot.api.sendRichMessage(chat_id, richMessage(text), opts as never).catch((e) => process.stderr.write(`telegram gateway: user-failure-notice send to ${chat_id} failed: ${e}\n`))
    },
    log: (m) => process.stderr.write(`telegram gateway: ${m}\n`),
  }
}

/**
 * Turn-end resolution of deferred user failure notices (#3293 finding 1).
 * Called from `endCurrentTurnAtomic` — the ONE funnel every turn-end path
 * passes through. `turnDeliveredReply` is `finalAnswerDelivered || replyCalled`
 * (the model explicitly replied → the turn recovered → notices are dropped by
 * the gate). The send loop lives in `user-failure-notices.ts`.
 */
function flushPendingUserFailureNotices(turnDeliveredReply: boolean, turnKey: string): void {
  flushDeferredUserNotices(turnDeliveredReply, turnKey, userFailureNoticeDeps())
}

/**
 * Legacy "restarted — ready" banner, used when BOOT_CARD_ENABLED=false.
 * Kept as a safe fallback so reverting to the old behavior is one env var flip.
 */
function postLegacyBanner(
  chatId: string,
  threadId: number | undefined,
  ackMessageId: number | undefined,
  ageSec: number,
  site: string,
): void {
  const text = `🎛️ Switchroom restarted — ready. (took ~${ageSec}s)`
  process.stderr.write(`telegram gateway: ${site}: posting legacy banner chat_id=${chatId}\n`)
  // #1075: thread-id-bearing call — route through robustApiCall so a
  // stale thread (THREAD_NOT_FOUND) becomes a swallowed log line, not
  // a crash. Use retryWithThreadFallback so the banner still lands on
  // the main chat when the topic is gone.
  retryWithThreadFallback(
    robustApiCall,
    (tid) =>
      lockedBot.api.sendRichMessage(chatId, richMessage(text), {
        ...(tid != null ? { message_thread_id: tid } : {}),
        ...(ackMessageId != null ? { reply_parameters: { message_id: ackMessageId } } : {}),
      }),
    { threadId, chat_id: chatId, verb: 'legacy-banner' },
  )
    .then((sent) => {
      if (HISTORY_ENABLED) {
        try {
          recordOutbound({
            chat_id: chatId,
            thread_id: threadId ?? null,
            message_ids: [sent.message_id],
            texts: [text],
            attachment_kinds: [],
          })
        } catch {
          /* best-effort */
        }
      }
    })
    .catch((err: Error) => {
      process.stderr.write(
        `telegram gateway: ${site}: legacy banner send failed: ${err.message}\n`,
      )
    })
}

// ─── Session/PTY tail state ───────────────────────────────────────────────
// The pinned progress card was deleted in #1122 PR3. The variables below
// are retained as permanent `null` so the dozens of optional-chained
// call sites scattered through this file (`progressDriver?.ingest(...)`,
// `unpinProgressCardForChat?.(...)`, etc.) remain valid TypeScript and
// short-circuit to no-ops at runtime. `progressDriver` is typed `any`
// so TS doesn't resolve `progressDriver?.X` to `never`.
const streamMode = process.env.SWITCHROOM_TG_STREAM_MODE ?? 'checklist'
// Per-agent stream throttle override via channels.telegram.stream_throttle_ms.
// When unset, draft-stream.ts applies DM/group defaults (400 ms DMs, 1000 ms
// groups). Parsed once at boot; sub-zero / NaN values fall back to undefined
// so the per-chat-type default wins. See `src/agents/scaffold.ts`
// `channelsToEnv()` for the yaml → env wiring.
const STREAM_THROTTLE_MS_OVERRIDE: number | undefined = (() => {
  const raw = process.env.SWITCHROOM_TG_STREAM_THROTTLE_MS
  if (raw == null || raw === '') return undefined
  const n = Number.parseInt(raw, 10)
  return Number.isFinite(n) && n >= 0 ? n : undefined
})()
const TURN_FLUSH_SAFETY_ENABLED = isTurnFlushSafetyEnabled()

// PR A — answer-ready quiescence flush debounce (ms). 0 = kill-switch (never
// arm). Resolved once at boot; env-tunable via SWITCHROOM_ANSWER_READY_FLUSH_MS.
const ANSWER_READY_FLUSH_MS = resolveAnswerReadyFlushMs(process.env)

// When SET, the answer-lane stream (telegram-plugin/answer-stream.ts) renders
// the model's transcript text as a USER-VISIBLE edit-in-place message. Default
// OFF: the lane stays dormant and the reply tool is the single canonical
// formatted message — no unformatted preliminary that flashes and gets deleted.
// With this flag on, minInitialChars is set to 1 and the first text chunk opens
// a visible preview immediately. At turn_end, if the model never called reply /
// stream_reply AND the streamed message has substantive captured text, the
// gateway materializes it as a pinged final answer (materialize()) and deletes
// the silent preview. When the model uses an explicit reply tool the prior
// streamed message is retracted instead.
// The draft transport (sendMessageDraft) is permanently retired — both ON and
// OFF use sendMessage + editMessageText; the difference is whether a visible
// preview is opened at all.
// Opt back IN per agent with SWITCHROOM_VISIBLE_ANSWER_STREAM=1.
const ANSWER_STREAM_VISIBLE_ENABLED = parseVisibleAnswerStreamEnabled(
  process.env.SWITCHROOM_VISIBLE_ANSWER_STREAM,
)
// Single source of truth for the answer-lane behaviour. The draft transport
// (sendMessageDraft) is permanently retired — the lane is either VISIBLE
// (opt-in) or DORMANT (the unconditional default: reply tool is the only
// message). Resolved here once and consulted at the createAnswerStream config,
// the materialize-as-answer guard, and the boot log.
const ANSWER_LANE = resolveAnswerLaneConfig({
  visibleEnabled: ANSWER_STREAM_VISIBLE_ENABLED,
})

// Whether to DELETE the activity/status feed when the final answer lands.
// Default OFF (2026-06-04, operator request): the status message stays in the
// chat as a record (finalized to an all-done render) instead of being deleted
// — no post-then-delete flicker. Opt IN per agent via
// channels.telegram.clear_status_on_completion: true (→ this env). See the
// clearActivitySummary doc-comment.
const CLEAR_STATUS_ON_COMPLETION = (() => {
  const raw = process.env.SWITCHROOM_TG_CLEAR_STATUS_ON_COMPLETION
  if (raw == null) return false
  const v = raw.trim().toLowerCase()
  return v === '1' || v === 'true' || v === 'on' || v === 'yes'
})()

// Whether to SILENTLY pin the already-rendered status message while its work
// is in-flight (auto-unpinned on completion). Default ON (silent + low-risk):
// keeps in-flight work in view when the conversation scrolls past it. This is
// the ONE sanctioned pin under `chat-is-the-single-source-of-truth` — it pins
// a message the chat ALREADY rendered (the per-turn activity/status message,
// the `🛠 Worker` message), never a new parallel surface, never with a device
// buzz. Opt OUT per agent via channels.telegram.pin_status_while_working: false
// (→ this env). See status-pin.ts / status-pin-driver.ts and
// `reference/invariants.md` § chat-is-the-single-source-of-truth.
const PIN_STATUS_WHILE_WORKING = (() => {
  const raw = process.env.SWITCHROOM_TG_PIN_STATUS_WHILE_WORKING
  if (raw == null) return true // default ON
  const v = raw.trim().toLowerCase()
  return !(v === '0' || v === 'false' || v === 'off' || v === 'no')
})()

// ─── Status-pin: single-owner state + reconcile ────────────────────────────
// EXACTLY ONE owner of pin state. Every desired-state change for a key routes
// through `reconcileStatusPin`, which computes ONE action (pin|unpin|noop) via
// the pure `decidePinAction` and executes it through `reconcilePin` (which
// drops the claim on unpin even if the API throws — so pin state can never get
// stuck). Two desired-state sources feed distinct keys:
//   - foreground: `fg:<statusKey>` — pinned while the per-turn activity message
//     is in-flight; unpinned at the canonical turn-end (purgeReactionTracking).
//   - background: `wk:<agentId>`   — pinned while the `🛠 Worker` message runs;
//     unpinned on that worker's completion (worker-feed finish).
// It does NOT touch the reply / stream_reply send handlers (the v1 bug was send
// handlers unconditionally unpinning on every send) and runs NO polling
// watchdog / getChat().pinned_message reconciler.
// ONE registry, keyed by pinKey → { messageId, chatId, pinnedAt } (#3809).
// This was three parallel Maps (state / chatIds / pinnedAt), written on the
// same commit but free to diverge; a `wk:` claim that lost its chatId entry was
// skipped by the mid-session reaper on every pass AND excluded from the durable
// store-orphan net, i.e. silently unreapable until the next boot. One record
// makes the invariant structural — see StatusPinClaim in status-pin-retarget.ts.
//
// F2 serialization: same-pinKey reconciles run one-at-a-time via
// `withPinReconcileLock` (status-pin-store.ts — kept there so it's
// unit-testable) so each reads a fresh `prev`; see its doc for the stale-`prev`
// race it closes. Adds zero Telegram API calls (a serialized noop still no-ops).
const statusPinClaims = new Map<string, StatusPinClaim>()
// Rights-aware negative cache (#3024): chats where an auto status-pin attempt
// failed with the permanent "not enough rights to manage pinned messages" 400.
// Per-process only — a restart clears it so a later-granted pin right re-enables
// auto-pin. The explicit `pin_message` MCP tool deliberately does NOT consult
// this cache (it always attempts and surfaces the error to the agent).
const statusPinRightsCache = new PinRightsCache()

// Durable snapshot of the pin claim set on the persistent per-agent volume
// (STATE_DIR = /state/agent/telegram in prod). Closes the crash hole: the
// in-memory Maps alone empty on restart, so a status pin left dangling by a
// crashed session is never unpinned and the service-message-deletion handler
// can't recognise it as ours. Every reconcile persists the current claim set;
// boot cleanup (statusPinBootCleanup, wired after lockedBot is defined) unpins
// each persisted entry and clears the store. STATIC mode and feature-off skip
// disk. Mirrors obligation-store.ts.
const STATUS_PIN_STORE_PATH = join(STATE_DIR, 'status-pins.json')
const statusPinStoreFs = {
  readFileSync: (p: string) => readFileSync(p, 'utf8'),
  writeFileSync: (p: string, d: string) => writeFileSync(p, d),
  renameSync: (a: string, b: string) => renameSync(a, b),
  existsSync: (p: string) => existsSync(p),
}
const statusPinPersistEnabled = !STATIC && PIN_STATUS_WHILE_WORKING

// Durable card-handle snapshot for the mid-turn activity card (Known Gap 1,
// `reference/rfcs/deterministic-turn-liveness.md`). Persisted on card OPEN,
// cleared on normal close/finalize; a boot-time reaper (wired alongside
// `statusPinBootCleanup`, same startup-mutex ordering constraint) finalizes
// any leftover record with one honest edit so a gateway restart mid-turn can
// never leave the card frozen forever. STATIC mode skips disk (dry-run, no
// durable volume) — same gate as the status-pin store.
const ACTIVITY_CARD_STORE_PATH = join(STATE_DIR, 'activity-cards-pending.json')
const activityCardStoreFs: ActivityCardStoreFsSeam = {
  readFileSync: (p: string) => readFileSync(p, 'utf8'),
  writeFileSync: (p: string, d: string) => writeFileSync(p, d),
  renameSync: (a: string, b: string) => renameSync(a, b),
  existsSync: (p: string) => existsSync(p),
}
const activityCardPersistEnabled = !STATIC

// Durable handle for the component-5 queued-status placeholder + #2995 busy-ack
// card (#3002). Both track their sent message id only in the in-memory
// `queuedStatusMsgIds` Map, so a restart between posting a card and its
// promote/reap strands a permanent stale "⏳ Queued…" line. Persisted on POST,
// cleared on in-process reap; a boot-time reaper (wired alongside
// `activityCardBootReaper`, same startup-mutex ordering constraint) DELETES any
// leftover card and clears the store — a "Queued" claim is always wrong after a
// restart, so deletion is the honest terminal (reap-on-boot only, no
// promote-across-restart). STATIC mode skips disk — same gate as the sibling
// stores.
const QUEUED_CARD_STORE_PATH = join(STATE_DIR, 'queued-cards-pending.json')
const queuedCardStoreFs: QueuedCardStoreFsSeam = {
  readFileSync: (p: string) => readFileSync(p, 'utf8'),
  writeFileSync: (p: string, d: string) => writeFileSync(p, d),
  renameSync: (a: string, b: string) => renameSync(a, b),
  existsSync: (p: string) => existsSync(p),
}
const queuedCardPersistEnabled = !STATIC

// Write-through helpers (#3002) — mirror the in-memory `queuedStatusMsgIds`
// set/delete onto the durable store. Best-effort + gated: no-op when the store
// isn't usable (STATIC = no durable volume). Called from postQueuedStatus /
// postBusyAck (post) and reapQueuedStatus (delete).
function persistQueuedCard(
  key: string,
  chatId: string,
  threadId: number | null,
  messageId: number,
): void {
  if (!queuedCardPersistEnabled) return
  writeQueuedCardRecord(QUEUED_CARD_STORE_PATH, queuedCardStoreFs, {
    key,
    chatId,
    threadId,
    messageId,
  })
}
function clearQueuedCard(key: string, messageId?: number): void {
  if (!queuedCardPersistEnabled) return
  clearQueuedCardRecord(QUEUED_CARD_STORE_PATH, queuedCardStoreFs, key, messageId)
}

// Slot-banner pin persistence (#421 crash-recovery). The slot banner is pinned
// in the owner chat when the agent is on a non-default OAuth slot. Rather than a
// parallel store + second boot hook, its pin is persisted in the SAME
// status-pins.json store under a distinct `banner:` pinKey, so the ONE existing
// runStatusPinBootCleanup unpins an orphaned banner on boot for free. Every
// write to the shared store is a per-key read-modify-write under the store's
// per-path lock (mutateStatusPinRow / reconcileAndPersistStatusPin), so the two
// pin kinds (map-backed status pins + this banner row) can never clobber each
// other's rows — the "other" rows always come from the authoritative on-disk
// file, never from a possibly-stale in-memory snapshot.
const BANNER_PIN_KEY = 'banner:owner'
// Banner persistence rides the same "store is usable" gate as status pins minus
// the worker-pin feature flag: the banner is an independent feature, so it must
// persist/recover whenever there's a real state volume (STATIC = no volume/dry
// run → no-op). The boot-cleanup gate below is widened to cover this.
const bannerPinPersistEnabled = !STATIC

// `pin_message` MCP-tool pin registration (#3001). Tool pins ride the same
// shared status-pins.json store under `tool:<chatId>:<messageId>` keys, but
// with a TTL row (`expiresAt`): a tool pin is a deliberate agent action with
// no "work finished" event, so a restart does NOT reset it — boot cleanup
// keeps unexpired tool rows and only unpins them once the TTL lapses (the
// backstop against agent-pinned messages accumulating forever). Independent
// of PIN_STATUS_WHILE_WORKING (it gates the auto status pin, not the tool).
const toolPinPersistEnabled = !STATIC
// 7 days: generous — an agent-pinned message the operator still cares about
// after a week has usually been re-pinned or acted on; anything older is the
// stale-pin long tail this issue exists to clear. Override for tuning.
const TOOL_PIN_TTL_MS = (() => {
  const v = Number(process.env.SWITCHROOM_TOOL_PIN_TTL_MS)
  return Number.isFinite(v) && v > 0 ? v : 7 * 24 * 60 * 60_000
})()

// Persist (or drop) the slot-banner's pin row into the shared store. Routes
// through mutateStatusPinRow: a read-modify-write for ONLY the banner:owner key,
// serialised on the store's per-path lock, so the live fg:/wk: status-pin rows
// on disk are carried through unchanged and never clobbered. Best-effort +
// gated: no-op when the store isn't usable (STATIC). Fire-and-forget — the
// mutation never rejects (persist is fail-open, load is fail-open).
function persistBannerRow(row: PersistedStatusPin | null): void {
  if (!bannerPinPersistEnabled) return
  void mutateStatusPinRow( // allow-raw-pin-store: banner row bookkeeping — the slot banner has its own sanctioned driver; this only mirrors its outcome into the shared store file.
    STATUS_PIN_STORE_PATH,
    statusPinStoreFs,
    BANNER_PIN_KEY,
    row,
  )
}

// The Bot API surface the pin driver needs. `lockedBot` is assigned late (in
// initGatewayBot) so it is read lazily; createStatusPinApi also asserts it
// exists and converts a send-gate SHED into a throw — see status-pin-api.ts.
function statusPinApi(): PinBotApi {
  return createStatusPinApi(
    () => lockedBot as unknown as PinCapableBot | undefined,
    robustApiCall as RobustApiSeam,
  )
}

/**
 * Boot-time orphan cleanup — thin gateway wrapper over the pure
 * `runStatusPinBootCleanup` (which owns the load → best-effort-unpin →
 * empty-store contract). Binds the live fs seam, the robust unpin api, and the
 * gateway logger.
 *
 * MUST run ONLY after this gateway wins the startup mutex (the store is a
 * shared per-agent file; a losing double-boot would unpin the live holder's
 * legitimate pins). Runs before any new pin claim is written, so the emptied
 * store leaves the service-message handler's ownership check with no false
 * positives.
 */
async function statusPinBootCleanup(): Promise<void> {
  // Runs when EITHER pin kind could have written the shared store: the
  // map-backed status pins (statusPinPersistEnabled) or the slot banner
  // (bannerPinPersistEnabled). A single cleanup drains ALL orphaned rows —
  // status pins AND banner alike — since they share status-pins.json.
  if (!statusPinPersistEnabled && !bannerPinPersistEnabled && !toolPinPersistEnabled) return
  const api = statusPinApi()
  const { cleared, retained, kept, total } = await runStatusPinBootCleanup({
    path: STATUS_PIN_STORE_PATH,
    fs: statusPinStoreFs,
    unpin: (chatId, messageId) => api.unpinChatMessage(chatId, messageId), // allow-raw-pin: boot cleanup runs BEFORE any claim exists — it reconciles the durable rows themselves, so there is nothing to route through reconcileStatusPin.
  })
  if (total > 0) {
    process.stderr.write(
      `telegram gateway: status-pin: cleared ${cleared}/${total} ` +
        `orphaned pin(s) from a prior session ` +
        `(retained ${retained} for retry, kept ${kept} unexpired tool pin(s))\n`,
    )
  }
}
/**
 * Boot-time orphan-card reaper (Known Gap 1,
 * `reference/rfcs/deterministic-turn-liveness.md`). Thin gateway wrapper over
 * the pure `runActivityCardBootReaper` — binds the live fs seam, a real
 * Telegram edit, and the gateway logger. Finalizes ANY card left open by a
 * prior (crashed/restarted) session with ONE honest edit — never a new
 * message, so no ping. Guarantee is AT-MOST-ONCE: the pure routine deletes each
 * record before attempting its edit and does not retry, so a failed edit
 * forfeits that orphan rather than risk a double-finalize on a later boot (see
 * the module doc in activity-card-store.ts for the full tradeoff). A benign-400
 * (card already gone) is reported as `vanished`, not `finalized`.
 *
 * MUST run ONLY after this gateway wins the startup mutex (the store is a
 * shared per-agent file; a losing double-boot would finalize a card the
 * still-alive holder's in-flight turn still legitimately owns) — identical
 * ordering constraint to `statusPinBootCleanup`.
 *
 * Deliberately does NOT attempt to resume climbing the old card: the resumed
 * turn (if any) opens its own fresh card. Honest finalization, not
 * resumption, is the goal (see the module doc in activity-card-store.ts).
 *
 * After the finalizing edit, also unpins the card, but ONLY for a record whose
 * persisted `pinned` flag is true — i.e. the card was actually pin-eligible on
 * open (`PIN_STATUS_WHILE_WORKING`). This unpin is DEFENSE-IN-DEPTH, not the
 * primary unpin path: `statusPinBootCleanup` already unpins orphaned status
 * pins from its own durable store on boot. The reaper's unpin is belt-and-
 * braces for the case where the two stores disagree; the record's `pinned`
 * flag must therefore reflect the ACTUAL pin outcome (see the open path), not
 * an unconditional `true`, or the reaper would attempt an unpin on a card that
 * was never pinned.
 */
async function activityCardBootReaper(): Promise<void> {
  if (!activityCardPersistEnabled) return
  const { finalized, vanished, unpinned, total } = await runActivityCardBootReaper({
    path: ACTIVITY_CARD_STORE_PATH,
    fs: activityCardStoreFs,
    finalizeCard: (record) =>
      robustApiCall(
        () =>
          lockedBot.api.editMessageText(
            record.chatId,
            record.activityMessageId,
            richMessage(restartOrphanCardFinalizeText(record.startedAt)),
            {},
          ),
        {
          chat_id: record.chatId,
          ...(record.threadId != null ? { threadId: record.threadId } : {}),
          verb: 'activity-card.boot-reap-finalize',
        },
      ),
    unpinCard: (record) =>
      robustApiCall(
        () => lockedBot.api.unpinChatMessage(record.chatId, record.activityMessageId), // allow-raw-pin: activity-card boot reaper — unpins a card recovered from the CARD store, which has no status-pin claim to reconcile through.
        {
          chat_id: record.chatId,
          ...(record.threadId != null ? { threadId: record.threadId } : {}),
          verb: 'activity-card.boot-reap-unpin',
        },
      ),
  })
  if (total > 0) {
    process.stderr.write(
      `telegram gateway: activity-card: finalized ${finalized}/${total} ` +
        `(vanished ${vanished}/${total}), unpinned ${unpinned}/${total} ` +
        `orphaned card(s) from a prior session (at-most-once)\n`,
    )
  }
}

/**
 * Boot-time reaper for orphaned queued-status / busy-ack cards (#3002). Thin
 * gateway wrapper over the pure `runQueuedCardBootReaper` — binds the live fs
 * seam, a robust Telegram delete, and the logger. Deletes any card persisted by
 * a prior (crashed/restarted) session and clears the store: a "⏳ Queued…" /
 * "On it" claim is always wrong after a restart, so deletion is the honest
 * terminal (reap-on-boot only, no promote-across-restart).
 *
 * MUST run ONLY after this gateway wins the startup mutex — same shared-file
 * ordering constraint as `activityCardBootReaper` / `statusPinBootCleanup`.
 */
async function queuedCardBootReaper(): Promise<void> {
  if (!queuedCardPersistEnabled) return
  const { deleted, total } = await runQueuedCardBootReaper({
    path: QUEUED_CARD_STORE_PATH,
    fs: queuedCardStoreFs,
    deleteCard: (record) =>
      robustApiCall(
        () => lockedBot.api.deleteMessage(record.chatId, record.messageId),
        {
          chat_id: record.chatId,
          ...(record.threadId != null ? { threadId: record.threadId } : {}),
          verb: 'queued-card.boot-reap-delete',
        },
      ),
  })
  if (total > 0) {
    process.stderr.write(
      `telegram gateway: queued-card: deleted ${deleted}/${total} ` +
        `orphaned queued/busy-ack card(s) from a prior session\n`,
    )
  }
}
// ─── Mid-session stale-card reaper (#2918) ──────────────────────────────────
// The boot reapers (markOrphanedWithTimeoutClassification + activityCardBoot-
// Reaper) run ONCE at startup. A turn whose owning SDK subprocess dies
// mid-session (SIGKILL / OOM / crash) without a clean end leaves its turns-DB
// row `ended_at IS NULL` and its activity card frozen on "working…" until the
// NEXT gateway boot — often many hours. This periodic sweep, running inside the
// live gateway, finalizes those orphans without waiting for a restart.
//
// LIVENESS (the critical correctness guard): a turn/card is reaped ONLY when no
// live in-flight turn owns it. The live set is derived from `currentTurnMap`
// (per-topic byKey) PLUS the singleton `currentTurn` mirror, so it is correct
// whether or not the per-topic-isolation flag is on. A healthy long-running
// turn is always in that set and is never swept. A TTL gate is a secondary
// guard against the just-started-not-yet-tracked race.
//
// Kill switch: set SWITCHROOM_MID_SESSION_CARD_REAPER=0 to disable (clean
// revert, mirrors #2919). TTL/interval overridable via env for tuning.
const MID_SESSION_CARD_REAPER_ENABLED =
  process.env.SWITCHROOM_MID_SESSION_CARD_REAPER !== '0'
const MID_SESSION_CARD_REAPER_TTL_MS = (() => {
  const v = Number(process.env.SWITCHROOM_MID_SESSION_CARD_REAPER_TTL_MS)
  return Number.isFinite(v) && v > 0 ? v : 15 * 60_000 // 15 min
})()
const MID_SESSION_CARD_REAPER_INTERVAL_MS = (() => {
  const v = Number(process.env.SWITCHROOM_MID_SESSION_CARD_REAPER_INTERVAL_MS)
  return Number.isFinite(v) && v > 0 ? v : 5 * 60_000 // 5 min
})()

// ─── Mid-session stale worker-pin reaper (#3001) ─────────────────────────────
// The `wk:<agentId>` pin is normally dropped by the worker's completion
// handler, but a missed onFinish (watcher crash / SDK SIGKILL / dropped JSONL
// tail) used to leave the pin glued to the chat until the NEXT gateway boot.
// This sweep (piggybacking on the mid-session reaper interval) unpins a
// claimed worker pin when the registry says its worker is TERMINAL, or when
// the pin has been held past a TTL. Pure decision in worker-pin-reaper.ts;
// each reap executes through reconcileStatusPin so the in-memory claim and
// the durable store row clear together.
//
// Kill switch: SWITCHROOM_WORKER_PIN_REAPER=0 disables (clean revert, mirrors
// SWITCHROOM_MID_SESSION_CARD_REAPER). TTL overridable via env for tuning.
const WORKER_PIN_REAPER_ENABLED =
  process.env.SWITCHROOM_WORKER_PIN_REAPER !== '0'
const WORKER_PIN_REAPER_TTL_MS = (() => {
  const v = Number(process.env.SWITCHROOM_WORKER_PIN_REAPER_TTL_MS)
  return Number.isFinite(v) && v > 0 ? v : WORKER_PIN_TTL_MS_DEFAULT // 6 h
})()

// Snapshot the turn_keys / topic keys owned by a live in-flight turn right now.
function liveTurnKeySets(): { registryKeys: Set<string>; topicKeys: Set<string> } {
  const registryKeys = new Set<string>()
  const topicKeys = new Set<string>()
  const add = (t: CurrentTurn | null | undefined): void => {
    if (t == null) return
    if (t.registryKey != null && t.registryKey.length > 0) registryKeys.add(t.registryKey)
    topicKeys.add(statusKey(t.sessionChatId, t.sessionThreadId))
  }
  for (const t of currentTurnMap.byKey.values()) add(t)
  add(currentTurn) // flag-OFF store + most-recent mirror
  return { registryKeys, topicKeys }
}

async function runMidSessionCardReaper(): Promise<void> {
  if (!MID_SESSION_CARD_REAPER_ENABLED) return
  const now = Date.now()
  const { registryKeys, topicKeys } = liveTurnKeySets()

  // 1) Stamp ownerless open turns-DB rows (the durable spinner signal).
  if (turnsDb != null) {
    try {
      const { reaped, reapedTurnKeys } = reapStaleOpenTurns(turnsDb, {
        activeTurnKeys: registryKeys,
        ttlMs: MID_SESSION_CARD_REAPER_TTL_MS,
        now,
      })
      if (reaped > 0) {
        process.stderr.write(
          `telegram gateway: mid-session reaper stamped ${reaped} orphaned turn(s) ` +
            `as 'reaped_stale' (${reapedTurnKeys.join(',')})\n`,
        )
      }
    } catch (err) {
      process.stderr.write(
        `telegram gateway: mid-session turn reaper error: ${(err as Error).message}\n`,
      )
    }
  }

  // 2) Finalize the leftover visible activity card(s) for those dead turns.
  if (activityCardPersistEnabled) {
    try {
      const { finalized, vanished, total } = await runActivityCardMidSessionReaper({
        path: ACTIVITY_CARD_STORE_PATH,
        fs: activityCardStoreFs,
        // A synthetic pre-turn key reads as ownerless here (self-reap is the fast
        // path; this is the crash backstop). EXCEPTION: a pre-turn handback still
        // enqueued behind an in-flight turn is NOT an orphan — keep it live while
        // claude is busy, else this 15-min backstop re-posts the false nudge the
        // self-reap gate removed. (Boot reaper stays ungated: boot is never mid-turn.)
        isLive: (record) =>
          topicKeys.has(record.turnKey) ||
          (handbackPreturnSignal.isPreTurnRecord(record.turnKey) && isMachineInTurn()),
        ttlMs: MID_SESSION_CARD_REAPER_TTL_MS,
        now,
        finalizeCard: (record) => {
          // Reap hook (design lever 4): a never-adopted pre-turn card being
          // finalized here must also stop its forever-running typing loop and
          // drop the seam's in-memory entry.
          if (handbackPreturnSignal.isPreTurnRecord(record.turnKey)) {
            handbackPreturnSignal.handleReaped(record.turnKey)
          }
          return robustApiCall(
            () =>
              lockedBot.api.editMessageText(
                record.chatId,
                record.activityMessageId,
                richMessage(restartOrphanCardFinalizeText(record.startedAt)),
                {},
              ),
            {
              chat_id: record.chatId,
              ...(record.threadId != null ? { threadId: record.threadId } : {}),
              verb: 'activity-card.mid-session-reap-finalize',
            },
          )
        },
        // #3001: route through reconcileStatusPin when the pin is a live
        // in-memory claim, so the claim AND the durable status-pins.json row
        // clear together (the raw-API unpin left both behind — the boot sweep
        // then re-unpinned an already-unpinned message and the service-message
        // handler kept a phantom claim). Falls back to the raw unpin when no
        // claim is tracked (e.g. claim already dropped out-of-band).
        unpinCard: async (record) => {
          const pinKey = `fg:${record.turnKey}`
          if (statusPinClaims.has(pinKey)) {
            await reconcileStatusPin(pinKey, record.chatId, { pinned: false })
            return true
          }
          return robustApiCall(
            () => lockedBot.api.unpinChatMessage(record.chatId, record.activityMessageId), // allow-raw-pin: activity-card mid-session reaper — same as the boot reaper: a card-store record, not a status-pin claim.
            {
              chat_id: record.chatId,
              ...(record.threadId != null ? { threadId: record.threadId } : {}),
              verb: 'activity-card.mid-session-reap-unpin',
            },
          )
        },
      })
      if (total > 0) {
        process.stderr.write(
          `telegram gateway: activity-card: mid-session finalized ${finalized}/${total} ` +
            `(vanished ${vanished}/${total}) orphaned card(s) (at-most-once)\n`,
        )
      }
    } catch (err) {
      process.stderr.write(
        `telegram gateway: mid-session card reaper error: ${(err as Error).message}\n`,
      )
    }
  }

  // 3) Reap stale `wk:` worker pins (#3001): a claimed worker pin whose worker
  //    is terminal in the registry (missed onFinish) or whose claim outlived
  //    the TTL. Executes through reconcileStatusPin so the in-memory claim and
  //    the durable store row clear together.
  if (WORKER_PIN_REAPER_ENABLED && PIN_STATUS_WHILE_WORKING) {
    try {
      // One record per claim (#3809): chatId and pinnedAt are fields of the
      // claim, so neither can go missing and strand the key as unreapable.
      const inMemoryCandidates = [...statusPinClaims.entries()]
        .filter(([k]) => k.startsWith('wk:'))
        .map(([pinKey, claim]) => ({ pinKey, chatId: claim.chatId, pinnedAt: claim.pinnedAt }))
      const inMemoryKeys = new Set(inMemoryCandidates.map((c) => c.pinKey))
      // #3001 durable group net: fold in `wk:` rows that live in the DURABLE
      // store but have NO in-memory claim — the divergence window where the
      // claim was lost but the Telegram pin + store row survive. These would
      // otherwise linger until the next boot cleanup; the reconciling sweep
      // recovers them mid-session too, group-safely (per-message unpin of a
      // bot-tracked row, NEVER an unpin-all, NEVER an untracked/human pin).
      const storeOnlyCandidates = statusPinPersistEnabled
        ? storeOnlyWorkerPinCandidates({
            rows: loadStatusPins(STATUS_PIN_STORE_PATH, statusPinStoreFs),
            inMemoryPinKeys: inMemoryKeys,
            now,
          })
        : []
      const storeOnlyKeys = new Set(storeOnlyCandidates.map((c) => c.pinKey))
      const candidates = [...inMemoryCandidates, ...storeOnlyCandidates]
      const reaps = decideWorkerPinReaps({
        pins: candidates,
        statusOf: (agentId) => {
          // #3207: coalesced feed pins are GROUP-level (`wk:group:<feedKey>`),
          // so `workerAgentIdOfPinKey` yields `group:<feedKey>`, not a real
          // jsonl agent id. Vouch for these off the live feed instead of the
          // registry: a group the feed still tracks is 'running' (exempt from
          // the TTL); a lingering group pin the feed no longer knows about is a
          // missed unpin → 'terminal' (reap now). The feed's own group-empty
          // unpin is the primary path; this is the missed-unpin backstop.
          if (agentId.startsWith('group:')) {
            // groupPinStatus distinguishes "no feed to ask" (→ 'unknown', TTL
            // only) from "the feed says this group is done" (→ 'terminal',
            // reap now). The `?.` shorthand conflated them and could unpin a
            // LIVE group pin during a feed-null window (#3811).
            return groupPinStatus(workerActivityFeed, agentId.slice('group:'.length))
          }
          if (turnsDb == null) return 'unknown'
          try {
            const row = getSubagentByJsonlId(turnsDb, agentId)
            if (row == null) return 'unknown'
            if (row.status === 'completed' || row.status === 'failed') return 'terminal'
            // A live 'running' row exempts the pin from the TTL (no churn on
            // healthy long workers); 'stalled' degrades to 'unknown' → TTL.
            if (row.status === 'running') return 'running'
            return 'unknown'
          } catch {
            return 'unknown' // DB hiccup degrades to "keep until TTL"
          }
        },
        ttlMs: WORKER_PIN_REAPER_TTL_MS,
        now,
      })
      for (const reap of reaps) {
        const storeOnly = storeOnlyKeys.has(reap.pinKey)
        process.stderr.write(
          `telegram gateway: worker-pin reaper unpinning ${reap.pinKey} ` +
            `(chat=${reap.chatId} reason=${reap.reason}` +
            `${storeOnly ? ' source=store-orphan' : ''})\n`,
        )
        if (storeOnly && reap.messageId != null) {
          // No in-memory claim to reconcile: unpin the exact tracked message
          // (per-message — group-safe) and drop the store row directly. Both
          // are best-effort/idempotent; a failed unpin still drops the row so
          // the next boot's cleanup is the final backstop.
          try {
            await statusPinApi().unpinChatMessage(reap.chatId, reap.messageId) // allow-raw-pin: store-orphan reap — by definition there is NO in-memory claim, so this unpins the exact tracked message id (group-safe, never unpin-all).
          } catch (err) {
            process.stderr.write(
              `telegram gateway: worker-pin reaper store-orphan unpin failed ` +
                `(${reap.pinKey} chat=${reap.chatId} msg=${reap.messageId}): ` +
                `${(err as Error).message}\n`,
            )
          }
          await mutateStatusPinRow( // allow-raw-pin-store: drops the row for the store orphan unpinned immediately above; there is no claim to reconcile.
            STATUS_PIN_STORE_PATH,
            statusPinStoreFs,
            reap.pinKey,
            null,
          )
        } else {
          await reconcileStatusPin(reap.pinKey, reap.chatId, { pinned: false })
        }
      }
    } catch (err) {
      process.stderr.write(
        `telegram gateway: worker-pin reaper error: ${(err as Error).message}\n`,
      )
    }
  }
}

// Single-flight: a pass awaits Telegram calls that can park behind a flood-wait
// for longer than the interval, so ticks fanned out. See periodic-sweep-guard.ts.
const midSessionReaperGuard = createPeriodicSweepGuard({
  run: runMidSessionCardReaper,
  onSkip: () => process.stderr.write(
    'telegram gateway: mid-session reaper tick skipped — previous pass still running\n',
  ),
  onError: (err) => process.stderr.write(
    `telegram gateway: mid-session reaper pass threw: ${(err as Error).message}\n`,
  ),
})

const midSessionCardReaper = isGatewayMain ? setInterval(() => {  // #2996 P0c gate
  void midSessionReaperGuard.tick()
}, MID_SESSION_CARD_REAPER_INTERVAL_MS) : undefined
midSessionCardReaper?.unref()

// NOTE: statusPinBootCleanup() is deliberately NOT invoked here at import time.
// The status-pin store is a SHARED per-agent file, and cleanup issues real
// unpinChatMessage calls. On a double-boot the losing gateway must NOT touch
// that shared state — its unpins would strip pins the STILL-ALIVE holder
// legitimately owns. So the call is gated on winning the startup mutex
// (top-level await below); see the acquireStartupLock block.

/**
 * The single entry point that mutates pin state for `pinKey`. Serialises
 * nothing itself — callers fire-and-forget; the pure decision + drop-on-unpin
 * contract keep state consistent. No-op when the feature is disabled.
 */
async function reconcileStatusPin(
  pinKey: string,
  chatId: string,
  desired: DesiredPin,
  /** Forum topic the pinned message lives in, when the caller knows it. Keyed
   *  into the claim + the durable row so a post-crash sweep can aim
   *  `unpinAllForumTopicMessages` at the right topic. */
  threadId?: number,
): Promise<void> {
  // Fire-and-forget hard boundary. Most callers invoke this as
  // `void reconcileStatusPin(...)` (auto status-pin is best-effort — it must
  // never affect turn flow). reconcilePin already swallows pin/unpin API
  // errors via onError, but the surrounding persistence + Map bookkeeping
  // (and any future edge) could still reject the returned promise. A rejected
  // fire-and-forget promise becomes a process-level `unhandledRejection` which
  // the gateway's handler crashes on — that is exactly how a benign
  // "not enough rights to manage pinned messages" 400 in a supergroup took the
  // whole gateway down (marko, 2026-07-01). Auto status-pin is cosmetic; it
  // must NEVER be able to crash the gateway. Any throw here is logged and
  // absorbed. (The `pin_message` MCP tool still surfaces failures to the agent
  // as a normal tool-error — that path is `executePinMessage`, not this one.)
  try {
    // Serialize per pinKey (F2): reconcileStatusPinInner reads `prev` from the
    // in-memory claim map at its top, so overlapping same-key reconciles must
    // run one-at-a-time or a stale `prev` clears the disk row under a live pin.
    await withPinReconcileLock(pinKey, () => reconcileStatusPinInner(pinKey, chatId, desired, threadId))
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err)
    process.stderr.write(
      `telegram gateway: status-pin reconcile absorbed error ` +
        `(key=${pinKey} chat=${chatId}): ${msg}\n`,
    )
  }
}

async function reconcileStatusPinInner(
  pinKey: string,
  chatId: string,
  desired: DesiredPin,
  threadId?: number,
): Promise<void> {
  if (!PIN_STATUS_WHILE_WORKING) return
  if (chatId.length === 0) return
  // Serialized per pinKey by `withPinReconcileLock` at the caller (F2), so this
  // `prev` snapshot is taken only after any prior same-key reconcile fully
  // settled — always the true current claim. Closes the stale-`prev` race (a
  // turn-end clear dropping the disk row under a flood-delayed open-pin) and the
  // older duplicate-pin concern (two edits both reading prev=null).
  const claim = statusPinClaims.get(pinKey)
  const prev: PinState | null = claim == null ? null : { messageId: claim.messageId }

  const runReconcileFrom = (action: PinLegAction, from: PinState | null) =>
    executePinLeg({
      api: statusPinApi(),
      chatId,
      prevState: from,
      action,
      rightsCache: statusPinRightsCache,
      onPinRightsDisabled: (chat) => {
        // Logged ONCE per chat per process (#3024). Every subsequent auto-pin
        // attempt in this chat is skipped silently until a restart clears the
        // cache — replacing the 41x/48h `status-pin pin failed` spam marko saw.
        process.stderr.write(
          `telegram gateway: status-pin disabled for chat ${chat}: bot lacks ` +
            `pin rights; grant 'Pin messages' admin right to re-enable after restart\n`,
        )
      },
      onError: (phase, err) => {
        const msg = err instanceof Error ? err.message : String(err)
        process.stderr.write(
          `telegram gateway: status-pin ${phase} failed (key=${pinKey} chat=${chatId}): ${msg}\n`,
        )
      },
    })

  // Persist ordering + the RETARGET two-leg expansion: status-pin-retarget.ts.
  await runStatusPinReconcile({
    pinKey,
    chatId,
    threadId,
    prev,
    desired,
    // persist:null ⇒ no durable row (STATIC / feature-off).
    persist: statusPinPersistEnabled
      ? { path: STATUS_PIN_STORE_PATH, fs: statusPinStoreFs }
      : null,
    runPin: runReconcileFrom,
    claims: statusPinClaims,
  })
}

// #3207: the per-worker `reconcileWorkerPin(agentId, …)` (keyed `wk:<agentId>`)
// was removed. Now that background workers COALESCE into one shared message per
// chat/thread, the pin is driven at the GROUP level by the feed itself
// (`reconcilePin` → `wk:group:<feedKey>`, wired at createWorkerActivityFeed):
// it pins when the group's first worker paints and unpins only when the group
// empties. A per-worker unpin used to physically unpin a message a sibling
// still needed, after which the survivor's re-pin NO-OP'd (its claim still
// named that id) — leaving live work unpinned (review blocker).

/** Unpin every owned status pin — used by the pre-restart sweep so a
 *  crash / interrupt never leaves a permanent pin behind. Best-effort;
 *  clears the claim regardless of the unpin outcome (drop-on-unpin). */
async function unpinAllStatusPins(): Promise<void> {
  // The chat id is a FIELD of the claim (#3809), so every claim is unpinnable —
  // there is no "claim we know about but cannot address" branch to fall through.
  for (const [key, claim] of [...statusPinClaims.entries()]) {
    await reconcileStatusPin(key, claim.chatId, { pinned: false })
  }
}

// ─── Stale-pin stack sweep ──────────────────────────────────────────────────
// A Telegram chat holds a STACK of pins; `getChat().pinned_message` exposes only
// the TOP and there is no list-pins method, so a probe-based cleanup never sees
// the rest. Worse (verified live 2026-07-29): a bare `unpinChatMessage` on a
// stale entry is a SILENT NO-OP that returns ok:true, so the gateway logged a
// clean sweep on every boot while the stack grew unbounded — 37 orphans across
// 5 agents, 21 in one chat. The drain, the rate gates and the durable
// obligation cursor live in stale-pin-sweep.ts; this is just the binding.
//
// Eligibility mirrors statusPinBootCleanup's mutex gate: set true ONLY after
// this gateway wins the startup lock, so a losing double-boot never clears the
// live holder's pins.
let stalePinSweepEligible = false
// Durable ledger: fsync'd tempfile + atomic rename, so a power cut leaves either
// the previous complete ledger or the new one — never a truncated file that
// forgets an in-flight drain.
const STALE_PIN_SWEEP_STORE_PATH = join(STATE_DIR, 'stale-pin-sweep.json')
const sweepStoreFs = {
  readFileSync: (p: string) => readFileSync(p, 'utf-8'),
  writeFileSync: (p: string, data: string) => atomicWriteFileSync(p, data, 0o600),
  existsSync: (p: string) => existsSync(p),
}
const stalePinSweeper: StalePinSweeper = createGatewayStalePinSweeper({
  telegram: { handle: () => lockedBot, call: robustApiCall },
  claims: () => statusPinClaims.values(),
  loadPinRows: () =>
    statusPinPersistEnabled || bannerPinPersistEnabled || toolPinPersistEnabled
      ? loadStatusPins(STATUS_PIN_STORE_PATH, statusPinStoreFs)
      : [],
  eligible: () => stalePinSweepEligible,
  // Share the live path's per-process pin-rights negative cache so the sweep
  // and executePinLeg agree on rights-less chats (D3): the sweep skips a chat
  // the live path already proved rights-less, and feeds its own reactive
  // discoveries back so the live path skips too.
  rightsCache: statusPinRightsCache,
  store: { path: STALE_PIN_SWEEP_STORE_PATH, fs: sweepStoreFs },
  // Per-deployment override only. UNSET (the normal case) means "take the
  // standing policy" — UNPIN_ALL_FORUM_TOPIC_ENABLED in stale-pin-sweep.ts,
  // i.e. the WHOLESALE topic drain stays off because it also removes pins this
  // gateway never placed. Set the env var to 1 to opt a deployment in.
  allowUnpinAllForumTopic:
    process.env.SWITCHROOM_PIN_SWEEP_UNPIN_ALL_TOPIC == null
      ? undefined
      : process.env.SWITCHROOM_PIN_SWEEP_UNPIN_ALL_TOPIC === '1',
})

/**
 * Boot-time pin cleanup + stale-pin stack sweep. Collects the `(chat, thread)`
 * targets with a prior-session pin record BEFORE the store reapers empty the
 * stores, runs the three boot reapers, marks the sweep eligible, then drains
 * each recorded target. Ordering and per-step isolation live in
 * `runBootPinSweepSteps` (boot-sweep-gate.ts) — a throwing reaper must not
 * strand `enableSweep`. Dispatched only via `bootPinSweepGate` below (mutex
 * won AND `lockedBot` constructed); fire-and-forget — never blocks boot.
 */
function runBootPinCleanupAndStalePinSweep(): Promise<void> {
  return runBootPinSweepSteps({
    scanSweepTargets: () =>
      collectSweepTargets({
        statusPins:
          statusPinPersistEnabled || bannerPinPersistEnabled || toolPinPersistEnabled
            ? loadStatusPins(STATUS_PIN_STORE_PATH, statusPinStoreFs)
            : [],
        activityCards: activityCardPersistEnabled
          ? loadActivityCards(ACTIVITY_CARD_STORE_PATH, activityCardStoreFs)
          : [],
        queuedCards: queuedCardPersistEnabled
          ? loadQueuedCards(QUEUED_CARD_STORE_PATH, queuedCardStoreFs)
          : [],
      }),
    statusPinCleanup: statusPinBootCleanup,
    activityCardReaper: activityCardBootReaper,
    queuedCardReaper: queuedCardBootReaper,
    // This gateway owns the shared pin state — enable the drain (this sweep
    // AND lazy first-inbound sweeps).
    enableSweep: () => {
      stalePinSweepEligible = true
    },
    seedPruneSweepCursors: () => reseedSweepLedger(STALE_PIN_SWEEP_STORE_PATH, sweepStoreFs),
    sweepTarget: (t: SweepTarget) => stalePinSweeper.sweepTarget(t),
    log: (line) => process.stderr.write(line),
  })
}

// #3664: needs BOTH the mutex (arm) and a constructed `lockedBot` (botReady,
// end of initGatewayBot) before it may run — see boot-sweep-gate.ts.
const bootPinSweepGate = createBootSweepGate({ run: runBootPinCleanupAndStalePinSweep, onError: (err) => process.stderr.write(`telegram gateway: boot pin cleanup / stale-pin sweep failed: ${(err as Error).message}\n`) })

// Activity feed. The gateway streams a live "what it's doing" tool-activity
// feed for every turn. The PreToolUse sidecar emits a `tool_label` per tool
// call (flush-independent, so it stays real-time on fast/clustered-tool
// turns); each label appends to `turn.mirrorLines`, and `renderActivityFeed`
// renders the capped list into an in-place EDITED message (sendMessage +
// editMessageText) anchored as a native reply-quote to the user's question.
// The feed clears on the first reply (hand-off to the answer) and again at
// turn_end (the no-reply safety net). It does NOT touch the answer-stream's
// draft/visible lane — the two render on separate surfaces, so they never
// collide.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
const progressDriver: any = null
const unpinProgressCardForChat: ((chatId: string, threadId: number | undefined) => void) | null = null
const getPinnedProgressCardMessageId: ((turnKey: string, agentId?: string) => number | null) | null = null
const completeProgressCardTurn:
  | ((args: { chatId: string; threadId: number | undefined; turnKey: string }) => void)
  | null = null
// #1122 PR3: flushProgressCardsForShutdown deleted with the card. No
// replacement needed — there are no pinned progress messages to flush.
let subagentWatcher: SubagentWatcherHandle | null = null
// Background-worker activity feed manager. Module-scoped so shutdown can stop()
// its internal heartbeat interval (mirrors subagentWatcher). Recreated per
// bridge connect; the stale handle's interval is unref'd, so a missed stop()
// can't keep the process alive, but we stop() on shutdown for cleanliness.
let workerActivityFeed: ReturnType<typeof createWorkerActivityFeed> | null = null

// ─── IPC server ───────────────────────────────────────────────────────────
const SOCKET_PATH = process.env.SWITCHROOM_GATEWAY_SOCKET ?? join(STATE_DIR, 'gateway.sock')
// Ensure the directory for the socket exists (#2996 P0c: gated — disk write).
if (isGatewayMain) mkdirSync(STATE_DIR, { recursive: true, mode: 0o700 })

// PID file + session marker. See pid-file.ts and session-marker.ts for
// the 2026-04-22 incident that motivates these. The PID file lets the
// in-agent plugin distinguish "gateway gone" from "socket blinked on a
// live gateway"; the session marker lets the crash-recovery banner
// distinguish a real process restart from a grammY poll-restart.
const GATEWAY_PID_PATH = process.env.SWITCHROOM_GATEWAY_PID_FILE ?? join(STATE_DIR, 'gateway.pid.json')
const GATEWAY_SESSION_MARKER_PATH = process.env.SWITCHROOM_GATEWAY_SESSION_MARKER ?? join(STATE_DIR, 'gateway-session.json')
// Separate from gateway-session.json (which fires the recovery banner on a
// real process restart) and from restart-pending.json (the user-initiated
// /restart marker carrying chat_id + ack_message_id). This one is written
// by the SIGTERM/SIGINT handler so the next boot can suppress the
// "recovered from unexpected restart" banner for planned shutdowns.
const GATEWAY_CLEAN_SHUTDOWN_MARKER_PATH = process.env.SWITCHROOM_GATEWAY_CLEAN_SHUTDOWN_MARKER ?? join(STATE_DIR, 'clean-shutdown.json')
const GATEWAY_STARTED_AT_MS = Date.now()

// Boot card: feature flag (default on) + handle for unpinning on first turn
const BOOT_CARD_ENABLED = process.env.SWITCHROOM_BOOT_CARD !== 'false'
let activeBootCard: BootCardHandle | null = null
// In-flight indicator for the boot card sendMessage. Set synchronously
// at the start of an emission, cleared in finally. The bridge-reconnect
// dedupe checks this so it can't race against the boot path's await.
// See issue #489 (klanker msgId 4715 + 4716, 2026-05-01 10:13:15).
let bootCardPending = false
// Boot-determined restart reason — see determineBridgeReconnectReason (B2).
let bootReasonAtStartup: RestartReason | null = null

// Issues card (#428) — pinned per-agent surface listing current
// unresolved entries from the issue sink (#425). Idempotent across
// the bridge-reconnect and boot-card paths so we never spawn two
// watchers per gateway lifetime.
const ISSUES_CARD_ENABLED = process.env.SWITCHROOM_ISSUES_CARD !== 'false'
let activeIssuesCard: IssuesCardHandle | null = null
let activeIssuesWatcher: IssuesWatcherHandle | null = null

/**
 * Idempotently start the issues card + watcher for this gateway. Called
 * from both the boot-path and bridge-reconnect paths once we've
 * resolved the chat to post into. Subsequent calls are no-ops — the
 * first call wins for the gateway's lifetime.
 */
function ensureIssuesCard(chatId: string, threadId: number | undefined): void {
  if (!ISSUES_CARD_ENABLED) return
  if (activeIssuesCard != null) return
  const agentSlug = process.env.SWITCHROOM_AGENT_NAME ?? '-'
  const agentDisplayName = resolvePersonaName(agentSlug)
  const stateDir = process.env.TELEGRAM_STATE_DIR
  if (!stateDir) {
    process.stderr.write(
      `telegram gateway: issues-card: TELEGRAM_STATE_DIR unset, skipping\n`,
    )
    return
  }
  const botApi: import('../issues-card.js').BotApiForIssuesCard = wrapIssuesCardApi(threadId)
  activeIssuesCard = createIssuesCardHandle({
    agentName: agentDisplayName,
    chatId,
    threadId,
    bot: botApi,
    log: (msg) => process.stderr.write(`telegram gateway: ${msg}\n`),
    // Closes #472 finding #19 — persist the card's message_id so a
    // gateway crashloop edits the existing pinned card on every boot
    // instead of posting a duplicate. Lives in the gateway's per-agent
    // state dir alongside other ephemerals.
    persistPath: join(stateDir, 'issues-card.json'),
  })
  activeIssuesWatcher = startIssuesWatcher({
    stateDir,
    card: activeIssuesCard,
    log: (msg) => process.stderr.write(`telegram gateway: ${msg}\n`),
  })
  process.stderr.write(
    `telegram gateway: issues-card: started watcher chat_id=${chatId} thread_id=${threadId ?? '-'} state_dir=${stateDir}\n`,
  )
}

// Startup mutex. Atomic single-writer claim on the PID file so two
// gateway processes can't race on Telegram's getUpdates long-poll.
// See startup-mutex.ts for the 2026-04-23 incident this closes
// (clerk-gateway looped 13+ times on 409 Conflict because the OLD
// process's long-poll TCP socket hadn't FIN'd before the NEW one
// started polling).
//
// Behaviour:
//   - acquired       → we own the file, log boot.lock_acquired, continue
//   - blocked (alive holder)  → log boot.lock_blocked, exit(1).
//                                systemd's restart-burst limiter
//                                (StartLimitBurst=10/IntervalSec=60)
//                                handles the back-off so we don't
//                                hot-loop spawning processes.
//   - acquired with stale recovery → log boot.lock_stale_recovered then
//                                     boot.lock_acquired
//
// We use top-level await so the mutex resolves BEFORE any other module
// code runs (in particular before the bot.start IIFE further down).
if (isGatewayMain) {  // #2996 P0c: gated in place; guarded await never runs on import
  const SWITCHROOM_AGENT_NAME = process.env.SWITCHROOM_AGENT_NAME ?? '-'
  try {
    const outcome = await acquireStartupLock({
      path: GATEWAY_PID_PATH,
      record: { pid: process.pid, startedAtMs: GATEWAY_STARTED_AT_MS },
      agentName: SWITCHROOM_AGENT_NAME,
    })
    if (outcome.status === 'blocked') {
      // Another live gateway already owns the lock. Exit non-zero so
      // systemd applies its restart-burst backoff. Logging done by
      // acquireStartupLock; add one extra line so the operator sees
      // WHY we're exiting.
      process.stderr.write(
        `telegram gateway: boot.aborting another_gateway_is_live holder_pid=${outcome.holder.pid} agent=${SWITCHROOM_AGENT_NAME}\n`,
      )
      process.exit(1)
    }
    // Backwards compatibility: the non-atomic writePidFile() that this
    // block REPLACES used to log a `wrote PID file` line. Keep an
    // equivalent so anything grepping older logs still finds it.
    process.stderr.write(
      `telegram gateway: wrote PID file ${GATEWAY_PID_PATH} pid=${process.pid} startedAt=${GATEWAY_STARTED_AT_MS}\n`,
    )
    // #3284 — this boot ACQUIRED the boot lock, so it is the surviving healthy
    // session. Consume the session-model carrier now (delete the carrier + the
    // bounded-retry attempt counter). start.sh no longer deletes the carrier
    // before apply: an apply-boot that wedged before reaching this point leaves
    // the carrier in place so the retry boot RE-APPLIES the intended model
    // instead of silently reverting to the configured default (the marko/klanker
    // boot.lock_stale_recovered_boot_mismatch revert). Best-effort, gated on
    // lock ownership so a LOSING double-boot never clears the winner's carrier.
    {
      const carrierAgentDir = resolveAgentDirFromEnv()
      if (carrierAgentDir != null) consumeSessionModelCarrierOnHealthyBoot(carrierAgentDir)
    }
    // We WON the startup mutex — the sole live owner of the shared per-agent
    // pin store may clear a dead session's orphans (a LOSING double-boot must
    // not, hence arming here, not at import). #3664: arming is HALF the
    // precondition — the gate holds the sweep until `lockedBot` exists.
    bootPinSweepGate.arm()
  } catch (err) {
    process.stderr.write(
      `telegram gateway: boot.lock_acquire_failed err=${(err as Error).message} agent=${SWITCHROOM_AGENT_NAME}\n`,
    )
    // Fall through to the legacy non-atomic write so we don't make
    // things WORSE on filesystems where link() doesn't work (FAT, some
    // FUSE mounts). The mutex is best-effort defence-in-depth; the
    // existing pid-file probe + 409-retry loop are still in place.
    try {
      writePidFile(GATEWAY_PID_PATH, { pid: process.pid, startedAtMs: GATEWAY_STARTED_AT_MS })
      process.stderr.write(`telegram gateway: wrote PID file ${GATEWAY_PID_PATH} pid=${process.pid} startedAt=${GATEWAY_STARTED_AT_MS} (mutex-fallback)\n`)
      // Mutex was unavailable (link() unsupported fs); the legacy pid-file
      // probe + 409-retry loop is still the liveness guard on this path. A
      // successful writePidFile here means no live holder was detected, so
      // running orphan cleanup is consistent with the pre-mutex behaviour.
      // #3284: same healthy-boot carrier consume as the mutex-acquired path —
      // a successful writePidFile means no live holder was detected, so this is
      // the surviving session.
      {
        const carrierAgentDir = resolveAgentDirFromEnv()
        if (carrierAgentDir != null) consumeSessionModelCarrierOnHealthyBoot(carrierAgentDir)
      }
      // #3026: same sequenced cleanup + DM sweep, same #3664 bot-ready gate.
      bootPinSweepGate.arm()
    } catch (writeErr) {
      process.stderr.write(`telegram gateway: writePidFile failed: ${writeErr}\n`)
    }
  }
}

// #1122: framework safety-net for "model is silent to the user for >5min."
// Starts a single setInterval poll that walks active turns; at 300s of
// silence the framework unwedges the turn. The generic "still working… /
// still thinking…" stall message it used to send was a stop-gap from
// before the live draft carried the progress beats and has been retired
// (the stall-stop-gap PR) — the surviving user-visible sends are the
// deterministic update_apply phase line and the approval-blocked re-ping.
// The model-targeted nudge ladder (ack/soft/firm) and the 60s awareness
// ping were retired earlier once the live-updating reply/draft took over
// the pacing job — only this single unwedge fallback remains. Honours
// SWITCHROOM_DISABLE_SILENCE_POKE=1 kill switch (no-op if set).
// Set when this gateway dispatches an `update_apply` to hostd that
// returns `started`; cleared when the dispatch poll resolves (terminal
// / not-configured / timeout). While set, the framework silence
// fallback substitutes hostd's real phase + elapsed for the generic
// "still working…" text — deterministic, model-free, the klanker
// incident fix. In-memory only; a gateway recreate naturally resets it.
let inFlightUpdate: { requestId: string; startedAt: number } | null = null

// Fix A — silence-fallback tuning (status-surface darkening, 2026-06-05). A long
// quiet tool stretch (foreground sub-agent / big research) crossed the 300s
// fallback and nulled currentTurn, darkening the live activity feed mid-work.
//   SWITCHROOM_SILENCE_FALLBACK_MS         — base threshold (default 300000)
//   SWITCHROOM_SILENCE_FALLBACK_HARD_MS    — hard ceiling for the in-flight-tool
//                                            defer (default 900000 = 15min)
//   SWITCHROOM_SILENCE_DEFER_INFLIGHT_TOOLS=1 — enable the defer. NOTE: this is
//                                            now set fleet-wide in defaults.env
//                                            (was a marko canary against #2162;
//                                            promoted to the fleet default). The
//                                            code default below is still OFF, so
//                                            the live behaviour comes from config.
function parsePositiveMsEnv(name: string, fallbackMs: number): number {
  const raw = process.env[name]
  if (raw == null || raw === '') return fallbackMs
  const n = Number(raw)
  return Number.isFinite(n) && n > 0 ? Math.floor(n) : fallbackMs
}
// Orphaned-reply "recently streaming" window (thinking-pause fix). If a genuine
// stream event landed within this window, the fuse re-arms instead of firing —
// so a long model reasoning pause (which emits no text/tool events) is
// survivable while a genuine multi-minute hang still surfaces. Default 120 s.
const ORPHANED_REPLY_STREAM_WINDOW_MS = parsePositiveMsEnv('SWITCHROOM_ORPHANED_REPLY_STREAM_WINDOW_MS', 120_000)
const SILENCE_FALLBACK_MS = parsePositiveMsEnv('SWITCHROOM_SILENCE_FALLBACK_MS', 300_000)
const SILENCE_FALLBACK_HARD_MS = parsePositiveMsEnv('SWITCHROOM_SILENCE_FALLBACK_HARD_MS', 900_000)
// #2527 — mid-turn liveness floor threshold (default 45s). Still gates the
// decision (`decideMidTurnFloor`, role + delivery + fire-once + timing) for a
// `user` turn working silently this long without a substantive answer.
// Phase 3 (deterministic-turn-liveness.md): the busy-but-silent case no
// longer sends TEXT at this threshold — the climbing card (Phase 1) covers
// it. The ONE surviving delivery gated by this threshold is the
// approval-blocked re-ping (see `onMidTurnFloor` below). Strictly below
// SILENCE_FALLBACK_MS (the loud 300s unwedge). Whole floor is
// kill-switchable via SWITCHROOM_TG_LIVENESS_FLOOR=0.
const SILENCE_FLOOR_MS = parsePositiveMsEnv('SWITCHROOM_SILENCE_FLOOR_MS', 45_000)
// #2527 — role-aware terminal reaction honesty (the "thumbs-up false done"
// fix). Default ON; SWITCHROOM_TG_TERMINAL_HONESTY=0 reverts to always-👍.
const LIVENESS_TERMINAL_HONESTY = process.env.SWITCHROOM_TG_TERMINAL_HONESTY !== '0'
// Option A transcript-prose delivery bridge. When a user turn ends without a
// final answer, the Stop hook scans transcript_path and — if it isolated a
// substantive answer the model wrote as plain text but never sent through the
// reply tool — persists it in silent-end-pending.json as `pendingText`. On the
// FIRST silent-end the gateway reads it back and delivers it directly via the
// normal send path, instead of relying on the (unreliable) Stop-hook re-prompt
// or waiting ~2-5 min for the obligation represent to recover it. Default ON;
// SWITCHROOM_TG_CAPTURED_PROSE_DELIVERY=0 reverts to the pre-bridge behaviour
// (re-prompt + represent only).
const CAPTURED_PROSE_DELIVERY_ENABLED =
  process.env.SWITCHROOM_TG_CAPTURED_PROSE_DELIVERY !== '0'
// SILENCE_DEFER_INFLIGHT_TOOLS: previously an opt-in (=1). The new
// isLegitimatelyWorking callback supersedes this — defer is now the DEFAULT
// when the callback is wired. The legacy flag is kept so `=0` still lets
// operators force-disable the defer (handled inside silence-poke.ts tick()).
// The old `=1` path is kept for back-compat but is now redundant.
const SILENCE_DEFER_INFLIGHT_TOOLS = process.env.SWITCHROOM_SILENCE_DEFER_INFLIGHT_TOOLS === '1'
// Production-liveness (2026-06-05 UAT finding). Count an activity-feed render or
// an answer-stream draft update as liveness for the silence clock, so a long
// tool/composition turn that's visibly producing doesn't trip the 300s fallback
// and null currentTurn mid-work. Default ON; SWITCHROOM_SILENCE_LIVENESS_PRODUCTION=0
// restores the legacy "only a real reply resets the clock" behaviour.
const SILENCE_LIVENESS_PRODUCTION = process.env.SWITCHROOM_SILENCE_LIVENESS_PRODUCTION !== '0'
// Sparse chat-legible memory (#2849, hindsight Phase 4). Surface ONE terse
// line in the originating chat/topic when the interactive session materially
// changes what it remembers (create_directive / invalidate / demote) — never
// on ordinary recall or routine consolidation. Default ON;
// SWITCHROOM_MEMORY_LEGIBILITY=0 disables it.
const MEMORY_LEGIBILITY_ENABLED = isMemoryLegibilityEnabled(process.env.SWITCHROOM_MEMORY_LEGIBILITY)
// Consolidation-driven legibility (#2849 follow-up, hindsight Phase 4). The
// "updated what I know about Y" side, driven by the background
// `consolidation.completed` webhook rather than a foreground tool call.
// OPT-IN (default OFF), unlike MEMORY_LEGIBILITY_ENABLED above: this path is
// fed by an unbounded background engine + a webhook the pinned hindsight image
// does not yet emit, so the RFC keeps it "sparse … clearly gated".
const CONSOLIDATION_LEGIBILITY_ENABLED = isConsolidationLegibilityEnabled(
  process.env.SWITCHROOM_CONSOLIDATION_LEGIBILITY,
)
// One long-lived limiter across all consolidation events — collapses a burst
// of material consolidations to at most one line per interval, and suppresses
// an identical "updated about X" line inside the dedup window.
const consolidationRateLimiter = new ConsolidationRateLimiter()

/**
 * Feed-survival predicate — the single source of truth for "is this turn
 * legitimately working?" used by BOTH teardown timers (orphaned-reply fuse
 * and silence-poke framework fallback).
 *
 * Returns true if ANY of the following hold for the given chat key:
 *
 *   (a) A foreground tool call is in flight in the current turn
 *       (`toolFlightTracker.isMidToolCall()`). This covers most tools
 *       including ask_user while it blocks awaiting a tap.
 *
 *   (b) Detached background work was dispatched in the current turn and has
 *       not yet resolved — `pendingProgress.hasPendingAsyncDispatch(key)`.
 *       Covers `Bash run_in_background:true` (which returns a near-instant
 *       handle, emptying inFlight, while the background process keeps
 *       running) and `Agent` / `Task` dispatches.
 *
 *   (c) A human-wait tool (`ask_user`) is open for this chat. A pending
 *       ask_user IS already captured by (a) while the tool_use is in flight,
 *       but we include the explicit pendingAskUser check for defence-in-depth
 *       (e.g. after an unlikely inFlight clear without a tool_result).
 *
 * The key is `statusKey(chatId, threadId)` — the same key used by
 * silencePoke / pendingProgress.
 */
function isLegitimatelyWorking(key: string): boolean {
  // (a) foreground in-flight tool.
  // NOTE: toolFlightTracker is GLOBAL, not per-key. In a hypothetical
  // multi-chat agent a tool in flight for chat A would make this return
  // true for chat B's key. Accepted: the gateway runs one Claude session
  // (one turn in flight at a time); true multi-chat concurrency is not
  // currently supported. (b) and (c) below are correctly per-key.
  if (toolFlightTracker.isMidToolCall()) return true
  // (b) detached background work dispatched this turn
  if (pendingProgress.hasPendingAsyncDispatch(key)) return true
  // (c) ask_user open for this chat (defence-in-depth)
  const { chatId: keyChatId } = parseKeyForSurvival(key)
  for (const entry of pendingAskUser.values()) {
    if (entry.chatId === keyChatId) return true
  }
  return false
}

/** Parse `<chatId>:<threadIdOrEmpty>` — mirrors silence-poke's parseKey.
 *  Local copy so we don't need to re-export from silence-poke. */
function parseKeyForSurvival(key: string): { chatId: string } {
  const idx = key.indexOf(':')
  return { chatId: idx < 0 ? key : key.slice(0, idx) }
}

// ─── Silence-poke timer options — extracted to liveness-wiring.ts (#2996 P8 PR-C3) ───
// `floorState` / `onMidTurnFloor` / `onFrameworkFallback` moved VERBATIM into
// `buildSilencePokeOptions`; the gateway builds the deps and still REGISTERS
// the timer here (P0c: the module exports the body; the gateway owns the boot
// side effect). The two user-visible sends stay behind the gateway bot-api
// retry policy via the injected `sendSilenceText` closure.

/** Live gateway deps for the extracted silence-poke wiring. */
function gatewayLivenessWiringDeps() {
  return {
    SILENCE_FALLBACK_MS,
    SILENCE_FALLBACK_HARD_MS,
    SILENCE_FLOOR_MS,
    SILENCE_DEFER_INFLIGHT_TOOLS,
    // #3551 — governs the teardown notice's tail sentence: only promise a
    // re-ask when one will ACTUALLY follow. #3575 review B1: this used to be
    // the static `OBLIGATION_LEDGER_ENABLED` env boolean, which is true for the
    // whole process and so promised a re-ask for turns whose obligation was
    // already closed (represent cap reached then escalated, or closed silently
    // by an outbound-since-open — obligation-wiring.ts:230/:294) or never
    // opened at all (synthetic / steering / interrupt inbound). It is now a
    // live per-turn lookup keyed on the turn's own origin id: `turn.turnId` is
    // `deriveTurnId(chat, thread, messageId)` for a real inbound
    // (stream-render.ts:273), the SAME identity the ledger keys on
    // (obligation-wiring.ts:118).
    isObligationOpenForTurn: (originTurnId: string | null): boolean =>
      OBLIGATION_LEDGER_ENABLED && originTurnId != null && obligationLedger.isOpen(originTurnId),
    TURN_PREVIEW_MAX,
    STATE_DIR,
    isLegitimatelyWorking,
    getCurrentTurn: (): CurrentTurn | null => currentTurn,
    // #3580 — the KEYED read the three liveness predicates in liveness-wiring.ts
    // use. Flag-OFF this IS the singleton (byte-equivalent to getCurrentTurn());
    // flag-ON it is THIS topic's own turn, not the most-recent-set mirror, which
    // answers about whichever topic started a turn last and so false-reaps.
    getCurrentTurnForKey: (key: string): CurrentTurn | null => currentTurnMap.get(key),
    getInFlightUpdate: () => inFlightUpdate,
    getTurnsDb: () => turnsDb,
    getInboundSpool: (): ReturnType<typeof createInboundSpool> | undefined => inboundSpool,
    sendToAgent: (agent: string, m: InboundMessage): boolean => ipcServer.sendToAgent(agent, m),
    // The one bot-api touch — kept here behind the retry policy.
    sendSilenceText: async (chatId: string, threadId: number | null, text: string, silent: boolean): Promise<void> => {
      await robustApiCall(
        () => bot.api.sendMessage(chatId, text, {
          ...(threadId != null ? { message_thread_id: threadId } : {}),
          disable_notification: silent,
        }),
        { chat_id: chatId, ...(threadId != null ? { threadId } : {}) },
      )
    },
    getMyAgentName,
    statusKey,
    activeTurnStartedAt,
    activeStatusReactions,
    lastPtyPreviewByChat,
    preambleSuppressor,
    purgeReactionTracking,
    currentTurnMap,
    turnLiveForItsTopic,
    endCurrentTurnForKey,
    // Getter, not an eager read: `pendingInboundBuffer` (const) is declared
    // LATER than the module-load `startTimer` call that invokes this builder,
    // so a by-value capture is a temporal-dead-zone ReferenceError that
    // crash-loops boot (#3392). A getter (matching getInboundSpool / getTurnsDb
    // / ipcServer) is read only when the fallback fires, well after module eval.
    getPendingInboundBuffer: () => pendingInboundBuffer,
    trackRedeliveredInbound,
    // Two-state desync unwedge (#3927): drain the parked store the fallback else leaves latched — see liveness-wiring + stream-render drainParkedTurnStartsForChat.
    drainParkedTurnStarts: (chatId: string, threadId: number | null): number => drainParkedTurnStartsForChat(gatewayStreamRenderDeps(), chatId, threadId != null ? String(threadId) : null).length,
    closeActivityLane,
    closeProgressLane,
    // Stage B: escalate a mid-tool + marker-stale fallback to a real restart.
    // No cooldown (see hang-restart-decision.ts § STORM GUARD): the ask-first
    // resume_watchdog_timeout path is the sole, sufficient storm guard.
    hangRestart: {
      stalenessThresholdMs: hangStalenessMs(),
      request: (reason: string, idleMs: number) => {
        triggerSelfRestart(getMyAgentName(), `hang-watchdog:${reason} idle=${Math.round(idleMs)}ms`)
      },
    },
  }
}
export type LivenessWiringDeps = ReturnType<typeof gatewayLivenessWiringDeps>

if (isGatewayMain) silencePoke.startTimer(buildSilencePokeOptions(gatewayLivenessWiringDeps()))

// PR3b-cutover: drive the delivery machine's TTL `tick`. The machine
// expires any turn whose `turnStartedAt` is older than TURN_TTL_MS
// (5 min) and drops global state back to idle — its structural
// equivalent of the imperative silence-poke framework-fallback. This
// is the load-bearing safety net for the cutover gate: even if a
// `turnEnd` event is somehow missed (the dangle class), the machine
// self-heals at TTL instead of pinning the gate "in-flight forever".
// shadowEmit only advances state + logs the predicted effects; we
// deliberately do NOT execute the machine's firePoke here (the
// imperative silence-poke still owns the user-facing ping), so there
// is no double-poke. unref so the interval never holds the process.
const DELIVERY_MACHINE_TICK_MS = 30_000
const _deliveryMachineTick = isGatewayMain ? setInterval(() => {  // #2996 P0c gate
  shadowEmit({ kind: 'tick', now: Date.now() })
}, DELIVERY_MACHINE_TICK_MS) : undefined
_deliveryMachineTick?.unref?.()

// Enrol a buffer-redelivered inbound in the deliver-until-acked queue so the
// existing sweep re-delivers it until claude's `enqueue` ack lands. Wired into
// EVERY redelivery path (bridgeUp drain, silence-poke fallback, flap/reply-gate
// flushes) — `send` returning true only means the bytes reached the bridge, NOT
// that claude consumed them. Right after a restart (esp. a slow MCP boot) the
// inject can hit a not-ready session and be silently dropped, and nothing
// retried it: the clerk 2026-06-03 lost-message incident. Mirrors the
// live-delivery tracking at the handleInbound site (chatKey + messageId), so
// DMs and supergroup forum topics are handled identically. Only real user
// inbounds are tracked — shouldTrackDelivery excludes steer/interrupt/
// synthetic-source/empty, which never produce an `enqueue` and would otherwise
// re-deliver forever.
function trackRedeliveredInbound(merged: InboundMessage): void {
  // Dead-air pre-turn signal: this is the shared CONFIRMED-release chokepoint
  // (buffer drain, idle-drain tick, bridge re-register). A released
  // subagent-handback gets a `typing…` + pre-turn card the imminent turn
  // adopts; a no-op for every non-handback inbound (guarded inside the seam).
  // Emitted BEFORE the delivery-confirm early-return so it fires regardless of
  // that feature flag. Design lever 1: emit at release, do NOT gate on
  // turn-in-flight (the common case is a worker finishing while the parent is
  // mid-turn on another topic).
  if (HANDBACK_PRETURN_ENABLED) handbackPreturnSignal.noteHandbackRelease(merged)
  if (!DELIVERY_CONFIRM_ENABLED) return
  // The boot-resume synthetic ('resume_interrupted') is the ONE synthetic we DO
  // enrol: a restart can drop it into a not-ready session exactly like a user
  // inbound, leaving the interrupted work silently un-resumed. Safe iff it
  // carries the chat_id + message_id that make its enqueue ack-able — see
  // isTrackableResumeSynthetic. Every other synthetic stays excluded below.
  const isTrackableResume = isTrackableResumeSynthetic(merged.meta)
  if (
    !isTrackableResume &&
    !shouldTrackDelivery({
      isSteering: false,
      isInterrupt: false,
      hasSource: merged.meta?.source != null,
      effectiveText: merged.text,
    })
  ) {
    return
  }
  // Button-tap anti-storm guard — mirrors the immediate-delivery path in
  // deliverButtonTapInbound. A tap synthesized without a source message
  // (`cbMessageId == null` → `messageId: 0`, no meta.message_id) has no id
  // the `enqueue` ack can ever match, so enrolling it would make the
  // never-drop sweep re-deliver it until TTL. The immediate path skips
  // tracking for such taps; a tap that buffered mid-turn and flushed through
  // here must be skipped identically (asymmetry = a storm on one path only).
  if (
    merged.meta?.button_callback === 'true' &&
    (merged.meta.message_id == null || merged.meta.message_id === '')
  ) {
    return
  }
  const key = chatKey(merged.chatId, merged.threadId != null ? Number(merged.threadId) : null)
  trackDelivery(
    deliveryQueue,
    key,
    merged,
    Date.now(),
    merged.messageId != null ? String(merged.messageId) : null,
  )
}

// ─── Delivery-confirm sweep — extracted to delivery-confirm-wiring.ts (#2996 P8 PR-C1) ───
// `runDeliveryConfirmSweep` / `redeliverStrandedInbound` / `sweepSuspendedTargets`
// moved VERBATIM; the gateway keeps the deps builder, thin wrappers, and the
// `setInterval` registration below (P0c: modules export the tick body; the
// gateway owns the timer). Idle gate crosses as `getCurrentTurnNull` ONLY.

/** Live gateway deps for the extracted delivery-confirm sweep wiring. */
function gatewayDeliveryConfirmDeps() {
  return {
    DELIVERY_CONFIRM_ENABLED, DELIVERY_CONFIRM_TIMEOUT_MS,
    getCurrentTurnNull: (): boolean => currentTurn == null,
    sendToAgent: (agent: string, m: InboundMessage): boolean => ipcServer.sendToAgent(agent, m),
    deliveryQueue, pendingInboundBuffer, pendingPermissions, pendingAskUser,
  }
}
export type DeliveryConfirmWiringDeps = ReturnType<typeof gatewayDeliveryConfirmDeps>

let _deliveryConfirmWiring: ReturnType<typeof createDeliveryConfirmWiring> | undefined
function deliveryConfirmWiring(): ReturnType<typeof createDeliveryConfirmWiring> {
  return (_deliveryConfirmWiring ??= createDeliveryConfirmWiring(gatewayDeliveryConfirmDeps()))
}

function runDeliveryConfirmSweep(): void {
  deliveryConfirmWiring().runDeliveryConfirmSweep()
}

const _deliveryConfirmSweep = isGatewayMain ? setInterval(runDeliveryConfirmSweep, DELIVERY_CONFIRM_SWEEP_MS) : undefined
_deliveryConfirmSweep?.unref?.()

startOutboxSweep({ isGatewayMain, stateDir: STATE_DIR, getBot: () => bot, getTurnsDb: () => turnsDb, dedupCheck: (c, t, x) => outboundDedup.check(c, t, x, Date.now()) != null, recordOutbound: HISTORY_ENABLED ? (chatId, threadId, message_ids, texts) => { try { recordOutbound({ chat_id: chatId, thread_id: threadId, message_ids, texts }) } catch { /* best-effort */ } } : undefined, resolveReplyMarkup: makeOutboxListenMarkupResolver({ resolveVoiceOutPlan: (t) => resolveVoiceOutPlan(loadAccess().voice_out, t), cachePut: (token, payload) => voiceOnDemandCache.put(token, payload), eagerVoiceEnabled, enqueuePreSynth: (j) => voicePreSynthQueue.enqueue(j) }), log: (l) => process.stderr.write(l) }) // outbox: single deliverer for Stop-hook prose; resolveReplyMarkup keeps the #3502 Listen button on net-delivered answers; recordOutbound persists the net-delivered answer to history.db (../outbox.ts)

// #1445 cross-turn pending-async ambient. When a turn ends after the
// model dispatched background async work (Agent / Task / Bash run-in-
// background) and the model has stopped speaking, keep editing the
// model's last reply in place at 60s intervals so the user sees
// ambient liveness during the wait. Edits are silent, never spawn a
// new pinged message, and stop the moment the user re-engages or the
// model synthesises a handback. The full design rationale lives in
// `pending-work-progress.ts`'s header docblock. Kill switch:
// `SWITCHROOM_DISABLE_PENDING_PROGRESS=1`.
if (isGatewayMain) pendingProgress.startTimer({
  editMessage: async (ctx) => {
    // #2669: re-edit via the SAME shape the anchor was sent with. A rich
    // anchor (the reply tool's default) re-edits via the rich-markdown
    // path so the body keeps rendering its markdown; a literal
    // `format:'text'` anchor re-edits as a plain string. This is the
    // single-rich-path successor to the #1698 parse-mode contract.
    await swallowingApiCall(
      () =>
        lockedBot.api.editMessageText(
          ctx.chatId,
          ctx.messageId,
          ctx.literalText ? ctx.newText : richMessage(ctx.newText),
          undefined,
        ),
      {
        chat_id: ctx.chatId,
        verb: 'pending-progress-edit',
        ...(ctx.threadId != null ? { threadId: ctx.threadId } : {}),
        // #3084 PR 2 / L1: the progress-card edit is the #1 documented ban
        // trigger (repeated editMessageText on one message). Tag COSMETIC and
        // pass messageId/editPayload so the gate's per-message floor + no-op
        // skip + coalescing engage, and the edit sheds while a window is open.
        priorityClass: 'cosmetic',
        messageId: ctx.messageId,
        editPayload: ctx.literalText ? ctx.newText : richMessage(ctx.newText),
      },
    )
  },
  emitMetric: (event) => emitRuntimeMetric(event),
  // #1760 defense-in-depth: if a newer turn for this chat is active at
  // tick time, the prior turn's pending-progress is stale (the
  // canonical teardown was missed). Drop the ticker instead of editing
  // the old anchor — see pending-work-progress.ts's docblock.
  isActiveTurnNewerThan: (key, activatedAt) => {
    const turnStartedAt = activeTurnStartedAt.get(key)
    return turnStartedAt != null && turnStartedAt > activatedAt
  },
})

// Per-agent buffer for synthetic inbounds the gateway couldn't deliver
// because the bridge wasn't connected at send-time. Drained on
// bridge-register so a fresh client picks up missed wake-ups before
// any other work happens. See #1150 — pre-buffer, an Approve tap on a
// vault_request_access card during the 100ms bridge-reconnect window
// would mint the grant but silently drop the `vault_grant_approved`
// inbound, leaving the agent stuck waiting for a manual poke.
// Durable inbound spool on the persistent per-agent volume
// (STATE_DIR = /state/agent/telegram in prod — survives container
// recreate). Makes the "⏳ your message is queued and will be
// processed when it reconnects" promise deterministic across a
// gateway/container restart (finn/carrie lost-on-restart incident,
// 2026-05-19). STATIC mode has no runtime/bridge, so no spool.
// #2996 P0e: createInboundSpool hydrates its in-memory projection from the
// on-disk spool at construction (readFileSync) — a module-load disk read.
// Defer past import; still constructs at the identical boot point in prod
// (isGatewayMain true). Under an import()/vitest load it stays undefined, which
// is exactly the STATIC-mode shape every reader already guards for (`!= null`).
let inboundSpool: ReturnType<typeof createInboundSpool> | undefined
if (isGatewayMain) inboundSpool = STATIC
  ? undefined
  : createInboundSpool({
      path: join(STATE_DIR, 'inbound-spool.jsonl'),
      fs: {
        appendFileSync: (p, d) => appendFileSync(p, d),
        readFileSync: (p) => readFileSync(p, 'utf8'),
        writeFileSync: (p, d) => writeFileSync(p, d),
        renameSync: (a, b) => renameSync(a, b),
        existsSync: (p) => existsSync(p),
        statSizeSync: (p) => statSync(p).size,
        fsyncFileSync: fsyncPathSync, fsyncDirSync: fsyncPathSync,
      },
      // #2789 B: durability degradation must be visible, not silent. When
      // spool appends start failing we're back to in-memory-only — a
      // later crash loses those messages. Latched log so the operator /
      // health surface sees the transition rather than a silent downgrade.
      onDegraded: (info) => {
        process.stderr.write(
          `telegram gateway: inbound-spool durability ` +
          `${info.degraded ? 'DEGRADED to in-memory-only' : 'RECOVERED'} ` +
          `path=${info.path} consecutiveFailures=${info.consecutiveFailures}` +
          `${info.error != null ? ` error=${info.error}` : ''}\n`,
        )
      },
    })

// #2789 A: the in-memory cap eviction used to silently drop the oldest
// buffered inbound within a live session (the durable spool copy only
// replays at boot / escalates after 15 min). Surface it as a coalesced,
// per-chat "messages deferred" notice so the eviction is visible — the
// evicted message still lives in the spool, so it is deferred, not lost.
const EVICT_NOTICE_COOLDOWN_MS = 5 * 60 * 1000
const evictNoticeByChat = new Map<string, number>()
const pendingInboundBuffer = createPendingInboundBuffer({
  spool: inboundSpool,
  onEvict: (_agent, evicted) => {
    const chat = evicted.chatId
    const evThread =
      typeof evicted.meta?.threadId === 'string' && evicted.meta.threadId
        ? Number(evicted.meta.threadId)
        : undefined
    const key = `${chat}:${evThread ?? '-'}`
    const last = evictNoticeByChat.get(key)
    const nowMs = Date.now()
    // Coalesce: at most one deferral notice per chat per cooldown so a
    // sustained >32 burst posts one line, not one per evicted message.
    if (last != null && nowMs - last < EVICT_NOTICE_COOLDOWN_MS) return
    evictNoticeByChat.set(key, nowMs)
    const threadOpts = evThread != null ? { message_thread_id: evThread } : {}
    // Honesty: the evicted message is NOT re-pushed into the buffer
    // in-session — its only in-session resolution is the escalation sweep
    // (sweepEscalations, ~15 min), which either delivers it or posts the
    // "couldn't deliver … please resend" retraction. So this notice must
    // NOT promise a prompt pickup ("shortly"), or it would contradict a
    // later escalation. Word it to match that reality: saved, handled when
    // the current turn frees up, and prompted-to-resend if it can't be.
    void swallowingApiCall(
      () =>
        bot.api.sendMessage(
          chat,
          "⏳ Messages are arriving faster than I can process them. Your messages are saved and will be handled once I finish the current turn — if any can't be picked up, I'll ask you to resend it.",
          { ...threadOpts },
        ),
      { chat_id: chat, verb: 'inbound-buffer-eviction' },
    )
  },
  // fix/backstop-duplicate-reply MUST-FIX 2 — stamp the handback marker at the
  // enqueue chokepoint so a boot-replayed handback (not just the live synthesis
  // push) populates it. Every `subagent_handback` push funnels through here.
  onHandbackEnqueue: (chatId, threadId, ts) => subagentHandbackMarker.record(chatId, threadId, ts),
  // F1 (fix/represent-double-send-delivery-recheck) — delivery-time represent
  // retract. Every drain path hands its buffered inbounds through this gate; a
  // stale `obligation_represent` (its reply landed since the sweep decided it) is
  // dropped here rather than duplicated into the CLI queue. See represent-delivery-guard.ts.
  beforeRedeliver: makeRepresentRedeliveryGuard({ enabled: OBLIGATION_LEDGER_ENABLED, historyEnabled: HISTORY_ENABLED, ledger: obligationLedger, hasOutboundDeliveredSince, minReplyChars: OBLIGATION_REPRESENT_GUARD_MIN_REPLY_CHARS, log: (l) => process.stderr.write(l) }),
})

// PR2 obligation-ledger idle sweep. Re-present an OPEN obligation only at a
// CLEAN idle: no turn in flight AND the inbound buffer is empty — so the
// existing buffer-drain has already had its turn and anything still OPEN is
// "delivered but never answered" (the 715 gap). Re-present by pushing a
// synthetic must-answer inbound through the SAME buffer→drain path (idempotent
// OPEN via meta.source; reuses tested delivery). Bounded: after maxRepresents,
// escalate to ONE operator-visible "did I miss this?" and close — no loop.
// No-op unless the flag is on; gated on the same idle predicate as the drains.
// DETERMINISM (closed-form, not sampled). The obligation ledger itself
// (obligation-ledger.ts) is a finite FSM with a total transition function and a
// strictly-decreasing measure μ = (REPRESENT_MAX - representCount) +
// (ESCALATE_MAX - escalateAttempts): every markRepresented/markEscalateAttempt
// decreases μ, both terms are bounded below, and at the floor the only move is
// close → terminal. So on the FSM, every OPEN reaches answered | escalation-
// delivered | bounded give-up (no cycle re-increments a counter). This sweep is
// the FSM's driver; its termination rests on three liveness facts, all bounded:
//   (1) the 5s setInterval keeps firing;
//   (2) the gate (turnInFlightForGate) opens — the machine turn is cleared at
//       turn-end (purgeReactionTracking / releaseTurnBufferGate), on bridge
//       disconnect (bridgeDown), and by the machine's 5-min TTL tick;
//   (3) the escalation send settles — bounded BY CONSTRUCTION via withDeadline
//       below (grammy has no request timeout, so an unbounded send was the one
//       way an obligation could get stuck OPEN forever — now closed);
//   (4) the background-work grace releases — an obligation skipped because
//       agentHasInFlightBackgroundWork() is true is bounded by
//       OBLIGATION_BACKGROUND_WORK_GRACE_MS (a hard wall-clock ceiling from
//       openedAt). Even a permanently-stuck/leaked worker signal cannot suppress
//       the act past the ceiling, so this adds NO unbounded liveness dependency:
//       decideAtIdle ignores the work signal once now ≥ openedAt + ceiling, μ
//       resumes decreasing, and termination still holds.
// The only residual liveness assumption is the bridge eventually reconnecting /
// the process restarting, which the entire gateway's inbound delivery already
// depends on and which durable spool + boot-replay make self-healing.
// True when the agent has in-flight autonomous sub-agent work the turn-in-flight
// gate does NOT see: a running background worker (countRunningWorkers — its row
// is INSERTed status='running' at dispatch, before the parent turn ends), OR an
// orphaned/extended-autonomous FOREGROUND sub-agent that outlived its turn and is
// still touching the turn-active marker (#2240; background activity deliberately
// does NOT touch the parent marker, so the two signals are complementary).
// Used ONLY by the obligation sweep to bound a false escalation during genuine
// post-turn work. The caller already established the turn machine is idle (the
// `turnInFlightForGate()` early-return), so a fresh marker here means orphaned
// sub-agent activity (or a just-ended turn within the freshness window — a
// harmless small extra grace, bounded by the ceiling either way).
function agentHasInFlightBackgroundWork(now: number): boolean {
  if (countRunningWorkers() > 0) return true
  const ageMs = readTurnActiveMarkerAgeMs(STATE_DIR, now)
  return ageMs != null && ageMs < TURN_ACTIVE_MARKER_FRESH_MS
}
/**
 * Option A transcript-prose delivery. Deliver the model's real final answer —
 * isolated by the Stop hook's transcript scan and persisted as `pendingText`
 * — directly via the normal send path on the first silent-end, then settle the
 * bookkeeping so neither the obligation represent nor the exhausted fallback
 * re-fires for the same answer.
 *
 * Double-send guard — content + turnKey dedup, NOT unconditional (Finding 4,
 * #3228: the earlier "airtight by construction" claim overstated it):
 *  - Before sending, `outboundDedup.check` is consulted. If the EXACT same
 *    content already went out under the SAME `registryKey` (a prior turn_end
 *    delivered it, or the re-prompted model's own reply landed), we SKIP the
 *    send and only settle bookkeeping.
 *  - After a successful send, `outboundDedup.record` is written so a late
 *    reply-tool retry with the same content is suppressed at its send site
 *    (executeReply / executeStreamReply already consult the same cache).
 *  - The obligation is CLOSED and the silent-end state CLEARED, so
 *    obligationSweep's "outbound delivered since open" guard and the represent
 *    never re-fire for this origin.
 *
 * Divergence boundary (honest scope): the dedup key is
 * `(chat, thread, normalized-content, registryKey)`. It suppresses the common
 * double-send — the SAME answer re-sent within the TTL under the same
 * registryKey. It does NOT catch a re-present that lands under a DIFFERENT
 * registryKey with REWORDED content (different hash AND different key → the
 * cross-turn carve-out in recent-outbound-dedup.ts:150-156 treats two non-null
 * differing turnKeys as a miss): that is a genuinely different outbound and is
 * out of scope for content-hash dedup. The obligation close + state clear are
 * what make captured-prose and the represent mutually exclusive for the
 * common case; the content dedup is a second, best-effort layer.
 *
 * Failure posture (Finding 1 + exhaustion-boundary gap, #3228): if the send
 * throws, the catch below arms the deterministic Stop-hook re-prompt via
 * recordUndeliveredTurnEnd (the shared teardown may have already closed the
 * obligation when replyCalled was true, so "leaving the obligation open" is NOT
 * a sufficient net on its own). Two sub-cases, honored via the `{exhausted}`
 * verdict threaded out of settleCapturedProseDelivery:
 *  - budget REMAINING (`exhausted:false`) → the silent-end state is (re)written
 *    and the Stop-hook re-prompt will recover the answer; nothing else to do.
 *  - budget SPENT (`exhausted:true`) → recordUndeliveredTurnEnd has CLEARED the
 *    state (the re-prompt can no longer fire), and the obligation was already
 *    closed by the interim-ack teardown, so the user would get NEITHER the
 *    answer NOR the apology. We therefore deliver a user-facing fallback: first
 *    retry the captured prose as PLAIN TEXT (a non-rich send often survives the
 *    markdown/parse error a rich send rejected — the user gets the real
 *    answer), and only if THAT also fails post the generic silentEndFallbackText
 *    apology. This mirrors the non-captured exhausted path (silent-end.ts /
 *    gateway turn_end #1161) so the captured path is never worse than main.
 */
async function deliverCapturedProse(args: {
  chatId: string
  threadId: number | undefined
  statusKeyStr: string
  registryKey: string | null
  originTurnId: string
  text: string
  /** Turn elapsed for the honest "(waited Ns)" apology clause; optional. */
  turnDurationMs?: number; replyToolThrewThisTurn?: boolean // #4141: label prose recovered from a turn whose reply tool threw (see outbound-send-path.ts)
}): Promise<void> {
  // #2996 P2: body moved VERBATIM to outbound-send-path.ts (single tested
  // send module). Injects the ONE `outboundDedup` instance (Amendment 1/9).
  return deliverCapturedProseCore(gatewayCapturedProseDeps(), args)
}

/** Live gateway deps for the extracted captured-prose delivery (#2996 P2). */
function gatewayCapturedProseDeps(): DeliverCapturedProseDeps {
  return {
    outboundDedup,
    bot,
    robustApiCall,
    redactOutboundText,
    recordOutbound,
    HISTORY_ENABLED,
    OBLIGATION_LEDGER_ENABLED,
    obligationLedger,
    clearSilentEndState,
    recordUndeliveredTurnEnd,
    hasOutboundDeliveredSince,
  }
}

/**
 * Crash-survival redelivery — the LIVE boot send (deterministic, zero model
 * tokens). Consumes the `pendingRedelivery` candidate captured during module
 * init and, if the interrupted turn's finished answer never reached the user,
 * re-projects it from the durable transcript and sends it FRAMED as a recovered
 * draft.
 *
 * ── Ordering guarantee (why this is NOT called during module init) ───────────
 * The Telegram raw send (`bot.api.sendRichMessage`) requires a CONNECTED client.
 * The boot-resume block that computes `pendingRedelivery` runs at module top,
 * BEFORE `bot.api.getMe()` and the grammy runner start — sending there would
 * fire against an unconnected client (or block the connect). So the candidate is
 * only STASHED at module init; this function is invoked exactly once from the
 * `didOneTimeSetup` block AFTER `getMe()` resolves — i.e. after the client is
 * connected and ready. This sequencing is a code-path guarantee, not prompt
 * discipline: the call site is unreachable until the poll loop has authenticated.
 *
 * ── Invariants honored ──────────────────────────────────────────────────────
 * - at-most-once per interruption: the durable text-identity oracle
 *   (`hasOutboundWithText`, scoped to this turn's `started_at`) skips when the
 *   answer already went out, and `markAnswerRedelivered` is stamped SYNCHRONOUSLY
 *   after the send resolves (first-write-wins). The send also writes its own
 *   `role='assistant'` history row, so a re-restart before the marker commits is
 *   still caught by the oracle (residual send→row race documented on the marker).
 * - RESUME_MAX_AGE_MS (3h) staleness, empty-text, trailing-not-text, and
 *   already-delivered/already-redelivered are all enforced by `decideRedeliver`.
 * - isApiErrorMessage lines are suppressed at the projector (never resurfaced).
 * - only trailing TEXT after the last tool_use is redelivered (mid-tool preamble
 *   is refused by `trailingIsText`).
 */
async function maybeRedeliverUndeliveredAnswer(): Promise<void> {
  const candidate = pendingRedelivery
  pendingRedelivery = null // consume once, regardless of outcome
  if (candidate == null || turnsDb == null) return
  const { turn, maxAgeMs } = candidate
  const sessionId = turn.session_id
  if (!sessionId) return

  // Resolve the EXACT transcript from the pinned session id (never a
  // most-recent-mtime scan, which a fresh boot session's file could shadow).
  let transcriptText: string
  try {
    const projectsDir = getProjectsDirForCwd()
    const path = join(projectsDir, `${sessionId}.jsonl`)
    if (!existsSync(path)) {
      process.stderr.write(
        `telegram gateway: crash-redelivery — transcript not found for turnKey=${turn.turn_key} ` +
        `session=${sessionId} (${path}); skipping\n`,
      )
      return
    }
    transcriptText = readFileSync(path, 'utf8')
  } catch (err) {
    process.stderr.write(
      `telegram gateway: crash-redelivery — transcript read failed turnKey=${turn.turn_key}: ${(err as Error).message}\n`,
    )
    return
  }

  const projected = projectTrailingAnswerFromTranscript(transcriptText)
  const threadIdNum =
    turn.thread_id != null && turn.thread_id !== '' ? Number(turn.thread_id) : undefined
  const threadIdForOracle: number | null = threadIdNum != null && Number.isFinite(threadIdNum) ? threadIdNum : null

  const decision = decideRedeliver({
    capturedText: projected.text,
    trailingIsText: projected.trailingIsText,
    // Durable text-identity oracle, scoped to THIS turn's window (`started_at`)
    // so an unrelated earlier turn's message can never false-positive-suppress.
    hasDeliveredText: HISTORY_ENABLED
      ? hasOutboundWithText(turn.chat_id, projected.text, threadIdForOracle, turn.started_at)
      : false,
    alreadyRedelivered: turn.answer_redelivered_at != null,
    ageMs: Math.max(0, Date.now() - turn.started_at),
    maxAgeMs,
  })

  if (!decision.redeliver || decision.framedText == null) {
    process.stderr.write(
      `telegram gateway: crash-redelivery skipped turnKey=${turn.turn_key} reason=${decision.skipReason ?? 'unknown'}\n`,
    )
    return
  }

  const chatId = turn.chat_id
  const out = redactOutboundText(decision.framedText, 'crash_redelivery')
  const chunks = splitMarkdownChunks(out, RICH_MESSAGE_MAX_CHARS)
  const sentIds: number[] = []
  try {
    let liveThreadId: number | undefined = threadIdNum != null && Number.isFinite(threadIdNum) ? threadIdNum : undefined
    for (const c of chunks) {
      const sent = await retryWithThreadFallback(
        robustApiCall,
        (tid) => {
          // Built as a variable (not an inline literal) so excess-property
          // checks don't reject `link_preview_options` on sendRichMessage's
          // narrow Other<> type — mirrors the captured-prose / turn-flush sites.
          const opts = {
            link_preview_options: { is_disabled: true },
            ...(tid != null ? { message_thread_id: tid } : {}),
          }
          return bot.api.sendRichMessage(chatId, richMessage(c), opts)
        },
        { threadId: liveThreadId, chat_id: chatId, verb: 'crash-redelivery.sendMessage' },
      )
      if (liveThreadId != null && (sent as { message_thread_id?: number }).message_thread_id == null) {
        liveThreadId = undefined
      }
      sentIds.push(sent.message_id)
    }
    // Record the send as a real assistant delivery so the durable oracle catches
    // a duplicate if we crash before the marker commits (self-idempotent).
    if (HISTORY_ENABLED && sentIds.length > 0) {
      try {
        recordOutbound({
          chat_id: chatId,
          thread_id: threadIdForOracle,
          message_ids: sentIds,
          texts: chunks,
        })
      } catch {}
    }
    // Stamp the at-most-once marker SYNCHRONOUSLY after the send resolves.
    try {
      markAnswerRedelivered(turnsDb, turn.turn_key)
    } catch (err) {
      process.stderr.write(
        `telegram gateway: crash-redelivery markAnswerRedelivered failed turnKey=${turn.turn_key}: ${(err as Error).message}\n`,
      )
    }
    process.stderr.write(
      `telegram gateway: crash-redelivery — delivered recovered answer (${out.length} chars, ` +
      `${chunks.length} chunk(s)) for turnKey=${turn.turn_key} chat=${chatId}\n`,
    )
  } catch (err) {
    // Send failed — leave the marker UNSTAMPED so a later restart retries rather
    // than silently dropping the recovered answer.
    process.stderr.write(
      `telegram gateway: crash-redelivery send failed turnKey=${turn.turn_key}: ${(err as Error).message} ` +
      `— left un-stamped for a later retry\n`,
    )
  }
}

function obligationSweep(): void {
  obligationWiring().obligationSweep()
}
if (isGatewayMain && !STATIC && OBLIGATION_LEDGER_ENABLED) {
  setInterval(obligationSweep, OBLIGATION_SWEEP_MS).unref()
}

// Gateway boot briefing (session_continuity.briefing: gateway — default
// legacy/off): a surface-scoped reorientation turn assembled from the durable
// history DB and delivered as <channel source="boot_briefing"> over the spool
// transport. Queued BEFORE the resume inbound below so a session that has
// both reorients first, then resumes. All decision/build logic (flag,
// --continue suppression, resume-window dedup, budget) lives in
// boot-briefing-wiring.ts / boot-briefing-builder.ts; never throws.
if (isGatewayMain && HISTORY_ENABLED) {
  await maybeQueueBootBriefing({
    env: process.env,
    stateDir: STATE_DIR,
    resumeMsg: bootResumeInbound?.msg ?? null,
    put: (agent, msg) =>
      inboundSpool != null ? inboundSpool.put(agent, msg) : pendingInboundBuffer.push(agent, msg),
  })
}
// Honest-restart-resume: inject the boot resume/report inbound built by the
// registry classifier above. When the spool exists we only PUT it (the
// boot-replay loop below pulls it into the in-memory buffer exactly once via
// liveEntries — pushing here too would double-queue). The turn_key-keyed
// spoolId makes this a no-op if a prior restart already queued the same turn
// and it hasn't been delivered yet — so a multi-restart sequence resumes a
// given turn once, not N times. When there's no spool (STATIC mode) push
// straight to the in-memory buffer.
if (isGatewayMain && bootResumeInbound != null) {
  if (inboundSpool != null) {
    inboundSpool.put(bootResumeInbound.agent, bootResumeInbound.msg)
  } else {
    pendingInboundBuffer.push(bootResumeInbound.agent, bootResumeInbound.msg)
  }
  // At-most-once resume (#2793 part A): now that the resume inbound is
  // DURABLY committed (spooled, or buffered in STATIC mode), stamp the
  // turn's `resumed_at` so a later restart can't re-mint a fresh resume for
  // the same turn and re-run side effects that already executed. This is
  // synchronous and runs before any async delivery/ack can interleave, so
  // the ledger is set before the spool entry can be consumed — closing the
  // accept-vs-consume double-execution window. Stamping AFTER the durable
  // put (never before) means a crash in between leaves the turn un-stamped
  // and the resume is retried, not silently dropped.
  const resumeTurnKey = bootResumeInbound.msg.meta?.resume_turn_key
  if (turnsDb != null && typeof resumeTurnKey === 'string' && resumeTurnKey.length > 0) {
    try {
      markTurnResumed(turnsDb, resumeTurnKey)
    } catch (err) {
      process.stderr.write(
        `telegram gateway: markTurnResumed failed turnKey=${resumeTurnKey}: ${(err as Error).message}\n`,
      )
    }
  }
}
// Boot-replay: re-queue every un-acked spooled inbound into the
// in-memory buffer so the existing drain triggers (onClientRegistered
// / silence-poke #1546 / idle-drain #1549) deliver them. push →
// spool.put dedups on the already-live id, so this re-push does NOT
// double-append. This is what makes a queued message survive a
// restart instead of being silently lost.
if (isGatewayMain && inboundSpool != null) {
  const replay = inboundSpool.liveEntries()
  for (const e of replay) pendingInboundBuffer.push(e.agent, e.msg)
  if (replay.length > 0) {
    process.stderr.write(
      `telegram gateway: inbound-spool boot-replay re-queued ${replay.length} ` +
      `un-acked inbound (durable-queue, survives restart)\n`,
    )
  }
}
const pendingPermissionBuffer = createPendingPermissionBuffer()

/**
 * Deliver a permission verdict to this agent's bridge, buffering on a
 * miss so it's redelivered when the bridge reconnects. Replaces the
 * bare `ipcServer.broadcast({type:'permission',...})` at every verdict
 * site (and the TTL-sweep auto-deny). broadcast was fire-and-forget:
 * a verdict produced while the bridge was mid-reconnect was dropped
 * and the claude turn stayed suspended INSIDE the MCP permission call
 * forever — the user tapped Approve/Deny and nothing happened, no
 * further output, permanent silence. sendToAgent is registered-keyed
 * and returns a real delivered bool; on a miss we buffer and
 * onClientRegistered re-sends so the reconnecting bridge relays the
 * verdict to the still-suspended call. A late verdict for a dead
 * request_id is harmless — the bridge relays it and Claude Code
 * ignores an unknown request_id. (Function declaration so the
 * pre-2747 TTL sweep can reference it; ipcServer/pendingPermissionBuffer
 * are resolved at call-time, after module init.)
 */
/**
 * The default permission-card action row: ❌ Deny · ✅ Allow ·
 * 🔁 Always… (the last only when a meaningful always-rule exists).
 * Tapping "🔁 Always…" swaps this row for the scope sub-menu; "← Back"
 * rebuilds this row. callback_data stays tiny (verb + 5-char id) so we
 * never approach Telegram's 64-byte ceiling.
 *
 * "✅ Allow" is no longer always literally "once": for a NARROW,
 * non-destructive scope it auto-grants a fixed 30-min window (so the same
 * action stops re-asking) — that is the default behavior of the allow tap,
 * not a separate button. Broad / MCP / destructive scopes stay truly once.
 * The post-tap card states which happened (honest-card contract). The
 * decision lives in the allow handler via resolveTimeBox; the label here is
 * deliberately neutral ("Allow", not "Allow once" or "Allow 30 min").
 */
function buildPermissionActionRow(
  requestId: string,
  showAlways: boolean,
): InlineKeyboard {
  const kb = new InlineKeyboard()
    .text('❌ Deny', `perm:deny:${requestId}`)
    .text('✅ Allow', `perm:allow:${requestId}`)
  if (showAlways) kb.text('🔁 Always…', `perm:always:${requestId}`)
  return kb
}

/**
 * Strip the inline keyboard from one or more timed-out permission cards and
 * append a "timed out — re-request to act" line (Bug 2 fix #1). Called from
 * the pendingStateReaper, which has no grammy `ctx`, so it edits via the
 * bot.api directly — routed through `swallowingApiCall` so a deleted card
 * (operator removed the message) is swallowed rather than crashing the sweep.
 *
 * A single `editMessageText` re-renders the original card body plus a
 * timed-out footer; omitting `reply_markup` drops the keyboard atomically
 * with the text edit (same approach the normal tap finalizer uses, which
 * strips the keyboard alongside its status-line edit). Best-effort: a failed
 * edit never blocks the auto-deny that already fired.
 */
async function stripTimedOutPermissionCards(
  cardText: string,
  cards: PermissionCardRef[],
): Promise<void> {
  for (const edit of buildTimedOutCardEdits(cardText, cards)) {
    await swallowingApiCall(
      // allow-raw-bot-api: routed through swallowingApiCall (retry policy); message-id-targeted edit (no thread to lose). Passing {} as opts (no reply_markup) strips the stale Allow/Deny keyboard atomically with the text edit.
      () => bot.api.editMessageText(edit.chatId, edit.messageId, richMessage(edit.text), {}),
      { chat_id: edit.chatId, verb: 'permission_timeout.strip' },
    )
  }
}

function dispatchPermissionVerdict(ev: PermissionEvent): void {
  const selfAgent = process.env.SWITCHROOM_AGENT_NAME ?? ''
  const delivered = ipcServer.sendToAgent(selfAgent, ev)
  if (!delivered) {
    pendingPermissionBuffer.push(selfAgent, ev)
    process.stderr.write(
      `telegram gateway: permission verdict buffered (bridge offline) ` +
      `request=${ev.requestId} behavior=${ev.behavior}\n`,
    )
  }
}

/**
 * #2861 re-arm: a `permission_request` re-sent by the bridge after a gateway
 * restart, for a request_id that's NO LONGER in `pendingPermissions` but is
 * still in the persisted card store. Restore the in-memory pending entry with
 * the ORIGINAL `startedAt` (so the existing TTL clock keeps running from the
 * original ask — an already-expired re-arm drops straight into the TTL
 * auto-deny sweep, which correctly unwedges claude) and re-attach the inline
 * keyboard on the EXISTING message(s) via editMessageText — never a new card.
 *
 * NEVER answers the card: only the question is restored (no-self-escalation).
 */
function rearmPermissionFromStore(
  msg: PermissionRequestForward,
  persisted: PersistedPermCard[],
): void {
  const { requestId, toolName, description, inputPreview } = msg
  // Original clock: take the earliest persisted startedAt (all entries for one
  // request share it, but be defensive).
  const startedAt = persisted.reduce(
    (min, c) => (c.startedAt < min ? c.startedAt : min),
    persisted[0].startedAt,
  )
  const cardText = persisted[0].cardText
  const cards = persisted.map(c => ({ chatId: c.chatId, messageId: c.messageId }))
  pendingPermissions.set(requestId, {
    tool_name: toolName,
    description,
    input_preview: inputPreview,
    startedAt,
    card_text: cardText,
    cards,
  })
  process.stderr.write(
    `telegram gateway: re-arming permission card(s) for request=${requestId} ` +
    `tool=${toolName} (${cards.length} card(s), original startedAt preserved)\n`,
  )
  // Re-attach the keyboard on each surviving card message. Message-id-targeted
  // edit — no thread needed, so THREAD_NOT_FOUND is not in the blast radius.
  const showAlways = resolveScopedAllowChoices(toolName, inputPreview) != null
  const keyboard = buildPermissionActionRow(requestId, showAlways)
  for (const c of cards) {
    void swallowingApiCall(
      // allow-raw-bot-api: routed through swallowingApiCall (retry policy); message-id-targeted edit (no thread to lose). Re-attaches the Allow/Deny keyboard on the persisted card after a gateway restart.
      () => bot.api.editMessageText(c.chatId, c.messageId, richMessage(cardText), { reply_markup: keyboard }),
      { chat_id: c.chatId, verb: 'permission_request.rearm' },
    )
  }
}

/**
 * Strip a single stale permission card: drop its keyboard and show the
 * "gateway restarted" notice. Shared by the boot-sweep (immediate legacy path
 * and the #2861 grace-period path). Best-effort — a deleted/inaccessible card
 * is swallowed, never fatal.
 */
async function stripStalePermissionCard(card: PersistedPermCard): Promise<void> {
  const toolLabel = card.toolName ?? 'unknown tool'
  const notice = `🔒 **${toolLabel}**\n\n⚠️ *Gateway restarted — this request is no longer active. Ask your agent to try again if needed.*`
  try {
    // allow-raw-bot-api: targeted by message_id; no thread needed; fire-and-forget boot sweep
    await bot.api.editMessageText(
      card.chatId,
      card.messageId,
      richMessage(notice),
      { reply_markup: { inline_keyboard: [] } },
    )
  } catch (err) {
    // Card may already be deleted, edited, or in an inaccessible chat — benign
    process.stderr.write(
      `telegram gateway: boot-sweep: stale-card strip failed ` +
      `${card.chatId}:${card.messageId}: ${(err as Error).message}\n`,
    )
  }
}

// ─── #3038 — bridge-dead watchdog ────────────────────────────────────────
// When the gateway (re)starts, the MCP bridge inside the running claude
// session normally re-registers on the IPC socket within seconds. If it
// died with the previous gateway (Claude Code never respawns a dead MCP
// server), the session stays alive but toolless/mute forever. This
// watchdog escalates: no real bridge registered within the grace window
// while claude is alive → bounce the container once (reason
// 'bridge-dead-resume') so the MCP server respawns. See
// bridge-dead-watchdog.ts for the guard rails.
// Config: SWITCHROOM_BRIDGE_DEAD_GRACE_MS (default 90s),
// SWITCHROOM_BRIDGE_DEAD_ESCALATION=0 disables.
const BRIDGE_DEAD_ESCALATION_ENABLED = process.env.SWITCHROOM_BRIDGE_DEAD_ESCALATION !== '0'
const BRIDGE_DEAD_GRACE_MS = (() => {
  const v = Number(process.env.SWITCHROOM_BRIDGE_DEAD_GRACE_MS)
  return Number.isFinite(v) && v > 0 ? v : DEFAULT_BRIDGE_DEAD_GRACE_MS
})()
const bridgeDeadWatchdog = createBridgeDeadWatchdog({
  graceMs: BRIDGE_DEAD_GRACE_MS,
  // Require a CONFIDENT claude match (comm === 'claude'), not
  // findAgentProcessInContainer's heaviest-node fallback: an orphaned or
  // unrelated node process must never flip a "claude not up" retry into a
  // container bounce (#3038 review finding 4). False negatives are safe —
  // the watchdog then retries forever instead of escalating.
  isSessionAlive: () => findAgentProcessInContainer()?.comm === 'claude',
  // `shuttingDown` is declared (let, module scope) further down this file;
  // the closure only runs when the grace timer fires, long after module
  // init completes, so the TDZ is never hit.
  isShuttingDown: () => shuttingDown,
  escalate: (reason) =>
    triggerSelfRestart(process.env.SWITCHROOM_AGENT_NAME ?? '', reason, 1500),
  crashLogPath: join(STATE_DIR, 'bridge-crash.log'),
  markerPath: join(STATE_DIR, 'bridge-dead-escalation.json'),
  log: (line) => process.stderr.write(`${line}\n`),
  // Cross-boot damper (#3038 review finding 1): the consumed marker's
  // consecutive-escalation count. At the cap, arm() stands down loudly
  // instead of restart-looping a deterministically-failing bridge.
  priorStreak: bridgeDeadPriorStreak,
  // #3086 — only THIS gateway's own primary bridge (registering under
  // $SWITCHROOM_AGENT_NAME) drives the watchdog. A secondary/relay client
  // (e.g. `overlord-relay`) registering a different name into this socket
  // is named + non-cron but must NOT mark the (still-alive) primary bridge
  // dead when it disconnects. Empty string ⟹ fall back to the pre-#3086
  // "any named non-cron client" test inside the watchdog.
  selfAgentName: process.env.SWITCHROOM_AGENT_NAME ?? '',
})
if (isGatewayMain && BRIDGE_DEAD_ESCALATION_ENABLED) {
  bridgeDeadWatchdog.arm()
  process.stderr.write(
    `telegram gateway: [bridge-dead-watchdog] armed (grace=${BRIDGE_DEAD_GRACE_MS}ms)\n`,
  )
}

// #2996 P0e: constructing the IPC server renames/unlinks the socket file and
// binds a UDS listener (`Bun.listen`) at call time — a hard module-load side
// effect (and the reason `import(gateway.ts)` threw `Bun is not defined` under
// vitest). Defer construction past import; it still constructs at the identical
// boot point in prod, where `isGatewayMain` is true. Definite-assignment `!`:
// every reader runs only after boot (in a handler / timer / startGateway), so
// the binding is always populated before first read on the prod path.
let ipcServer!: IpcServer
if (isGatewayMain) ipcServer = createIpcServer({
  socketPath: SOCKET_PATH,

  onClientRegistered(client: IpcClient) {
    process.stderr.write(`telegram gateway: bridge registered — agent=${client.agentName}\n`)
    // Cheap-cron (§2.4/§3.3): a `<agent>-cron` bridge is the Tier-1 cheap,
    // STATUS-SILENT session — it must NOT drive the gateway's singleton
    // machinery. Drain any boot-window cron fire to it, then return early.
    // #4348: the drain routes through `redeliverBufferedInbound` (the shared
    // ack chokepoint) so a spooled fire is acked and never re-fires on restart.
    if (isCronIdentity(client.agentName)) {
      drainCronBridgeOnRegister(client, pendingInboundBuffer, inboundSpool ?? undefined, (l) => process.stderr.write(l))
      return
    }
    // Phase 2b shadow: ONLY emit bridgeUp for the REAL bridge sidecar
    // (with an agent name). Anonymous IPC clients (recall.py, mcp
    // handshakes, etc.) connect briefly without a name and would
    // false-positive a bridgeUp/bridgeDown cycle that doesn't reflect
    // the real bridge state. This bug — discovered post-v0.12.24 — was
    // causing the shadow state to read `bridge_dead` even when the
    // real bridge was healthy, because every recall.py connect+disconnect
    // would flip the state.
    const bridgeUpEffects = client.agentName != null
      ? shadowEmit({ kind: 'bridgeUp', at: Date.now() })
      : []
    // #3038 — a REAL (named, non-cron) bridge registered: stand the
    // bridge-dead watchdog down. Anonymous clients (recall.py, mcp
    // handshakes), cron-session bridges, and secondary/relay clients
    // registering a name other than this gateway's own agent (#3086) must
    // NOT satisfy it — the watchdog gates on the identity INTERNALLY
    // (isRealBridgeIdentity vs selfAgentName), so this call is safe wherever
    // it sits relative to the cron early-return above (#3038 review finding 5).
    bridgeDeadWatchdog.noteBridgeRegistered(client.agentName)
    client.send({ type: 'status', status: 'agent_connected' })

    // Phase 2b PR 3a — bridgeUp cutover. The state machine's `bridgeUp`
    // transition returns `redeliverPersistedPermVerdicts`, `drainBuffer`,
    // and `logTrace` effects. The dispatcher executes them in order:
    // the perm-verdict drain unblocks any claude turn suspended inside
    // an MCP permission call; the inbound drain flushes synthetic
    // inbounds queued while the bridge was offline (#1150) so the agent
    // wakes up to missed wake-ups before the boot-card path below runs.
    // Lossless: `redeliverBufferedInbound` re-buffers per-message misses
    // and `spool.ack` tombstones confirmed deliveries. Skipped when
    // agentName is null (pre-handshake / anonymous client — those
    // bridges never registered an identity and can't have accumulated
    // buffered inbounds keyed by name).
    if (client.agentName != null) {
      dispatchEffects(bridgeUpEffects, {
        selfAgent: client.agentName,
        ipcServer,
        pendingInboundBuffer,
        inboundSpool: inboundSpool ?? null,
        pendingPermissionBuffer,
        client,
        // Enrol each drained user inbound in the deliver-until-acked queue
        // so the 5s sweep re-delivers until claude's `enqueue` ack lands —
        // a socket-write into a still-booting session is NOT consumption
        // (clerk lost-message incident, 2026-06-03).
        onUserInboundDelivered: trackRedeliveredInbound,
      })
    }

    // Prefix-cache warmup (cold-start TTFO RFC, opt-in via
    // SWITCHROOM_PREFIX_WARMUP=1). Fires a synthetic inbound to claude
    // BEFORE the user's next real message so Anthropic's prefix cache
    // is warm on the user-perceived first turn. Gated, debounced
    // (5-min cooldown per agent), and skipped if no boot chat resolves.
    // Claude responds NO_REPLY per inline instruction; existing
    // silent-marker suppression at gateway.ts:5906 swallows the
    // outbound. See reference/rfcs/cold-start-ttfo.md Option A.
    if (client.agentName != null) {
      maybeFireWarmup({
        selfAgent: client.agentName,
        client,
        resolveBootTarget: () => {
          const marker = readRestartMarker()
          const ageMs = marker ? Date.now() - marker.ts : undefined
          const target = resolveBootChatId(marker, ageMs)
          if (!target) return null
          return { chatId: target.chatId, threadId: target.threadId }
        },
      })
    }

    // If the agent reconnected after a restart, post a boot card. The
    // restart-marker carries the ack chat; else fall back to resolveBootChatId
    // so crash-recovery reconnects also get a card. Skip if the boot path
    // already posted a card OR its sendMessage is in-flight (issue #489,
    // klanker 2026-05-01; earlier dedupe 2026-04-26 only covered the
    // post-resolution case). See `shouldSkipDuplicateBootCard`.
    const dedupeDecision = shouldSkipDuplicateBootCard({ activeBootCard, bootCardPending }, 'bridge-reconnect')
    if (dedupeDecision.skip) {
      process.stderr.write(`telegram gateway: bridge-reconnect: skipping boot card (${dedupeDecision.reason})\n`)
    } else {
      const nowMs = Date.now()
      const marker = readRestartMarker()
      const cleanMarker = readCleanShutdownMarker(GATEWAY_CLEAN_SHUTDOWN_MARKER_PATH)
      const storedSession = readSessionMarker(GATEWAY_SESSION_MARKER_PATH)
      const markerAgeMs = marker ? nowMs - marker.ts : undefined

      if (marker) {
        const ageSec = Math.max(1, Math.round((markerAgeMs ?? 0) / 1000))
        process.stderr.write(`telegram gateway: bridge-reconnect: restart-marker present, chat_id=${marker.chat_id} age=${ageSec}s agent=${client.agentName}\n`)
        clearRestartMarker()
      }

      // B2: boot path cleared the markers — reuse its reason (boot-reason.ts).
      const reason = determineBridgeReconnectReason({ marker, cleanMarker, sessionMarker: storedSession,
        now: nowMs, gatewayStartedAtMs: GATEWAY_STARTED_AT_MS, bootReason: bootReasonAtStartup })
      const target = resolveBootChatId(marker, markerAgeMs)

      if (target) {
        const { chatId, threadId, ackMsgId } = target
        process.stderr.write(`telegram gateway: bridge-reconnect: posting boot card reason=${reason} chat_id=${chatId} thread_id=${threadId ?? '-'} ackReply=${ackMsgId ?? '-'} boot_card=${BOOT_CARD_ENABLED}\n`)
        ensureIssuesCard(chatId, threadId)
        if (BOOT_CARD_ENABLED) {
          const agentDir = resolveAgentDirFromEnv()
          const agentSlug = process.env.SWITCHROOM_AGENT_NAME ?? client.agentName ?? '-'
          const agentDisplayName = resolvePersonaName(agentSlug)
          const botApiForCard: import('./boot-card.js').BotApiForBootCard = wrapBootCardApi(threadId)
          // Symmetric to the boot path: claim ownership synchronously so a
          // second bridge-reconnect in the same lifetime can't race against
          // an in-flight sendMessage here either (#489).
          bootCardPending = true
          // PR C: surface the most recent terminal update_apply audit
          // row if it lands within the lookback window AND no other
          // boot has claimed it. Cheap (one file read + one O_EXCL).
          const updateOutcomeLine = (() => {
            try { return maybeRenderUpdateAnnouncement() ?? undefined } catch { return undefined }
          })()
          const resolvedAgentDirForCard = agentDir ?? (process.env.TELEGRAM_STATE_DIR ? require('path').dirname(process.env.TELEGRAM_STATE_DIR) : '/tmp')
          startBootCard(chatId, threadId, botApiForCard, {
            agentName: agentDisplayName,
            agentSlug,
            version: formatBootVersion(),
            agentDir: resolvedAgentDirForCard,
            gatewayInfo: { pid: process.pid, startedAtMs: GATEWAY_STARTED_AT_MS },
            restartReason: reason,
            restartAgeMs: markerAgeMs,
            restartReasonDetail: cleanMarker?.reason,
            loadAccounts: () => loadAccountsForBootCard(agentSlug),
            probeQuotaViaBroker: (t) => probeQuotaForBootCard(agentSlug, t),
            tmuxSupervisor: process.env.SWITCHROOM_TMUX_SUPERVISOR === '1',
            dockerMode: process.env.SWITCHROOM_RUNTIME === 'docker',
            configSnapshotPath: join(resolvedAgentDirForCard, '.config-snapshot.json'),
            bootCardStatePath: join(resolvedAgentDirForCard, '.boot-card-msgid.json'),
            floodStatePath: FLOOD_STATE_PATH,
            ...(updateOutcomeLine ? { updateOutcomeLine } : {}),
          }, ackMsgId).then(handle => {
            activeBootCard = handle
          }).catch((err: Error) => {
            process.stderr.write(`telegram gateway: bridge-reconnect: boot card error: ${err.message}\n`)
          }).finally(() => {
            bootCardPending = false
          })
        } else {
          const ageSec = markerAgeMs != null ? Math.max(1, Math.round(markerAgeMs / 1000)) : 0
          postLegacyBanner(chatId, threadId, ackMsgId, ageSec, 'bridge-reconnect')
        }
      } else {
        process.stderr.write(`telegram gateway: bridge-reconnect: no known chat for boot card (reason=${reason}) — skipping\n`)
      }
    }
  },

  onClientDisconnected(client: IpcClient) {
    // Cheap-cron §2.4: a `<agent>-cron` bridge is the status-silent cron
    // session. Its disconnect (e.g. B3 lazy idle-teardown) must NOT touch
    // the MAIN agent's singleton state — emitting bridgeDown (the shadow
    // state is unkeyed) or flushOnAgentDisconnect (flushes the main agent's
    // active reactions / disposes its progress driver mid-turn) would be the
    // "premature 👍" bug for the main session. Symmetric to the cron gate in
    // onClientRegistered / onSessionEvent / onPtyPartial.
    if (isCronIdentity(client.agentName)) {
      process.stderr.write(`telegram gateway: cron-session bridge disconnected — agent=${client.agentName}\n`)
      return
    }
    // ONLY log "bridge disconnected" + emit bridgeDown for the REAL
    // bridge sidecar (matching the bridgeUp gate above). Anonymous IPC
    // clients — e.g. recall.py's one-shot legacy update_placeholder
    // handshake — connect and disconnect constantly with agentName=null;
    // logging those as "bridge disconnected — agent=null" reads as a
    // bridge flap in the supervisor log when nothing flapped. The
    // anonymous disconnect is still traced by disconnect-flush.ts.
    if (client.agentName != null) {
      process.stderr.write(`telegram gateway: bridge disconnected — agent=${client.agentName}\n`)
      shadowEmit({ kind: 'bridgeDown', at: Date.now() })
      // #3038 — the real bridge went away mid-life. Re-arm the grace
      // window: a normal claude restart re-registers within seconds and
      // stands it down; a bridge that died for good escalates once (the
      // once-per-boot fuse inside the watchdog caps it). Cron/anonymous and
      // secondary/relay identities (a name other than this gateway's own
      // agent, #3086) are ignored inside the watchdog itself (finding 5) —
      // so a transient relay disconnect never bounces a healthy container.
      if (BRIDGE_DEAD_ESCALATION_ENABLED) bridgeDeadWatchdog.noteBridgeDisconnected(client.agentName)
    }

    // Scope the flush to clients that actually registered as an agent.
    // Anonymous one-shot connections (e.g. recall.py's legacy
    // update_placeholder IPC handshake) close their socket as soon as the
    // single JSON line is sent — firing this handler with agentName=null.
    // The old code unconditionally flushed every active reaction to 👍 and
    // disposed the progress driver, which fired the "premature 👍" UX bug
    // mid-turn whenever recall.py ran. See `disconnect-flush.ts` for the
    // gating policy and the test in
    // `tests/gateway-disconnect-flush.test.ts` for the contract.
    flushOnAgentDisconnect({
      agentName: client.agentName,
      activeStatusReactions,
      activeReactionMsgIds,
      activeTurnStartedAt,
      activeDraftStreams,
      clearActiveReactions: () => {
        const ad = resolveAgentDirFromEnv()
        if (ad) clearActiveReactions(ad)
      },
      disposeProgressDriver: () => {
        // dispose is optional on the ProgressDriver interface — chain
        // through both possibly-undefined hops. Caught by
        // scripts/check-plugin-references.mjs (TS2722).
        progressDriver?.dispose?.({ preservePending: true })
      },
      // #2650: the bridge died mid-turn — its turn-long `typing…` loop never
      // hits the canonical turn-end stop, leaving a stale "typing…" until the
      // next turn. Sweep every live loop here (gated to registered-agent
      // disconnect inside flushOnAgentDisconnect).
      stopTurnTypingLoops: () => {
        turnTypingLoop.stopAll()
        // Shutdown drain: also cancel every armed catch-up so no typing ping
        // fires after the gateway has stopped.
        typingEmitter.reset()
      },
      // #3552 — the bridge died with turns in flight; disarm each dead turn's
      // silence-poke state HERE. Before this, the armed 300s timer outlived the
      // turn and was only dropped when the fallback eventually fired against the
      // stale key and logged `turn_ended_cleanly_during_window` (504 events in
      // 14 days vs 110 real fires). `endTurn` is idempotent, so being called for
      // a key reported by both flush loops is safe.
      onTurnKeyEnded: (key) => silencePoke.endTurn(key),
      // When dangling activeTurnStartedAt keys were swept (setDone raced
      // disconnect), the module-scope `currentTurn` may also point at the
      // dead bridge's turn. Null it so the next inbound starts a fresh
      // turn instead of inheriting a ghost.
      onDanglingTurnsSwept: () => {
        if (currentTurn != null) {
          process.stderr.write(
            `telegram gateway: disconnect-flush nulled currentTurn (bridge died with turn in flight)\n`,
          )
          // PR-4e — the bridge DIED with a turn in flight: EVERY per-topic entry
          // is a ghost, not just the mirror's. Clear the whole map + mirror.
          // Flag-OFF: this nulls the singleton only (the map is empty), verbatim.
          // PR-E (M1): under the v2 funnel this is the named 'bridge-died-clear'
          // reason — atom-clear ONLY (no purge / obligation close / drain).
          if (TURN_END_FUNNEL_V2) turnEndFunnel().endTurn('bridge-died-clear')
          else clearAllCurrentTurns()
        }
      },
      log: (msg) => process.stderr.write(`${msg}\n`),
    })
    // #4173 — a MAIN-bridge death is a turn-completion proxy: the dead session
    // can never deliver a flush-ended turn's real turn_end, so close any open
    // flush windows now (the replay grace still covers a reconnect replay).
    // Scoped to a registered non-cron agent; rationale in stream-render.ts.
    if (client.agentName != null && !isCronIdentity(client.agentName)) {
      subagentReplyAuthority.reset() // #4176 — the sub-agents died with the session
      const closedWindows = closeFlushCompletionWindows(flushedTurnSupersede, Date.now())
      if (closedWindows > 0) {
        process.stderr.write(
          `telegram gateway: bridge disconnect closed ${closedWindows} open flush-completion window(s) (#4173)\n`,
        )
      }
    }
  },

  async onToolCall(client: IpcClient, msg: ToolCallMessage): Promise<ToolCallResult> {
    process.stderr.write(`telegram gateway: ipc: tool_call tool=${msg.tool} agent=${client.agentName ?? '-'} clientId=${client.id ?? '-'} callId=${msg.id}\n`)
    if (!isCronIdentity(client.agentName)) sessionConsumeSignal.noteMainToolCall() // consumption proxy (session-consume-signal.ts)
    try {
      // #4172 — the calling client's identity gates reply supersede authority
      // (see replyCallerIsForeignSession, cron-session.ts).
      const result = await executeToolCall(msg.tool, msg.args, client.agentName)
      return { type: 'tool_call_result', id: msg.id, success: true, result }
    } catch (err) {
      return {
        type: 'tool_call_result',
        id: msg.id,
        success: false,
        error: err instanceof Error ? err.message : String(err),
      }
    }
  },

  onSessionEvent(client: IpcClient, msg: SessionEventForward) {
    // Cheap-cron §2.4: the cron session is status-silent — its session
    // events must not drive the main agent's progress card, transcript
    // tail, currentTurn, or silence-poke. Its reply still flows (onToolCall
    // is not gated). currentTurn was never set for a cron fire (onInjectInbound
    // skips markClaudeBusy), so the card machinery has nothing to attach to.
    if (isCronIdentity(client.agentName)) return
    // Track the session-tail's attached file for the proactive-
    // compaction occupancy read (see maybeProactiveCompact).
    if (msg.activeFile) lastSessionActiveFile = msg.activeFile
    // Crash-survival redelivery: durably pin the claude session id onto the
    // current turn's row the first time we see a session event for it, WHILE
    // the turn is live (so a later crash preserves it). Boot redelivery then
    // resolves the EXACT `<sessionId>.jsonl` for the interrupted turn rather
    // than a most-recent-mtime heuristic that a fresh boot session shadows.
    // First-write-wins in SQL (`session_id IS NULL`); the in-memory guard just
    // avoids a redundant UPDATE on every event of the same turn.
    if (turnsDb != null && msg.activeFile != null) {
      const stampKey = currentTurn?.registryKey ?? null
      if (stampKey != null && stampKey !== lastSessionStampedTurnKey) {
        const sessionId = basename(msg.activeFile).replace(/\.jsonl$/, '')
        if (sessionId) {
          try {
            stampTurnSessionId(turnsDb, stampKey, sessionId)
            lastSessionStampedTurnKey = stampKey
          } catch (err) {
            process.stderr.write(
              `telegram gateway: stampTurnSessionId failed turnKey=${stampKey}: ${(err as Error).message}\n`,
            )
          }
        }
      }
    }
    const ev = msg.event as unknown as SessionEvent
    if (ev.kind === 'task_notification') cliTaskNotifLedger.record(ev.taskId, ev.status, Date.now()) // double-wake dedup — ledger doc in subagent-handback-marker.ts
    // #1122/#1126: session events used to be ingested into the pinned progress
    // card here (`progressDriver.ingest`). The card is retired and the driver
    // is permanently null, so that call was a dead no-op — removed. Session
    // events still drive the live surfaces via `handleSessionEvent`.
    handleSessionEvent(ev)
    // Problem B: keep the deferred-interrupt boundary tracker in lockstep with
    // the session stream (tool_use opens, tool_result/turn_end close). If a `!`
    // interrupt is parked waiting for a clean boundary and this event drains
    // the last in-flight tool, fire it now rather than waiting out the timer.
    toolFlightTracker.onEvent(ev)
    if (pendingDeferredInterrupt != null && !toolFlightTracker.isMidToolCall()) {
      void fireDeferredInterrupt('boundary')
    }
    // #3020: a parked halt-now (/stop, bare "stop", empty `!`) waits on the
    // same boundary — kick its waiters whenever the tracker may have drained.
    notifyHaltBoundaryWaiters()
    // #1122 silence-poke: surface activity signals from the session
    // stream so the 300s framework-fallback message wording is honest
    // (thinking vs working, plus the longest-running in-flight tool).
    if (currentTurn != null) {
      const key = statusKey(currentTurn.sessionChatId, currentTurn.sessionThreadId)
      applySilencePokeSessionEvent(silencePoke, pendingProgress, key, ev)
    }
  },

  onPermissionRequest(_client: IpcClient, msg: PermissionRequestForward) {
    const { requestId, toolName, description, inputPreview } = msg
    // #2861 idempotent re-send handling. The bridge re-sends every outstanding
    // permission_request on each IPC (re)connect, so the same request_id can
    // arrive more than once. Disposition:
    //   duplicate → already live in pendingPermissions; ignore (no 2nd card).
    //   rearm     → gone from memory (gateway restarted) but the persisted card
    //               store still has it; restore + re-attach keyboard in place.
    //   fresh     → new ask; fall through to the normal card-posting path.
    // Either re-claim marks the id so the grace-period boot-sweep won't strip
    // it. Kill switch SWITCHROOM_PERMISSION_REARM=0 skips this entirely (legacy
    // behavior: a re-send would post a duplicate card, as before this fix).
    if (isPermissionRearmEnabled()) {
      const persisted = pendingPermissions.has(requestId)
        ? []
        : permCardStore.loadAll().filter(e => e.requestId === requestId)
      const disposition = classifyPermissionRequest({
        hasPending: pendingPermissions.has(requestId),
        persistedCount: persisted.length,
      })
      if (disposition === 'duplicate') {
        process.stderr.write(
          `telegram gateway: permission_request duplicate re-send ignored ` +
          `request=${requestId} (already pending)\n`,
        )
        return
      }
      if (disposition === 'rearm') {
        // Re-arm restores the pending entry; the grace-period boot-sweep
        // preserves anything live in pendingPermissions, so it won't strip it.
        rearmPermissionFromStore(msg, persisted)
        return
      }
    }
    // "⏱ 30 min" short-circuit: if the operator tapped a live scoped grant
    // covering this exact request, auto-allow without posting a card. CRITICAL:
    // dispatch WITHOUT a `rule` so the bridge does NOT cache it untimed
    // (sessionAllowRules has no TTL — a `rule` here would silently promote the
    // 30-min window to session-forever). The fixed window lives only in
    // scopedGrants. lookupScopedGrant fails closed on expiry and on a
    // destructive Bash command matching a family grant. No card, no pending
    // entry, no awaiting reaction — the turn just continues, silently.
    const scopedTtl = scopedApprovalTtlMs()
    if (scopedTtl > 0) {
      const hit = lookupScopedGrant(scopedGrants, selfAgentName(), toolName, inputPreview, Date.now())
      if (hit) {
        // Silent auto-allow — no card was posted and the turn was never parked
        // on the awaiting glyph, so we intentionally OMIT the resume-glyph flip
        // and the agent-voiced resume message (posting "got it, continuing" on
        // every auto-allowed call is the exact noise this tier removes). The
        // `no-card-verdict` sentinel below exempts this callsite from the
        // resume-guard pairing test.
        dispatchPermissionVerdict({ type: 'permission', requestId, behavior: 'allow' }) // no-card-verdict
        process.stderr.write(
          `telegram gateway: scoped-approval auto-allow tool=${toolName} rule="${hit}" ` +
          `request=${requestId} (time-boxed window)\n`,
        )
        return
      }
    }
    // No-repeat short-circuit: this exact (tool, input) already timed out and
    // the operator hasn't been active since (the suppression map is cleared on
    // any operator activity). Deny it WITH a timeout-duplicate reason and post
    // NO second card — the model retrying into an absent operator is the loop
    // this closes. The turn still unblocks (deny verdict), and a returning
    // operator resets suppression so the next ask gets a fresh card.
    if (PERMISSION_NO_REPEAT_ENABLED) {
      const sig = permissionSignature(toolName, inputPreview)
      if (isRecentTimeoutDuplicate(permissionTimeoutSignatures, sig, Date.now(), PERMISSION_DUPLICATE_WINDOW_MS)) {
        // no-card-verdict: no card was posted and the turn was never parked on
        // the awaiting glyph, so we omit the resume-reaction flip / resume msg.
        dispatchPermissionVerdict({
          type: 'permission',
          requestId,
          behavior: 'deny',
          message: duplicateDenyMessage,
        })
        process.stderr.write(
          `telegram gateway: permission no-repeat short-circuit — duplicate of a ` +
          `timed-out request tool=${toolName} request=${requestId} (no card posted)\n`,
        )
        return
      }
    }
    // Natural-language card body — a plain sentence ("Gymbro wants to
    // edit: supplement-log.md" + a why-line), never a raw tool id.
    // The operator sees what is being requested and why at a glance.
    // Mirrors the `vault_request_access` card layout. Sent via the
    // rich-markdown path below.
    const text = formatPermissionCardBody({
      toolName,
      inputPreview,
      description,
      agentName: _client.agentName,
    })
    // `card_text` is retained so the TTL reaper can re-edit the SAME body
    // with a "timed out" footer while stripping the keyboard atomically
    // (Bug 2 fix #1) — the reaper has no grammy ctx to read the live text.
    const pendEntry = { tool_name: toolName, description, input_preview: inputPreview, startedAt: Date.now(), card_text: text, cards: [] }
    pendingPermissions.set(requestId, pendEntry)
    // Compact action row: ❌ Deny · ✅ Allow · 🔁 Always… — the scope of an
    // "always" grant stays hidden until the operator taps "🔁 Always…",
    // which swaps the row for a scope choice (this file / any file ⚠️). The
    // "🔁 Always…" button only appears when we can synthesize a meaningful
    // rule for this tool; unknown tools get the two-button row only. "Allow"
    // itself auto-grants a 30-min window for narrow non-destructive scopes
    // (decided in the allow handler), so there is no separate time-box button.
    // Captured BEFORE the send: the status-reaction parking below needs the
    // turn that raised this card, and `currentTurn` can be re-pointed by a
    // concurrent inbound while the send is in flight.
    const activeTurn = currentTurn
    // #3084 follow-up — the send now lives in postPermissionCard() so the
    // reaper can RE-DRIVE it when a flood window closes. This is the first
    // delivery attempt; if it fails against an open ban the entry is marked
    // undeliverable and held, never auto-denied.
    postPermissionCard(requestId, pendEntry)
    // Park the turn's status reaction on 🙏 (awaiting your tap) and
    // suspend the stall watchdog — a turn blocked on the operator is not
    // stalled, so it must not degrade to 🥱/😨 while the card sits
    // unanswered. The verdict path (`resumeReactionAfterVerdict`) flips it
    // back to a working state the instant you tap.
    if (activeTurn != null) {
      activeStatusReactions
        .get(statusKey(activeTurn.sessionChatId, activeTurn.sessionThreadId))
        ?.setAwaiting()
    }
  },

  onHeartbeat(_client: IpcClient, _msg: HeartbeatMessage) {
    // Heartbeat received — no action needed, the server tracks lastHeartbeat
  },

  onScheduleRestart(client: IpcClient, msg: ScheduleRestartMessage) {
    const { agentName } = msg;

    // Check if any turn is currently in flight.
    // Gated on the delivery machine (actually-handed-to-claude turns)
    // not activeTurnStartedAt (receipt-eager), so a buffered topic-B
    // inbound doesn't pin this as turnInFlight=true forever.
    const turnInFlight = turnInFlightForGate();

    if (!turnInFlight) {
      // No active turn, restart immediately. Cycle both the agent and
      // gateway side-by-side so telegram-plugin code changes always
      // propagate. Send the client response FIRST, then trigger the
      // restart after a brief delay so the IPC response has flushed
      // before we get killed. (Under docker the helper SIGTERM's PID 1;
      // under systemd it spawns a detached `systemctl restart`.)
      try {
        client.send({
          type: 'schedule_restart_result',
          success: true,
          restartedImmediately: true,
        });
        triggerSelfRestart(agentName, 'schedule-restart-immediate');
      } catch (err) {
        client.send({
          type: 'schedule_restart_result',
          success: false,
          error: err instanceof Error ? err.message : String(err),
        });
        process.stderr.write(`telegram gateway: restart spawn failed for ${agentName}: ${err}\n`);
      }
    } else {
      // Turn is active, schedule restart for when turn completes
      process.stderr.write(`telegram gateway: scheduling restart for ${agentName} after current turn\n`);

      // Set a flag that will be checked when turns complete
      pendingRestarts.set(agentName, Date.now());

      client.send({
        type: 'schedule_restart_result',
        success: true,
        waitingForTurn: true,
      });
    }
  },

  onOperatorEvent(_client: IpcClient, msg: OperatorEventForward) {
    // Bridge has detected an Anthropic API error (or synthetic gateway-side
    // event). chatId on the wire is currently always empty — operator events
    // are agent-level, not tied to a specific user message; the helper
    // resolves the destination from `access.allowFrom`.
    emitGatewayOperatorEvent({
      kind: msg.kind as OperatorEventKind,
      agent: msg.agent,
      detail: msg.detail,
      suggestedActions: [],
      firstSeenAt: new Date(),
    })
  },

  // onUpdatePlaceholder handler removed in #553 PR 5 — fake placeholder
  // text (`🔵 thinking`, `📚 recalling memories`, `💭 thinking`) is no
  // longer emitted. recall.py's update_placeholder IPC calls become
  // benign no-ops: the IPC client validates the wire shape but no
  // server-side handler is registered, so the message is silently
  // ignored at dispatch.

  /**
   * Forwarded PTY-tail partial: the latest extracted assistant-reply
   * text from Claude Code's TUI rendering. Routes through
   * `handlePtyPartial` (declared further down) which writes the text
   * into the active draft stream for `currentSessionChatId`. The chat
   * id is resolved from the most recent enqueue session_event the
   * bridge has forwarded — same pattern as the legacy monolith path
   * in server.ts.
   *
   * Best-effort: silently no-op when the stream isn't ready (no chat
   * resolved yet, suppressed by an in-flight reply, dedup match).
   * `handlePtyPartial` does its own buffering for the
   * partial-before-enqueue race.
   */
  onPtyPartial(client: IpcClient, msg: PtyPartialForward) {
    // Cheap-cron §2.4: cron session is status-silent — no visible reply
    // stream from its PTY tail (it would edit a card the main session owns).
    if (isCronIdentity(client.agentName)) return
    handlePtyPartial(msg.text)
  },

  /**
   * Phase 2 cron-fold-in: forward a synthesized inbound from the
   * in-agent scheduler sibling to the registered bridge for the
   * named agent. The wrapped `inbound` envelope is shipped verbatim
   * — the in-agent scheduler is the synthesis authority (it runs
   * `dispatchAsInbound` from `src/scheduler/dispatch.ts` to build
   * the message). The gateway only validates wire shape (handled
   * in ipc-server.ts:validateClientMessage) and routes.
   *
   * Logs every fire so an operator can correlate the agent's
   * transcript turn against the scheduler's audit row by `prompt_key`.
   */
  async onRequestDriveApproval(client: IpcClient, msg) {
    // RFC E §4.2 Cut 2 — Drive-write PreToolUse hook is asking the
    // gateway to post a diff-preview card so the user can decide.
    await handleRequestDriveApproval(client, msg, {
      agentName: getMyAgentName(),
      loadAllowFrom: () => loadAccess().allowFrom,
      loadTargetChat: () => {
        const access = loadAccess()
        const operator = access.allowFrom[0]
        if (operator === undefined) return null
        // For DM-paired setups the target chat IS the operator's
        // user id. For group setups the gateway already has a topic
        // routing surface (see how /folders posts) — this picks the
        // DM path which is the common case; group-routing follow-up
        // can extend this.
        // PR4b emitter sweep — supergroup-mode adds an explicit
        // topic. Drive approval cards follow the originating turn
        // (operator-initiated tool call), admin alias fallback.
        const activeTurn = currentTurn
        // Attach the topic only when `operator` IS the agent's supergroup —
        // operator DMs have no topics (marko brevo wedge, 2026-06-02).
        const driveTopic = topicForRecipient({
          recipientChatId: operator,
          resolvedTopic: resolveAgentOutboundTopic({
            kind: 'hostd-approval',
            originThreadId: activeTurn?.sessionThreadId,
          }),
          supergroupChatId: resolveAgentSupergroupChatId(),
        })
        return {
          chatId: operator,
          ...(driveTopic != null ? { threadId: driveTopic } : {}),
        }
      },
      registerApproval: async (args) => {
        const r = await kernelApprovalRequest({
          agent_unit: args.agent_unit,
          scope: args.scope,
          action: args.action,
          approver_set: args.approver_set,
          why: args.why,
          ttl_ms: args.ttl_ms,
        })
        if (r === null || r.state === 'rate_limited') return null
        return {
          request_id: r.request_id,
          expires_at_ms: r.expires_at,
        }
      },
      postCard: async (args) => {
        try {
          const sent = await robustApiCall(
            () =>
              bot.api.sendRichMessage(args.chatId, richMessage(args.text), {
                ...(args.threadId !== undefined
                  ? { message_thread_id: args.threadId }
                  : {}),
                reply_markup: args.replyMarkup as never,
              }),
            {
              chat_id: String(args.chatId),
              verb: 'drive-approval-card',
              ...(args.threadId !== undefined ? { threadId: args.threadId } : {}),
            },
          )
          return { messageId: (sent as { message_id: number }).message_id }
        } catch (err) {
          process.stderr.write(
            `telegram gateway: drive-approval postCard failed: ${(err as Error).message}\n`,
          )
          return null
        }
      },
      buildCard: ({ preview, suggestRequestId }) =>
        buildDiffPreviewCard({ preview, suggestRequestId }),
      log: (m) => process.stderr.write(`telegram gateway: drive-approval — ${m}\n`),
    })
  },

  /**
   * RFC #1873 §8 — MS-365 write approval card. Mirrors
   * onRequestDriveApproval but with the weak-metadata v1 preview shape
   * (no diff-preview — just plain text card).
   */
  async onRequestMs365Approval(client: IpcClient, msg) {
    await handleRequestMs365Approval(client, msg, {
      agentName: getMyAgentName(),
      loadAllowFrom: () => loadAccess().allowFrom,
      loadTargetChat: () => {
        const access = loadAccess()
        const operator = access.allowFrom[0]
        if (operator === undefined) return null
        // PR4b emitter sweep — MS365 write approval cards route into
        // the originating turn's topic in supergroup mode, admin
        // alias fallback for background cases. Same shape as hostd /
        // drive approvals below.
        const activeTurn = currentTurn
        // Topic valid only in the agent's supergroup — never on the operator DM.
        const ms365Topic = topicForRecipient({
          recipientChatId: operator,
          resolvedTopic: resolveAgentOutboundTopic({
            kind: 'hostd-approval',
            originThreadId: activeTurn?.sessionThreadId,
          }),
          supergroupChatId: resolveAgentSupergroupChatId(),
        })
        return {
          chatId: operator,
          ...(ms365Topic != null ? { threadId: ms365Topic } : {}),
        }
      },
      registerApproval: async (args) => {
        const r = await kernelApprovalRequest({
          agent_unit: args.agent_unit,
          scope: args.scope,
          action: args.action,
          approver_set: args.approver_set,
          why: args.why,
          ttl_ms: args.ttl_ms,
        })
        if (r === null || r.state === 'rate_limited') return null
        return {
          request_id: r.request_id,
          expires_at_ms: r.expires_at,
        }
      },
      postCard: async (args) => {
        try {
          const sent = await robustApiCall(
            () =>
              bot.api.sendMessage(args.chatId, args.text, {
                ...(args.threadId !== undefined
                  ? { message_thread_id: args.threadId }
                  : {}),
                reply_markup: args.replyMarkup as never,
              }),
            {
              chat_id: String(args.chatId),
              verb: 'ms365-approval-card',
              ...(args.threadId !== undefined ? { threadId: args.threadId } : {}),
            },
          )
          return { messageId: (sent as { message_id: number }).message_id }
        } catch (err) {
          process.stderr.write(
            `telegram gateway: ms365-approval postCard failed: ${(err as Error).message}\n`,
          )
          return null
        }
      },
      log: (m) => process.stderr.write(`telegram gateway: ms365-approval — ${m}\n`),
    })
  },

  /**
   * #1623 — hostd-initiated config-edit approval card. hostd posts a
   * `request_config_approval` message; we render the card via
   * `handleRequestConfigApproval`, awaiting the operator tap (or
   * timeout) before sending `config_approval_resolved` back. After
   * hostd's apply attempt completes it posts
   * `request_config_finalize` to flip the card to the terminal
   * outcome.
   */
  async onRequestConfigApproval(client: IpcClient, msg) {
    const { handleRequestConfigApproval } = await import(
      './config-approval-handler.js'
    )
    const { InlineKeyboard } = await import('grammy')
    await handleRequestConfigApproval(client, msg, {
      agentName: getMyAgentName(),
      loadTargetChat: () => {
        const access = loadAccess()
        const operator = access.allowFrom[0]
        if (operator === undefined) return null
        // PR4b emitter sweep — hostd config-approval cards are
        // operator-initiated (someone typed /update apply or tapped
        // a button). Follow the originating turn when there is one;
        // admin alias fallback in supergroup mode otherwise. Helper
        // returns undefined for non-supergroup agents → behavior
        // unchanged.
        const activeTurn = currentTurn
        // Topic valid only in the agent's supergroup — never on the operator DM.
        const cfgTopic = topicForRecipient({
          recipientChatId: operator,
          resolvedTopic: resolveAgentOutboundTopic({
            kind: 'hostd-approval',
            originThreadId: activeTurn?.sessionThreadId,
          }),
          supergroupChatId: resolveAgentSupergroupChatId(),
        })
        return {
          chatId: operator,
          ...(cfgTopic != null ? { threadId: cfgTopic } : {}),
        }
      },
      buildKeyboard: (requestId, epoch) =>
        new InlineKeyboard()
          .text('✅ Approve', `cfg:${requestId}:${epoch}:approve`)
          .text('🚫 Deny', `cfg:${requestId}:${epoch}:deny`),
      postCard: async (args) => {
        try {
          const sent = await robustApiCall(
            () =>
              // allow-raw-bot-api: sendRichMessage routed through robustApiCall (not in the THREAD_NOT_FOUND blast pattern)
              bot.api.sendRichMessage(args.chatId, richMessage(args.text), {
                ...(args.threadId !== undefined
                  ? { message_thread_id: args.threadId }
                  : {}),
                reply_markup: args.replyMarkup as never,
              }),
            {
              chat_id: String(args.chatId),
              verb: 'config-approval-card',
              ...(args.threadId !== undefined ? { threadId: args.threadId } : {}),
            },
          )
          return { messageId: (sent as { message_id: number }).message_id }
        } catch (err) {
          process.stderr.write(
            `telegram gateway: config-approval postCard failed: ${(err as Error).message}\n`,
          )
          return null
        }
      },
      editCard: async (args) => {
        try {
          await robustApiCall(
            () =>
              bot.api.editMessageText(args.chatId, args.messageId, richMessage(args.text), {
                // Strip the inline keyboard on a terminal/interim edit so the
                // [Approve]/[Deny] buttons stop being tappable on a resolved card.
                ...(args.stripKeyboard ? { reply_markup: { inline_keyboard: [] } } : {}),
              }),
            { chat_id: String(args.chatId), verb: 'config-approval-edit' },
          )
        } catch (err) {
          process.stderr.write(
            `telegram gateway: config-approval editCard failed: ${(err as Error).message}\n`,
          )
        }
      },
      // #1762: send the full diff as a `.patch` attachment when the
      // card body would exceed Telegram's 4096-char sendMessage limit.
      postAttachment: async (args) => {
        const input = new InputFile(Buffer.from(args.content, 'utf8'), args.filename)
        await robustApiCall(
          () =>
            bot.api.sendDocument(args.chatId, input, {
              ...(args.threadId !== undefined
                ? { message_thread_id: args.threadId }
                : {}),
            }),
          {
            chat_id: String(args.chatId),
            verb: 'config-approval-attachment',
            ...(args.threadId !== undefined ? { threadId: args.threadId } : {}),
          },
        )
      },
      log: (m) =>
        process.stderr.write(`telegram gateway: config-approval — ${m}\n`),
      // #1977 single-tap correlation: auto-approve a config edit the
      // gateway itself just queued in response to an operator tap on
      // the "🔁 Always allow" permission card. Forge-resistant — the
      // match requires the rule the diff ADDS to equal a rule the
      // gateway queued; an agent-forged edit touching any other field
      // finds no entry and falls through to a real operator card.
      tryAutoResolve: (msg) => {
        sweepStaleAlwaysAllowCorrelations()
        // `extractAddedAllowRule` only locates a CANDIDATE entry by the
        // rule token — it is shape-based, not YAML-location-aware, so it
        // is NOT the security gate. The gate is an EXACT byte-match of
        // the incoming diff against the diff the gateway itself
        // synthesized and queued. A forged config_propose_edit (the same
        // consented token placed under `deny:`/`secrets:`, a different
        // field, or any other byte difference) won't match → falls
        // through to a real operator approval card.
        const added = extractAddedAllowRule(msg.unifiedDiff)
        if (added) {
          const key = `${msg.agentName}::${added}`
          const entry = pendingAlwaysAllowCorrelations.get(key)
          if (entry && entry.unifiedDiff === msg.unifiedDiff) {
            pendingAlwaysAllowCorrelations.delete(key)
            return 'approve'
          }
        }
        // hindsight Phase 5: a mental-model PROPOSAL the operator already
        // approved on the proposal card. The gateway pre-registered the EXACT
        // diff; auto-approve on a byte-exact match (the security gate), so no
        // second card is posted. Any forged/other edit finds no entry and
        // falls through to a real operator card.
        sweepStaleMentalModelCorrelations()
        const mmKey = mentalModelCorrelationKey(msg.agentName, msg.unifiedDiff)
        const mmEntry = pendingMentalModelCorrelations.get(mmKey)
        if (mmEntry && mmEntry.unifiedDiff === msg.unifiedDiff) {
          pendingMentalModelCorrelations.delete(mmKey)
          return 'approve'
        }
        return null
      },
    })
  },

  async onRequestConfigFinalize(client: IpcClient, msg) {
    const { handleRequestConfigFinalize } = await import(
      './config-approval-handler.js'
    )
    await handleRequestConfigFinalize(client, msg, {
      editCard: async (args) => {
        try {
          await robustApiCall(
            () =>
              bot.api.editMessageText(args.chatId, args.messageId, richMessage(args.text), {
                // Finalize is terminal — drop the keyboard so buttons are gone.
                ...(args.stripKeyboard ? { reply_markup: { inline_keyboard: [] } } : {}),
              }),
            { chat_id: String(args.chatId), verb: 'config-approval-finalize' },
          )
        } catch (err) {
          process.stderr.write(
            `telegram gateway: config-finalize editCard failed: ${(err as Error).message}\n`,
          )
        }
      },
      log: (m) =>
        process.stderr.write(`telegram gateway: config-finalize — ${m}\n`),
    })
  },

  // #2726 — hostd-initiated rollout status message. Part 1 uses this only for
  // the terminal ping; Part 2 uses the same post as the FIRST narration
  // message, then EDITs it (onRolloutStatusEdit) as later phases arrive. This
  // is an ORDINARY operator-DM message, NOT a pinned card — the framework
  // speaking a plain progress line in the chat. We reply with the message_id so
  // hostd can edit it later; a post failure replies ok:false (hostd then just
  // won't edit — the durable audit log remains the record).
  async onRolloutStatusPost(client: IpcClient, msg: RolloutStatusPostMessage) {
    const self = process.env.SWITCHROOM_AGENT_NAME
    if (self && msg.agentName !== self) {
      process.stderr.write(
        `telegram gateway: rollout_status_post rejected — agent mismatch (${msg.agentName} != ${self})\n`,
      )
      try {
        client.send({ type: 'rollout_status_posted', requestId: msg.requestId, ok: false, reason: 'agent mismatch' })
      } catch { /* best effort */ }
      return
    }
    const operator = loadAccess().allowFrom[0]
    if (operator === undefined) {
      process.stderr.write(`telegram gateway: rollout_status_post — no operator chat (allowFrom empty)\n`)
      try {
        client.send({ type: 'rollout_status_posted', requestId: msg.requestId, ok: false, reason: 'no operator chat' })
      } catch { /* best effort */ }
      return
    }
    try {
      const sent = await robustApiCall(
        () =>
          // allow-raw-bot-api: rich progress line, routed through robustApiCall.
          bot.api.sendRichMessage(operator, richMessage(msg.text), {}),
        { chat_id: String(operator), verb: 'rollout-status-post' },
      )
      const messageId = (sent as { message_id: number }).message_id
      process.stderr.write(
        `telegram gateway: rollout_status_post agent=${msg.agentName} request=${msg.requestId} message_id=${messageId}\n`,
      )
      try {
        client.send({ type: 'rollout_status_posted', requestId: msg.requestId, ok: true, messageId })
      } catch { /* best effort */ }
    } catch (err) {
      process.stderr.write(
        `telegram gateway: rollout_status_post send failed: ${(err as Error).message}\n`,
      )
      try {
        client.send({ type: 'rollout_status_posted', requestId: msg.requestId, ok: false, reason: (err as Error).message })
      } catch { /* best effort */ }
    }
  },

  // #2726 Part 2 / #4065 — edit the previously-posted rollout status message in
  // place as later phases arrive, and REPLY with the outcome so hostd can tell
  // an applied edit from an edit into a deleted card (see rollout-status-edit.ts).
  // Still fire-and-forget toward the roll: hostd never blocks on the reply.
  onRolloutStatusEdit(client: IpcClient, msg: RolloutStatusEditMessage) {
    return handleRolloutStatusEdit(
      {
        selfAgentName: process.env.SWITCHROOM_AGENT_NAME,
        operatorChatId: () => loadAccess().allowFrom[0],
        editMessage: (chatId, messageId, text) =>
          robustApiCall(
            () =>
              // allow-raw-bot-api: in-place edit of the ordinary status message.
              bot.api.editMessageText(chatId, messageId, richMessage(text), {}),
            // BOTH opt-outs are load-bearing — see "TWO swallows" in
            // rollout-status-edit.ts. A SHED edit and a SWALLOWED benign
            // `400 message to edit not found` each resolve WITHOUT throwing,
            // and the handler reads success from the absence of a throw.
            { chat_id: String(chatId), verb: 'rollout-status-edit',
              priorityClass: 'critical', rethrowBenign400: true },
          ),
        log: (m) => process.stderr.write(`telegram gateway: ${m}\n`),
      },
      client,
      msg,
    )
  },

  onInjectInbound(_client: IpcClient, msg: InjectInboundMessage) {
    // #3114 — do NOT unconditionally stamp the MAIN idle clock here. A cron
    // fire (Tier-1 cheap-cron routed to `<agent>-cron`, or a Tier-2 main-
    // session cron) whose cadence is shorter than `idle_clear_after` would
    // otherwise re-arm the timer on every fire and suppress idle-clear
    // permanently. After #3113 a cron that does real work already stamps the
    // main clock via handleSessionEvent, so the blanket fire-time stamp is
    // redundant for main-bridge fires and wrong for cheap-cron (whose session
    // events are dropped for the cron identity). Only non-cron injects
    // (reaction, vault grant, resume — genuine operator/session presence) stamp
    // at inject time. See isCronInjectFire for the documented main-session-poll
    // residual (a Tier-2 NO_REPLY poll still warms the clock via its real turn).
    if (!isCronInjectFire(msg.inbound.meta)) markIdleActivity()
    const promptKey = typeof msg.inbound.meta?.prompt_key === 'string'
      ? msg.inbound.meta.prompt_key
      : 'unknown'
    const source = typeof msg.inbound.meta?.source === 'string'
      ? msg.inbound.meta.source
      : 'unknown'
    // Cheap-cron (reference/rfcs/cheap-cron-sessions.md §3.3): a Tier-1 fire
    // carries meta.session='cron' → route to the derived `<agent>-cron`
    // bridge (a 2nd interactive Sonnet session in the same container).
    // Every other fire (and all of today's callers) routes to the agent
    // unchanged. Route+buffer share the same target so a fire that lands
    // mid cron-session-spawn buffers under the cron identity and drains to
    // it on register.
    // Graceful Tier-1 fallback (cheap-crons JTBD: a cron must NEVER be
    // dropped because of tier routing). A cron-routed fire whose `<agent>-cron`
    // bridge isn't connected (boot-forked session not up yet for a hot-added
    // frequent cron, or a crashed cron session) falls back to the MAIN agent
    // bridge so the fire lands now; it routes cheap again once the session is
    // up. See deliverInjectWithFallback.
    // #2793 part B — durable cron boot-replay. A fire the scheduler is
    // REPLAYING across a restart carries `meta.replay_fire_ms`; route it
    // through the durable inbound spool so accept and consume are ledgered
    // separately (mirrors the real-inbound path). The scheduler's own
    // scheduler.jsonl records the fire at socket-accept, which stops
    // findMissedFires from re-firing it — but a socket accept is NOT proof
    // the session consumed it. Spooling here means: if the session isn't up
    // (accepted-but-not-consumed), the entry stays un-acked and the spool's
    // boot-replay re-delivers it on the next gateway boot (closes the
    // silent-loss window); and the stable `spoolId` (keyed on the replayed
    // fire) dedups a re-replay so it lands at most once (closes the
    // double-fire window). Live cron ticks never set replay_fire_ms, so they
    // keep the fire-and-forget path unchanged. STATIC mode has no spool —
    // fall through to the legacy path.
    const isDurableReplay =
      inboundSpool != null &&
      typeof msg.inbound.meta?.replay_fire_ms === 'string' &&
      msg.inbound.meta.replay_fire_ms.length > 0
    if (isDurableReplay && inboundSpool != null) {
      // Durable ACCEPT: put before delivery so a crash between accept and
      // consume leaves the entry recoverable (boot-replay re-delivers).
      // Idempotent by stable spoolId — a re-replay of the same missed fire
      // is a no-op while the prior entry is still un-acked.
      inboundSpool.put(msg.agentName, msg.inbound as unknown as InboundMessage)
    }
    const { target, delivered, fellBackToMain } = deliverInjectWithFallback(
      msg.agentName,
      msg.inbound.meta,
      (t) => ipcServer.sendToAgent(t, msg.inbound),
    )
    if (isDurableReplay && inboundSpool != null && delivered) {
      // Durable CONSUME: the fire reached a live bridge, so tombstone the
      // spool entry (same "delivered to a live registered bridge" ack
      // semantics the inbound spool uses — see its v1 scope note). On a
      // miss we leave it un-acked: the pendingInboundBuffer.push below
      // buffers it for the reconnect drain, and the durable spool copy is
      // re-delivered on the next boot if this process dies first.
      inboundSpool.ack(msg.inbound as unknown as InboundMessage)
    }
    if (fellBackToMain) {
      process.stderr.write(
        `telegram gateway: cron fire fell back to main session (no cron bridge) agent=${msg.agentName} prompt_key=${promptKey}\n`,
      )
      // #2307 Tier-1 observability: a climbing counter means the cron session is
      // down (registered then died, or never came up) — the Tier-1 saving is
      // lost for this fire. Surfaced via the unified runtime-metrics fan-out.
      emitRuntimeMetric({ kind: 'cron_fell_back_to_main', agent: msg.agentName, prompt_key: promptKey })
    }
    process.stderr.write(
      `telegram gateway: inject_inbound agent=${msg.agentName} target=${target}${fellBackToMain ? " (fellback)" : ""} source=${source} prompt_key=${promptKey} delivered=${delivered}\n`,
    )
    // #1150: same buffer-on-failure pattern as vault_grant_approved.
    // Only reached if BOTH the cron bridge and the main bridge are down
    // (e.g. mid-restart) — buffer under the bridge we tried last so it
    // drains on the next register.
    if (!delivered) {
      pendingInboundBuffer.push(target, msg.inbound)
    }
  },

  // #2307 Tier-0 action tier — a MODEL-FREE outbound post. The agent-scheduler
  // fires this for a `kind: action` `telegram-message`; the gateway posts the
  // (already-substituted) text to the agent's OWN chat with NO model: no
  // inject_inbound, no session wake, no currentTurn mutation. Two fences:
  //   1. agentName must match this gateway's own SWITCHROOM_AGENT_NAME.
  //   2. chatId must be an allowlisted chat for this agent (assertAllowedChat).
  // An action carries no chat target of its own — the scheduler supplies the
  // agent's own chat — so 2 is belt-and-braces against a malformed/foreign id.
  onSendOutbound(_client: IpcClient, msg: SendOutboundMessage) {
    const self = process.env.SWITCHROOM_AGENT_NAME
    if (self && msg.agentName !== self) {
      process.stderr.write(
        `telegram gateway: send_outbound rejected — agent mismatch (${msg.agentName} != ${self})\n`,
      )
      return
    }
    try {
      assertAllowedChat(msg.chatId)
    } catch (err) {
      process.stderr.write(
        `telegram gateway: send_outbound rejected — ${(err as Error).message}\n`,
      )
      return
    }
    const threadId = msg.threadId
    // #2669: literal `text` mode → plain send; everything else → rich markdown.
    const literalText = msg.parseMode === 'text'
    const outOpts = {
      ...(threadId != null && threadId !== 1 ? { message_thread_id: threadId } : {}),
    }
    // allow-raw-bot-api: wrapped in swallowingApiCall (retry policy); thread-aware send.
    // General topic (thread 1) sends omit message_thread_id per the outbound convention.
    void swallowingApiCall(
      (): Promise<{ message_id: number }> =>
        literalText
          ? bot.api.sendMessage(msg.chatId, msg.text, outOpts)
          : bot.api.sendRichMessage(msg.chatId, richMessage(msg.text), outOpts),
      { chat_id: msg.chatId, verb: 'cron-action-send', ...(threadId != null ? { threadId } : {}) },
    )
    process.stderr.write(
      `telegram gateway: send_outbound agent=${msg.agentName} chat=${msg.chatId} thread=${threadId ?? '-'} len=${msg.text.length}\n`,
    )
  },

  // The wedge-watchdog detected claude's /rate-limit-options weekly-quota menu
  // (a TUI wall that never produced a 429, so the inference-path auto-fallback
  // never fired). Trigger the SAME fleet auto-fallback the 429 path uses,
  // threading the parsed weekly reset as markExhausted's `until` — with a
  // weekly-scale FALLBACK when the sidecar couldn't parse it (resetAt absent):
  // passing undefined would let markExhausted use its ~5h default, which would
  // un-exhaust a weekly-walled account and re-wedge it within hours. The
  // existing chain handles the rest (roll to a fallback subscription account,
  // or the all-exhausted operator alert when none has quota). Fire-and-forget.
  onQuotaWallDetected(_client: IpcClient, msg: QuotaWallDetectedMessage) {
    const untilMs = resolveExhaustUntil(msg.resetAt)
    process.stderr.write(
      `telegram gateway: quota_wall_detected agent=${msg.agentName} ` +
        `until=${new Date(untilMs).toISOString()}` +
        (msg.resetAt == null ? ' (reset unparsed → +7d default)' : '') +
        ' — triggering fleet auto-fallback\n',
    )
    void fireFleetAutoFallback(
      msg.agentName,
      untilMs,
      // Enriched announcement: the sidecar-parsed reset (when present) keeps
      // the recovery line honest even when the old account's probe fails.
      msg.resetAt != null ? new Date(msg.resetAt) : undefined,
    )
  },

  // Issue #2971 — read-only wedge-watchdog probe: is there a live pending
  // permission request (Telegram approval card) for this agent right now?
  // Sourced directly from `pendingPermissions` — no mutation, no card
  // posting, just a snapshot read. The watchdog uses this to decide whether
  // to Esc a shape-persistent permission-prompt TUI or defer to the card /
  // the #2724 TTL reaper. Always answered synchronously and on the SAME
  // connection so the watchdog's short (~2s) budget can resolve promptly.
  onQueryPendingPermission(client: IpcClient, msg: QueryPendingPermissionMessage) {
    const self = process.env.SWITCHROOM_AGENT_NAME
    if (self && msg.agentName !== self) {
      process.stderr.write(
        `telegram gateway: query_pending_permission rejected — agent mismatch (${msg.agentName} != ${self})\n`,
      )
      try {
        client.send({ type: 'pending_permission_status', correlationId: msg.correlationId, pending: false })
      } catch { /* best effort */ }
      return
    }
    // Any LIVE entry answers the question — this gateway serves exactly one
    // agent, so `pendingPermissions` is already scoped to `msg.agentName`.
    const [requestId] = pendingPermissions.keys()
    const pending = pendingPermissions.size > 0
    try {
      client.send({
        type: 'pending_permission_status',
        correlationId: msg.correlationId,
        pending,
        ...(pending && requestId ? { requestId } : {}),
      })
    } catch (err) {
      process.stderr.write(
        `telegram gateway: query_pending_permission reply failed: ${(err as Error).message}\n`,
      )
    }
  },

  // #2975 Stage 2 — read-only pre-approval query from hostd. Answer whether the
  // EXACT (agent, diff) pair is already operator-consented so hostd can skip the
  // config_propose_edit rate limit for that persist. NEVER mutates state: it
  // only peeks the correlation maps by byte-exact match (isDiffPreApproved).
  // Fail-closed by construction — any agent mismatch or missing correlation
  // answers `preApproved: false`.
  onCheckPreApproved(client: IpcClient, msg: CheckPreApprovedMessage) {
    let preApproved = false
    try {
      const self = process.env.SWITCHROOM_AGENT_NAME
      // This gateway serves exactly one agent; a query for a different agent
      // can never be pre-approved here.
      if (!self || msg.agentName === self) {
        preApproved = isDiffPreApprovedLive(msg.agentName, msg.unifiedDiff)
      }
    } catch (err) {
      process.stderr.write(
        `telegram gateway: check_pre_approved errored — ${(err as Error).message} (failing closed)\n`,
      )
      preApproved = false
    }
    try {
      client.send({ type: 'pre_approved_result', correlationId: msg.correlationId, preApproved })
    } catch (err) {
      process.stderr.write(
        `telegram gateway: check_pre_approved reply failed: ${(err as Error).message}\n`,
      )
    }
  },

  // #2670 one-tap self-improvement — persist a skill-improvement proposal and
  // post its Approve/Dismiss card. The store transition + apply-injection on
  // Approve are owned by handleSkillProposalCallback (so a gateway restart
  // between post and tap still resolves correctly). Placed AFTER
  // onQuotaWallDetected so it doesn't fall inside the source slice that
  // send-outbound-wiring.test.ts takes between onSendOutbound and
  // onQuotaWallDetected.
  // Thin delegate — body lives in self-improve-proposal-wiring.ts to keep the
  // gateway line ratchet flat. Placed AFTER onQuotaWallDetected so it doesn't
  // fall inside the source slice send-outbound-wiring.test.ts takes between
  // onSendOutbound and onQuotaWallDetected.
  onPostSkillProposal(_client: IpcClient, msg: PostSkillProposalMessage) {
    handlePostSkillProposal(msg, { bot, assertAllowedChat, swallowingApiCall })
  },

  // RFC amendment §"corrections as eval cases" — thin delegate; the
  // DETERMINISTIC applier runs on Approve in handleEvalCaseProposalCallback,
  // NOT a model turn. Body in self-improve-proposal-wiring.ts.
  onPostEvalCaseProposal(_client: IpcClient, msg: PostEvalCaseProposalMessage) {
    handlePostEvalCaseProposal(msg, { bot, assertAllowedChat, swallowingApiCall })
  },

  // Buzz Phase 2b: the duplex peer's advisory publish outcome — no-op unless the hub mirror booted.
  onBuzzPublishResult: (_c, m) => getBuzzMirror()?.onPublishResult(m),
  log: (msg) => process.stderr.write(`telegram gateway: ipc — ${msg}\n`),
})
// Buzz Phase 2b: boot the hub mirror (dark unless channels.buzz.enabled + mode both); wires the peer transport, else a no-op.
if (isGatewayMain) maybeBootBuzzMirror((msg) => ipcServer.sendToBuzzPeer(msg))

// ─── Webhook ingest server (RFC webhook-via-gateway-socket) ───────────────
// Under the Docker runtime the host-side web receiver runs as the operator
// UID and cannot write this agent's UID-owned dir (EACCES 500) nor connect
// gateway.sock. When `channels.telegram.webhook_via_gateway` is set, the
// receiver instead forwards verified+rendered events here over a dedicated
// peercred-gated UDS; this gateway (agent UID) owns the jsonl append,
// dedup, and dispatch firing. Wrapped so any failure is best-effort and can
// NEVER crash gateway boot (which would take the agent down).
if (isGatewayMain) (() => {  // #2996 P0c: gated — starts webhook-ingest UDS server
  try {
    const selfAgent = process.env.SWITCHROOM_AGENT_NAME ?? ''
    if (!selfAgent) return

    let viaGateway = false
    try {
      const cfg = loadSwitchroomConfig()
      const raw = cfg.agents?.[selfAgent]
      viaGateway = raw
        ? resolveAgentConfig(cfg.defaults, cfg.profiles, raw).channels?.telegram
            ?.webhook_via_gateway === true
        : false
    } catch (err) {
      process.stderr.write(
        `telegram gateway: webhook-ingest config probe failed: ${(err as Error).message}\n`,
      )
    }
    if (!viaGateway) return

    // Allowed peer UIDs: the agent's own UID (self-connections) + the
    // operator/receiver UID emitted into the env by the compose generator
    // (SWITCHROOM_WEBHOOK_RECEIVER_UID == operatorUid). Fail-closed: if the
    // receiver UID is unset, only self can connect → receiver gets 503,
    // surfacing the misconfiguration instead of silently accepting any UID.
    const allowedUids: number[] = []
    const ownUid = typeof process.getuid === 'function' ? process.getuid() : null
    if (ownUid !== null) allowedUids.push(ownUid)
    const receiverUidRaw = process.env.SWITCHROOM_WEBHOOK_RECEIVER_UID
    const receiverUid = receiverUidRaw ? Number(receiverUidRaw) : NaN
    if (Number.isInteger(receiverUid)) allowedUids.push(receiverUid)

    const socketPath = join(STATE_DIR, 'webhook.sock')

    // In-process delivery of a synthesized webhook turn — the same
    // sendToAgent + buffer-on-failure primitive onInjectInbound uses, so a
    // webhook fire landing mid bridge-reconnect is buffered, not dropped.
    const webhookInject = (agentName: string, inbound: unknown): boolean => {
      // The wire record is a structural mirror of the bridge's
      // InboundMessage (same cast the scheduler's ipcDispatcher uses).
      const msg = inbound as InboundMessage
      const delivered = ipcServer.sendToAgent(agentName, msg)
      if (!delivered) pendingInboundBuffer.push(agentName, msg)
      return delivered
    }

    startWebhookIngestServer({
      socketPath,
      allowedUids,
      log: (s) => process.stderr.write(`telegram gateway: ${s}`),
      onRecord: (req) =>
        recordWebhookEvent(
          {
            agent: selfAgent,
            source: req.source,
            event_type: req.event_type,
            ts: req.ts,
            rendered_text: req.rendered_text,
            payload: req.payload,
            ...(req.delivery_id ? { delivery_id: req.delivery_id } : {}),
          },
          {
            inject: webhookInject,
            log: (s) => process.stderr.write(`telegram gateway: ${s}`),
            onConsolidation: surfaceConsolidationLegibility,
          },
        ),
    })
  } catch (err) {
    process.stderr.write(
      `telegram gateway: webhook-ingest server start failed (non-fatal): ${(err as Error).message}\n`,
    )
  }
})()

// ─── Opportunistic idle-drain of pendingInboundBuffer ─────────────────────
// The THIRD drain trigger, beside bridge re-register (onClientRegistered) and
// the silence-poke framework fallback (#1546): neither fires when a message is
// buffered during a bridge-IPC flap that settles with no clean re-register while
// claude is idle, so it orphans until a manual restart (finn, 2026-05-19). Gated
// zero-cost/zero-churn: skip when nothing is buffered, when the bridge is dead,
// or when a turn is in flight (#1556 — a message delivered mid-turn is typed into
// claude's TUI composer and the auto-submit races turn-completion, stranding it).
const IDLE_DRAIN_INTERVAL_MS = 5000
// F2 (drain half) — bounded busy-defer. A ~5-min poke can clear the machine turn
// while the CLI is still producing the answer; draining a represent into that busy
// session re-queues it BEHIND the real reply → a duplicate. Defer while busy,
// bounded so a wedged session still drains (F1 then retracts it post-reply).
// staleGap = 3 poll intervals: a longer gap between busy consultations means the
// buffer drained via a non-idle path so the next one is a NEW episode (#4341 f/u).
const idleDrainBusyDefer = makeSessionBusyDrainDeferral(OBLIGATION_BACKGROUND_WORK_GRACE_MS, IDLE_DRAIN_INTERVAL_MS * 3)
if (isGatewayMain && !STATIC) {
  setInterval(() => {
    const selfAgent = process.env.SWITCHROOM_AGENT_NAME ?? ''
    const r = idleDrainTick(
      pendingInboundBuffer,
      selfAgent,
      () => {
        // #1556: never drain mid-turn — that re-creates the composer
        // wedge this buffer exists to prevent. Gate reads the delivery
        // machine (turnInFlightForGate) AND, per F2, stream-render's live-turn
        // mirror (a poke can clear the former while the latter is still busy).
        if (turnInFlightForGate()) return false
        const sessionBusy = (currentTurn != null && currentTurn.endedAt == null) || parkedTurnStartCount() > 0
        if (idleDrainBusyDefer(sessionBusy, Date.now())) return false
        const c = ipcServer.getClient(selfAgent)
        return c != null && c.isAlive()
      },
      (m) => ipcServer.sendToAgent(selfAgent, m),
      inboundSpool,
      trackRedeliveredInbound,
    )
    if (r != null && r.redelivered > 0) {
      process.stderr.write(
        `telegram gateway: idle-drain flushed ${r.redelivered}/${r.drained} ` +
        `buffered inbound for ${selfAgent}` +
        `${r.rebuffered > 0 ? ` (${r.rebuffered} re-buffered)` : ''}\n`,
      )
    }
    // Bounded escalation: a spooled inbound still un-acked past its
    // bound (default 15 min — well past the 5-min silence-poke ladder)
    // is undeliverable in practice. Retract the "will be processed"
    // promise EXPLICITLY (honest failure) instead of letting it sit
    // forever. This is what makes the guarantee deterministic: every
    // queued message ends either delivered or visibly retracted.
    inboundSpool?.sweepEscalations((e, { postNotice, droppedCount }) => {
      const chat = e.msg.chatId
      const escThread =
        typeof e.msg.meta?.threadId === 'string' && e.msg.meta.threadId
          ? Number(e.msg.meta.threadId)
          : undefined
      const threadOpts = escThread != null ? { message_thread_id: escThread } : {}
      // Reap any "Queued — replying in #X" placeholder for this topic first:
      // the message is being declared undeliverable, so the queued-status must
      // not dangle beside the "couldn't deliver" notice (idempotent best-effort;
      // a normal turn-start/turn-end reaps far sooner — this is the 15-min edge).
      // Reaping happens for EVERY dropped entry; only the user-facing notice is
      // coalesced (postNotice), so a burst of undeliverable inbounds doesn't
      // leave dangling placeholders even when its notice is suppressed.
      reapQueuedStatus(chat, escThread)
      // Coalesced per chat by the spool's sliding window — a multi-restart
      // outage that re-ages a synthetic into the bound every 15 min posts ONE
      // notice, not one per cycle (the 2026-06-09 marko "please resend" spam).
      if (!postNotice) return
      // #2789 C: report the REAL number of dropped messages for this chat
      // in this sweep rather than under-counting a multi-message drop as a
      // single one.
      const n = droppedCount > 0 ? droppedCount : 1
      const noticeText =
        n === 1
          ? "⚠️ I couldn't deliver an earlier message to the agent after repeated retries (it survived restarts but the agent never picked it up). Please resend it."
          : `⚠️ I couldn't deliver ${n} earlier messages to the agent after repeated retries (they survived restarts but the agent never picked them up). Please resend them.`
      void swallowingApiCall(
        () =>
          bot.api.sendMessage(chat, noticeText, { ...threadOpts }),
        { chat_id: chat, verb: 'inbound-spool-escalation' },
      )
    })
  }, IDLE_DRAIN_INTERVAL_MS).unref()
}

// ─── Tool execution ──────────────────────────────────────────────────────

/** Allowlisted tool names that bridges may invoke via IPC. Prevents a rogue
 *  bridge from calling arbitrary functions by name. */
const ALLOWED_TOOLS = new Set([
  'reply', 'progress_update', 'react', 'download_attachment',
  'edit_message', 'send_typing', 'pin_message', 'delete_message',
  'forward_message', 'get_recent_messages',
  'send_checklist', 'update_checklist',
  'ask_user',
  'send_sticker', 'send_gif',
  'vault_request_save',
  'vault_request_access',
  'request_secret',
  'mental_model_propose',
  'linear_agent_activity',
  'linear_create_issue',
  'linear_agent_setup',
])

async function executeToolCall(
  tool: string,
  args: Record<string, unknown>,
  // #4172 — calling client identity; only the reply path consumes it today.
  callerAgentName: string | null = null,
): Promise<unknown> {
  if (!ALLOWED_TOOLS.has(tool)) {
    throw new Error(`tool not allowed: ${tool}`)
  }
  switch (tool) {
    case 'reply':
      return executeReply(args, callerAgentName)
    case 'progress_update':
      return executeProgressUpdate(args)
    case 'react':
      return executeReact(args)
    case 'download_attachment':
      return executeDownloadAttachment(args)
    case 'edit_message':
      return executeEditMessage(args)
    case 'send_typing':
      return executeSendTyping(args)
    case 'pin_message':
      return executePinMessage(args)
    case 'delete_message':
      return executeDeleteMessage(args)
    case 'forward_message':
      return executeForwardMessage(args)
    case 'get_recent_messages':
      return executeGetRecentMessages(args)
    case 'send_checklist':
      return executeSendChecklist(args)
    case 'update_checklist':
      return executeUpdateChecklist(args)
    case 'ask_user':
      return executeAskUser(args)
    case 'send_sticker':
      return executeSendSticker(args)
    case 'send_gif':
      return executeSendGif(args)
    case 'vault_request_save':
      return cardToolHandlers.executeVaultRequestSave(args)
    case 'vault_request_access':
      return cardToolHandlers.executeVaultRequestAccess(args)
    case 'request_secret':
      return cardToolHandlers.executeRequestSecret(args)
    case 'mental_model_propose':
      return cardToolHandlers.executeMentalModelPropose(args)
    case 'linear_agent_activity':
      return executeLinearAgentActivity(args)
    case 'linear_create_issue':
      return executeLinearCreateIssue(args)
    case 'linear_agent_setup':
      return executeLinearAgentSetup(args)
    default:
      throw new Error(`unknown tool: ${tool}`)
  }
}

async function executeSendChecklist(args: Record<string, unknown>): Promise<{ content: Array<{ type: string; text: string }> }> {
  const chat_id = String(args.chat_id ?? '')
  if (!chat_id) throw new Error('send_checklist: chat_id is required')
  const title = args.title as string | undefined
  if (!title) throw new Error('send_checklist: title is required')
  const tasks = args.tasks as Array<{ text: string; done?: boolean }> | undefined
  if (!Array.isArray(tasks) || tasks.length === 0) throw new Error('send_checklist: tasks must be a non-empty array')
  const threadId = args.message_thread_id != null ? Number(args.message_thread_id) : undefined
  const replyTo = parseSourceMessageId(args.reply_to as string | number | null | undefined) ?? undefined // #4368: drop a fabricated/out-of-int32 anchor so the send lands unanchored, not 400
  const protectContent = args.protect_content === true

  assertAllowedChat(chat_id)

  // #2044 outbound secret scrub. Checklist title + task strings are
  // agent-authored free text sent to Telegram, same class as the reply
  // `text` path and ask_user — route both through the SAME redactor before
  // send (via the pure, unit-tested redactChecklistFields helper) so an
  // echoed token / DATABASE_URL is masked.
  const { title: redactedTitle, tasks: redactedTasks } = redactChecklistFields(
    title,
    tasks,
    (t) => redactOutboundText(t, 'send_checklist'),
  )

  // Graceful degradation: native sendChecklist is Business-account-only, so
  // ordinary chats (the fleet norm) get a formatted text render instead of a
  // raw Telegram 400 (rationale + orchestration in checklist-fallback.ts).
  const literal = (loadAccess().parseMode ?? 'html') === 'text'
  const sendOpts = {
    ...(threadId != null ? { message_thread_id: threadId } : {}),
    ...(replyTo != null ? { reply_parameters: { message_id: replyTo } } : {}),
    ...(protectContent ? { protect_content: true } : {}),
  }
  const result = await performSendChecklist({
    businessConnectionId: resolveBusinessConnectionId(),
    nativeAvailable: CHECKLIST_API_AVAILABLE,
    sendNative: rawSendChecklist,
    sendText: (text) => robustApiCall(
      (): Promise<{ message_id: number }> =>
        literal
          // allow-raw-bot-api: literal checklist text-fallback send routed through robustApiCall
          ? lockedBot.api.sendMessage(chat_id, text, sendOpts as never)
          // allow-raw-bot-api: checklist text-fallback send routed through robustApiCall
          : lockedBot.api.sendRichMessage(chat_id, richMessage(text), sendOpts as never),
      { verb: 'sendMessage', chat_id, threadId },
    ),
    literalText: literal,
    log: (l) => process.stderr.write(`telegram gateway: ${l}`),
  }, { title: redactedTitle!, tasks: redactedTasks!, chatId: Number(chat_id), replyToMessageId: replyTo, protectContent })

  checklistStore.set(checklistStoreKey(chat_id, result.message_id), result.state)
  process.stderr.write(`telegram gateway: send_checklist: sent chatId=${chat_id} messageId=${result.message_id} tasks=${tasks.length} mode=${result.mode}\n`)
  return { content: [{ type: 'text', text: sendChecklistToolText(result) }] }
}

/**
 * Per-(agent,reason) cooldown for the Linear-auth-dead operator alert. The
 * triggering 401 recurs on every Linear call once the token expires, so
 * without a cooldown the operator would be paged on every capture/activity.
 * One alert per reason per window is enough to surface the action item.
 */
const linearAuthAlertLast = new Map<string, number>()
const LINEAR_AUTH_ALERT_COOLDOWN_MS = 6 * 60 * 60 * 1000

/**
 * Surface an un-healable Linear auth failure (no refresh bundle / revoked
 * refresh token) to the operator as a Telegram message — not just a gateway
 * log line. Deduped per (agent,reason) and gated by SWITCHROOM_LINEAR_AUTH_ALERT=0.
 * Best-effort: a failed send never affects the agent's turn.
 */
function notifyLinearAuthDead(info: { agent: string; reason: LinearAuthDeadReason; detail: string }): void {
  if (process.env.SWITCHROOM_LINEAR_AUTH_ALERT === '0') return
  const key = `${info.agent}:${info.reason}`
  const now = Date.now()
  const last = linearAuthAlertLast.get(key)
  if (last != null && now - last < LINEAR_AUTH_ALERT_COOLDOWN_MS) return
  void (async () => {
    try {
      const chatId = loadAccess().allowFrom[0]
      if (!chatId) return
      const threadId = topicForRecipient({
        recipientChatId: chatId,
        resolvedTopic: resolveAgentOutboundTopic({ kind: 'linear-auth' }) ?? chatThreadMap.get(chatId),
        supergroupChatId: resolveAgentSupergroupChatId(),
      })
      const text = buildLinearAuthDeadMessage(info.agent, info.reason)
      await swallowingApiCall(
        () =>
          // allow-raw-bot-api: wrapped in swallowingApiCall (retry policy)
          bot.api.sendRichMessage(chatId, richMessage(text), {
            ...(threadId != null ? { message_thread_id: threadId } : {}),
          }),
        { chat_id: chatId, verb: 'linearAuthDead' },
      )
      // Stamp the cooldown only after a successful send so a transient
      // Telegram failure doesn't burn the 6h window (the 401 recurs and will
      // retry the page on the next Linear call).
      linearAuthAlertLast.set(key, now)
      process.stderr.write(`telegram gateway: linear auth-dead alert sent agent=${info.agent} reason=${info.reason}\n`)
    } catch {
      /* best-effort */
    }
  })()
}

async function executeLinearAgentActivity(args: Record<string, unknown>): Promise<{ content: Array<{ type: string; text: string }> }> {
  return emitLinearAgentActivity(args, { onAuthUnrecoverable: notifyLinearAuthDead })
}

async function executeLinearCreateIssue(args: Record<string, unknown>): Promise<{ content: Array<{ type: string; text: string }> }> {
  return createLinearIssue(args, { onAuthUnrecoverable: notifyLinearAuthDead })
}

async function executeLinearAgentSetup(args: Record<string, unknown>): Promise<{ content: Array<{ type: string; text: string }> }> {
  return runLinearAgentSetup(args)
}

async function executeUpdateChecklist(args: Record<string, unknown>): Promise<{ content: Array<{ type: string; text: string }> }> {
  const chat_id = String(args.chat_id ?? '')
  if (!chat_id) throw new Error('update_checklist: chat_id is required')
  const message_id = args.message_id as string | undefined
  if (!message_id) throw new Error('update_checklist: message_id is required')
  const title = args.title as string | undefined
  const tasks = args.tasks as Array<{ id?: string; text?: string; done?: boolean }> | undefined

  assertAllowedChat(chat_id)

  // #2044 outbound secret scrub. update_checklist forwards the same
  // agent-authored title + task text to Telegram as send_checklist, so it
  // shares the identical leak class — redact both through the reply-path
  // redactor (via the shared redactChecklistFields helper) before the edit
  // lands. title / tasks may be undefined here (partial patch); the helper
  // passes undefined through untouched.
  const { title: redactedTitle, tasks: redactedTasks } = redactChecklistFields(
    title,
    tasks,
    (t) => redactOutboundText(t, 'update_checklist'),
  )

  // Graceful degradation (checklist-fallback.ts): the patch is applied to the
  // stored per-message state and the message re-rendered in the mode it was
  // sent in. Failures come back structured, never as a raw Telegram 400.
  const literal = (loadAccess().parseMode ?? 'html') === 'text'
  const key = checklistStoreKey(chat_id, message_id)
  const result = await performUpdateChecklist({
    state: checklistStore.get(key),
    businessConnectionId: resolveBusinessConnectionId(),
    nativeAvailable: CHECKLIST_API_AVAILABLE,
    editNative: rawEditMessageChecklist,
    // allow-raw-bot-api: checklist text-fallback edit routed through robustApiCall
    editText: async (text) => { await robustApiCall(() => lockedBot.api.editMessageText(chat_id, Number(message_id), literal ? text : richMessage(text))) },
    literalText: literal,
    log: (l) => process.stderr.write(`telegram gateway: ${l}`),
    chatId: Number(chat_id),
    messageId: Number(message_id),
  }, { title: redactedTitle, tasks: redactedTasks })

  if (result.ok) checklistStore.set(key, result.state)
  process.stderr.write(`telegram gateway: update_checklist: ${result.ok ? `updated mode=${result.mode}` : `failed reason=${result.reason}`} chatId=${chat_id} messageId=${message_id}\n`)
  return { content: [{ type: 'text', text: updateChecklistToolText(result, Number(message_id)) }] }
}

/**
 * Outbound secret scrub (#2044). The agent is trusted, but it can still
 * echo a secret it read from a file, env, or a not-yet-vaulted value into
 * a reply — and outbound text had no redaction at all. This masks any
 * detected secret in agent-authored text BEFORE it is logged (the stderr
 * previews), forwarded (sent to Telegram), or stored (recordOutbound).
 *
 * It runs the SAME `detectSecrets` engine as the inbound gate, so a
 * pattern added once (e.g. the Sanctum `<id>|<token>` shape, #2043) covers
 * both directions. Applied at the entry of every agent-free-text tool
 * (reply / stream_reply / edit_message), mutating the text in place so all
 * downstream consumers — voice scrub, dedup key, chunker, answer-stream
 * diffing, history record — see the masked value. This is the same
 * in-place-mutation contract the voice scrub already relies on, which
 * keeps the answer-stream's incremental edit diffing consistent (it always
 * compares redacted-against-redacted).
 */
function redactOutboundText(text: string, site: string): string {
  const masked = redact(text)
  if (masked !== text) {
    // Never log the secret — only that a mask fired, and where.
    process.stderr.write(`telegram gateway: outbound secret masked site=${site}\n`)
  }
  return masked
}

/** Default per-voice-note chunk size (chars). A long reply is split into
 *  sequential voice notes of roughly this size on sentence/paragraph
 *  boundaries. Only the OpenAI (cloud) engine still uses this — the kokoro
 *  sidecar now takes the whole reply in one call and returns a single note. */
const VOICE_OUT_DEFAULT_CHUNK_CHARS = 600

/** Hard ceiling for a single OpenAI TTS request. OpenAI's TTS input caps at
 *  4096 chars, so client-side chunks for that engine never exceed this; the
 *  reply is spoken across sequential notes when it's longer. (The kokoro path
 *  no longer chunks — the sidecar owns length and returns one file.) */
const VOICE_OUT_HARD_CHUNK_CAP = 4096

/**
 * On-demand voice-out (reply_mode='on-demand'). Instead of synthesizing at
 * reply time, the gateway appends a single "🔊 Listen" inline button carrying
 * a reserved `voice:<token>` callback_data; audio is synthesized + sent only
 * when the user taps it. This keeps the voice pipeline subscription-honest and
 * visible — zero GPU/sidecar work happens behind the user's back.
 *
 * We cache the (speech-normalized text, voice, speed) needed to synthesize by
 * TOKEN, not message_id, because the message_id is not known at send time.
 * Bounded LRU with a TTL so a stale button (tapped an hour later) degrades to
 * a graceful "expired" toast rather than pinning reply text in memory forever.
 */
// Persist the Listen-token cache under STATE_DIR (= /state/agent/telegram in
// prod, a volume that survives container recreation). Without this the Map was
// wiped on every gateway restart, so a 🔊 Listen button tapped on a message
// sent before the restart degraded to "Voice expired". The same TTL + LRU cap
// still applies; expired entries are dropped on load.
const voiceOnDemandCache = new VoiceOnDemandCache({
  persistPath: join(STATE_DIR, 'voice-ondemand.json'),
})

// ─── Eager voice pre-synthesis (#2763) ─────────────────────────────────────
// Whenever a reply becomes Listen-eligible (a voiceOnDemandCache entry is
// persisted alongside the Listen button), ALSO synthesize the audio in the
// background via the LOCAL sidecar and park it on disk, so the 🔊 Listen tap
// attaches the pre-made file instantly instead of waiting on the GPU. Local
// engine only (kokoro — zero token/dollar cost); the openai cloud engine
// never pre-synthesizes. Strictly off the reply critical path: jobs drain
// through a bounded FIFO (concurrency 1, drop-oldest past the cap) and every
// failure is swallowed — the tap just falls back to the lazy synth path.
// Kill switch: SWITCHROOM_DISABLE_EAGER_VOICE=1 (the sweep still runs so old
// files age out).
const VOICE_CACHE_DIR = join(STATE_DIR, 'voice-cache')

const voicePreSynthQueue = new PreSynthQueue({
  runJob: async (job) => {
    const sidecarToken = await materializeSidecarToken()
    if (!sidecarToken) return // sidecar unavailable — lazy path will retry on tap
    const result = await synthesizeViaSidecar({
      token: sidecarToken,
      // Same deterministic normalization the lazy Listen path applies —
      // job.text is normalizeForSpeech(reply); normalizeForTts is the #2760
      // L1 pass on top.
      text: normalizeForTts(job.text),
      voice: job.voice,
      speed: job.speed,
    })
    if (!result.ok) {
      process.stderr.write(
        `telegram gateway: voice-presynth: sidecar synthesis failed token=${job.token} reason=${result.reason}\n`,
      )
      return
    }
    const filePath = writeVoiceCacheFile(VOICE_CACHE_DIR, job.token, result.audio)
    voiceOnDemandCache.setFilePath(job.token, filePath)
    // TODO(first-tap-instant): pre-mint the Telegram file_id here so even the
    // FIRST user tap sends by id (no upload). Would require uploading this ogg
    // once to the bot's OWN hidden storage/log chat and calling
    // voiceOnDemandCache.setTelegramFileId(job.token, msg.voice.file_id).
    // Deferred: no storage-chat id exists in config/env today, and the product
    // invariant forbids sending audio to the USER's chat without a tap — so a
    // dedicated bot-storage chat id must be added first. Until then, the first
    // tap uploads (via the disk fast-path) and captures the id for reuse; only
    // the second+ taps are instant.
    process.stderr.write(
      `telegram gateway: voice-presynth: cached ${result.audio.length} bytes at ${filePath} ` +
        `(${result.durationMs}ms, backlog=${voicePreSynthQueue.size})\n`,
    )
  },
})

/** Rolling 7-day TTL + 500MB size-budget sweep over VOICE_CACHE_DIR. Runs at
 *  boot and hourly; ALWAYS runs (even under the eager-voice kill switch) so
 *  previously written files age out. Crash-safe: missing dir/files tolerated. */
function sweepVoiceCache(): void {
  try {
    const result = sweepVoiceCacheDir({ dir: VOICE_CACHE_DIR })
    if (result.deletedTokens.length > 0) {
      voiceOnDemandCache.prune(result.deletedTokens)
      process.stderr.write(
        `telegram gateway: voice-presynth: sweep removed ${result.deletedTokens.length} file(s), ` +
          `${result.remainingBytes} bytes remain\n`,
      )
    }
  } catch (err) {
    // Defence in depth — sweepVoiceCacheDir is already per-file crash-safe.
    process.stderr.write(`telegram gateway: voice-presynth: sweep failed: ${String(err)}\n`)
  }
}

if (isGatewayMain && !STATIC) {
  sweepVoiceCache() // boot sweep — covers a died timer / long downtime
  setInterval(sweepVoiceCache, VOICE_SWEEP_INTERVAL_MS).unref()
}

type VoiceOutAccess = NonNullable<Access['voice_out']>

/**
 * Resolve whether outbound TTS is active for this reply, and how
 * (engine + reply_mode + the plain-text TTS chunks). PR-C2.
 *
 * Mirrors the voice-IN engine-resolution precedence (message:voice
 * handler): the compose-injected SWITCHROOM_VOICE_ENGINE verdict gates the
 * local 'kokoro' engine, exactly like the STT sidecar. The 'openai' engine
 * is an honest-exception cloud path gated on an api_key vault ref — it does
 * NOT require a local verdict.
 *
 * Returns null when voice-out is off / not applicable; otherwise a plan the
 * caller acts on. `ttsChunks` is speech-normalized plain text (markdown and
 * TTS-mispronounced symbols removed — see normalizeForSpeech).
 *
 * ONE voice note per response: the kokoro (local sidecar) path now sends the
 * WHOLE normalized reply to `/tts` in a SINGLE call — the sidecar chunks +
 * concatenates internally on the GPU and returns a single ogg/opus file — so
 * `ttsChunks` is a single element for kokoro. `max_chars` is no longer a hard
 * client-side splitter for kokoro; it's retired for that path (the sidecar
 * owns length). The openai (cloud) engine keeps client-side chunking because
 * OpenAI's TTS input has its own hard cap; each chunk is one voice note.
 */
function resolveVoiceOutPlan(
  voiceOut: VoiceOutAccess | undefined,
  replyText: string,
): {
  engine: 'kokoro' | 'openai'
  voice?: string
  speed: number
  apiKeyRef?: string
  replyMode: 'voice+text' | 'voice-only' | 'on-demand'
  ttsChunks: string[]
} | null {
  if (voiceOut?.enabled !== true) return null

  const engine = voiceOut.engine ?? 'kokoro'

  // Engine gating mirrors the voice-in handler precedence: the
  // compose-injected env wins, then the persisted host-capabilities file,
  // then a fail-safe 'cloud'. The in-container ~/.switchroom is a read-only
  // view that does NOT carry host-capabilities.json, so the env is
  // load-bearing in-fleet (see message:voice). Kokoro requires 'local';
  // openai requires a resolvable api_key.
  if (engine === 'kokoro') {
    const envVoiceEngine = process.env.SWITCHROOM_VOICE_ENGINE
    const voiceEngine: VoiceEngine =
      envVoiceEngine === 'local' || envVoiceEngine === 'cloud'
        ? envVoiceEngine
        : loadHostCapabilities()?.voice.engine ?? 'cloud'
    if (voiceEngine !== 'local') return null
  }

  // Speech-normalized TTS input: strip markdown AND translate/drop the
  // symbols TTS mispronounces (~, backticks, arrows, tables, code fences,
  // link URLs) REGARDLESS of mode so the engine reads clean prose. Applied
  // for BOTH engines — the older partial stripMarkdown pass leaked `~`,
  // code fences and arrows.
  const ttsText = normalizeForSpeech(replyText)
  if (ttsText.length === 0) return null

  // ONE voice note for kokoro: the sidecar accepts arbitrarily long text and
  // returns a single concatenated ogg/opus file, so we send the whole reply
  // in one call — no client-side splitting, no multi-sendVoice. `max_chars`
  // is retired as a hard splitter here.
  //
  // OpenAI still needs client-side chunking (its TTS input has a hard cap),
  // so for that engine we split at the engine cap; each chunk is one note.
  let ttsChunks: string[]
  if (engine === 'kokoro') {
    ttsChunks = [ttsText]
  } else {
    const chunkChars = Math.min(
      voiceOut.max_chars ?? VOICE_OUT_DEFAULT_CHUNK_CHARS,
      VOICE_OUT_HARD_CHUNK_CAP,
    )
    ttsChunks = chunkTtsText(ttsText, chunkChars)
  }
  if (ttsChunks.length === 0) return null

  // Kokoro playback speed: default 1.1 (fleet default) when unset, clamped to
  // 0.5–2.0. Threaded into the /tts body by synthesizeVoiceOut. The OpenAI
  // path ignores it.
  const speed = clampTtsSpeed(voiceOut.speed, VOICE_OUT_DEFAULT_SPEED)

  return {
    engine,
    voice: voiceOut.voice,
    speed,
    apiKeyRef: voiceOut.api_key,
    replyMode: voiceOut.reply_mode ?? 'voice+text',
    ttsChunks,
  }
}

/**
 * Synthesize `ttsText` into OGG/Opus bytes via the configured engine.
 * Best-effort: returns null on ANY failure (logged to stderr), never
 * throws. The caller treats null as "voice unavailable, fall back to
 * text". PR-C2.
 */
async function synthesizeVoiceOut(plan: {
  engine: 'kokoro' | 'openai'
  voice?: string
  speed?: number
  apiKeyRef?: string
  ttsText: string
}): Promise<Uint8Array | null> {
  try {
    // #2760 Phase 1: deterministic L1 TTS normalization, applied at the
    // single choke point where every engine's request body is built.
    // On by default; kill switch: SWITCHROOM_DISABLE_TTS_NORMALIZE=1.
    const ttsText = normalizeForTts(plan.ttsText)
    if (plan.engine === 'kokoro') {
      const token = await materializeSidecarToken()
      if (!token) return null // materializeSidecarToken already logged why.
      const result = await synthesizeViaSidecar({
        token,
        text: ttsText,
        voice: plan.voice,
        speed: plan.speed,
      })
      if (!result.ok) {
        process.stderr.write(
          `telegram gateway: voice-out: local sidecar synthesis failed reason=${result.reason}` +
            (result.detail ? ` detail=${JSON.stringify(result.detail).slice(0, 100)}` : '') +
            '\n',
        )
        return null
      }
      process.stderr.write(
        `telegram gateway: voice-out: local sidecar synthesized ${result.audio.length} bytes in ${result.durationMs}ms ` +
          `voice=${result.voice ?? '?'} audio_s=${result.audioSeconds ?? '?'} chars=${plan.ttsText.length}\n`,
      )
      return result.audio
    }

    // engine === 'openai' — honest-exception cloud path.
    const apiKey = await materializeVoiceKey({ apiKeyRef: plan.apiKeyRef })
    if (!apiKey) return null // materializeVoiceKey already logged why.
    const result = await synthesizeViaOpenAi({
      apiKey,
      text: ttsText,
      voice: plan.voice,
    })
    if (!result.ok) {
      process.stderr.write(
        `telegram gateway: voice-out: openai synthesis failed reason=${result.reason}` +
          (result.detail ? ` detail=${JSON.stringify(result.detail).slice(0, 100)}` : '') +
          '\n',
      )
      return null
    }
    process.stderr.write(
      `telegram gateway: voice-out: openai synthesized ${result.audio.length} bytes in ${result.durationMs}ms ` +
        `voice=${result.voice} chars=${plan.ttsText.length}\n`,
    )
    return result.audio
  } catch (err) {
    // Defence in depth: the synth helpers never throw, but the vault
    // materialize calls might. Voice is best-effort — swallow + fall back.
    process.stderr.write(
      `telegram gateway: voice-out: synthesis threw (non-fatal): ${err instanceof Error ? err.message : String(err)}\n`,
    )
    return null
  }
}

async function executeReply(
  args: Record<string, unknown>,
  callerAgentName: string | null = null,
): Promise<{ content: Array<{ type: string; text: string }> }> {
  // #2996 P2: the ~1,400-line orchestration body moved VERBATIM to
  // outbound-send-path.ts `sendReply()` — the single tested send primitive.
  // #1664 — the turn is pinned HERE at entry (same read, same position as the
  // old inline `const turn = currentTurn`) and passed in `req`; the façade
  // also gets a live `getCurrentTurn()` accessor for the deliberate live
  // re-reads (Amendment 9: each call site keeps its pin-vs-live choice).
  // #4172 — a foreign-session caller gets no supersede/bypass/latch authority.
  return sendReply(gatewaySendReplyDeps(), {
    args,
    turn: currentTurn,
    callerIsForeignSession: replyCallerIsForeignSession(callerAgentName),
  })
}

/** Live gateway deps for the extracted send façade (#2996 P2). Built fresh
 *  per call (cheap object literal) so every member reference is current. */
function gatewaySendReplyDeps(): SendReplyGatewayDeps {
  return {
    // the ONE live instances (Amendment 1/9 — never re-new in a module)
    outboundDedup, flushedTurnSupersede,
    firstTextReplyLogged, suppressPtyPreview,
    activeDraftStreams, lastPtyPreviewByChat,
    voiceOnDemandCache, voicePreSynthQueue,
    pendingProgress, signalTracker,
    silencePoke,
    getCurrentTurn: () => currentTurn,
    getLastActiveTurnChatId: () => lastActiveTurnChatId,
    HISTORY_ENABLED, TURN_ORIGIN_ROUTING_ENABLED,
    AUTOCLASSIFY_MIDTURN_SHADOW,
    MAX_ATTACHMENT_BYTES,
    MAX_CHUNK_LIMIT,
    PHOTO_EXTS,
    lockedBot,
    robustApiCall,
    swallowingApiCall,
    loadAccess,
    redactOutboundText,
    assertAllowedChat,
    assertSendable,
    statusKey,
    streamKey,
    resolveReplyOwnerTurn,
    findTurnByOriginId, findTurnByQuotedMessageId, findLatestTurnForChat,
    resolveAnswerThreadWithLog,
    resolveThreadId,
    getLatestInboundMessageId,
    getLastSubagentHandbackAt,
    subagentReplyAuthority,
    recordOutbound,
    emissionAuthorityFor,
    clearActivitySummary,
    startTypingLoop,
    stopTypingLoop,
    logOutbound,
    closeObligationOnSubstantiveReply,
    finalizeStatusReaction,
    releaseTurnBufferGate,
    reapQueuedStatus,
    noteAgentOutputAt,
    rememberAgentButtonMeta,
    resolveVoiceOutPlan,
    synthesizeVoiceOut,
    publishToTelegraph,
    clearSilentEndState,
    emitRuntimeMetric,
    shadowEmit,
    progressDriver,
  }
}

async function executeProgressUpdate(args: Record<string, unknown>): Promise<unknown> {
  if (!args.chat_id) throw new Error('progress_update: chat_id is required')
  if (!args.text) throw new Error('progress_update: text is required')

  const chat_id = String(args.chat_id ?? '')
  let text = args.text as string
  const threadId = resolveThreadId(chat_id, args.message_thread_id as string | undefined)
  const key = statusKey(chat_id, threadId)

  assertAllowedChat(chat_id)

  // Outbound secret scrub (#2044). progress_update was the ONLY send site not
  // calling redactOutboundText, so a secret the agent echoed into a progress
  // line reached Telegram unmasked (reply/stream_reply/edit_message/turn_flush
  // all redact). Mask BEFORE the 300-char truncation below: a secret straddling
  // the 300-char cut would otherwise be sliced apart and evade the detector, so
  // redaction has to run on the full untruncated text first.
  text = redactOutboundText(text, 'progress_update')

  // Truncate to 300 chars
  if (text.length > 300) {
    text = text.slice(0, 299) + '…'
  }

  const now = Date.now()

  // Rate limit: ≥ 20s between calls
  const lastSent = progressUpdateLastSent.get(key)
  if (lastSent != null) {
    const elapsed = now - lastSent
    if (elapsed < 20_000) {
      return {
        content: [
          {
            type: 'text',
            text: JSON.stringify({ ok: false, reason: 'too_soon', retryAfterMs: 20_000 - elapsed }),
          },
        ],
      }
    }
  }

  // Attention cap: max 5 DELIVERIES per turn when a turn atom exists, else a
  // rolling 15-min/chat fallback when the inbound minted none (handback /
  // progress-inbound turns) so a worker can't send at the 20s floor forever
  // and defeat the documented per-turn cap. Both count deliveries only. The
  // slot is RESERVED before the send (via sendWithProgressCap below) so two
  // truly-concurrent same-key calls can't both pass the check and overshoot
  // the cap, and it is RELEASED if the send throws — so a thrown send never
  // burns a slot even under concurrency (#4328 Fix 2 preserved).
  const turnStart = activeTurnStartedAt.get(key)

  // Issue #305 Option A — the card-injection path (route a sub-agent's
  // `progress_update` narrative into its row on the parent's pinned card)
  // was retired with the progress card in #1122/#1126: `progressDriver` is
  // permanently null, so `recordSubAgentNarrative` could never fire and the
  // whole `resolveCallingSubagent` → card-inject block was a dead no-op that
  // always fell through here. Removed. Sub-agent progress now surfaces via
  // the `🛠 Worker` activity feed + the model's own in-voice handback, and a
  // `progress_update` call always takes the plain message-send path below.

  // Send plain message (no quote-reply). Single rich-markdown path (#2669):
  // `parseMode:'text'` config opts into a literal plain send; everything
  // else ships raw GFM markdown via sendRichMessage.
  const access = loadAccess()
  const literalText = (access.parseMode ?? 'html') === 'text'

  const sendOpts = {
    ...(threadId != null ? { message_thread_id: threadId } : {}),
  }

  // Reserve the attention-cap slot, send, and release the slot on a throw. A
  // successful send KEEPS the reservation (it IS the delivery record), so no
  // extra counting runs after the send. `capped` short-circuits when the
  // reservation is refused.
  const capped = await sendWithProgressCap(
    { key, now, turnStart, turnCount: progressUpdateTurnCount },
    (): Promise<{ message_id: number }> =>
      robustApiCall(
        (): Promise<{ message_id: number }> =>
          literalText
            // allow-raw-bot-api: literal progress-update send routed through robustApiCall
            ? lockedBot.api.sendMessage(chat_id, text, sendOpts as never)
            : lockedBot.api.sendRichMessage(chat_id, richMessage(text), sendOpts as never),
        { verb: 'sendMessage', chat_id, threadId },
      ),
  )
  if (capped.capped) {
    return {
      content: [
        {
          type: 'text',
          text: JSON.stringify({ ok: false, reason: 'turn_limit' }),
        },
      ],
    }
  }
  const sent = capped.result

  // Record in sent-message history. RecordOutboundArgs uses `texts`
  // (parallel array to message_ids), not `text` — the singular-name
  // typo silently omitted progress_update outbounds from the history
  // DB. Caught by scripts/check-plugin-references.mjs (TS2561).
  if (HISTORY_ENABLED) {
    recordOutbound({
      chat_id,
      thread_id: threadId ?? null,
      message_ids: [sent.message_id],
      texts: [text],
    })
  }

  progressUpdateLastSent.set(key, now)

  // The delivery slot was already reserved before the send (sendWithProgressCap
  // above), so there is nothing to count here — a successful send keeps its
  // reservation and a thrown send released it.

  // Issue #203: progress_update is a user-visible signal — tick the
  // silent-gap tracker so it doesn't count as silent time.
  try {
    signalTracker.noteSignal(key, Date.now())
  } catch { /* best-effort signal */ }
  // #4330: model-driven user-visible outbound — reset the silence clock like a reply send.
  try { silencePoke.noteOutbound(key, Date.now()) } catch { /* best-effort */ }

  return {
    content: [
      {
        type: 'text',
        text: JSON.stringify({ ok: true, message_id: sent.message_id }),
      },
    ],
  }
}

/**
 * `ask_user` MCP tool. Closes #574.
 *
 * The agent calls `ask_user({ chat_id, question, options[] })`; we
 * post the question to Telegram with one inline-keyboard button per
 * option, store the outstanding prompt in `pendingAskUser`, and
 * return a Promise that resolves when the user taps a button (the
 * callback dispatcher at the bottom of this file calls our resolve)
 * or the TTL fires. Either way, the agent's `tool_call_result` is a
 * structured `AskUserOutcome` it can branch on.
 *
 * Failure modes:
 *   - assertAllowedChat throws → return error to agent, no message sent.
 *   - sendMessage throws → reject the deferred immediately so the
 *     agent doesn't sit forever; map to `{ kind: 'cancelled', reason }`.
 *   - timeout → resolve `{ kind: 'timeout' }`, edit the message to
 *     show "(no response)" so the user knows the prompt expired.
 *   - gateway shutdown / chat-close → resolve `{ kind: 'cancelled' }`
 *     for every outstanding ask in that chat (see
 *     clearAskUserPromptsForChat below).
 */
async function executeAskUser(rawArgs: Record<string, unknown>): Promise<unknown> {
  const args = validateAskUserArgs(rawArgs as unknown as AskUserArgs)
  assertAllowedChat(args.chatId)

  // #2044 outbound secret scrub. The question text and each option/button
  // label are agent-authored free text sent to Telegram, exactly like the
  // reply `text` path — an agent that echoes a token or DATABASE_URL it just
  // read into a question or a button label would transmit it unmasked. Route
  // both through the SAME redactor as reply (via the pure, unit-tested
  // redactAskUserFields helper), assigning back onto the validated args so
  // every downstream consumer — the send, the timeout-edit re-render, and
  // the tap-echo of the chosen label stored in pendingAskUser — sees the
  // masked value.
  const scrubbed = redactAskUserFields(args.question, args.options, (t) =>
    redactOutboundText(t, 'ask_user'),
  )
  args.question = scrubbed.question
  args.options = scrubbed.options

  // Resolve thread + reply-to using the same auto-thread heuristic
  // executeReply uses, so an agent that omits message_thread_id still
  // routes into the right forum topic and quotes the user's last
  // inbound message by default.
  const threadId = resolveThreadId(args.chatId, args.threadId)
  let replyTo: number | undefined = args.replyTo
  if (replyTo == null && HISTORY_ENABLED) {
    try {
      const latest = getLatestInboundMessageId(args.chatId, threadId ?? null)
      if (latest != null) replyTo = latest
    } catch (err) {
      process.stderr.write(`telegram gateway: ask_user quote lookup failed: ${(err as Error).message}\n`)
    }
  }

  // Build inline keyboard — one button per option, stacked vertically
  // so each label gets the full chat width on a phone. Telegram
  // supports horizontal pairs, but vertical reads cleanly even on
  // narrow screens.
  const askId = generateAskId()
  const keyboard = new InlineKeyboard()
  for (let i = 0; i < args.options.length; i++) {
    keyboard.text(args.options[i], encodeAskCallback(askId, i))
    if (i < args.options.length - 1) keyboard.row()
  }

  // Send the question. We need the message_id back so we can edit-in-
  // place on resolution / timeout — that's what makes the surface feel
  // alive (button tap turns into "✅ <choice>" inline) rather than a
  // graveyard of unanswered questions in the chat history.
  const sendOpts: Record<string, unknown> = {
    reply_markup: keyboard,
  }
  if (threadId != null) sendOpts.message_thread_id = threadId
  if (replyTo != null) sendOpts.reply_parameters = { message_id: replyTo }

  let messageId: number | null = null
  try {
    // #1075: thread-id-bearing — route through retryWithThreadFallback
    // so a deleted topic still gets the ask_user card on the main chat.
    const sent = await retryWithThreadFallback<{ message_id: number }>(
      robustApiCall,
      (tid) => {
        const opts = { ...sendOpts }
        if (tid == null) delete opts.message_thread_id
        else opts.message_thread_id = tid
        return lockedBot.api.sendRichMessage(args.chatId, richMessage(args.question), opts)
      },
      { threadId, chat_id: args.chatId, verb: 'ask_user.sendMessage' },
    )
    messageId = sent.message_id
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err)
    return { content: [{ type: 'text', text: JSON.stringify({ kind: 'cancelled', reason: `send-failed: ${msg}` }) }] }
  }

  // Open the deferred. The promise resolves either:
  //   1. via the callback dispatcher (user tap), or
  //   2. via the timeout below.
  return new Promise<unknown>((resolveTool) => {
    const timer = setTimeout(() => {
      const entry = pendingAskUser.get(askId)
      pendingAskUser.delete(askId)
      if (!entry) return
      // Edit the question to remove buttons + show timeout state.
      // Best-effort: a failed edit doesn't change the outcome.
      // #1075: edit operates on a message inside the (possibly-deleted)
      // thread — swallow on THREAD_NOT_FOUND so we don't crash on
      // timeout cleanup.
      void swallowingApiCall(
        () =>
          lockedBot.api.editMessageText(
            args.chatId,
            entry.messageId!,
            richMessage(`${args.question}\n\n_⏱ no response within ${Math.round(args.timeoutMs / 1000)}s_`),
          ),
        {
          chat_id: args.chatId,
          verb: 'ask_user.timeout-edit',
          ...(threadId != null ? { threadId } : {}),
        },
      )
      resolveTool({ content: [{ type: 'text', text: JSON.stringify({ kind: 'timeout' } satisfies AskUserOutcome) }] })
    }, args.timeoutMs)

    pendingAskUser.set(askId, {
      options: args.options,
      chatId: args.chatId,
      threadId,
      messageId,
      startedAt: Date.now(),
      timer,
      resolve: (outcome: AskUserOutcome) => {
        // Caller already deleted from map + cleared timer.
        resolveTool({ content: [{ type: 'text', text: JSON.stringify(outcome) }] })
      },
    })
  })
}

/**
 * Cancel every outstanding ask_user in a given chat. Called when the
 * gateway shuts down or when a turn ends without the question being
 * answered (the next user message implicitly invalidates pending
 * prompts — they'd otherwise leak across turns, which is confusing).
 */
function clearAskUserPromptsForChat(chatId: string, reason: string): void {
  for (const [askId, entry] of pendingAskUser.entries()) {
    if (entry.chatId !== chatId) continue
    clearTimeout(entry.timer)
    pendingAskUser.delete(askId)
    entry.resolve({ kind: 'cancelled', reason })
  }
}

/**
 * `send_sticker` MCP tool (#576). Send a Telegram sticker, resolving
 * either a raw file_id or an operator-curated alias from
 * `access.stickers`. Validation lives in the pure
 * `resolveStickerSendArgs` helper; this function is just glue.
 */
async function executeSendSticker(rawArgs: Record<string, unknown>): Promise<unknown> {
  const access = loadAccess()
  const args = resolveStickerSendArgs(rawArgs as unknown as StickerSendArgs, access.stickers ?? {})
  assertAllowedChat(args.chatId)

  // Same auto-thread + auto-reply heuristic as executeReply, so the
  // sticker lands in the right forum topic and quotes the user's
  // last inbound when not explicitly overridden.
  const threadId = resolveThreadId(args.chatId, args.threadId)
  let replyTo: number | undefined = args.replyTo
  if (replyTo == null && HISTORY_ENABLED) {
    try {
      const latest = getLatestInboundMessageId(args.chatId, threadId ?? null)
      if (latest != null) replyTo = latest
    } catch (err) {
      process.stderr.write(`telegram gateway: send_sticker quote lookup failed: ${(err as Error).message}\n`)
    }
  }

  const baseSendOpts: Record<string, unknown> = {}
  if (replyTo != null) baseSendOpts.reply_parameters = { message_id: replyTo }

  // #1075: thread-id-bearing — drop the thread on THREAD_NOT_FOUND so
  // the sticker still lands on the main chat.
  const sent = await retryWithThreadFallback<{ message_id: number }>(
    robustApiCall,
    (tid) => {
      const opts = { ...baseSendOpts }
      if (tid != null) opts.message_thread_id = tid
      return lockedBot.api.sendSticker(args.chatId, args.fileId, opts)
    },
    { threadId, chat_id: args.chatId, verb: 'sendSticker' },
  )
  process.stderr.write(
    `telegram gateway [outbound] ${new Date().toISOString()} path=sticker ` +
    `chat=${args.chatId} msg_id=${sent.message_id} ` +
    `resolution=${args.resolution}${args.aliasName ? ` alias=${args.aliasName}` : ''}\n`,
  )
  return {
    content: [{
      type: 'text',
      text: JSON.stringify({
        kind: 'sent',
        message_id: sent.message_id,
        resolution: args.resolution,
        ...(args.aliasName ? { alias: args.aliasName } : {}),
      }),
    }],
  }
}

/**
 * `send_gif` MCP tool (#576). Send an animated GIF / MP4 / WebM via
 * Telegram's sendAnimation. Accepts file_id or operator-trusted https
 * URL — there is no GIF search; agents pass references they've seen
 * or that the user has shared.
 */
async function executeSendGif(rawArgs: Record<string, unknown>): Promise<unknown> {
  const args = resolveGifSendArgs(rawArgs as unknown as GifSendArgs)
  assertAllowedChat(args.chatId)

  const threadId = resolveThreadId(args.chatId, args.threadId)
  let replyTo: number | undefined = args.replyTo
  if (replyTo == null && HISTORY_ENABLED) {
    try {
      const latest = getLatestInboundMessageId(args.chatId, threadId ?? null)
      if (latest != null) replyTo = latest
    } catch (err) {
      process.stderr.write(`telegram gateway: send_gif quote lookup failed: ${(err as Error).message}\n`)
    }
  }

  const baseSendOpts: Record<string, unknown> = {}
  if (args.caption != null) baseSendOpts.caption = args.caption
  if (replyTo != null) baseSendOpts.reply_parameters = { message_id: replyTo }

  // #1075: thread-id-bearing — drop the thread on THREAD_NOT_FOUND.
  const sent = await retryWithThreadFallback<{ message_id: number }>(
    robustApiCall,
    (tid) => {
      const opts = { ...baseSendOpts }
      if (tid != null) opts.message_thread_id = tid
      return lockedBot.api.sendAnimation(args.chatId, args.animationRef, opts)
    },
    { threadId, chat_id: args.chatId, verb: 'sendAnimation' },
  )
  process.stderr.write(
    `telegram gateway [outbound] ${new Date().toISOString()} path=gif ` +
    `chat=${args.chatId} msg_id=${sent.message_id} ref_kind=${args.refKind}\n`,
  )
  return {
    content: [{
      type: 'text',
      text: JSON.stringify({
        kind: 'sent',
        message_id: sent.message_id,
        ref_kind: args.refKind,
      }),
    }],
  }
}

/**
 * Telegraph publishing helper (#579). Lazy-creates a Telegraph
 * account on first use and caches the access_token at
 * `<STATE_DIR>/telegraph-account.json`. Returns the published URL
 * on success or null on any failure (caller falls back to normal
 * chunked HTML sending).
 *
 * Caller must already have decided that publishing is desired
 * (text > threshold AND telegraph.enabled). This function is the
 * I/O wrapper around the pure helpers in telegraph.ts.
 */
async function publishToTelegraph(
  text: string,
  shortName: string,
  authorName: string | undefined,
): Promise<string | null> {
  const accountPath = join(STATE_DIR, 'telegraph-account.json')
  let account: TelegraphAccount | null = null
  try {
    if (existsSync(accountPath)) {
      const raw = readFileSync(accountPath, 'utf-8')
      const parsed = JSON.parse(raw) as Partial<TelegraphAccount>
      if (parsed.shortName && parsed.accessToken) {
        account = parsed as TelegraphAccount
      }
    }
  } catch (err) {
    process.stderr.write(`telegram gateway: telegraph cache read failed: ${(err as Error).message}\n`)
  }

  if (account == null) {
    const created = await createTelegraphAccount({ shortName, authorName })
    if (!created.ok) {
      process.stderr.write(`telegram gateway: telegraph createAccount failed: ${created.reason}\n`)
      return null
    }
    account = created.value
    try {
      mkdirSync(STATE_DIR, { recursive: true, mode: 0o700 })
      writeFileSync(accountPath, JSON.stringify(account, null, 2), { mode: 0o600 })
    } catch (err) {
      process.stderr.write(`telegram gateway: telegraph cache write failed: ${(err as Error).message}\n`)
      // proceed — we have the token in memory for this turn at least
    }
  }

  const title = deriveTelegraphTitle(text)
  const content = markdownToTelegraphNodes(text)
  const page = await createTelegraphPage({
    accessToken: account.accessToken,
    title,
    content,
    authorName,
  })
  if (!page.ok) {
    process.stderr.write(`telegram gateway: telegraph createPage failed: ${page.reason}\n`)
    return null
  }
  process.stderr.write(`telegram gateway: telegraph published url=${page.value.url} title=${JSON.stringify(title)} chars=${text.length}\n`)
  return page.value.url
}

// executeVaultRequestSave moved verbatim to card-tool-handlers.ts (#2996
// P5-tail) — invoked as cardToolHandlers.executeVaultRequestSave(args) from the
// tool dispatcher; its stores (pendingVaultRequestSaves, pendingCardStore) stay
// here and are injected.

// ─── #2045 request_secret — agent asks the operator to PROVIDE a secret ───
//
// The third member of the agent-vault tool family. `vault_request_save`
// = agent HAS a value and asks to save it; `vault_request_access` = agent
// needs read access to an existing key; `request_secret` = agent needs a
// value it does NOT have. The operator provides it through a secure card:
// they tap [Provide securely], send the value once, and the gateway deletes
// the message instantly + writes it straight to the vault. The raw value is
// never recorded to history, never logged, never returned to the agent —
// the agent only ever references `vault:<key>`. This removes the reason an
// agent would ever ask a user to paste a secret as a normal chat message.
// PendingSecretRequest + ArmedSecretCapture moved to callback-query-handlers.ts
// (#2996 P5) with handleSecretRequestCallback; imported back above. The stores
// below hold the SAME singleton instances injected into the callback handlers.
// chat_id -> the armed capture: the operator's NEXT message in this chat is
// the value for `key`. Set when [Provide securely] is tapped.
// Storage extracted to pending-state-stores.ts (#2996 Phase 3 step 2). Swept by
// sweepSecretRequests (below) — a plain delete-past-TTL, no wake (transient
// post-tap window). Direction preserved: now - armed_at > TTL.
const armedSecretCaptures = createSweepableStore<ArmedSecretCapture>(
  (v, now) => now - v.armed_at > ARMED_SECRET_CAPTURE_TTL_MS,
)
const PENDING_SECRET_REQUEST_TTL_MS = 30 * 60_000 // card lifetime
const ARMED_SECRET_CAPTURE_TTL_MS = 10 * 60_000   // window to send the value after tapping
// stageId -> request (lives until tapped or TTL). Storage extracted to
// approval-card-stores.ts (#2996 Phase 3): the store owns the Map + co-locates
// the TTL sweep; expireSecretRequestCard (the wake logic) stays gateway-side.
const pendingSecretRequests = createSweepableCardStore<PendingSecretRequest>({
  isExpired: (v, n) => n - v.staged_at > PENDING_SECRET_REQUEST_TTL_MS,
  expire: () => expireSecretRequestCard,
  log: () => cardExpiryLog,
})

function sweepSecretRequests(now = Date.now()): void {
  pendingSecretRequests.sweep(now)
  // armedSecretCaptures is a TRANSIENT post-tap window (never persisted): it's
  // only set after the operator taps [Provide securely], and the request is
  // no longer parked-on-a-card. Just drop stale ones — no wake needed.
  armedSecretCaptures.sweep(now)
}

// executeRequestSecret moved verbatim to card-tool-handlers.ts (#2996 P5-tail)
// — invoked as cardToolHandlers.executeRequestSecret(args) from the tool
// dispatcher. Its store (pendingSecretRequests) and the sweepSecretRequests
// reaper hook (which also sweeps the transient armedSecretCaptures, shared with
// the handleInbound capture path below) stay here and are injected. The secret
// WRITE + secure-capture path (writeRequestedSecret / captureProvidedSecret)
// stays here too — it's on the inbound path, not the tool-call path.

/**
 * Write a provided secret to the vault. Mirrors the vrs:save write branch:
 * posture-attested broker put under telegram-id mode (no passphrase), else
 * the cached-passphrase CLI path. Returns the same {ok, output} shape.
 */
async function writeRequestedSecret(key: string, value: string, chat_id: string): Promise<{ ok: boolean; output: string }> {
  if (VAULT_APPROVAL_AUTH_MODE === 'telegram-id') {
    return await defaultVaultWritePosture(key, value)
  }
  const cached = vaultPassphraseCache.get(chat_id)
  if (!cached || cached.expiresAt <= Date.now()) {
    return { ok: false, output: 'VAULT-LOCKED: run /vault unlock once in this chat, then have the agent re-request.' }
  }
  return defaultVaultWrite(key, value, cached.passphrase)
}

/**
 * Secure value capture. Called early in handleInbound: if this chat is
 * armed (operator tapped [Provide securely]), the inbound message IS the
 * secret value. Delete it, write to the vault under the requested key, tell
 * the agent it's available, and STOP — never record / log / forward the raw
 * value. Returns true if it consumed the message (caller must return).
 */
async function captureProvidedSecret(
  ctx: Context,
  chat_id: string,
  msgId: number | undefined,
  value: string,
): Promise<boolean> {
  const armed = armedSecretCaptures.get(chat_id)
  if (!armed || Date.now() - armed.armed_at > ARMED_SECRET_CAPTURE_TTL_MS) {
    if (armed) armedSecretCaptures.delete(chat_id)
    return false
  }
  armedSecretCaptures.delete(chat_id)
  const pending = pendingSecretRequests.get(armed.stageId)
  pendingSecretRequests.delete(armed.stageId)
  pendingCardStore.remove(armed.stageId)

  // Delete the raw message FIRST — surfaces a warning if it fails.
  if (msgId != null) await deleteSensitiveMessage(chat_id, msgId, 'provided secret value')

  const write = await writeRequestedSecret(armed.key, value, chat_id)
  if (!write.ok) {
    const parsed = parseVaultCliError(write.output)
    const rendered = renderVaultCliError(parsed, { verb: 'save', key: armed.key })
    const body = rendered.suppressRaw ? rendered.html : `⚠️ vault write failed:\n\`\`\`\n${write.output}\n\`\`\``
    await switchroomReply(ctx, `${body}\n\n_The secret was NOT saved. The agent can re-request with \`request_secret\`._`, { html: true })
    // Wake the agent too (review #2047 finding #3): it ended its turn
    // waiting for a synthetic inbound; without this it stalls silently.
    const fts = Date.now()
    const failMsg: InboundMessage = {
      type: 'inbound',
      chatId: chat_id,
      ...(armed.threadId != null ? { threadId: armed.threadId } : {}),
      messageId: fts,
      user: 'vault-broker',
      userId: 0,
      ts: fts,
      text: `⚠️ The secret you requested for \`vault:${armed.key}\` could NOT be saved (vault write failed). Do not assume it is available; tell the operator or try request_secret again.`,
      meta: {
        source: 'secret_provide_failed',
        agent: armed.agent,
        ...(armed.threadId != null ? { message_thread_id: String(armed.threadId) } : {}),
        key: armed.key,
        stage_id: armed.stageId,
      },
    }
    deliverResumeSyntheticOrBuffer(armed.agent, failMsg)
    return true
  }

  await switchroomReply(
    ctx,
    `✅ saved as \`vault:${escapeHtmlForTg(armed.key)}\` (masked: \`${escapeHtmlForTg(maskToken(value))}\`). The agent can now reference it.`,
    { html: true },
  )

  // Resume the requesting agent with a synthetic inbound — mirrors the
  // vault_grant_approved injection. The value is NOT included; only the key.
  const ts = Date.now()
  const synthetic: InboundMessage = {
    type: 'inbound',
    chatId: chat_id,
    ...(armed.threadId != null ? { threadId: armed.threadId } : {}),
    messageId: ts,
    user: 'vault-broker',
    userId: 0,
    ts,
    text:
      `✅ Operator provided the secret you requested. It is saved as ` +
      `\`vault:${armed.key}\` — reference it the usual way. Resume the task ` +
      `that was waiting on this credential. Do NOT ask the operator to paste it.`,
    meta: {
      source: 'secret_provided',
      agent: armed.agent,
      ...(armed.threadId != null ? { message_thread_id: String(armed.threadId) } : {}),
      key: armed.key,
      stage_id: armed.stageId,
    },
  }
  const delivered = deliverResumeSyntheticOrBuffer(armed.agent, synthetic)
  process.stderr.write(
    `telegram gateway: secret_provided injection agent=${armed.agent} key=${armed.key} stage=${armed.stageId} delivered=${delivered}\n`,
  )
  return true
}

// executeVaultRequestAccess moved verbatim to card-tool-handlers.ts (#2996
// P5-tail) — invoked as cardToolHandlers.executeVaultRequestAccess(args) from
// the tool dispatcher; its store (pendingVaultRequestAccesses), the broker
// probe (listViaBroker) and VAULT_REQUEST_ACCESS_TTL_MS stay here / are
// injected.

/** Read the live switchroom.yaml bytes for diff/dup-check. Mirrors the
 *  always-allow persistence path's config read. */
function readLiveSwitchroomConfigText(): string {
  const cfgPath = process.env.SWITCHROOM_CONFIG ?? findSwitchroomConfigFile()
  return readFileSync(cfgPath, 'utf8')
}

// executeMentalModelPropose (and its MENTAL_MODEL_NAME_REGEX, whose only user
// it was) moved verbatim to card-tool-handlers.ts (#2996 P5-tail) — invoked as
// cardToolHandlers.executeMentalModelPropose(args) from the tool dispatcher.
// Its store (pendingMentalModelProposes), the rate limiter
// (checkMentalModelProposeRate + mentalModelProposeTimes[]), the schema caps
// (MENTAL_MODEL_SOURCE_QUERY_MAX / MENTAL_MODEL_MAX_TOKENS_CAP /
// MENTAL_MODEL_PROPOSE_MAX_PER_WINDOW), and readLiveSwitchroomConfigText stay
// here and are injected; expiry (expireMentalModelProposeCard) and boot restore
// (restorePendingApprovalCards) stay here untouched.

async function executeReact(args: Record<string, unknown>): Promise<unknown> {
  if (!args.chat_id) throw new Error('react: chat_id is required')
  if (!args.message_id) throw new Error('react: message_id is required')
  if (!args.emoji) throw new Error('react: emoji is required')
  assertAllowedChat(String(args.chat_id ?? ''))
  await sendReaction(
    String(args.chat_id ?? ''),
    Number(args.message_id),
    args.emoji as ReactionTypeEmoji['emoji'],
  )
  return { content: [{ type: 'text', text: 'reacted' }] }
}

async function executeDownloadAttachment(args: Record<string, unknown>): Promise<unknown> {
  if (!args.file_id) throw new Error('download_attachment: file_id is required')
  const file_id = String(args.file_id)
  // Validate file_id format — Telegram file IDs are alphanumeric with dashes/underscores
  if (!/^[\w-]{10,200}$/.test(file_id)) {
    throw new Error('download_attachment: invalid file_id format')
  }
  const file = await bot.api.getFile(file_id)
  if (!file.file_path) throw new Error('Telegram returned no file_path — file may have expired')
  // Build download URL — token is embedded but NEVER included in error messages.
  // Bounded fetch (30s) — without a timeout, the agent's tool_call hangs
  // indefinitely on a stalled CDN connection.
  const downloadUrl = `https://api.telegram.org/file/bot${TOKEN}/${file.file_path}`
  let res: Response
  try {
    res = await fetch(downloadUrl, { signal: AbortSignal.timeout(30_000) })
  } catch (err) {
    // Sanitize: never leak the token in network error messages
    throw new Error(`download failed: network error`)
  }
  if (!res.ok) throw new Error(`download failed: HTTP ${res.status}`)
  const buf = Buffer.from(await res.arrayBuffer())
  const dlPath = buildAttachmentPath({
    inboxDir: INBOX_DIR,
    telegramFilePath: file.file_path,
    fileUniqueId: file.file_unique_id,
    now: Date.now(),
  })
  mkdirSync(INBOX_DIR, { recursive: true, mode: 0o700 })
  assertInsideInbox(INBOX_DIR, dlPath)
  writeFileSync(dlPath, buf, { mode: 0o600 })
  return { content: [{ type: 'text', text: dlPath }] }
}

async function executeEditMessage(args: Record<string, unknown>): Promise<unknown> {
  if (!args.chat_id) throw new Error('edit_message: chat_id is required')
  if (!args.message_id) throw new Error('edit_message: message_id is required')
  if (args.text == null || args.text === '') throw new Error('edit_message: text is required and cannot be empty')
  assertAllowedChat(String(args.chat_id ?? ''))
  const editAccess = loadAccess()
  const editFormat = (args.format as string | undefined) ?? (editAccess.parseMode ?? 'html')
  // Single rich-markdown path (#2669): `format:'text'` edits as a literal
  // plain string; everything else edits via the rich-markdown path.
  const editLiteralText = editFormat === 'text'
  // #3501: route through the single shared outbound seam (repair → paragraph-
  // break → redact → punctuation/bold → temporal → voice scrub) instead of the
  // former hand-mirrored inline pipeline. The edit path's deviations are options:
  // literalText skips paragraph/punctuation/bold/spacers + temporal (a literal
  // edit lands byte-for-byte); addSpacers folds the idempotent U+00A0 paragraph
  // spacer into the rich formatting step. tz/nowMs drive the temporal pass.
  const _editNorm = normalizeOutboundBody(args.text as string, 'edit_message', redactOutboundText, {
    literalText: editLiteralText,
    addSpacers: !editLiteralText,
    tz: resolveEnvTimezone(),
    nowMs: Date.now(),
  })
  let editRawText = _editNorm.text
  if (_editNorm.voiceReplaced > 0) {
    emitRuntimeMetric({
      kind: 'voice_scrub_applied',
      chatKey: statusKey(String(args.chat_id ?? ''), undefined),
      replaced: _editNorm.voiceReplaced,
      site: 'edit_message',
    })
  }
  const edited = await robustApiCall(
    () => lockedBot.api.editMessageText(
      String(args.chat_id ?? ''), Number(args.message_id),
      editLiteralText ? editRawText : richMessage(editRawText),
    ),
  )
  const id = typeof edited === 'object' && edited ? (edited as any).message_id : args.message_id
  if (HISTORY_ENABLED) {
    try {
      recordEdit({ chat_id: String(args.chat_id ?? ''), message_id: Number(args.message_id), text: args.text as string })
    } catch (err) {
      process.stderr.write(`telegram gateway: history recordEdit failed: ${err}\n`)
    }
  }
  // Buzz Phase 2b: mirror the edit as a debounced Buzz correction keyed on the edited id — no-op when Buzz is dark or the message was never published; post-delivery, never throws.
  getBuzzMirror()?.mirrorCorrection({ telegramMessageKey: `${String(args.chat_id ?? '')}:${Number(args.message_id)}`, scrubbedText: editRawText })
  return { content: [{ type: 'text', text: `edited (id: ${id})` }] }
}

async function executeSendTyping(args: Record<string, unknown>): Promise<unknown> {
  if (!args.chat_id) throw new Error('send_typing: chat_id is required')
  const stChatId = String(args.chat_id ?? '')
  assertAllowedChat(stChatId)
  // #273: granular chat actions. Default 'typing' preserves the
  // existing tool semantics; agents can opt in to upload_document,
  // record_voice, etc. so the indicator the user sees matches what
  // the agent is actually doing. Reject unsupported strings up front
  // — a silent passthrough would surface as 400 BAD_REQUEST in
  // sendChatAction, which is harder to diagnose.
  const rawAction = args.action
  let action: ChatAction = 'typing'
  if (typeof rawAction === 'string' && rawAction.length > 0) {
    if (!CHAT_ACTION_WHITELIST.has(rawAction as ChatAction)) {
      throw new Error(
        `send_typing: action="${rawAction}" is not in Telegram's chat-action whitelist. ` +
        `Allowed: ${Array.from(CHAT_ACTION_WHITELIST).join(', ')}`,
      )
    }
    action = rawAction as ChatAction
  }
  // PR3 supergroup-mode: resolve thread from args or fall back to the
  // last-seen thread for this chat so the indicator lands in the topic
  // the agent is working in (rather than the chat root).
  const stThreadId = resolveThreadId(stChatId, args.message_thread_id as string | number | undefined) ?? null
  startTypingLoop(stChatId, stThreadId, action)
  setTimeout(() => stopTypingLoop(stChatId, stThreadId), 30000)
  for (const [key, ctrl] of activeStatusReactions.entries()) {
    if (key.startsWith(`${stChatId}:`)) ctrl.setTool()
  }
  return { content: [{ type: 'text', text: `${action} indicator sent (auto-refreshes every 4s, stops after 30s or next reply)` }] }
}

async function executePinMessage(args: Record<string, unknown>): Promise<unknown> {
  if (!args.chat_id) throw new Error('pin_message: chat_id is required')
  if (!args.message_id) throw new Error('pin_message: message_id is required')
  const pinChatId = String(args.chat_id ?? '')
  assertAllowedChat(pinChatId)
  // #1075: wrap through robustApiCall so flood-wait / transient network
  // errors are retried. THREAD_NOT_FOUND on a stale topic surfaces to the
  // agent as a tool-error — pinning a vanished message is genuinely a
  // failure the agent should see.
  const pinMsgId = Number(args.message_id)
  await robustApiCall(
    () => lockedBot.api.pinChatMessage(pinChatId, pinMsgId), // allow-raw-pin: MCP `pin_message` tool — an explicit, agent-requested pin of an arbitrary message, not a progress surface with a claim.
    { chat_id: pinChatId, verb: 'pin_message' },
  )
  // An explicit pin succeeded here, so the bot demonstrably HAS pin rights in
  // this chat now — clear any auto-pin negative-cache entry (#3024) so the auto
  // status-pin path resumes immediately rather than waiting for a restart. The
  // explicit tool itself never consults the cache; a failure above still
  // surfaces to the agent as a normal tool error (robustApiCall rethrows).
  statusPinRightsCache.clear(pinChatId)
  // #3001: register the tool pin in the shared status-pin store under a
  // `tool:` key so it is no longer fire-and-forget. Unlike work-scoped
  // fg:/wk: rows a tool pin has no "work finished" event, so a restart does
  // NOT reset it — boot cleanup keeps the row until its TTL, then unpins the
  // (likely long-forgotten) message. Best-effort fire-and-forget: a store
  // failure must never fail the tool call the pin already landed for.
  if (toolPinPersistEnabled) {
    const toolPinKey = `tool:${pinChatId}:${pinMsgId}`
    void mutateStatusPinRow(STATUS_PIN_STORE_PATH, statusPinStoreFs, toolPinKey, { // allow-raw-pin-store: records the TTL-scoped `tool:` row for the explicit pin above so the boot sweep can expire it.
      pinKey: toolPinKey,
      chatId: pinChatId,
      messageId: pinMsgId,
      expiresAt: Date.now() + TOOL_PIN_TTL_MS,
    })
  }
  return { content: [{ type: 'text', text: `pinned message ${args.message_id}` }] }
}

async function executeDeleteMessage(args: Record<string, unknown>): Promise<unknown> {
  if (!args.chat_id) throw new Error('delete_message: chat_id is required')
  if (!args.message_id) throw new Error('delete_message: message_id is required')
  const delChatId = String(args.chat_id ?? '')
  const delMessageId = Number(args.message_id)
  assertAllowedChat(delChatId)
  await robustApiCall(() => lockedBot.api.deleteMessage(delChatId, delMessageId), { chat_id: delChatId })
  if (HISTORY_ENABLED) {
    try { deleteFromHistory({ chat_id: delChatId, message_id: delMessageId }) } catch (err) {
      process.stderr.write(`telegram gateway: history deleteFromHistory failed: ${err}\n`)
    }
  }
  return { content: [{ type: 'text', text: `deleted message ${delMessageId}` }] }
}

async function executeForwardMessage(args: Record<string, unknown>): Promise<unknown> {
  if (!args.chat_id) throw new Error('forward_message: chat_id is required')
  if (!args.from_chat_id) throw new Error('forward_message: from_chat_id is required')
  if (!args.message_id) throw new Error('forward_message: message_id is required')
  const fwdChatId = String(args.chat_id ?? '')
  const fwdFromChatId = args.from_chat_id as string
  const fwdMsgId = Number(args.message_id)
  assertAllowedChat(fwdChatId)
  const threadId = resolveThreadId(fwdChatId, args.message_thread_id as string | undefined)
  const fwd = await robustApiCall(
    () => lockedBot.api.forwardMessage(fwdChatId, fwdFromChatId, fwdMsgId, {
      ...(threadId != null ? { message_thread_id: threadId } : {}),
    }),
    { threadId, chat_id: fwdChatId },
  )
  if (HISTORY_ENABLED) {
    try {
      recordOutbound({
        chat_id: fwdChatId,
        thread_id: threadId ?? null,
        message_ids: [fwd.message_id],
        texts: [`(forwarded from ${fwdFromChatId}/${fwdMsgId})`],
      })
    } catch (err) {
      process.stderr.write(`telegram gateway: history recordOutbound (forward) failed: ${err}\n`)
    }
  }
  return { content: [{ type: 'text', text: `forwarded (id: ${fwd.message_id})` }] }
}

async function executeGetRecentMessages(args: Record<string, unknown>): Promise<unknown> {
  if (!HISTORY_ENABLED) {
    return {
      content: [{ type: 'text', text: 'history capture is disabled — set historyEnabled: true in access.json and restart' }],
      isError: true,
    }
  }
  if (!args.chat_id) throw new Error('get_recent_messages: chat_id is required')
  const chat_id = String(args.chat_id ?? '')
  assertAllowedChat(chat_id)
  const rawThread = args.message_thread_id as string | undefined
  let thread_id: number | null | undefined
  if (rawThread === undefined) thread_id = undefined
  else if (rawThread === '' || rawThread === '0' || rawThread === 'null') thread_id = null
  else thread_id = Number(rawThread)
  const limit = args.limit != null ? Number(args.limit) : 10
  const before_message_id = args.before_message_id != null ? Number(args.before_message_id) : undefined

  const rows = queryHistory({ chat_id, thread_id, limit, before_message_id })
  const summary = rows
    .map(r => {
      const who = r.role === 'user' ? r.user ?? 'user' : 'assistant'
      // Local am/pm wall-clock (NOT UTC ISO) — this buffer is read straight
      // into the model's context via get_recent_messages, so every timestamp
      // it shows must be local to avoid competing with the local-time hint.
      const time = fmtLocalStamp(r.ts * 1000, resolveEnvTimezone())
      const attach = r.attachment_kind ? ` [${r.attachment_kind}]` : ''
      // Match server.ts get_recent_messages format exactly — both code paths
      // serve the same MCP tool, so the agent's parsing must not depend on
      // which entry point handled the call. See issue #119 for replyCtx;
      // reaction tag added in #297 with the server.ts format as canonical.
      const replyCtx = r.reply_to_message_id != null
        ? ` ↪️#${r.reply_to_message_id}${r.reply_to_text ? `:"${r.reply_to_text.slice(0, 60)}${r.reply_to_text.length > 60 ? '…' : ''}"` : ''}`
        : ''
      const reactionTag = r.user_reaction ? ` [reaction: ${r.user_reaction}]` : ''
      return `[${time}] ${who}${attach}${replyCtx}: ${r.text}${reactionTag}`
    })
    .join('\n')
  return {
    content: [
      { type: 'text', text: summary || '(no recent messages)' },
      { type: 'text', text: JSON.stringify({ chat_id, thread_id: thread_id ?? null, count: rows.length, messages: rows }, null, 2) },
    ],
  }
}

// ─── Session event handling ───────────────────────────────────────────────

function resetOrphanedReplyTimeout(): void {
  const turn = currentTurn
  if (turn?.orphanedReplyTimeoutId != null) {
    clearTimeout(turn.orphanedReplyTimeoutId)
    turn.orphanedReplyTimeoutId = null
  }
  if (turn == null) return
  if (shouldArmOrphanedReplyTimeout({
    currentSessionChatId: turn.sessionChatId,
    capturedTextCount: turn.capturedText.length,
    replyCalled: turn.replyCalled,
    // #1122/#1126: the pinned card is retired and `progressDriver` is
    // permanently null, so this suppression signal is always false. Kept as a
    // literal (the shouldArm* predicate still accepts the flag) rather than
    // reading the dead driver.
    progressCardActive: false,
  })) {
    turn.orphanedReplyTimeoutId = setTimeout(() => {
      // The timer fires asynchronously; re-read currentTurn so we
      // don't operate on a captured-but-superseded turn. If a new
      // turn (or no turn) is in flight, the original turn's backstop
      // is no longer ours to fire.
      const t = currentTurn
      if (t == null || t !== turn) return
      t.orphanedReplyTimeoutId = null
      if (shouldArmOrphanedReplyTimeout({
        currentSessionChatId: t.sessionChatId,
        capturedTextCount: t.capturedText.length,
        replyCalled: t.replyCalled,
        // #1122/#1126: retired card / null driver — always false (see above).
        progressCardActive: false,
      })) {
        // Feed-survival guard: re-arm the fuse while the turn is
        // legitimately working — an in-flight tool, a detached background
        // process (Bash run_in_background), or a human-wait tool (ask_user).
        // This extends the original "isMidToolCall" guard to cover the
        // detached-work cases that empty inFlight prematurely.
        //
        // Cap logic:
        //  • Foreground tools / detached background work: bound by
        //    ORPHANED_REPLY_MAX_REARMS (20 × 30 s = 10 min). A genuinely
        //    hung tool still surfaces after the cap.
        //  • Human-wait tools (ask_user): NEVER forcibly backstop while
        //    ask_user is open for this chat — the human simply hasn't
        //    tapped yet. We keep re-arming unconditionally until the prompt
        //    resolves (TTL or tap) and inFlight empties.
        const turnKey = statusKey(t.sessionChatId, t.sessionThreadId)
        const working = isLegitimatelyWorking(turnKey)
        const humanWaiting = (() => {
          for (const entry of pendingAskUser.values()) {
            if (entry.chatId === t.sessionChatId) return true
          }
          return false
        })()
        // Route the rearm decision through the per-turn LivenessTracker. It
        // rearms when working OR recently-streaming (thinking-pause survival)
        // OR human-waiting; working/recently-streaming rearms count against
        // ORPHANED_REPLY_MAX_REARMS while human-wait rearms stay uncapped.
        const now = Date.now()
        const recentlyStreaming = t.liveness.recentlyStreaming(now, ORPHANED_REPLY_STREAM_WINDOW_MS)
        const decision = t.liveness.decideOnExpiry({
          working,
          humanWaiting,
          now,
          windowMs: ORPHANED_REPLY_STREAM_WINDOW_MS,
          maxRearms: ORPHANED_REPLY_MAX_REARMS,
        })
        if (decision.rearm) {
          process.stderr.write(
            `telegram gateway: orphaned-reply fuse expired — re-arming` +
            ` (rearm ${t.liveness.orphanedReplyRearmCount}/${ORPHANED_REPLY_MAX_REARMS},` +
            ` in_flight=${toolFlightTracker.inFlightCount()},` +
            ` human_wait=${humanWaiting},` +
            ` recently_streaming=${recentlyStreaming},` +
            ` bg_work=${pendingProgress.hasPendingAsyncDispatch(turnKey)})\n`,
          )
          resetOrphanedReplyTimeout()
          return
        }
        if (decision.countsAgainstCap) {
          process.stderr.write(
            `telegram gateway: orphaned-reply rearm cap reached (${ORPHANED_REPLY_MAX_REARMS}) — forcing backstop despite working state\n`,
          )
        }
        process.stderr.write(
          `telegram gateway: orphaned-reply timeout (${ORPHANED_REPLY_TIMEOUT_MS}ms) — forcing backstop\n`,
        )
        handleSessionEvent({ kind: 'turn_end', durationMs: -1 })
      }
    }, ORPHANED_REPLY_TIMEOUT_MS)
  }
}

/**
 * PR A — DETERMINISTIC answer-ready quiescence flush controller.
 *
 * The orchestration (arm / debounce / rollover-guard / fire-time re-verify /
 * stage-don't-send / disarm) lives in the extracted, unit-tested
 * `AnswerReadyFlushController` (answer-ready-flush.ts) — the gateway only
 * supplies the thin deps below and calls `.reset()` / `.clear(turn)`.
 *
 * - `reset()` (from `case 'text'`): (re)arm iff the turn has a genuine composed
 *   terminal answer (the SAME `decideTurnFlush` classifier the turn-flush branch
 *   uses) AND is quiescent. Each text chunk re-arms → the debounce.
 * - `clear(turn)` (from tool activity + `endCurrentTurnAtomic`): the DISARM.
 * - on fire: re-pin `currentTurn === turn`, re-verify quiescence, then STAGE the
 *   answer on the still-live turn (`stageWindowMs` — see ANSWER_STAGE_MS) and
 *   promote only when the completion window closes with no reply, dispatching
 *   the positive `answer-ready-quiescence` synthetic turn_end through the
 *   IDENTICAL turn-flush send path. A reply landing in the window discards the
 *   stage (msgs 25843/25844); a real turn_end delivers via the turn-flush branch.
 *
 * Exactly-once: the synthetic turn_end's `endCurrentTurnAtomic` nulls the atom,
 * so a later REAL turn_end (or the orphaned backstop) short-circuits at its
 * `turn != null` guard; `endCurrentTurnAtomic` also calls `.clear(turn)` so a
 * real turn_end that lands FIRST cancels a pending flush/stage.
 *
 * The `answer-ready-quiescence` reason bypasses the `durationMs===-1`
 * recently-streaming SUPPRESSION guard: quiescence IS the positive "streaming
 * has settled" signal, the opposite of the hung-turn backstop that guard covers.
 */
const answerReadyFlush = new AnswerReadyFlushController<CurrentTurn>({
  getCurrentTurn: () => currentTurn,
  getArmInput: (turn) => ({
    flush: {
      chatId: turn.sessionChatId,
      replyCalled: turn.replyCalled,
      capturedText: turn.capturedText,
      capturedBlockMeta: turn.capturedBlockMeta,
      flushEnabled: TURN_FLUSH_SAFETY_ENABLED,
    },
    inFlightToolCount: toolFlightTracker.inFlightCount(),
    hasPendingAsyncDispatch: pendingProgress.hasPendingAsyncDispatch(
      statusKey(turn.sessionChatId, turn.sessionThreadId),
    ),
    flushWindowMs: ANSWER_READY_FLUSH_MS,
  }),
  getTimerHandle: (turn) => turn.answerReadyFlushTimeoutId,
  setTimerHandle: (turn, handle) => {
    turn.answerReadyFlushTimeoutId = handle
  },
  onFlush: () =>
    handleSessionEvent({ kind: 'turn_end', durationMs: -1, reason: 'answer-ready-quiescence' }),
  stageWindowMs: resolveAnswerStageMs(process.env), // stage-don't-send — see ANSWER_STAGE_MS
  log: (msg) => process.stderr.write(`telegram gateway: ${msg}\n`),
})

/** PR A — disarm the answer-ready flush timer for a turn (thin adapter). */
function clearAnswerReadyFlushTimeout(turn: CurrentTurn | null): void {
  answerReadyFlush.clear(turn)
}

/** PR A — (re)arm the answer-ready flush timer for the current turn (debounce). */
function resetAnswerReadyFlushTimeout(): void {
  answerReadyFlush.reset()
}

