/** Accumulation cap for a foreground sub-agent's nested narrative lines.
 *  Slightly larger than NESTED_MAX_LINES so the render's "↳ +N earlier…"
 *  header is meaningful without growing unbounded on a long sub-agent. */
const FOREGROUND_SUBAGENT_ACCUM_MAX = 12



















// Enqueue-time early-open timers, keyed by status-key. One per in-flight turn;
// cleared at turn-end (`stopEarlyLivenessOpen`) so a leaked timer can never fire
// against a successor turn. `unref()` so it never holds the process alive.
const earlyLivenessOpenTimers = new Map<string, ReturnType<typeof setTimeout>>()






if (isGatewayMain && !STATIC && FEED_HEARTBEAT_ENABLED) {
  setInterval(feedHeartbeatTick, FEED_HEARTBEAT_TICK_MS).unref()
}



// ─── Sub-agent handback dead-air pre-turn signal ─────────────────────────────
// Closes the gap between a background sub-agent's handback being RELEASED for
// delivery (the buffer drain) and the parent turn that consumes it minting +
// rendering its first tool/narration. On release we emit a `typing…` loop + a
// "reading the worker's results…" card; the imminent turn ADOPTS that exact
// card (by inbound identity) so it's one continuous card lifecycle finalized by
// the turn's normal `clearActivitySummary`, never a second card. See
// handback-preturn-signal.ts for the design + the red-team holes each lever
// closes. Kill switch: SWITCHROOM_HANDBACK_PRETURN=0.
const HANDBACK_PRETURN_ENABLED = !STATIC && process.env.SWITCHROOM_HANDBACK_PRETURN !== '0'
const HANDBACK_PRETURN_HTML = '🤝 Reading the worker’s results…'

async function openHandbackPreTurnCard(
  chatId: string,
  threadId: number | null,
): Promise<number | null> {
  if (STATIC) return null
  try {
    const sent = await robustApiCall(
      // allow-raw-bot-api: sendRichMessage routed through robustApiCall (not in the THREAD_NOT_FOUND blast pattern)
      () =>
        bot.api.sendRichMessage(chatId, richMessage(HANDBACK_PRETURN_HTML), {
          ...(threadId != null ? { message_thread_id: threadId } : {}),
          disable_notification: true,
        }),
      {
        chat_id: chatId,
        ...(threadId != null ? { threadId } : {}),
        verb: 'handback-preturn.send',
      },
    )
    return sent?.message_id ?? null
  } catch (err) {
    process.stderr.write(
      `telegram gateway: handback pre-turn card send failed: ${(err as Error).message}\n`,
    )
    return null
  }
}

// Deterministic recovery for a genuinely-orphaned handback: delete the frozen
// pre-turn card, re-inject the handback through the pending-inbound buffer, and
// past the retry cap emit fleet-health telemetry — never an operator-facing
// "needs a nudge" card. See handback-orphan-recovery.ts.
const handbackOrphanRecovery = createHandbackOrphanRecovery({
  deleteMessage: (chatId, messageId, threadId) =>
    robustApiCall(() => bot.api.deleteMessage(chatId, messageId), {
      chat_id: chatId,
      ...(threadId != null ? { threadId } : {}),
      verb: 'handback-preturn.orphan-delete',
    }),
  pushInbound: (inbound) =>
    pendingInboundBuffer.push(process.env.SWITCHROOM_AGENT_NAME ?? '', inbound),
})

const handbackPreturnSignal = createHandbackPreturnSignal({
  chatKey: (chatId, threadId) => chatKey(chatId, threadId) as string,
  deriveTurnId: (chatId, threadId, messageId) => deriveTurnId(chatId, threadId, messageId),
  startTypingLoop: (chatId, threadId) => startTurnTypingLoop(chatId, threadId),
  stopTypingLoop: (chatId, threadId) => stopTurnTypingLoop(chatId, threadId),
  openCard: openHandbackPreTurnCard,
  deleteCard: handbackOrphanRecovery.deleteCard,
  reinjectHandback: handbackOrphanRecovery.reinjectHandback,
  escalateOrphan: handbackOrphanRecovery.escalateOrphan,
  writeCardRecord: (record) => {
    if (!activityCardPersistEnabled) return
    writeActivityCardRecord(ACTIVITY_CARD_STORE_PATH, activityCardStoreFs, record)
  },
  clearCardRecord: (turnKey, activityMessageId) => {
    if (!activityCardPersistEnabled) return
    clearActivityCardRecord(ACTIVITY_CARD_STORE_PATH, activityCardStoreFs, turnKey, activityMessageId)
  },
  // Lever 5: never paint a pre-turn card beneath a turn that already delivered
  // its answer / ended by the time the debounce fires.
  isTurnSettled: (key) => {
    const live = currentTurnMap.get(key)
    return live != null && (live.finalAnswerDelivered || live.endedAt != null)
  },
  // #3544: a turn that is still LIVE on this topic owns the typing loop for the
  // key — the seam's age-based orphan reap must not stop it out from under the
  // composing turn (its canonical turn-end is the stop-owner). Deliberately NOT
  // `isTurnSettled`'s condition: a turn that already delivered its answer is
  // "settled" for card purposes but may still be mid-turn, and `endedAt != null`
  // is the only signal that the turn-end stop has run.
  hasLiveTurn: (key) => {
    const live = currentTurnMap.get(key)
    if (live == null || live.endedAt != null) return false
    // Under the emission-authority kill-switch OFF (the default) `get(key)`
    // returns the most-recent-set SINGLETON regardless of key — so verify the
    // live turn actually belongs to THIS topic before suppressing the stop.
    // Without this check a live turn on chat B would keep a stale chat-A pre-turn
    // typing loop running forever (a leaked interval — strictly worse than the
    // dark-indicator bug). Flag-ON is already per-key; the check is a no-op there.
    return statusKey(live.sessionChatId, live.sessionThreadId) === key
  },
  // Queue-state gate for the orphan reap (see the signal's `isClaudeBusy` doc):
  // a handback queued behind an in-flight turn is not orphaned.
  isClaudeBusy: () => isMachineInTurn(),
  // 2026-08-02 invisible-consumption gate — see session-consume-signal.ts.
  sessionActivitySince: (sinceTs) => sessionConsumeSignal.activitySince(sinceTs),
})

/**
 * #2849 hindsight Phase 4 — sparse chat-legible memory.
 *
 * Fire-and-forget: if this main-agent tool call is a material memory
 * operation (create_directive → 📌 remembered; invalidate/demote → ✂️
 * forgot), send ONE terse real message into the turn's originating
 * chat/topic. Routes on `turn.sessionChatId` / `turn.sessionThreadId`
 * (the originating topic, never the operator DM), through
 * `retryWithThreadFallback` so a deleted forum topic can't crash the
 * gateway. Non-material tool calls return silently — no line on ordinary
 * recall or routine consolidation. Kill-switch: SWITCHROOM_MEMORY_LEGIBILITY=0.
 */
/**
 * Fix 1.3 (#2903): a memory-legibility line must render only AFTER the write
 * is confirmed. We stage the detected event on `tool_use` (keyed by
 * `toolUseId`) and flush the 📌/✂️ line on the matching SUCCESSFUL
 * `tool_result` — a failed write (engine down / isError envelope) drops the
 * staged line, so chat never claims "remembered" for a write that errored.
 *
 * A hindsight `tools/call` returns HTTP 200 + `is_error:true` on failure, and
 * Claude Code surfaces that on the transcript `tool_result` block, which
 * `session-tail` projects onto `ev.isError`. That is the confirmed-success
 * signal we gate on.
 */
interface MemoryLegibilityRoute {
  chatId: string
  threadId: number | undefined
  toolName: string
}
const memoryLegibilityStager = new MemoryLegibilityStager<MemoryLegibilityRoute>()

function sendMemoryLegibilityLine(
  event: NonNullable<ReturnType<typeof detectMemoryLegibilityEvent>>,
  chatId: string,
  threadId: number | undefined,
): void {
  const line = renderMemoryLegibilityLine(event)
  void retryWithThreadFallback(
    robustApiCall,
    (tid) =>
      bot.api.sendMessage(chatId, line, {
        parse_mode: 'HTML',
        // Status surface, not the user's answer — never ping the device.
        disable_notification: true,
        ...(tid != null ? { message_thread_id: tid } : {}),
      }),
    { threadId, chat_id: chatId, verb: 'memory-legibility.sendMessage' },
  ).catch((err) => {
    process.stderr.write(
      `telegram gateway: memory-legibility send failed: ${
        err instanceof Error ? err.message : String(err)
      }\n`,
    )
  })
}

/** Stage a material memory event observed on `tool_use`. Nothing is sent yet;
 *  the line is flushed by `confirmMemoryLegibility` on a successful result. */
function surfaceMemoryLegibility(
  turn: CurrentTurn,
  toolName: string,
  toolUseId: string | null | undefined,
  input: Record<string, unknown> | undefined,
): void {
  if (!MEMORY_LEGIBILITY_ENABLED) return
  const event = detectMemoryLegibilityEvent(toolName, input)
  if (event == null) return
  const chatId = turn.sessionChatId
  const threadId = turn.sessionThreadId
  // Without a toolUseId we cannot correlate a result to confirm success. This
  // effectively never happens (Claude Code always stamps a tool_use id), so
  // rather than claim an unconfirmed "remembered", we skip and log.
  if (toolUseId == null || toolUseId.length === 0) {
    process.stderr.write(
      `telegram gateway: memory-legibility ${event.kind} SKIPPED (no toolUseId) ` +
        `chat=${chatId} tool=${toolName}\n`,
    )
    return
  }
  memoryLegibilityStager.stage(toolUseId, event, { chatId, threadId, toolName })
  process.stderr.write(
    `telegram gateway: memory-legibility ${event.kind} STAGED chat=${chatId} ` +
      `thread=${threadId ?? '-'} tool=${toolName} id=${toolUseId}\n`,
  )
}

/** Flush (or drop) a staged memory-legibility line on its matching
 *  `tool_result`. Sends only on confirmed success; a failed write is dropped
 *  so chat never claims "remembered" for a write that errored. */
function confirmMemoryLegibility(
  toolUseId: string | null | undefined,
  isError: boolean | undefined,
): void {
  const resolved = memoryLegibilityStager.confirm(toolUseId, isError)
  if (resolved == null) {
    if (isError === true) {
      process.stderr.write(
        `telegram gateway: memory-legibility DROPPED (write errored) id=${toolUseId}\n`,
      )
    }
    return
  }
  const { event, meta } = resolved
  process.stderr.write(
    `telegram gateway: memory-legibility ${event.kind} CONFIRMED chat=${meta.chatId} ` +
      `thread=${meta.threadId ?? '-'} tool=${meta.toolName} id=${toolUseId}\n`,
  )
  sendMemoryLegibilityLine(event, meta.chatId, meta.threadId)
}

/**
 * #2849 hindsight Phase 4 (follow-up) — consolidation-driven legibility.
 *
 * The gateway-side sink for a verified `hindsight` / `consolidation.completed`
 * webhook. `recordWebhookEvent` has already logged the event for audit and
 * resolved the agent's channel target; this decides whether it is MATERIAL
 * (a genuine store/correct — else nothing), rate-limits it hard, and — only
 * if it clears both gates — sends ONE terse "🧠 updated what I know about Y"
 * real message with notifications suppressed. Never injects a model turn.
 * OPT-IN via SWITCHROOM_CONSOLIDATION_LEGIBILITY.
 */
function surfaceConsolidationLegibility(
  rec: WebhookGatewayRecord,
  target: { chatId: string; threadId?: number },
): void {
  if (!CONSOLIDATION_LEGIBILITY_ENABLED) return
  const event = detectConsolidationEvent(rec.payload)
  if (event == null) return // routine no-op consolidation — surface nothing
  const agent = rec.agent
  // Rate-limiter clock MUST be wall-clock (Date.now()), never rec.ts: rec.ts
  // can be derived from the (attacker-influenceable) webhook payload, and a
  // spoofed far-past / far-future timestamp would poison the per-agent
  // min-interval gate — either permanently opening it (stale ts always older
  // than the window) or jamming it shut. The limiter only cares about "how
  // long since the last surface on THIS gateway", which is a local wall-clock
  // question.
  if (!consolidationRateLimiter.allow(agent, consolidationSignature(event), Date.now())) {
    process.stderr.write(
      `telegram gateway: consolidation-legibility ${event.kind} rate-limited ` +
        `agent=${agent} topic='${event.topic}'\n`,
    )
    return
  }
  const chatId = target.chatId
  const threadId = target.threadId
  const line = renderConsolidationLine(event)
  process.stderr.write(
    `telegram gateway: consolidation-legibility ${event.kind} chat=${chatId} ` +
      `thread=${threadId ?? '-'} agent=${agent}\n`,
  )
  void retryWithThreadFallback(
    robustApiCall,
    (tid) =>
      bot.api.sendMessage(chatId, line, {
        parse_mode: 'HTML',
        // Status surface, not the user's answer — never ping the device.
        disable_notification: true,
        ...(tid != null ? { message_thread_id: tid } : {}),
      }),
    { threadId, chat_id: chatId, verb: 'consolidation-legibility.sendMessage' },
  ).catch((err) => {
    process.stderr.write(
      `telegram gateway: consolidation-legibility send failed: ${
        err instanceof Error ? err.message : String(err)
      }\n`,
    )
  })
}

/** Blocked-paid-dependency alerting — policy in `mcp-credential-failure.ts`,
 *  seam in `gateway/mcp-failure-hook.ts`. Tees the SAME
 *  `emitGatewayOperatorEvent` path so there is ONE operator-alert mechanism. */
const noteMcpDependencyFailure = createMcpFailureHook({ agent: AGENT_NAME, emit: emitGatewayOperatorEvent })

function handleSessionEvent(ev: SessionEvent): void {
  noteMcpDependencyFailure(ev)
  handleSessionEventCore(gatewayStreamRenderDeps(), ev)
}

