// ─── PTY partial handler ─────────────────────────────────────────────────
function handlePtyPartial(text: string): void {
  // #2044 outbound secret scrub. The PTY-tail partial is the assistant's
  // reply text extracted from Claude Code's TUI as it renders — an agent
  // that echoes a secret shows it here (in the live draft-preview stream)
  // BEFORE the reply tool ever fires, and this path forwards the text
  // straight to Telegram with no other redaction. Mask at the gateway
  // boundary through the SAME reply-path redactor so the draft stream, its
  // dedup key, and lastPtyPreviewByChat all compare redacted-against-
  // redacted — the identical in-place-mutation invariant the answer stream
  // relies on. Idempotent: replaying a buffered (already-masked) partial
  // re-masks to itself.
  text = redactOutboundText(text, 'pty_preview')
  // #1067: build the PtyHandlerState from a snapshot of currentTurn.
  // The pty-partial-handler module keeps its own state-shape contract
  // (currentSessionChatId / currentSessionThreadId) because it's
  // independently tested; we adapt the names at this boundary.
  const turn = currentTurn
  const state: PtyHandlerState = {
    currentSessionChatId: turn?.sessionChatId ?? null,
    currentSessionThreadId: turn?.sessionThreadId,
    pendingPtyPartial: pendingPtyPartial != null ? { text: pendingPtyPartial } : null,
    activeDraftStreams,
    suppressPtyPreview,
    lastPtyPreviewByChat,
  }
  handlePtyPartialPure(text, state, {
    // grammy's Bot has a wider api shape than the local StreamBotApi
    // interface; runtime-compatible. Cast through never.
    bot: bot as never,
    retry: robustApiCall,
    logEvent: logStreamingEvent,
    onStreamSend: (chatId, messageId, charCount) => {
      logOutbound('pty_preview', chatId, messageId, charCount, 'initial_send')
      logStreamingEvent({ kind: 'draft_send', chatId, messageId, charCount })
    },
    onStreamEdit: (chatId, messageId, charCount) =>
      logStreamingEvent({ kind: 'draft_edit', chatId, messageId, charCount, sameAsLast: false }),
    onFirstPartial: (chatId, charCount) => {
      process.stderr.write(`telegram gateway: pty first partial — chat=${chatId} chars=${charCount}\n`)
    },
    writeError: (line) => process.stderr.write(line),
  })
  pendingPtyPartial = state.pendingPtyPartial?.text ?? null
}

function handlePtyActivity(text: string): void {
  // #2044 outbound secret scrub. PTY-activity is agent-derived free text
  // forwarded to Telegram via handleStreamReply — same leak class as the
  // draft preview above. Redact through the reply-path redactor before it
  // streams. (This handler is currently unwired in the gateway — the live
  // PTY path is handlePtyPartial — but the mask is kept here so the fix is
  // durable if the activity lane is ever re-armed.)
  text = redactOutboundText(text, 'pty_activity')
  // #1067: snapshot at entry. handleStreamReply is async and runs in
  // the background via void; the closure already captures `chatId` /
  // `threadId` locals, so the supersession is correctly scoped.
  const turn = currentTurn
  if (turn == null) return
  if (shouldSuppressToolActivity(text)) return
  const chatId = turn.sessionChatId
  const threadId = turn.sessionThreadId
  const access = loadAccess()
  void handleStreamReply(
    {
      chat_id: chatId,
      text,
      done: false,
      message_thread_id: threadId != null ? String(threadId) : undefined,
      format: 'text',
      lane: 'activity',
    },
    { activeDraftStreams },
    {
      // See StreamBotApi cast comment above (line ~2522 area).
      bot: bot as never,
      retry: robustApiCall,
      repairEscapedWhitespace,
      assertAllowedChat,
      resolveThreadId,
      disableLinkPreview: access.disableLinkPreview !== false,
      defaultFormat: 'text',
      logStreamingEvent,
      historyEnabled: false,
      recordOutbound,
      writeError: (line) => process.stderr.write(line),
      // PR B note: this is the PTY-activity stream, NOT the LLM
      // stream_reply path. PTY drives many tiny partials as a TUI
      // re-renders; 600 ms is a deliberate compromise tuned for the
      // PTY flicker characteristics, not LLM token cadence. The
      // transport-aware defaults (300/1000) deliberately do NOT
      // apply here. If you change this, also check
      // telegram-plugin/pty-partial-handler.ts:159 which has the
      // same value for the same reason.
      throttleMs: 600,
    },
  ).catch((err) => {
    process.stderr.write(`telegram gateway: pty activity stream failed: ${(err as Error).message}\n`)
  })
}

// ─── Gate / inbound routing ───────────────────────────────────────────────

/**
 * Reasons the gate may drop an inbound. Surfaced through the rate-limited
 * `logGateDeny` so operators can debug allowlist / pairing misconfigs
 * without crawling the telegram-plugin source. Found while tracking down
 * a fuzz failure on 2026-05-13 where 23 inbounds were silently dropped —
 * a single line in the gateway log would have replaced ~30 min of
 * investigation.
 */
type GateDropReason =
  | 'dm_policy_disabled'
  | 'no_sender'
  | 'allowlist_no_match'
  | 'pairing_resend_exhausted'
  | 'pairing_capacity'
  | 'group_unknown'
  | 'group_allowFrom_no_match'
  | 'group_mention_required'
  | 'unknown_chat_type'

type GateResult =
  | { action: 'deliver'; access: Access }
  | { action: 'drop'; reason: GateDropReason }
  | { action: 'pair'; code: string; isResend: boolean }

/**
 * Per-(chat_id, senderId, reason) suppression so a chatty unauthorized
 * sender doesn't flood the gateway log. First hit always logs; repeats
 * within {@link GATE_DENY_LOG_WINDOW_MS} are silently swallowed.
 */
const gateDenyLastLoggedAt = new Map<string, number>()
const GATE_DENY_LOG_WINDOW_MS = 60_000

function logGateDeny(ctx: Context, reason: GateDropReason): void {
  // Defence in depth: never throw from the log helper. A misshapen ctx
  // (e.g. partial test fixture) would otherwise sink the inbound path.
  try {
    // `group_mention_required` is routine traffic in any active group
    // chat — every non-mentioning message from an allowlisted member
    // hits this reason. With per-(chat,sender) rate-limiting that's
    // still up to N log lines per minute per active group, which is
    // noise rather than signal: `requireMention=true` is doing exactly
    // what it's configured to do. Gate behind a debug env var so
    // operators can opt into it when they're explicitly debugging a
    // group-mention configuration. The other 8 reasons are all
    // genuine misconfig / unauthorized signals and stay loud.
    if (reason === 'group_mention_required' && process.env.SWITCHROOM_GATEWAY_DEBUG_DENY !== '1') {
      return
    }
    const chatId = ctx.chat?.id != null ? String(ctx.chat.id) : '?'
    const senderId = ctx.from?.id != null ? String(ctx.from.id) : '?'
    const chatType = ctx.chat?.type ?? '?'
    const key = `${chatId}:${senderId}:${reason}`
    const now = Date.now()
    const prev = gateDenyLastLoggedAt.get(key)
    if (prev != null && now - prev < GATE_DENY_LOG_WINDOW_MS) return
    gateDenyLastLoggedAt.set(key, now)
    process.stderr.write(
      `telegram gateway: inbound dropped reason=${reason} chat_id=${chatId} ` +
      `chat_type=${chatType} sender_id=${senderId}\n`,
    )
  } catch { /* swallow — best-effort log */ }
}

/**
 * Wrap `decideDmCommandGate` (pure helper in
 * `../dm-command-gate.ts`) with grammy ctx + access.json side effects.
 * Returns null (silent drop) on every reject path. See
 * dm-command-gate.ts for the upstream backport (#894) rationale.
 */
function dmCommandGate(ctx: Context): { access: Access; senderId: string } | null {
  const access = loadAccess()
  const pruned = pruneExpired(access)
  if (pruned) saveAccess(access)
  const decision = decideDmCommandGate({
    chatType: ctx.chat?.type,
    senderId: ctx.from?.id != null ? String(ctx.from.id) : undefined,
    dmPolicy: access.dmPolicy,
    allowFrom: access.allowFrom,
  })
  if (!decision.allow) return null
  return { access, senderId: decision.senderId }
}

function gate(ctx: Context): GateResult {
  const access = loadAccess()
  const pruned = pruneExpired(access)
  if (pruned) saveAccess(access)
  if (access.dmPolicy === 'disabled') return { action: 'drop', reason: 'dm_policy_disabled' }
  const from = ctx.from
  if (!from) return { action: 'drop', reason: 'no_sender' }
  const senderId = String(from.id)
  const chatType = ctx.chat?.type

  if (chatType === 'private') {
    if (access.allowFrom.includes(senderId)) return { action: 'deliver', access }
    if (access.dmPolicy === 'allowlist') return { action: 'drop', reason: 'allowlist_no_match' }

    for (const [code, p] of Object.entries(access.pending)) {
      if (p.senderId === senderId) {
        if ((p.replies ?? 1) >= 2) return { action: 'drop', reason: 'pairing_resend_exhausted' }
        p.replies = (p.replies ?? 1) + 1
        saveAccess(access)
        return { action: 'pair', code, isResend: true }
      }
    }
    if (Object.keys(access.pending).length >= 3) return { action: 'drop', reason: 'pairing_capacity' }
    const code = randomBytes(3).toString('hex')
    const now = Date.now()
    access.pending[code] = {
      senderId,
      chatId: String(ctx.chat!.id),
      createdAt: now,
      expiresAt: now + 60 * 60 * 1000,
      replies: 1,
    }
    saveAccess(access)
    return { action: 'pair', code, isResend: false }
  }

  if (chatType === 'group' || chatType === 'supergroup') {
    const groupId = String(ctx.chat!.id)
    const policy = access.groups[groupId]
    if (!policy) return { action: 'drop', reason: 'group_unknown' }
    const groupAllowFrom = policy.allowFrom ?? []
    const requireMention = policy.requireMention ?? true
    if (groupAllowFrom.length > 0 && !groupAllowFrom.includes(senderId)) {
      return { action: 'drop', reason: 'group_allowFrom_no_match' }
    }
    if (requireMention && !isMentioned(ctx, access.mentionPatterns)) {
      return { action: 'drop', reason: 'group_mention_required' }
    }
    return { action: 'deliver', access }
  }

  return { action: 'drop', reason: 'unknown_chat_type' }
}

function isMentioned(ctx: Context, extraPatterns?: string[]): boolean {
  const entities = ctx.message?.entities ?? ctx.message?.caption_entities ?? []
  const text = ctx.message?.text ?? ctx.message?.caption ?? ''
  for (const e of entities) {
    if (e.type === 'mention') {
      const mentioned = text.slice(e.offset, e.offset + e.length)
      if (mentioned.toLowerCase() === `@${botUsername}`.toLowerCase()) return true
    }
    if (e.type === 'text_mention' && e.user?.is_bot && e.user.username === botUsername) return true
  }
  if (ctx.message?.reply_to_message?.from?.username === botUsername) return true
  for (const pat of extraPatterns ?? []) {
    try { if (new RegExp(pat, 'i').test(text)) return true } catch {}
  }
  return false
}

function isAuthorizedSender(ctx: Context): boolean {
  const from = ctx.from
  if (!from) return false
  const senderId = String(from.id)
  const access = loadAccess()
  if (ctx.chat?.type === 'private') return access.allowFrom.includes(senderId)
  if (ctx.chat?.type === 'group' || ctx.chat?.type === 'supergroup') {
    const groupId = String(ctx.chat.id)
    const policy = access.groups[groupId]
    if (!policy) return false
    const groupAllowFrom = policy.allowFrom ?? []
    if (groupAllowFrom.length > 0 && !groupAllowFrom.includes(senderId)) return false
    return true
  }
  return false
}

// Adversarial-review F4 — a group configured with an EMPTY `allowFrom`
// authorizes every member (isAuthorizedSender returns true for any sender in
// that group). That's an intentional "whole-group" access mode, but it means
// `/usage` would expose per-account email labels + quota headroom to every
// member of a broadly-shared group. Harden minimally: for the quota-bearing
// card in a non-private chat, mask account labels (reusing the demo-mask
// machinery) UNLESS the group pinned a non-empty `allowFrom` — i.e. an
// explicit operator-curated member list is treated as trusted enough to see
// the real labels. Private (operator DM) chats are never masked. This changes
// only what /usage REVEALS, not who may run it. The pure decision lives in
// ./usage-mask.ts (shouldMaskUsageLabels) so it is unit-testable without
// importing the whole gateway module.
function shouldMaskAccountLabels(ctx: Context): boolean {
  const groupAllowFrom =
    ctx.chat?.type === 'group' || ctx.chat?.type === 'supergroup'
      ? loadAccess().groups[String(ctx.chat.id)]?.allowFrom
      : undefined
  return shouldMaskUsageLabels(ctx.chat?.type, groupAllowFrom)
}

// safeName moved to ./media-message-handlers.ts (switchroom#2996 P6 cluster A);
// imported above and shared with the attachment handlers still inline here.

// ─── Inbound message handling ─────────────────────────────────────────────

// ── PR-0 characterization-harness export seam (#2996 P7) ──────────────────
// `handleInboundCoalesced` / `handleInbound` are the inbound-routing
// extraction target (P7). The characterization harness in
// `tests/inbound-router-characterization.test.ts` drives them functionally
// with real intercept code executing, spying only at the Deps boundary
// (the delivery machine / dispatch / tmux / secret-detect modules). That
// requires (a) the two entrypoints be importable and (b) a minimal accessor
// onto the module-local turn/intercept state the harness must seed to reach
// each intercept branch. This is the ONE small production change PR-0 needs
// (design finding F1). Nothing here is referenced on the prod boot path.
export const __inboundRouterTestSeam = {
  // Turn-state stores (mid-turn steer classification + status-KPI reads).
  activeStatusReactions,
  activeTurnStartedAt,
  lastAgentOutputAt,
  // Intercept-precondition stores (seed to reach each gauntlet branch).
  pendingReauthFlows,
  pendingPermissions,
  secretStaging,
  vaultPassphraseCache,
  // ipcServer is only assigned on the prod boot path (isGatewayMain); under
  // a test import it is undefined, so the imperative deliver / permission-
  // verdict paths would deref undefined. Let the harness inject a fake.
  setIpcServer: (s: IpcServer): void => { ipcServer = s },
  // The coalesce window holds real setTimeout flush timers whose callback
  // fires `void handleInbound(...)`. Under a test import, an entry still
  // buffered when a test ends flushes DURING a later test and pollutes its
  // dispatch log (the #3359 CI flake: the "stop with attachment" entry's
  // deferred flush delivered mid-way through the FAIL-CLOSED test). Exposed
  // so the harness can `peek()` (assert content-path buffering) and
  // `reset()` (cancel stale timers) in beforeEach. Read/reset only — no
  // production behaviour change.
  inboundCoalescer,
  // ── P8 PR-A: turn-lifecycle WIRING handles (the parity oracle for PR-E). ──
  // The turn-end funnel + its idle stores + the two idle-only sweeps, exposed
  // read/drive-only so `turn-lifecycle-characterization.test.ts` can pin the
  // wiring (map purge, obligation close, buffer drain, no-reply timer arm,
  // pending-restart drain at turn-complete) BEFORE any of it moves to
  // `turn-end.ts` (PR-B) / the wiring modules (PR-C). No production behaviour
  // change — these are the same identifiers the deps builders will inject.
  // `setCurrentTurn` is the SANCTIONED keyed writer (PR-4e accessor), NOT a raw
  // `currentTurn =` setter — the harness registers a live turn through it so
  // the funnel's keyed-liveness guard sees it.
  setCurrentTurn,
  getCurrentTurn: (): CurrentTurn | null => currentTurn,
  // Test-teardown reset of the live-turn store (the disconnect/bridge-died
  // ghost-clear primitive; PR-E names it a `*-clear` no-op-effect reason). The
  // harness calls it in beforeEach so a live turn a prior case left set can't
  // leak into the next case's `currentTurn?.replyCalled` fallback read.
  clearAllCurrentTurns,
  endCurrentTurnAtomic,
  purgeReactionTracking,
  releaseTurnBufferGate,
  armNoReplyDrainTimer,
  // PR-E: the v2 dispatcher (always constructible; production callsites route
  // through it only under SWITCHROOM_TURN_END_FUNNEL_V2=1) + the captured flag,
  // so the harness can pin ghost-clear no-op effects and drive both branches.
  endTurn: (
    reason: TurnEndReason,
    args?: { turn?: CurrentTurn; opts?: { deferRecord?: boolean; deferObligationClose?: boolean }; key?: string; endingTurn?: CurrentTurn },
  ) => turnEndFunnel().endTurn(reason, args),
  TURN_END_FUNNEL_V2,
  statusKey,
  obligationLedger,
  pendingInboundBuffer,
  pendingRestarts,
  deliveryQueue,
  runDeliveryConfirmSweep,
  obligationSweep,
  activeReactionMsgIds,
}

export async function handleInboundCoalesced(
  ctx: Context,
  text: string,
  downloadImage: (() => Promise<string | undefined>) | undefined,
  attachment?: AttachmentMeta,
): Promise<void> {
  // `!`-prefix interrupt (#575) bypasses coalescing. If we let an
  // interrupt sit in the coalesce window, an earlier non-`!` message
  // arriving in the same window would prepend itself and the marker
  // would no longer be at position 0 — handleInbound's parser would
  // miss it and the user's interrupt would silently get merged into a
  // normal turn. Bypass to handleInbound directly so the marker
  // stays at the start of the text. Checked first so a `!`-prefixed
  // media caption still interrupts.
  if (parseInterruptMarker(text).isInterrupt) {
    return handleInbound(ctx, text, downloadImage, attachment)
  }

  // #3020: bare "stop" is a kill switch, same urgency as `!` — bypass the
  // coalesce window so it fires mid-turn instead of merging into a normal
  // turn (and so an earlier buffered message can't prepend itself and defeat
  // the exact-word parse in handleInbound). Pure text only: a photo/document
  // captioned "stop" is content for the agent (e.g. a stop sign to look at),
  // not a halt request — attachments flow through the normal pipeline.
  if (parseStopKeyword(text) && downloadImage == null && attachment == null) {
    return handleInbound(ctx, text, downloadImage, attachment)
  }

  const hasAttachment = downloadImage != null || attachment != null
  const maxAttachments = coalesceMaxAttachments()

  // Albums (media_group_id): coalesce only when the cap allows >1 attachment
  // (A2). At the default cap of 10 the parts share the coalesce key and fold
  // into one multi-attachment turn (the cap-overflow bypass below catches
  // parts past the cap). With the cap lowered to 1 each album part keeps its
  // own turn — the single-attachment merge can't carry sibling photos, so
  // bypassing avoids dropping them.
  if (hasAttachment && ctx.message?.media_group_id != null && maxAttachments <= 1) {
    return handleInbound(ctx, text, downloadImage, attachment)
  }

  const from = ctx.from
  if (!from) return

  // An attachment past the per-agent cap would be dropped by the capped merge.
  // Bypass it to its own turn so no media is silently lost. At the default
  // cap of 10 this fires on the 11th attachment; with the cap lowered to 1 it
  // fires on the SECOND, preserving A1 behaviour.
  if (hasAttachment) {
    const probeKey = inboundCoalesceKey(
      String(ctx.chat!.id),
      ctx.message?.message_thread_id,
      String(from.id),
    )
    if ((bufferedAttachmentKeys.get(probeKey) ?? 0) >= maxAttachments) {
      return handleInbound(ctx, text, downloadImage, attachment)
    }
  }

  // F2 fix (#553): fire 👀 reaction on RAW arrival, before the coalesce
  // wait blocks first paint. Pre-fix, the controller's setQueued() inside
  // handleInbound only ran AFTER the coalesce flush (default gapMs=1500),
  // so the user perceived ~1.5s of silence after their message landed.
  // The spec deadline is 800ms.
  //
  // The controller's later setQueued() in handleInbound still runs on
  // flush; Telegram dedupes setMessageReaction calls with the same
  // emoji, so the visible state is unchanged. The duplicate emit is
  // one extra API call per coalesced burst — trivial cost vs. the UX win.
  //
  // Eligibility:
  //   - PRIVATE chat only (group flow uses requireMention/allowFrom
  //     checks that need the full gate; pre-acking those risks reacting
  //     to messages we'd later drop).
  //   - Sender already in access.allowFrom (paired) — unpaired senders
  //     get the pairing-required reply via the full gate path.
  //   - No active turn for this (chat, thread) — mid-turn messages
  //     would otherwise flash 👀 over the current 🔥/🤔 state.
  //   - msgId present (always true for `bot.on('message:*')` paths but
  //     defensive against future routers that might call this without one).
  maybeEarlyAckReaction(ctx, from)
  // #2527 — if this lands mid-turn, the user is asking "what's happening?";
  // fire the liveness floor immediately (DM + supergroup alike).
  maybePokeFloorForMidTurnInbound(ctx, from)

  const key = inboundCoalesceKey(
    String(ctx.chat!.id),
    ctx.message?.message_thread_id,
    String(from.id),
  )
  const result = inboundCoalescer.enqueue(key, {
    text,
    ctx,
    downloadImage,
    attachment,
    // Parsed HERE (not in merge) because merge only sees the last ctx —
    // each buffered entry keeps its own forwarded-message origin.
    forwardOrigin: parseForwardOrigin(ctx.message?.forward_origin),
  })
  // Coalescing disabled (window <= 0): flush immediately, preserving any
  // media this message carried.
  if (result.bypass) return handleInbound(ctx, text, downloadImage, attachment)
  // Count the open window's attachments so any part past the cap (the 11th
  // at the default cap of 10, or the second when lowered to 1) bypasses
  // rather than overflows the capped merge (cleared in onFlush).
  if (hasAttachment) bufferedAttachmentKeys.set(key, (bufferedAttachmentKeys.get(key) ?? 0) + 1)
}

/**
 * Fire the 👀 status reaction immediately for paired DM users sending
 * a fresh-turn message. Returns silently for ineligible cases — the
 * caller proceeds either way; this is a UX optimisation, not a gate.
 *
 * Fire-and-forget: failures are swallowed since the controller's
 * setQueued() will retry the same emoji after the coalesce flush.
 */
function maybeEarlyAckReaction(ctx: Context, from: NonNullable<Context['from']>): void {
  const msgId = ctx.message?.message_id
  if (msgId == null) return
  const chatType = ctx.chat?.type
  // Intentionally DM-only (#2527 surface-parity note): pre-acking a GROUP
  // message risks reacting to one the full gate (requireMention / topic
  // scoping) would later DROP. The SUBSTANTIVE liveness parity a supergroup
  // needs — the mid-turn floor and the role-aware terminal reaction — is
  // surface-agnostic (keyed on statusKey + loop role, no chat-type branch),
  // so a forum topic gets identical never-silent guarantees without this
  // sub-second 👀 optimisation. See `maybePokeFloorForMidTurnInbound` for
  // the surface-agnostic "Status?" short-circuit.
  if (chatType !== 'private') return
  const chatId = String(ctx.chat!.id)
  const threadId = ctx.message?.is_topic_message ? ctx.message.message_thread_id : undefined
  if (activeTurnStartedAt.has(statusKey(chatId, threadId))) return
  const access = loadAccess()
  if (!access.allowFrom.includes(String(from.id))) return
  void sendReaction(chatId, msgId, '👀' as ReactionTypeEmoji['emoji']).catch(() => {})
  // #2527: log the early-ack fire so operators can see how often the
  // fast pre-coalesce DM path triggers vs. the controller path.
  logStreamingEvent({ kind: 'early_ack_reaction', chatId, messageId: msgId, emoji: '👀' })
  // #553 PR 3: also fire the native "typing…" indicator. Bridges the
  // visual gap between the early-ack 👀 reaction and the first real
  // model text. No fake content — Telegram clients render this natively
  // and it auto-expires after ~5s if not refreshed (the answer-lane
  // first edit will land long before then under the new defaults).
  // Through the shared emitter (#3084): a cold chat still lights up
  // instantly; a chat already pinged inside the floor doesn't pay twice.
  emitChatAction(chatId, null, 'typing')
}

/**
 * #2527 — "Status?" short-circuit. A message arriving DURING an active turn
 * (the user explicitly asking what's happening) fires the mid-turn liveness
 * floor immediately, bypassing the timer/working gates. Surface-agnostic:
 * works identically in a DM and a forum-supergroup topic (keyed on statusKey).
 * Idempotent per turn (the floor's fire-once latch) and kill-switch-gated.
 */
function maybePokeFloorForMidTurnInbound(ctx: Context, from: NonNullable<Context['from']>): void {
  const rawChatId = ctx.chat?.id
  if (rawChatId == null) return
  const chatId = String(rawChatId)
  const threadId = ctx.message?.is_topic_message ? ctx.message.message_thread_id : undefined
  const key = statusKey(chatId, threadId)
  // Only mid-turn: a turn must already be in flight for this (chat, thread).
  if (!activeTurnStartedAt.has(key)) return
  const access = loadAccess()
  if (!access.allowFrom.includes(String(from.id))) return
  silencePoke.pokeFloorNow(key, Date.now())
}

// Live collaborators for the extracted intercept gauntlet (switchroom#2996 P7).
// Bound once; every field is a live reference (never a value snapshot). `botApi`
// is a lazy accessor for `bot.api` (the grammY `bot` is assigned late on the
// prod boot path) so the moved raw call keeps riding the same
// `swallowingApiCall` retry wrapper it used inline, deref'd at call time.
// Admission-head collaborators (#2996 P7 PR-10): boot-fixed TOPIC_ID scoping
// value + the live gate/deny-logger references.
const inboundAdmissionDeps: InboundAdmissionDeps = {
  topicId: TOPIC_ID ?? null,
  gate,
  logGateDeny: logGateDeny as InboundAdmissionDeps['logGateDeny'],
}
const inboundInterceptorDeps: InboundInterceptorDeps = {
  pendingSessionCommand,
  turnInFlightForGate,
  sendReaction,
  executeHaltNow,
  swallowingApiCall,
  botApi: () => bot.api,
  log: line => process.stderr.write(line),
  loadAccess,
  toolFlightTracker,
  cancelInterruptedObligation,
  dispatchPermissionVerdict,
  resumeReactionAfterVerdict,
  pendingPermissions,
  postPermissionResumeMessage,
  pendingAuthAddFlows,
  looksLikeAuthCode,
  reauthInterceptTtlMs: REAUTH_INTERCEPT_TTL_MS,
  submitAccountAuthCode,
  addAccountViaBroker,
  cleanAuthAddScratchDir,
  cancelAccountAuthSession,
  switchroomReply,
  escapeHtmlForTg,
  redactAuthCode: (chatId, redactMsgId) =>
    redactAuthCodeMessage(redactAuthCodeApi as never, chatId, redactMsgId, line =>
      process.stderr.write(line),
    ),
  pendingReauthFlows,
  execAuthCode,
  renderAuthCodeOutcome: outcome => renderAuthCodeOutcome(outcome as AuthCodeOutcome | null),
  preBlock,
  formatSwitchroomOutput,
  formatAuthOutputForTelegram,
  pendingVaultOps,
  vaultInputTtlMs: VAULT_INPUT_TTL_MS,
  vaultPassphraseTtlMs: VAULT_PASSPHRASE_TTL_MS,
  vaultPassphraseCache,
  deleteSensitiveMessage,
  executeVaultOp,
  unlockViaBroker,
  callbackQueryHandlers: () => callbackQueryHandlers,
  pendingVaultRequestAccesses,
  pendingVaultRequestSaves,
  vaultKeyRegex: VAULT_KEY_REGEX,
  vaultKeyRegexLabel: VAULT_KEY_REGEX_LABEL,
  secretStaging,
  awaitingAuthCodeAt,
  authCodeContextTtlMs: AUTH_CODE_CONTEXT_TTL_MS,
  deferredSecrets,
  deferredKey,
  mintDeferredSecretKernelRequest,
  buildDeferredSecretKeyboard,
}

export async function handleInbound(
  ctx: Context,
  text: string,
  downloadImage: (() => Promise<string | undefined>) | undefined,
  attachment?: AttachmentMeta,
  // A2: 2nd..Nth attachments folded into this coalesced turn. Each is
  // resolved (photos downloaded) and surfaced as numbered meta fields
  // (image_path_2, attachment_file_id_2, …) alongside the primary.
  extraAttachments?: CoalesceAttachment[],
  // Forwarded-message origins for a coalesced burst (deduped, arrival
  // order — see the coalescer's merge). Left undefined by the direct /
  // bypass call sites; handleInbound then parses THIS ctx's
  // forward_origin itself, so single-message forwards work on every path.
  coalescedForwardOrigins?: ForwardOriginInfo[],
): Promise<void> {
  markIdleActivity() // any inbound resets the idle auto-clear timer + re-arms
  const messageThreadId = ctx.message?.message_thread_id

  // Topic-scope + access-gate admission head — moved to admitInbound
  // (#2996 P7 PR-10); drop/pair early-return semantics unchanged.
  const admission = await admitInbound(ctx, inboundAdmissionDeps)
  if (!admission.admitted) return
  const result = { action: 'deliver' as const, access: admission.access as Access }

  // A real message from an allowed sender (gate passed) ⇒ the operator is
  // present, so reset any no-repeat suppression: the next time the agent asks
  // for something that timed out earlier, they should see a fresh card.
  clearPermissionTimeoutSuppression('operator inbound')
  // #2862 — operator is back; re-offer any approvals that timed out meanwhile.
  maybePostMissedApprovalDigest('operator inbound')

  // First inbound after boot: drain any stale STACKED pins in this exact
  // (chat, thread) that the boot getChat() probe can't see (DMs skip the probe
  // AND getChat exposes only the newest pin). The durable obligation cursor
  // dedups with the boot sweep and with a prior drain of the same target; the
  // rights precheck and rate gates apply as usual, and a non-forum supergroup
  // is skipped. No-op until the startup mutex is won. Fire-and-forget.
  //
  // This runs on EVERY inbound; `sweepTarget` is at-most-once per target per
  // process (and coalesces concurrent callers), so a busy chat cannot
  // re-attempt a partial drain once per message. That guard lives in the
  // sweeper, not here, so the boot caller inherits it too.
  {
    const inboundChatId = ctx.chat?.id
    if (inboundChatId != null) {
      void stalePinSweeper.sweepTarget({
        chatId: String(inboundChatId),
        threadId: ctx.message?.message_thread_id,
        isForum: ctx.chat?.is_forum === true,
      })
    }
    // Outbox envelope-less routing (F2) is scoped to each record's OWN stamped
    // per-session origin chat (captured at Stop), not a gateway-global stamp.
  }

  // Capture wall-clock receive time for inbound_ack metric (#203).
  // Must be after gate() so early-exit paths (drop/pair) don't skew the delta.
  //
  // Measurement caveat: the `setMessageReaction` API call that posts the 👀
  // is `void`-dispatched (fire-and-forget) before the metric is logged, so
  // `ackDelayMs` measures gateway-receive → reaction-DISPATCH not
  // gateway-receive → reaction-ACKNOWLEDGED-by-Telegram. The optimistic
  // bias is one network RTT (~50–200ms typically). Acceptable for
  // ambient-signal alerting (the dominant variance is reasoning time, not
  // network RTT) but not a user-perceived end-to-end measurement.
  const inboundReceivedAt = Date.now()

  // Snapshot the machine's in-turn state AT RECEIPT, before this handler
  // emits the `inbound` event (that emit is DEFERRED below to the
  // delivery-commit point — search DEFERRED_INBOUND_EMIT). A fresh-turn
  // inbound transitions the machine idle→in_turn; reading after the emit
  // would see THIS message's own just-started turn and self-block it.
  //
  // WHY THE INBOUND EMIT IS DEFERRED (overlord /usage wedge, 2026-07-08):
  // the `inbound` event drives the AUTHORITATIVE turn-in-flight gate
  // (turnInFlightForGate → isMachineInTurn). Emitting it HERE — at handler
  // entry, before the intercept gauntlet below (permission-reply, /auth
  // paste-back, interrupt-empty, secret-detect drop, …) — drove the machine
  // into `bridge_alive_in_turn` for messages that then EARLY-RETURN as an
  // intercept and never become a turn. No delivery, and critically no
  // `turnEnd` ever fires, so the machine held the gate closed until the
  // 5-min TTL tick force-cleared it — buffering every subsequent inbound
  // (including /usage) the whole time (the dangerous over-hold direction
  // the bake-era gate-parity probe flagged). Fix: emit `inbound` only once
  // the message clears every intercept and reaches the deliver-or-buffer
  // decision, keeping the machine in lockstep with the delivery lifecycle
  // it models.
  const machineInTurnAtReceipt = isMachineInTurn()

  // #1556 self-blocking fix (v0.12.22): snapshot the live turn-state
  // BEFORE the fresh-turn branch (line ~7357) sets activeTurnStartedAt
  // for THIS inbound. The #1556 delivery gate further down asks "is a
  // turn ALREADY in flight" — but if we read activeTurnStartedAt.size
  // at the gate, we see the entry this handler just wrote, and buffer
  // the very message that just started the turn. Symptom: every first
  // post-restart message in each thread was held 5 minutes until the
  // silence-poke fallback drained the buffer; the "5-min blank after
  // restart" wedge documented in
  // feedback_5min_restart_wedge_violates_vision.md.
  //
  // Why ONLY first-after-restart, not every steady-state message: the
  // fresh-turn branch fires only when `priorActive = activeStatusReactions.get(key)`
  // returns null (no controller currently running for this chat+thread).
  // In a live conversation, the controller from the previous turn
  // typically hasn't been cleared yet when the user's follow-up
  // arrives (or follow-ups arrive mid-turn, taking the queued path) —
  // so the else branch at ~7313 is skipped and the .set never fires.
  // A fresh container after restart has EMPTY `activeStatusReactions`,
  // so the very first message in each thread is guaranteed to enter
  // the fresh-turn branch and trigger the self-block.
  //
  // Why snapshot, not move-the-set(): the .set() at ~7357 is embedded
  // in a coupled init bundle (controller, msgIds, signalTracker.reset,
  // silencePoke.startTurn, the 👀 reaction emit). Moving only the .set
  // splits the bundle in ways future maintainers will drift; moving
  // the WHOLE bundle past the gate changes user-visible ack timing
  // (👀 wouldn't land until after the gate decides to deliver, hiding
  // an ack on the buffered path). The snapshot is the minimal precise
  // fix. Phase 2b's state-machine extraction will revisit this
  // structurally.
  // Gated on the machine's "turns claude has been handed" state, not
  // activeTurnStartedAt (eager set on receipt). In supergroup mode,
  // topic A active + topic B inbound arriving: B sees true (A is
  // busy) → B is buffered correctly, AND the gate cleanly reopens
  // when A's turnEnd clears the machine → flush triggers → B delivered.
  // This is "was a turn in flight at receipt", not a live
  // post-this-inbound read — see machineInTurnAtReceipt's comment.
  const turnInFlightAtReceipt = machineInTurnAtReceipt

  const access = result.access
  const from = ctx.from!
  const chat_id = String(ctx.chat!.id)
  const msgId = ctx.message?.message_id

  if (messageThreadId != null) chatThreadMap.set(chat_id, messageThreadId)

  // #1122 KPI: classify "are you still working / status?" pings as the
  // primary lagging KPI of the conversational-turn-UX redesign. Every fire
  // means the design failed to make the user feel heard. Read-only —
  // never alters routing; the text still reaches the agent.
  try {
    const classification = classifyInbound(text)
    if (classification.isStatusQuery) {
      const priorKey = statusKey(chat_id, messageThreadId)
      const priorTurnStartedAt = activeTurnStartedAt.get(priorKey)
      const priorTurnInFlight = activeStatusReactions.get(priorKey) != null
      emitRuntimeMetric({
        kind: 'inbound_status_query',
        chat_id,
        message_id: msgId ?? null,
        thread_id: messageThreadId ?? null,
        text_length: text.length,
        prior_turn_in_flight: priorTurnInFlight,
        seconds_since_turn_start: priorTurnStartedAt != null
          ? Math.round((inboundReceivedAt - priorTurnStartedAt) / 1000)
          : null,
      })
    }
  } catch (err) {
    // Classifier is fire-and-forget — never break inbound on a metric error.
    process.stderr.write(`telegram gateway: inbound classifier error: ${(err as Error).message}\n`)
  }

  // `!`-prefix interrupt (#575). Closes
  // `reference/jobs/steer-or-queue-mid-flight.md`'s correction path.
  //
  // Behavior:
  //   1. SIGINT the agent service. This kills any in-flight turn —
  //      same primitive that powers `switchroom agent interrupt`.
  //      It's heavy, but the user explicitly asked for it; correctness
  //      beats elegance here.
  //   2. Strip the `!` and forward the body as a fresh turn so the
  //      agent sees clean intent. If the body is empty (just `!`),
  //      send a clarifying reply instead — forwarding empty text
  //      would just yield a tool-result-of-nothing.
  //   3. React with ⚡ on the `!` message so the user has a visible
  //      ack that the interrupt landed (separate from the 👀 the
  //      coalescer-bypass path skipped).
  //
  // Authorization: same allowFrom gate as any inbound message —
  // unauthorized senders never reach this code (gate() above).
  // Interrupt requires the same trust as sending a normal message.
  // #3020: bare operator "stop" — the kill switch without the `!` marker.
  // Exact-word only (parseStopKeyword): "stop the build" flows to the agent
  // as a normal turn. Intercepted here (never forwarded) so it fires mid-turn
  // instead of queueing behind the very turn it's trying to cancel.
  // Authorization: same allowFrom gate as any inbound (gate() above).
  // Pure text only (7b): a photo/attachment captioned "stop" is content for
  // the agent, not a halt request — it must never trip the halt-and-drop
  // path (the caption + attachment flow through as a normal turn).
  // Problem B: defer this `!`'s SIGINT to a safe boundary instead of firing it
  // synchronously. Extracted to interceptInterruptMarker (#2996 P7 PR-3);
  // `deferInterrupt` comes back as an at-receipt captured VALUE the delivery
  // site consumes (when true the synchronous SIGINT was skipped and the built
  // inbound is stashed at the delivery site, #3020 semantics unchanged).
  // `interrupt` is parsed from the ORIGINAL text on both arms (isInterrupt
  // feeds the downstream envelope/delivery path).
  let interrupt: ReturnType<typeof parseInterruptMarker>
  let deferInterrupt = false
  if (INBOUND_ROUTER_V2) {
    // v2 (#2996 P7 PR-11): consolidated pre-turn chain — stop-keyword then
    // interrupt-marker, ordering owned by runPreTurnIntercepts. Same
    // intercept functions as the legacy arm; the characterization harness +
    // inbound-router-v2-chain.test.ts pin parity.
    interrupt = parseInterruptMarker(text)
    const pre = await runPreTurnIntercepts(
      {
        stop: { text, chat_id, msgId, messageThreadId, downloadImage, attachment, extraAttachments },
        interrupt: { interrupt, chat_id, msgId, messageThreadId },
      },
      inboundInterceptorDeps,
    )
    if (pre.handled) return
    deferInterrupt = pre.deferInterrupt
    // Replace the inbound text with the `!` body and continue normal
    // processing. The agent receives a fresh turn with no `!` prefix.
    if (pre.replacedText != null) text = pre.replacedText
  } else {
    {
      const stopOutcome = await interceptStopKeyword(
        { text, chat_id, msgId, messageThreadId, downloadImage, attachment, extraAttachments },
        inboundInterceptorDeps,
      )
      if (stopOutcome.handled) return
    }

    interrupt = parseInterruptMarker(text)
    {
      const interruptOutcome = await interceptInterruptMarker(
        { interrupt, chat_id, msgId, messageThreadId },
        inboundInterceptorDeps,
      )
      if (interruptOutcome.handled) return
      deferInterrupt = interruptOutcome.deferInterrupt
      // Replace the inbound text with the `!` body and continue normal
      // processing. The agent receives a fresh turn with no `!` prefix.
      if (interruptOutcome.replacedText != null) text = interruptOutcome.replacedText
    }
  }

  // Issue #109: when the user has to ask "status?" mid-turn, the live progress
  // surface (status reactions + the edit-in-place `🛠 Worker` feed) may have
  // failed its job. Log the event with a snapshot of what is ACTUALLY in
  // flight so we can count + analyze frequency. We don't intercept the
  // message — it still flows through to the agent, since the agent may have a
  // useful answer the surfaces haven't communicated yet.
  //
  // Truthful telemetry (was a lying diagnostic): the pinned progress card was
  // retired in #1122/#1126 and `progressDriver` is now permanently null, so
  // the old `progressDriver.peek(...)` snapshot ALWAYS reported idle/zero
  // regardless of live work — actively misleading debugging. We now read the
  // LIVE surfaces instead: the running-background-worker DB count
  // (`countRunningWorkers`), the `🛠 Worker` activity-feed size, the
  // cross-turn pending-async-dispatch flag (`pending-work-progress.ts`), and
  // whether a turn is active (`activeTurnStartedAt`). A live background worker
  // ⇒ non-idle. A `ux-failure` is emitted ONLY when all of those are genuinely
  // zero AND no turn is active — i.e. the user asked "status?" and there really
  // was nothing in flight for the surfaces to have shown.
  //
  // Log shape (grep anchor: "status-query"):
  //   status-query agent=<n> chat_id=<n> thread=<n|none> stage=<stage>
  //                turn_age_s=<int> running_workers=<n> worker_feed=<n>
  //                pending_async=<0|1>
  // When idle, a second line carries the grep anchor "ux-failure: status-query".
  //
  // `turn_age_s` is always a non-negative integer; `-1` is the sentinel for
  // "no active turn" so structured-log parsers (Loki, Datadog, awk) can treat
  // the field as numeric without string-comparison branches.
  if (STATUS_QUERY_RE.test(text)) {
    try {
      const thread = messageThreadId != null ? String(messageThreadId) : 'none'
      const key = statusKey(chat_id, messageThreadId)
      const turnStartedAt = activeTurnStartedAt.get(key)
      const turnActive = turnStartedAt != null
      const surfaces: StatusQuerySurfaces = {
        turnActive,
        turnAgeS: turnActive
          ? Math.max(0, Math.floor((Date.now() - turnStartedAt) / 1000))
          : -1,
        runningWorkers: countRunningWorkers(),
        workerFeedSize: workerActivityFeed?.size ?? 0,
        pendingAsync: pendingProgress.hasPendingAsyncDispatch(key) ? 1 : 0,
      }
      const telemetry = deriveStatusQueryTelemetry(surfaces)
      const agentName = process.env.SWITCHROOM_AGENT_NAME ?? '-'
      process.stderr.write(
        formatStatusQueryLine(agentName, String(chat_id), thread, surfaces, telemetry),
      )
      if (telemetry.idle) {
        process.stderr.write(formatStatusQueryUxFailureLine(agentName, String(chat_id), thread))
      }
    } catch (err) {
      process.stderr.write(`telegram gateway: status-query telemetry failed: ${(err as Error).message}\n`)
    }
  }

  // PR3 supergroup-mode: keyed by chatKey(chat, thread) so an OAuth code
  // pasted into topic A isn't intercepted when topic B has a separate flow
  // pending (security: prevents cross-topic credential mis-attribution).
  const interceptKey = chatKey(chat_id, messageThreadId) as string

  if (INBOUND_ROUTER_V2) {
    // v2 (#2996 P7 PR-11): consolidated reply/paste-back chain — permission
    // → auth-add → loopback (incl. #3084 fail-safe) → reauth → vault →
    // secret-staging, ordering owned by runPasteBackIntercepts. Same
    // intercept functions as the legacy arm below.
    const pasteBackOutcome = await runPasteBackIntercepts(
      { ctx, text, chat_id, msgId, interceptKey },
      inboundInterceptorDeps,
    )
    if (pasteBackOutcome.handled) return
  } else {
    // Permission-reply intercept (moved to interceptPermissionReply, #2996 P7
    // PR-4; PERMISSION_REPLY_RE lives in inbound-interceptors.ts now).
    {
      const permOutcome = interceptPermissionReply({ text, chat_id, msgId }, inboundInterceptorDeps)
      if (permOutcome.handled) return
    }

    // `/auth add` paste-back intercept — sibling to pendingReauthFlows.
    // Both intercepts are deliberate so the LLM never sees the OAuth
    // code (it doesn't need to + plaintext OAuth in chat history is bad
    // hygiene). The add-flow intercept comes first because /auth add
    // creates fresh credentials at the broker layer, vs /reauth which
    // mutates an existing agent's slot — different success paths.
    //
    // PR3 supergroup-mode: keyed by chatKey(chat, thread) so an OAuth
    // code pasted into topic A isn't intercepted when topic B has a
    // separate /auth add flow pending (security: prevents cross-topic
    // credential mis-attribution).
    // (moved to interceptAuthAdd, #2996 P7 PR-5; the anchor literal
    // pendingAuthAddFlows.get(interceptKey) lives inside the delegation now)
    {
      const authAddOutcome = await interceptAuthAdd(
        { ctx, text, chat_id, msgId, interceptKey },
        inboundInterceptorDeps,
      )
      if (authAddOutcome.handled) return
    }

    // Loopback OAuth relay paste-back intercept (issue #2582) — sibling to
    // the /auth add intercept above. When a Google/Microsoft loopback relay is
    // pending for this chat and the operator pastes their `127.0.0.1:<port>`
    // redirect URL, validate `state` and hand the code to the waiting CLI
    // listener. The LLM never sees the code (same hygiene rationale as above).
    // Consume-gate is deliberately narrow (PR #3100 review finding 1): only a
    // message that actually parses as a loopback redirect — carrying a code,
    // or a provider `error` param — is consumed and deleted. Unrelated chatter
    // that merely mentions localhost/127.0.0.1 flows through untouched.
    // (moved to interceptLoopbackRelay incl. the #3084 fail-safe redaction tail,
    // #2996 P7 PR-6)
    {
      const loopbackOutcome = await interceptLoopbackRelay(
        { ctx, text, chat_id, msgId, interceptKey },
        inboundInterceptorDeps,
      )
      if (loopbackOutcome.handled) return
    }

    // Auth-code (reauth) intercept — moved to interceptReauth (#2996 P7 PR-7).
    // Structural anchor for gateway-loopback-paste-redact.test.ts ordering:
    // const pendingReauth = pendingReauthFlows.get(interceptKey) now lives in
    // the interceptor; the delegation below preserves its position.
    {
      const reauthOutcome = await interceptReauth(
        { ctx, text, chat_id, msgId, interceptKey },
        inboundInterceptorDeps,
      )
      if (reauthOutcome.handled) return
    }

    // Vault intercept — moved to interceptVault (#2996 P7 PR-8).
    {
      const vaultOutcome = await interceptVault({ ctx, text, chat_id, msgId }, inboundInterceptorDeps)
      if (vaultOutcome.handled) return
    }

    // Secret-detect follow-up command intercept — moved to
    // interceptSecretStagingCommand (#2996 P7 PR-9).
    {
      const stagingOutcome = await interceptSecretStagingCommand(
        { ctx, text, chat_id, msgId },
        inboundInterceptorDeps,
      )
      if (stagingOutcome.handled) return
    }
  }

  // Typing indicator in the ORIGINATING topic — on a supergroup-topic inbound,
  // an un-threaded sendChatAction shows "typing" in General, not the topic the
  // user is in. messageThreadId is the inbound's thread (undefined in a DM).
  // Floor-gated through the shared emitter (#3084).
  emitChatAction(chat_id, messageThreadId ?? null, 'typing')

  // Parse explicit prefixes first. `/steer ` / `/s ` opts IN to steering;
  // `/queue ` / `/q ` are legacy aliases that opt in to the new default (queued).
  const parsedSteer = parseSteerPrefix(text)
  const isSteerPrefix = parsedSteer.steering
  const parsedQueue = isSteerPrefix ? { queued: false, body: parsedSteer.body } : parseQueuePrefix(text)
  const isQueuedPrefix = parsedQueue.queued
  let effectiveText = isSteerPrefix ? parsedSteer.body : (isQueuedPrefix ? parsedQueue.body : text)

  // --- #2045 provided-secret capture ---
  // If this chat is armed (operator tapped [Provide securely] on a
  // request_secret card), THIS message is the secret value: delete it,
  // write it to the vault, resume the agent, and STOP. Runs before secret
  // detection, recordInbound, and the IPC broadcast so the raw value is
  // never recorded, logged, or forwarded.
  if (armedSecretCaptures.has(chat_id)) {
    // Capture the RAW message text, not effectiveText — the secret value
    // must be vaulted verbatim, without the steer/queue prefix-stripping or
    // trim that effectiveText applies (review #2047 finding #1). A
    // credential that legitimately starts with `/s` or has surrounding
    // whitespace would otherwise be mangled.
    const consumed = await captureProvidedSecret(ctx, chat_id, msgId ?? undefined, text)
    if (consumed) return
  }

  // Secret detection + vault-scrub — moved to interceptSecretDetectPipeline
  // (#2996 P7 PR-9). FAIL-CLOSED semantics live in the interceptor; on the
  // pass-through path the (possibly vault-scrubbed) effectiveText is adopted
  // for everything downstream — history, envelope, IPC.
  {
    const secretOutcome = await interceptSecretDetectPipeline(
      { ctx, chat_id, msgId, effectiveText },
      inboundInterceptorDeps,
    )
    if (secretOutcome.handled) return
    effectiveText = secretOutcome.effectiveText
  }
  // Status reaction controller install + fresh-turn init + progress-card
  // startTurn — moved to armTurnStartSurfaces (turn-start-surfaces.ts, #2996
  // P8 PR-D). Called on the shared tail both inbound-router arms (legacy inline
  // + the SWITCHROOM_INBOUND_ROUTER_V2 chain) converge to, so turn-start
  // surfaces are byte-identical whichever way the router flag points. Runs at
  // the same await point (the #472-finding-17 prior-draft finalize await is
  // load-bearing). `isSteering` / `priorTurnStartedAt` come back for the
  // downstream steering-meta + delivery path.
  const { isSteering, priorTurnStartedAt } = await turnStartSurfaces().armTurnStartSurfaces({
    chat_id,
    msgId,
    messageThreadId,
    text,
    effectiveText,
    access,
    inboundReceivedAt,
    isSteerPrefix,
    isQueuedPrefix,
  })

  const imagePath = downloadImage ? await downloadImage() : undefined

  // A2: resolve the extra attachments (2nd..Nth in a coalesced multi-media
  // burst). Photos are downloaded the same way as the primary; documents/
  // voice carry only attachment metadata (the agent fetches them via
  // download_attachment). Numbered meta fields below let the agent see each.
  const extraResolved: Array<{ imagePath?: string; attachment?: AttachmentMeta }> = []
  if (extraAttachments && extraAttachments.length > 0) {
    for (const ex of extraAttachments) {
      const exImagePath = ex.downloadImage ? await ex.downloadImage() : undefined
      extraResolved.push({ imagePath: exImagePath, attachment: ex.attachment })
    }
  }
  // Flatten the numbered meta fields once so the InboundMessage literal can
  // spread them. Primary is "1" (unsuffixed); extras start at "_2".
  const extraMeta = buildExtraAttachmentMeta(extraResolved)
  // Total attachment count (primary + extras) so the agent knows how many to
  // expect without probing for numbered fields. Only emitted when >1.
  const primaryHasAttachment = imagePath != null || attachment != null
  const attachmentCount = (primaryHasAttachment ? 1 : 0) + extraResolved.length

  // Reply-to + forward-origin context — moved to buildReplyForwardContext
  // (#2996 P7 PR-10, pure builder).
  const replyForwardCtx = buildReplyForwardContext({
    ctx,
    coalescedForwardOrigins,
    replyToTextMax: REPLY_TO_TEXT_MAX,
  })
  const {
    replyToMessageId,
    forwardOrigins,
    forwardOriginMeta,
    primaryForwardOrigin,
  } = replyForwardCtx

  // Reply-to buffer fallback (post-reset continuity, resolveReplyToFromBuffer).
  // On a native reply to the BOT's OWN message, Telegram delivers
  // reply_to_message.message_id but NOT its .text — so the live reply text is
  // empty even though we authored (and, via recordOutbound, persisted) that
  // message to history.db (role='assistant', 30-day retention). Recover it so
  // the antecedent survives a session reset. Fills replyToText (raw, so the
  // recordInbound write below persists it — envelope-only would leave the row
  // NULL and starve future briefings), replyToTextEscaped (channel meta), and
  // replyToRole (the reply_to_role attribute). Only when the live text is
  // empty; degrades silently when history is off / the row is missing.
  const {
    replyToText,
    replyToTextEscaped,
    replyToRole,
  } = resolveReplyToFromBuffer({
    replyToMessageId,
    replyToText: replyForwardCtx.replyToText,
    replyToTextEscaped: replyForwardCtx.replyToTextEscaped,
    historyEnabled: HISTORY_ENABLED,
    replyToTextMax: REPLY_TO_TEXT_MAX,
    lookup: (messageId) => lookupMessageRoleAndText(chat_id, messageId),
  })

  if (HISTORY_ENABLED) {
    try {
      recordInbound({
        chat_id,
        thread_id: messageThreadId ?? null,
        message_id: msgId,
        user: from.username ?? String(from.id),
        user_id: String(from.id),
        ts: ctx.message?.date ?? Math.floor(Date.now() / 1000),
        text: effectiveText,
        attachment_kind: attachment?.kind,
        reply_to_message_id: replyToMessageId ?? null,
        reply_to_text: replyToText ?? null,
        forwarded_from: primaryForwardOrigin?.name ?? null,
        forwarded_from_type: primaryForwardOrigin?.type ?? null,
        forwarded_from_id: primaryForwardOrigin?.id != null ? String(primaryForwardOrigin.id) : null,
        forwarded_date: forwardOriginDateIso(primaryForwardOrigin),
        forwarded_message_id: primaryForwardOrigin?.messageId ?? null,
      })
    } catch (err) {
      process.stderr.write(`telegram gateway: history recordInbound failed: ${err}\n`)
    }
  }

  // Build steering meta.
  // priorTurnInProgress is true for ANY mid-turn follow-up (queued or steering).
  // isSteering = explicit /steer or /s prefix was used.
  // isQueuedMidTurn = prior turn was in flight and no steer prefix (new default).
  const priorTurnInProgress = isSteering || (priorTurnStartedAt != null)
  const isQueuedMidTurn = priorTurnInProgress && !isSteering
  let secondsSinceTurnStart: number | undefined
  let priorAssistantPreview: string | undefined
  if (priorTurnInProgress) {
    if (priorTurnStartedAt != null) {
      secondsSinceTurnStart = Math.max(0, Math.floor((Date.now() - priorTurnStartedAt) / 1000))
    }
    if (HISTORY_ENABLED) {
      try {
        const rows = queryHistory({ chat_id, thread_id: messageThreadId ?? null, limit: 10 })
        for (let i = rows.length - 1; i >= 0; i--) {
          const r = rows[i]!
          if (r.role === 'assistant' && r.text && r.text.length > 0) {
            priorAssistantPreview = formatPriorAssistantPreview(r.text, 200)
            break
          }
        }
      } catch {}
    }
  }

  // Dispatch to connected bridge via IPC — the InboundMessage envelope
  // assembly moved to buildInboundEnvelope (#2996 P7 PR-10, pure builder).
  // Every input is an at-call captured value; the machine emit and the
  // deliver-or-buffer dispatch below stay wired exactly as before.
  const inboundMsg: InboundMessage = buildInboundEnvelope({
    ctx,
    chat_id,
    messageThreadId,
    msgId,
    effectiveText,
    imagePath,
    attachment,
    attachmentCount,
    extraMeta,
    from,
    access,
    isSteering,
    isQueuedPrefix,
    isQueuedMidTurn,
    priorTurnInProgress,
    secondsSinceTurnStart,
    priorAssistantPreview,
    replyToMessageId,
    replyToTextEscaped,
    replyToRole,
    forwardOriginMeta,
    topicFramingEnabled: TOPIC_FRAMING_ENABLED,
    personDirectory: PERSON_DIRECTORY,
    isDmChatId,
  })
  // Deliver to THIS agent's registered bridge, buffering on miss.
  // broadcast()/clientCount() were the wrong primitives: broadcast is
  // not registered-keyed (writes to any alive socket incl. an
  // unregistered pre-handshake one) and yields no delivered signal,
  // and clientCount() counts unregistered sockets — so a bridge
  // mid-reconnect made clientCount()>0, the message was broadcast into
  // a non-registered socket, the "restarting" notice was suppressed,
  // and the user's message was silently lost. The old "queued either
  // way" comment was false: broadcast does not queue. sendToAgent is
  // registered-keyed + returns a real delivered bool; on a miss we
  // push to pendingInboundBuffer, which onClientRegistered drains on
  // the next bridge register — so the notice below is now truthful.
  const selfAgent = process.env.SWITCHROOM_AGENT_NAME ?? ''

  // #1556: turn-gated delivery. A non-steering inbound that arrives
  // mid-turn must NOT be sent to the bridge now — claude would type it
  // into its TUI composer and the auto-submit races turn-completion,
  // stranding the message (the lawgpt wedge, 2026-05-19). Buffer it;
  // `purgeReactionTracking`'s turn-complete hook and the turn-gated
  // idle-drain flush it the instant claude goes idle, where the channel
  // notification submits cleanly as a fresh turn. Steering messages are
  // exempt — reaching claude mid-turn is the whole point of /steer.
  //
  // CRITICAL: turnInFlight reads the snapshot taken at receipt above,
  // not `activeTurnStartedAt.size > 0` live. The fresh-turn branch at
  // line ~7357 already populated the Map for THIS inbound's turn;
  // reading the live size here would self-block (see the comment on
  // turnInFlightAtReceipt for the wedge symptom this fixes).
  // Problem B: a deferred `!` interrupt. The synchronous SIGINT was skipped
  // above (a tool was in flight) — claude is still working. Don't deliver the
  // replacement body now (it would race the live tool); stash the fully-built
  // inbound and let `fireDeferredInterrupt` SIGINT + deliver at the next clean
  // boundary, or when the max-wait timer expires. Rapid repeated `!` coalesce:
  // the latest body replaces the stashed inbound, the original deadline holds
  // so the wait stays bounded.
  if (deferInterrupt) {
    const selfAgentDefer = process.env.SWITCHROOM_AGENT_NAME ?? ''
    if (pendingDeferredInterrupt != null) {
      pendingDeferredInterrupt.inboundMsg = inboundMsg
      pendingDeferredInterrupt.msgId = msgId ?? null
      process.stderr.write(
        `telegram gateway: deferred-interrupt coalesced (replacing pending body) agent=${selfAgentDefer} chat=${chat_id} msg=${msgId ?? '-'}\n`,
      )
    } else {
      const maxWaitMs = resolveInterruptMaxWaitMs(loadAccess().interruptMaxWaitMs)
      pendingDeferredInterrupt = {
        agentName: selfAgentDefer,
        inboundMsg,
        chatId: chat_id,
        msgId: msgId ?? null,
        threadId: messageThreadId ?? undefined,
        registeredAt: Date.now(),
        deadlineTimer: setTimeout(() => { void fireDeferredInterrupt('timeout') }, maxWaitMs),
      }
      process.stderr.write(
        `telegram gateway: deferred-interrupt parked agent=${selfAgentDefer} chat=${chat_id} ` +
        `msg=${msgId ?? '-'} max_wait_ms=${maxWaitMs} in_flight=${toolFlightTracker.inFlightCount()}\n`,
      )
    }
    return
  }

  // DEFERRED_INBOUND_EMIT — drive the delivery state machine's `inbound`
  // event HERE, not at handler entry. Every intercept/early-return above
  // (permission-reply, /auth paste-back, interrupt-empty, secret-detect
  // drop, drop/pair) has been passed, so any message reaching this point is
  // a genuine turn the imperative code is about to deliver or buffer. That
  // keeps the machine's authoritative turn-in-flight state in lockstep with
  // the imperative delivery it models and can never be advanced into
  // `bridge_alive_in_turn` by a message that never becomes a turn — the
  // overlord /usage wedge of 2026-07-08 (see machineInTurnAtReceipt above).
  // isSteering is now the real classification (computed at ~line 16289), so
  // the machine correctly distinguishes a mid-turn steer (delivered, no new
  // turn) from a fresh turn.
  // PR3c cutover (#2794 / #2996): the payload now carries the REAL
  // ipc-protocol InboundMessage (previously null) so the machine's
  // deliverToBridge / bufferInbound / persistInbound effects are executable,
  // and the returned effects are CAPTURED — under the cutover they are
  // dispatched below and become the authoritative deliver-vs-buffer routing.
  // The machine treats the payload as opaque, so the kill-switch shadow
  // trace is unchanged.
  const machineInboundEffects = shadowEmit({
    kind: 'inbound',
    key: statusKey(chat_id, messageThreadId) as _ChatKey,
    msg: {
      msgId: msgId ?? 0,
      isSteering,
      payload: inboundMsg,
    },
    at: Date.now(),
  })

  // PR2 obligation-ledger OPEN — BEFORE the buffer-until-idle / deliver split so
  // a mid-turn cross-topic inbound (the 715 case) is tracked whether it is
  // buffered or delivered now. Idempotent + gated; no-op when the flag is off.
  openObligationFromInbound(inboundMsg, {
    isSteering,
    isInterrupt: interrupt.isInterrupt,
    effectiveText,
  })

  // ── Machine-authoritative inbound routing (#2794 cutover; kill switch
  // removed in #2996 P1) ─────────────────────────────────────────────────
  // The machine's effect list is AUTHORITATIVE for the deliver-vs-buffer
  // routing: the effects captured at the emit above are executed through
  // `dispatchEffects` (wired to real executors in #3006).
  //
  // Two carve-outs still route to the imperative delivery body below (both
  // documented in the RFC as un-modeled by the machine; the twin-body
  // behavior is the contract until the machine grows the events — tracked
  // as the #2794 PR4 remainder):
  //   1. `!`-interrupt while the machine reads in_turn — the interrupt
  //      carve-out delivers (the SIGINT'd turn may never emit
  //      turn_complete, so buffering would strand the body; see
  //      decideInboundDelivery). The machine has no interrupt concept yet
  //      and would buffer.
  //   2. machine reads bridge_dead — the imperative body attempts the send
  //      and, on miss, applies the shouldTrackDelivery carve-outs
  //      (steering / interrupt / sourced bodies are dropped, not replayed
  //      orphaned after restart) + posts the restart notice. The machine's
  //      unconditional buffer+persist would replay a steer as a fresh turn.
  const machineDelivers = machineInboundEffects.some((e) => e.kind === 'deliverToBridge')
  const machineBuffers = machineInboundEffects.some((e) => e.kind === 'bufferInbound')
  // ANCHORED STRING — must match the machine's bridge-dead inbound trace
  // stage verbatim (see the anchor comment at its emit site in
  // inbound-delivery-machine.ts + the pin test in
  // inbound-delivery-cutover-flip.test.ts).
  const machineBridgeDead = machineInboundEffects.some(
    (e) => e.kind === 'logTrace' && e.stage === 'inbound_bridge_dead_buffer',
  )
  const machineAuthoritative =
    !machineBridgeDead &&
    (machineDelivers || (machineBuffers && interrupt.isInterrupt !== true))
  if (machineAuthoritative && machineBuffers) {
    // Machine says: mid-turn non-steering inbound → buffer until idle (the
    // #1556 contract). dispatchEffects executes bufferInbound (+ the
    // idempotent persistInbound — push() already spools when a spool is
    // attached) + the logTrace. The queued-status UX below is presentation,
    // not routing — it stays imperative on both paths until PR4.
    dispatchEffects(machineInboundEffects, {
      selfAgent,
      ipcServer,
      pendingInboundBuffer,
      inboundSpool: inboundSpool ?? null,
      pendingPermissionBuffer,
    })
    process.stderr.write(
      `telegram gateway: inbound held mid-turn (machine) agent=${selfAgent} ` +
      `chat=${chat_id} msg=${msgId ?? '-'} — will flush on turn-complete\n`,
    )
    const inFlightThreadM = currentTurn?.sessionThreadId
    const crossTopicQueuedCardM =
      QUEUED_STATUS_UX_ENABLED &&
      !isDmChatId(chat_id) &&
      messageThreadId != null &&
      messageThreadId !== inFlightThreadM
    if (crossTopicQueuedCardM) {
      postQueuedStatus(chat_id, messageThreadId, inFlightThreadM)
    } else {
      maybePostBusyAck('buffer-until-idle', chat_id, messageThreadId ?? undefined)
    }
    return
  }

  // #2917 rapid-fire FIFO: the at-receipt machine snapshot is used here (a
  // live machine read WOULD self-block — the inbound event above already
  // advanced the machine for this key). The machine's synchronous advance
  // at the emit is itself the pre-await reservation a concurrent same-chat
  // inbound observes, so per-chat FIFO holds without the deleted legacy
  // busy-key reservation.
  const deliveryGate = reserveInboundDelivery({
    turnInFlight: turnInFlightAtReceipt,
    isSteering,
    // Interrupt-marker carve-out (2026-05-24): the `!`-prefixed body
    // must bypass the "buffer-until-turn-complete" gate because the
    // SIGINT'd turn often doesn't emit turn_complete, leaving the
    // body stranded in pendingInboundBuffer indefinitely. The
    // `interrupt` const is computed at the start of handleInbound
    // (line ~7606) and remains in scope here. When the user fires
    // `!`-with-body, this delivers the body as a fresh inbound to
    // the freshly-killed bridge.
    isInterrupt: interrupt.isInterrupt,
  })
  // PR3c: the legacy buffer branch runs ONLY when the machine is not
  // authoritative (kill switch / carve-out fallback) — the machine buffer
  // path above already returned for machine-routed buffering.
  if (!machineAuthoritative && deliveryGate.decision === 'buffer-until-idle') {
    pendingInboundBuffer.push(selfAgent, inboundMsg)
    process.stderr.write(
      `telegram gateway: inbound held mid-turn agent=${selfAgent} ` +
      `chat=${chat_id} msg=${msgId ?? '-'} — will flush on turn-complete\n`,
    )
    // Component 5 (Hook A) — queued-status UX. When this buffered inbound
    // is in a DIFFERENT forum topic than the in-flight turn, the user in
    // that topic otherwise sees only a 👀 reaction (or nothing). Post one
    // self-updating status into the buffered message's OWN topic so they
    // know they're queued. Suppressed for DMs (no topics) and same-topic
    // queues (the in-flight turn's own card already covers them).
    const inFlightThread = currentTurn?.sessionThreadId
    const crossTopicQueuedCard =
      QUEUED_STATUS_UX_ENABLED &&
      !isDmChatId(chat_id) &&
      messageThreadId != null &&
      messageThreadId !== inFlightThread
    if (crossTopicQueuedCard) {
      postQueuedStatus(chat_id, messageThreadId, inFlightThread)
    } else {
      // #2995 mid-flight busy ack — ONLY the surfaces the cross-topic card
      // suppresses (DMs, same-topic). Mutually exclusive with
      // postQueuedStatus above: both record into queuedStatusMsgIds only
      // AFTER their sendMessage awaits resolve, so calling both here would
      // race past each other's has(key) check and double-card the topic.
      // When the running turn is inside one LONG tool step, a buffered
      // quick question would otherwise wait minutes with only a 👀; post a
      // silent deterministic "Queued — currently inside <tool>" card.
      maybePostBusyAck('buffer-until-idle', chat_id, messageThreadId ?? undefined)
    }
    return
  }

  // Pre-send composer clear (the marko wedge). The inbound is about to be
  // delivered as an MCP `notifications/claude/channel` notification, which
  // the unmodified CLI appends into its composer and auto-submits ONLY when
  // the composer is empty + idle. The #1556 gate above guarantees idle, but
  // NOT empty: stale typed-ahead / ghost text stranded in the composer
  // (observed live on agent `marko`: "Yes, go ahead on both") makes the
  // appended inbound fail to submit and silently swallows every subsequent
  // queued inbound until a hard restart. Wipe the composer first so the
  // notification lands at a clean line. Soft-fail by contract — a clear
  // failure (no tmux session under legacy_pty, socket missing, timeout)
  // must NEVER block delivery; log and proceed.
  if (selfAgent) {
    try {
      const { clearAgentComposer } = await import('../../src/agents/tmux.js')
      const cleared = clearAgentComposer({ agentName: selfAgent })
      if ('error' in cleared) {
        process.stderr.write(
          `telegram gateway: pre-send composer-clear soft-failed agent=${selfAgent}: ${cleared.error} — delivering anyway\n`,
        )
      }
    } catch (err) {
      process.stderr.write(
        `telegram gateway: pre-send composer-clear threw agent=${selfAgent}: ${(err as Error).message} — delivering anyway\n`,
      )
    }
  }

  // ── Machine deliver path (#2794) ───────────────────────────────────────
  // The machine said deliver (fresh turn: setTurnStarted + deliverToBridge;
  // steer: deliverToBridge only). dispatchEffects executes the send; the
  // post-send branches below: delivered → steer ack + delivery-confirm
  // tracking; miss → durable-buffer per the shouldTrackDelivery carve-outs
  // and post the restart notice. NOTE the machine already advanced to
  // in_turn at the emit; a send-miss therefore leaves the machine in_turn
  // until the TTL tick clears it (subsequent inbounds in that window are
  // machine-buffered with the queued busy-ack — the documented RFC
  // carve-out row).
  if (machineAuthoritative) {
    let machineDelivered = false
    dispatchEffects(machineInboundEffects, {
      selfAgent,
      ipcServer,
      pendingInboundBuffer,
      inboundSpool: inboundSpool ?? null,
      pendingPermissionBuffer,
      // setTurnStarted is a deliberate no-op at gateway scope (#2996 P1):
      // the machine's own idle→in_turn transition at the emit IS the
      // authoritative turn marker now that the legacy claudeBusyKeys
      // mirror is deleted. Wired (not omitted) so the dispatcher's
      // `unwired` trace stays meaningful for genuinely missing wiring.
      onSetTurnStarted: () => {},
      onDeliverResult: (_k, ok) => {
        machineDelivered = ok
      },
    })
    if (machineDelivered) {
      if (isSteering) {
        maybePostBusyAck('steer', chat_id, messageThreadId ?? undefined)
      }
      // The chat key is what the delivery-confirm tracker matches acks on.
      const busyKey = chatKeyForInbound(inboundMsg)
      if (
        DELIVERY_CONFIRM_ENABLED &&
        shouldTrackDelivery({
          isSteering,
          isInterrupt: interrupt.isInterrupt,
          hasSource: inboundMsg.meta?.source != null,
          effectiveText,
        })
      ) {
        trackDelivery(deliveryQueue, busyKey, inboundMsg, Date.now(), String(inboundMsg.messageId))
      }
    } else {
      // Send missed while the machine read bridge-alive. Buffer per the
      // shouldTrackDelivery carve-outs, then notify. (The machine stays
      // in_turn until the TTL tick / bridge-flap clears it — see the
      // carve-out note above.)
      if (
        shouldTrackDelivery({
          isSteering,
          isInterrupt: interrupt.isInterrupt,
          hasSource: inboundMsg.meta?.source != null,
          effectiveText,
        })
      ) {
        pendingInboundBuffer.push(selfAgent, inboundMsg)
      }
      const threadOptsM = messageThreadId != null ? { message_thread_id: messageThreadId } : {}
      void swallowingApiCall(
        () => bot.api.sendMessage(chat_id, '⏳ Agent is restarting — your message is queued and will be processed when it reconnects.', { ...threadOptsM }),
        {
          chat_id,
          verb: 'agent-restarting-notice',
          ...(messageThreadId != null ? { threadId: messageThreadId } : {}),
        },
      )
    }
    return
  }

  const delivered = ipcServer.sendToAgent(selfAgent, inboundMsg)
  if (delivered) {
    // #2995 — a steer delivered mid-turn while the turn is stuck inside one
    // long tool step gets a deterministic ack (worded as a steer, not
    // "Queued" — classification visibility): the model can't narrate the
    // steer until the blocking call returns. Posted only AFTER the bridge
    // dispatch succeeded — a "Steer noted" card for a send that missed
    // (bridge offline → buffered/dropped below) would be untrue.
    if (isSteering) {
      maybePostBusyAck('steer', chat_id, messageThreadId ?? undefined)
    }
    // The chat key is what the delivery-confirm tracker matches acks on.
    const busyKey = chatKeyForInbound(inboundMsg)
    // Track until claude acks via `enqueue` (the marko drop-wedge): if no ack
    // lands, the message stranded in the composer and the sweep re-delivers
    // it. Track ONLY messages that produce an `enqueue` to ack against —
    // shouldTrackDelivery excludes steering / `!` interrupt (amend the running
    // turn), synthetic (meta.source) inbounds, and empty bodies, all of which
    // never enqueue and would re-deliver forever. The tracked messageId lets
    // the ack match only THIS message's enqueue (not a synthetic turn sharing
    // the key). See shouldTrackDelivery / ackDelivery (inbound-delivery-confirm.ts).
    if (
      DELIVERY_CONFIRM_ENABLED &&
      shouldTrackDelivery({
        isSteering,
        isInterrupt: interrupt.isInterrupt,
        hasSource: inboundMsg.meta?.source != null,
        effectiveText,
      })
    ) {
      trackDelivery(deliveryQueue, busyKey, inboundMsg, Date.now(), String(inboundMsg.messageId))
    }
  }
  if (!delivered) {
    // Only persist fresh user turns to the durable spool. Steering / `!`
    // interrupt / empty bodies are mid-turn amendments or no-ops that would
    // arrive orphaned if replayed as a fresh turn after a restart — drop them
    // (the restart notice below tells the user to re-send). Mirrors the
    // tracking + #1556-gate carve-outs.
    if (
      shouldTrackDelivery({
        isSteering,
        isInterrupt: interrupt.isInterrupt,
        hasSource: inboundMsg.meta?.source != null,
        effectiveText,
      })
    ) {
      pendingInboundBuffer.push(selfAgent, inboundMsg)
    }
    const threadOpts = messageThreadId != null ? { message_thread_id: messageThreadId } : {}
    // #1075: thread-id-bearing — swallow via robustApiCall so a deleted
    // topic doesn't crash the gateway. Fire-and-forget; the inbound is
    // genuinely buffered now, so the hint is accurate, not a guess.
    void swallowingApiCall(
      () => bot.api.sendMessage(chat_id, '⏳ Agent is restarting — your message is queued and will be processed when it reconnects.', { ...threadOpts }),
      {
        chat_id,
        verb: 'agent-restarting-notice',
        ...(messageThreadId != null ? { threadId: messageThreadId } : {}),
      },
    )
  }
}

// ─── Switchroom CLI helpers ───────────────────────────────────────────────
const SWITCHROOM_CLI = process.env.SWITCHROOM_CLI_PATH ?? 'switchroom'
const SWITCHROOM_CONFIG = process.env.SWITCHROOM_CONFIG

function switchroomExec(args: string[], timeoutMs = 15000): string {
  const fullArgs = SWITCHROOM_CONFIG ? ['--config', SWITCHROOM_CONFIG, ...args] : args
  return execFileSync(SWITCHROOM_CLI, fullArgs, {
    encoding: 'utf-8',
    timeout: timeoutMs,
    env: { ...process.env, FORCE_COLOR: '0', NO_COLOR: '1' },
    maxBuffer: 4 * 1024 * 1024,
  })
}

function switchroomExecCombined(args: string[], timeoutMs = 15000): string {
  const fullArgs = SWITCHROOM_CONFIG ? ['--config', SWITCHROOM_CONFIG, ...args] : args
  const quoted = [SWITCHROOM_CLI, ...fullArgs].map((a) => `'${String(a).replace(/'/g, "'\\''")}'`).join(' ')
  return execSync(`${quoted} 2>&1`, {
    encoding: 'utf-8',
    timeout: timeoutMs,
    env: { ...process.env, FORCE_COLOR: '0', NO_COLOR: '1' },
    maxBuffer: 4 * 1024 * 1024,
    shell: '/bin/bash',
  })
}

// #789 — button-choice-confirmation ("✅ You chose: X") annotation state.
//
// Two once-per-process warning dedupe sets keyed by agent slug: one for the
// parseMode gate (annotation only supports the default 'html' parse mode),
// one for the single_use mismatch (a re-tappable keyboard can never be
// annotated, so a confirmation request on it silently no-ops). The decision
// + rendered text are pure functions in inline-keyboard-callbacks.ts
// (resolveTapAnnotation) so they can be unit-tested against the exact payload.
const buttonConfirmParseModeWarned = new Set<string>()
const buttonConfirmSingleUseWarned = new Set<string>()

type SwitchroomReplyMarkup =
  | InlineKeyboard
  | { force_reply: true; input_field_placeholder?: string; selective?: boolean }

async function switchroomReply(
  ctx: Context,
  text: string,
  options: {
    html?: boolean
    reply_markup?: SwitchroomReplyMarkup
    // PR5 — supergroup-mode slash-command smart split (CPO #4).
    // 'query' (default semantics) follows the originating topic;
    // 'mutation' and 'heavy' route to admin alias in supergroup mode;
    // omitted/undefined preserves legacy in-place reply behavior.
    classification?: 'query' | 'mutation' | 'heavy'
  } = {},
): Promise<void> {
  const chatId = String(ctx.chat!.id)
  const baseThreadId = resolveThreadId(chatId, ctx.message?.message_thread_id)
  // PR5 — when caller flagged the reply as mutation/heavy AND we're
  // in supergroup mode, override the in-place thread with the
  // admin-alias topic. For 'query' (or non-supergroup), routedOpts
  // is `{}` and baseThreadId wins → behavior unchanged.
  const routedOpts = options.classification
    ? slashCommandReplyOpts(ctx, options.classification)
    : {}
  const threadId = routedOpts.message_thread_id ?? baseThreadId
  const replyOpts = {
    ...(threadId != null ? { message_thread_id: threadId } : {}),
    ...(options.reply_markup ? { reply_markup: options.reply_markup } : {}),
  }
  // #2669: `options.html` now means "render `text` as GFM markdown via the
  // rich-message path" (legacy field name kept). Plain otherwise.
  //
  // Every deterministic slash-command card ships through this html branch as
  // RAW markdown (no reply-path normalization). Under the Bot API 10.1 GFM
  // renderer a lone `\n` is a SOFT break, so a card whose builder stacks
  // labelled fields with single `\n` (e.g. `/usage`, `/model`, `/auth`)
  // renders as one run-on blob. `hardenCardBreaks` promotes those lone
  // field breaks to GFM hard breaks (`  \n`) while leaving lists / tables /
  // fenced code / blockquotes / headings on their native single `\n` — the
  // same treatment the direct-send cards get from `stackCardLines`.
  if (options.html) {
    await ctx.replyWithRichMessage(richMessage(hardenCardBreaks(text)), replyOpts)
  } else {
    await ctx.reply(text, replyOpts)
  }
}

/**
 * Best-effort delete of a message that contains a sensitive value
 * (passphrase, vault secret, raw detected secret). Closes #472 finding
 * #22 — pre-fix every site `void bot.api.deleteMessage(...).catch(() => {})`
 * silently swallowed failures, leaving the secret visible in chat
 * history forever with no operator signal.
 *
 * On failure: log loudly to stderr AND post an in-chat warning naming
 * the message_id the user must delete manually. Awaited so the caller
 * can rely on at-least-attempt + at-least-notify semantics.
 */
async function deleteSensitiveMessage(
  chatId: string,
  msgId: number,
  reason: string,
): Promise<void> {
  try {
    // #1075: wrap through robustApiCall for flood-wait retries. THIS
    // ONE must still throw on permanent failure — the caller's contract
    // is "delete the secret, otherwise log loudly + warn user", and
    // swallowing would lose the audit signal.
    await robustApiCall(
      () => bot.api.deleteMessage(chatId, msgId),
      { chat_id: chatId, verb: 'deleteSensitiveMessage' },
    )
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err)
    process.stderr.write(
      `telegram gateway: SECURITY: delete of ${reason} message ${msgId} in chat ${chatId} FAILED: ${msg}. ` +
      `The sensitive value remains visible in chat history.\n`,
    )
    // In-chat warning so the user knows to delete manually. Best-effort
    // — if this also fails (rare; same chat just rejected our delete),
    // the stderr log is the audit trail.
    await swallowingApiCall(
      () =>
        // allow-raw-bot-api: wrapped in swallowingApiCall (retry policy)
        bot.api.sendRichMessage(
          chatId,
          richMessage(`⚠️ **Could not auto-delete message containing your ${escapeHtmlForTg(reason)}.**\n\nPlease delete message \`${msgId}\` manually so the value is not retained in chat history.\n\n_Reason: ${escapeHtmlForTg(msg)}_`),
          {},
        ),
      { chat_id: chatId, verb: 'deleteSensitiveMessage.warning' },
    )
  }
}

/**
 * Expand the special `all` keyword into the real agent list for restart-
 * driving. The CLI handles its own expansion for the YAML mutation; this
 * helper exists so the gateway's post-CLI restart loop knows whom to
 * bounce. Returns `agents` unchanged when `all` is not present.
 */
async function resolveAgentsForRestart(agents: string[]): Promise<string[]> {
  if (!(agents.length === 1 && agents[0] === 'all')) return agents
  type AgentListResp = { agents: Array<{ name: string }> }
  const data = switchroomExecJson<AgentListResp>(['agent', 'list'])
  return data?.agents?.map(a => a.name).filter(Boolean) ?? []
}

function getMyAgentName(): string {
  const fromEnv = process.env.SWITCHROOM_AGENT_NAME
  if (fromEnv && fromEnv.trim().length > 0) return fromEnv.trim()
  return basename(process.cwd())
}

function isSelfTargetingCommand(name: string): boolean {
  if (name === 'all') return true
  return name === getMyAgentName()
}

// ─── Restart marker ───────────────────────────────────────────────────────
type RestartMarker = { chat_id: string; thread_id: number | null; ack_message_id: number | null; ts: number }

/**
 * In-memory timestamp of the most recent planned restart written by this
 * gateway process. The restart-watchdog reads this (with a freshness
 * window) instead of `readRestartMarker()` to decide whether a NRestarts
 * uptick is user-initiated.
 *
 * The disk marker is unsafe for that purpose because the bridge-reconnect
 * handler clears it within ~1-2s of agent boot, before the next watchdog
 * tick (every 30s by default). That race made every \`/restart agent\`
 * produce a misleading "agent restarted unexpectedly" card. The in-memory
 * timestamp is set on every \`writeRestartMarker\` and survives bridge-
 * reconnect clearing, eliminating the false positive.
 *
 * 60s window is generous enough to cover systemd kill → restart →
 * bridge-reconnect (typically 2–5s) plus the next watchdog tick. After
 * 60s, any further NRestarts increment is genuinely unexpected.
 */
let lastPlannedRestartAt: number | null = null
const PLANNED_RESTART_FRESHNESS_MS = 60_000

function restartMarkerPath(): string | null {
  const agentDir = resolveAgentDirFromEnv()
  if (!agentDir) return null
  return join(agentDir, 'restart-pending.json')
}
function writeRestartMarker(marker: RestartMarker): void {
  const p = restartMarkerPath(); if (!p) return
  try {
    writeFileSync(p, JSON.stringify(marker))
    lastPlannedRestartAt = Date.now()
    process.stderr.write(`telegram gateway: restart-marker: write chat_id=${marker.chat_id} thread_id=${marker.thread_id ?? '-'} ack=${marker.ack_message_id ?? '-'} path=${p}\n`)
  } catch (err) {
    process.stderr.write(`telegram gateway: writeRestartMarker failed: ${err}\n`)
  }
}

/**
 * True when this gateway process initiated a planned restart in the last
 * `PLANNED_RESTART_FRESHNESS_MS`. Used by the restart-watchdog as the
 * authoritative "was this a /restart" signal — see `lastPlannedRestartAt`
 * comment for why the disk marker can't carry this responsibility.
 */
function isPlannedRestartFresh(now: number = Date.now()): boolean {
  if (lastPlannedRestartAt == null) return false
  return now - lastPlannedRestartAt < PLANNED_RESTART_FRESHNESS_MS
}
function readRestartMarker(): RestartMarker | null {
  const p = restartMarkerPath(); if (!p) return null
  try { return JSON.parse(readFileSync(p, 'utf8')) as RestartMarker } catch { return null }
}
function clearRestartMarker(): void {
  const p = restartMarkerPath(); if (!p) return
  try {
    rmSync(p, { force: true })
    process.stderr.write(`telegram gateway: restart-marker: cleared path=${p}\n`)
  } catch {}
}

/**
 * Resolve which Telegram chat should receive the boot card.
 *
 * Fallback chain:
 *   1. restart-pending.json chat_id (if present and fresh)
 *   2. SUBAGENT_OWNER_CHAT_ID env var
 *   3. Most recent inbound from history SQLite
 *   4. null → skip (no known chat)
 *
 * TODO: add test coverage for the history-SQLite fallback path
 */
function resolveBootChatId(
  marker: { chat_id: string; thread_id: number | null; ack_message_id: number | null; ts: number } | null,
  ageMs?: number,
): { chatId: string; threadId: number | undefined; ackMsgId: number | undefined } | null {
  // 1. Restart marker — operator-initiated; honor where they typed
  //    /restart. The marker carries the exact chat+thread context; no
  //    routing override because the user expects to see the boot card
  //    in the same lane where they invoked the restart.
  if (marker != null && (ageMs == null || ageMs < 5 * 60_000)) {
    return {
      chatId: marker.chat_id,
      threadId: marker.thread_id ?? undefined,
      ackMsgId: marker.ack_message_id ?? undefined,
    }
  }

  // For non-marker paths (spontaneous boot, crash recovery, env var,
  // history fallback): supergroup-mode agents route the boot card to
  // the `alerts` alias topic (or default_topic_id fallback) so the
  // operator sees lifecycle events in a predictable lane instead of
  // chat-root. For fleet-mode / DM agents the helper returns undefined
  // → behavior unchanged (lands at chat-root as today). PR4b of
  // supergroup-mode rollout (reference/rfcs/supergroup-mode.md).
  const supergroupBootTopic = resolveAgentOutboundTopic({ kind: 'boot' })
  const bootSupergroup = resolveAgentSupergroupChatId()
  // The boot topic is valid only in the agent's supergroup — attach it per
  // recipient so a DM owner doesn't 400 (marko #2096 class); the supergroup
  // owner gets the boot/alerts lane, a DM gets a thread-less boot card.

  // 2. Env var
  const envChat = process.env.SUBAGENT_OWNER_CHAT_ID
  if (envChat) return { chatId: envChat, threadId: topicForRecipient({ recipientChatId: envChat, resolvedTopic: supergroupBootTopic, supergroupChatId: bootSupergroup }), ackMsgId: undefined }
  // 3. Most-recent inbound from history
  if (HISTORY_ENABLED) {
    try {
      const access = loadAccess()
      const ownerChatId = access.allowFrom[0]
      if (ownerChatId) {
        const recent = queryHistory({ chat_id: ownerChatId, limit: 1 })
        if (recent.length > 0) return { chatId: ownerChatId, threadId: topicForRecipient({ recipientChatId: ownerChatId, resolvedTopic: supergroupBootTopic, supergroupChatId: bootSupergroup }), ackMsgId: undefined }
      }
    } catch {}
  }
  // 4. No known chat
  return null
}

/**
 * Resolve the supergroup-mode topic for an outbound event, or
 * undefined when the agent isn't in supergroup-owned mode. Best-effort
 * — any config-read failure returns undefined and the caller falls
 * through to today's behavior. Generic over every OutboundEvent
 * variant so the same helper backs boot card, compact card, vault,
 * permission, hostd, and watchdog emitters.
 *
 * Called sparingly (boot/reconnect, compaction edges, approval-card
 * dispatch) — not per turn — so the cost of a fresh config-read per
 * call is well within budget.
 */
function resolveAgentOutboundTopic(
  event: Parameters<typeof resolveOutboundTopicHelper>[1],
): number | undefined {
  const agentName = process.env.SWITCHROOM_AGENT_NAME
  if (!agentName) return undefined
  try {
    const cfg = loadSwitchroomConfig()
    const rawAgent = cfg.agents?.[agentName]
    if (!rawAgent) return undefined
    const resolved = resolveAgentConfig(cfg.defaults, cfg.profiles, rawAgent)
    const tg = resolved.channels?.telegram
    if (!tg) return undefined
    // The router treats the absence of default_topic_id as
    // "fleet-mode" and returns undefined for ops-lane events (the
    // caller's existing fallback). Only supergroup-owned agents
    // (with default_topic_id set) get a routed value.
    return resolveOutboundTopicHelper(tg as _OutboundRouterConfig, event)
  } catch {
    return undefined
  }
}

/**
 * The agent's supergroup chat id (`channels.telegram.chat_id`) when it is in
 * supergroup-owned mode, else undefined. A forum topic id resolved by
 * {@link resolveAgentOutboundTopic} is valid ONLY in this chat — used by
 * {@link topicForRecipient} to decide whether an approval/permission card sent
 * to a given recipient (operator DMs vs the supergroup itself) may carry a
 * `message_thread_id`. Attaching a topic to a DM is the marko brevo wedge
 * (2026-06-02): the card fails with "message thread not found" and auto-denies.
 */
function resolveAgentSupergroupChatId(): string | undefined {
  const agentName = process.env.SWITCHROOM_AGENT_NAME
  if (!agentName) return undefined
  try {
    const cfg = loadSwitchroomConfig()
    const rawAgent = cfg.agents?.[agentName]
    if (!rawAgent) return undefined
    const resolved = resolveAgentConfig(cfg.defaults, cfg.profiles, rawAgent)
    const tg = resolved.channels?.telegram as { chat_id?: string | number } | undefined
    return tg?.chat_id != null ? String(tg.chat_id) : undefined
  } catch {
    return undefined
  }
}

/** Whether THIS agent has `channels.telegram.linear_agent.enabled`. Used by the
 *  proactive Linear-auth watch to skip agents that aren't Linear actors. */
function isSelfLinearAgentEnabled(): boolean {
  const agentName = process.env.SWITCHROOM_AGENT_NAME
  if (!agentName) return false
  try {
    const cfg = loadSwitchroomConfig()
    const rawAgent = cfg.agents?.[agentName]
    if (!rawAgent) return false
    const resolved = resolveAgentConfig(cfg.defaults, cfg.profiles, rawAgent)
    const la = (resolved.channels?.telegram as { linear_agent?: { enabled?: boolean } } | undefined)?.linear_agent
    return la?.enabled === true
  } catch {
    return false
  }
}

/**
 * One proactive Linear-auth check for this agent (boot + interval). Reads the
 * refresh bundle via the broker; missing → operator alert, near-expiry →
 * proactive rotate, revoked → operator alert. Best-effort, never throws.
 * Disabled with SWITCHROOM_LINEAR_AUTH_WATCH_POLL_MS=0.
 */
async function runLinearAuthWatch(): Promise<void> {
  const agent = process.env.SWITCHROOM_AGENT_NAME
  if (!agent) return
  const io = brokerRefreshIO(agent)
  const status = await runLinearAuthCheck({
    agent,
    linearEnabled: isSelfLinearAgentEnabled,
    readBundle: io.readBundle,
    refresh: () => performLinearRefresh(io),
    onAuthDead: notifyLinearAuthDead,
    log: (s) => process.stderr.write(s),
  })
  if (status !== 'disabled' && status !== 'fresh') {
    process.stderr.write(`telegram gateway: linear-auth-watch agent=${agent} status=${status}\n`)
  }
}

/**
 * Stamp a user-facing restart reason into the clean-shutdown marker
 * (same file the SIGTERM handler writes to and the next session greeting
 * consumes). Called by /restart, /new, /reset BEFORE the
 * detached `switchroom agent restart …` CLI fires — so the agent-side
 * greeting card shows who asked ("user: /restart from chat") instead of
 * the downstream CLI's "cli: restart" default.
 *
 * Best-effort: if the write fails, the restart still proceeds. The
 * downstream CLI will fall back to its own "cli: restart" marker (the
 * CLI uses preserveExisting to avoid clobbering a fresh user marker).
 */
function stampUserRestartReason(reason: string): void {
  try {
    writeCleanShutdownMarker(GATEWAY_CLEAN_SHUTDOWN_MARKER_PATH, {
      ts: Date.now(),
      signal: 'SIGTERM',
      reason,
    })
    process.stderr.write(`telegram gateway: restart-reason.stamped reason=${JSON.stringify(reason)} path=${GATEWAY_CLEAN_SHUTDOWN_MARKER_PATH}\n`)
  } catch (err) {
    process.stderr.write(`telegram gateway: restart-reason.stamp_failed err=${(err as Error).message}\n`)
  }
}

/**
 * Fire-and-forget a detached `switchroom` CLI invocation.
 *
 * `onFailure`, if provided, is called with the child's exit code and the
 * tail of `detached-spawn.log` when the child exits non-zero BEFORE
 * ~5 seconds have passed (the rough window during which the gateway is
 * still alive and hasn't yet been SIGTERM'd by its own restart). This
 * lets us surface "agent not found in switchroom.yaml" and other
 * fail-fast CLI errors to the Telegram user instead of silently
 * swallowing them into detached-spawn.log.
 */
/**
 * Detect whether `systemd-run --user` is callable. Cached for the
 * process lifetime — the answer is essentially fixed by the host OS.
 *
 * When available, `spawnSwitchroomDetached` wraps every spawn through
 * `systemd-run --user --scope --collect` so the spawned child escapes
 * the gateway's cgroup. Without this escape, restarting the gateway
 * cgroup-kills the in-flight child mid-restart, and the agent service
 * never actually restarts (#177).
 *
 * `--scope` makes a transient scope unit (lives in its own cgroup,
 * doesn't trigger the spawn-supervised semantics of `--service`).
 * `--collect` auto-removes the unit when it exits so we don't
 * accumulate transient units.
 */
let _systemdRunPath: string | null | undefined
function resolveSystemdRunPath(): string | null {
  if (_systemdRunPath !== undefined) return _systemdRunPath
  // Try `command -v systemd-run` via execSync; on missing-binary or
  // a non-systemd box we set null and fall back to direct spawn.
  try {
    const out = execSync('command -v systemd-run 2>/dev/null', { encoding: 'utf-8' }).trim()
    _systemdRunPath = out.length > 0 ? out : null
  } catch {
    _systemdRunPath = null
  }
  return _systemdRunPath
}

/**
 * PR5 — supergroup-mode slash-command smart split (CPO #4 design).
 *
 * Classifies a slash-command response by event class and returns the
 * `message_thread_id` an outbound reply should target in supergroup
 * mode, or `undefined` when the agent isn't in supergroup-owned mode
 * (caller falls through to grammY's default `ctx.reply` which
 * routes to the originating topic).
 *
 * Three classes:
 *   - `query` (`/help`, `/status`, etc.) — follows the originating
 *     topic, identical to default `ctx.reply` behaviour.
 *   - `mutation` (`/restart`, `/update apply`) — admin alias.
 *   - `heavy` (`/logs`, `/audit`, `/upgradestatus`, `/memory <q>`)
 *     — admin alias (operational separation per CPO #4).
 *
 * Callers spread the returned topic onto their send opts:
 *
 *   await ctx.reply(text, {
 *     ...opts,
 *     ...slashCommandReplyOpts(ctx, 'heavy'),
 *   })
 *
 * Returns `{}` when no override is needed (non-supergroup, or
 * helper resolved to the originating topic). Returns
 * `{ message_thread_id: N }` otherwise.
 */
function slashCommandReplyOpts(
  ctx: Context,
  classification: 'query' | 'mutation' | 'heavy',
): { message_thread_id?: number } {
  const originThreadId = ctx.message?.message_thread_id
  const event =
    classification === 'query'
      ? ({ kind: 'command-query', originThreadId } as const)
      : classification === 'mutation'
        ? ({ kind: 'command-mutation' } as const)
        : ({ kind: 'command-heavy' } as const)
  const target = resolveAgentOutboundTopic(event)
  if (target == null) return {}
  // Avoid the spurious explicit thread_id when it would equal the
  // implicit-reply destination — keeps the wire identical to default
  // ctx.reply for the query class in supergroup mode.
  if (target === originThreadId) return {}
  return { message_thread_id: target }
}

/**
 * Detect whether `docker` is callable from this process — required by
 * `switchroom update`'s pull-images and recreate-containers steps.
 *
 * The gateway runs INSIDE the agent container (cron-fold-in / Phase 4
 * docker model), which by design has no docker binary AND no socket
 * mount. We probe both: binary on PATH (via `docker --version`) and
 * socket on disk (via existsSync). True only if BOTH are present —
 * mirroring the actual requirements `switchroom update` will hit when
 * it shells out.
 *
 * Cached: docker availability doesn't change at runtime within a
 * single container generation.
 */
let _dockerReachable: boolean | undefined
function isDockerReachable(): boolean {
  if (_dockerReachable !== undefined) return _dockerReachable
  // Cheap socket probe first — if the mount is absent, no need to
  // pay the execSync cost. Common-case fast-path on docker installs.
  if (!existsSync('/var/run/docker.sock')) {
    _dockerReachable = false
    return _dockerReachable
  }
  try {
    // -version is fast and doesn't require an actual daemon roundtrip
    // for binary-present probing. Bounded timeout in case the binary
    // exists but blocks (unlikely but defensive).
    execSync('docker --version', { stdio: 'ignore', timeout: 2000 })
    _dockerReachable = true
  } catch {
    _dockerReachable = false
  }
  return _dockerReachable
}

// @internal exported for tests — resets the docker-reachable cache so
// a test can swap underlying state and observe the new probe result.
export function _resetDockerReachableCache(): void {
  _dockerReachable = undefined
}

// hostd dispatch lives in `hostd-dispatch.ts` (extracted for testability).
// Re-export the cache-reset so existing test patterns that reach into
// gateway.ts for `_resetDockerReachableCache` find a parallel hook.
export { _resetHostdEnabledCache }

function spawnSwitchroomDetached(
  args: string[],
  onFailure?: (info: { code: number; tail: string }) => void,
): void {
  const fullArgs = SWITCHROOM_CONFIG ? ['--config', SWITCHROOM_CONFIG, ...args] : args
  const logPath = join(STATE_DIR, 'detached-spawn.log')
  let outFd: number | null = null
  try {
    mkdirSync(STATE_DIR, { recursive: true })
    outFd = openSync(logPath, 'a')
    writeFileSync(logPath, `\n[${new Date().toISOString()}] spawn ${SWITCHROOM_CLI} ${fullArgs.join(' ')}\n`, { flag: 'a' })
  } catch {}
  // Escape the gateway's cgroup via systemd-run --scope when available.
  // Without this, a gateway service restart (e.g. triggered as part of
  // the detached child's own work) cgroup-kills the child mid-flight.
  // See #177.
  const systemdRun = resolveSystemdRunPath()
  const spawnBin = systemdRun ?? SWITCHROOM_CLI
  const spawnArgs = systemdRun
    ? ['--user', '--scope', '--collect', '--quiet', '--', SWITCHROOM_CLI, ...fullArgs]
    : fullArgs
  const child = spawn(spawnBin, spawnArgs, {
    detached: true,
    stdio: outFd != null ? ['ignore', outFd, outFd] : 'ignore',
    env: { ...process.env, FORCE_COLOR: '0', NO_COLOR: '1' },
  })
  if (outFd != null) { try { closeSync(outFd) } catch {} }

  if (onFailure) {
    const started = Date.now()
    child.on('exit', (code) => {
      // Only surface "obvious-fail" exits — non-zero within 5 seconds.
      // A successful restart kills us before we'd ever see the exit
      // event, so any exit we DO observe here is almost certainly
      // fail-fast (bad agent name, bad args, missing config).
      if (code == null || code === 0) return
      if (Date.now() - started > 5000) return
      let tail = ''
      try {
        const full = readFileSync(logPath, 'utf8')
        tail = full.split('\n').slice(-30).join('\n').trim()
      } catch { /* best effort */ }
      try { onFailure({ code, tail }) } catch (err) {
        process.stderr.write(`telegram gateway: spawn onFailure handler threw: ${err}\n`)
      }
    })
    child.on('error', (err) => {
      try { onFailure({ code: -1, tail: String(err) }) } catch { /* ignore */ }
    })
  }

  child.unref()
}

/**
 * Build an `onFailure` handler that posts a user-facing error reply back
 * to the Telegram chat when a detached `switchroom` child fails fast.
 * Also clears the restart marker so the "🎛️ restarted — ready" follow-up
 * doesn't get stuck forever.
 */
function notifyDetachedFailure(
  chatId: string,
  threadId: number | null,
  label: string,
): (info: { code: number; tail: string }) => void {
  return ({ code, tail }) => {
    clearRestartMarker()
    const snippet = tail ? tail.slice(-800) : '(no output captured)'
    const text =
      `❌ **${escapeHtmlForTg(label)} failed** (exit ${code}):\n` +
      preBlock(snippet)
    // Fire-and-forget — we're off the command-handler context and don't
    // have an await to block on anyway.
    // #1075: thread-id-bearing, fire-and-forget — swallow on
    // THREAD_NOT_FOUND so a deleted topic doesn't crash the detached-
    // failure handler.
    void swallowingApiCall(
      () =>
        lockedBot.api.sendRichMessage(chatId, richMessage(text), {
          // Detached restart/update child-failure notice — status, not
          // the user's answer. Silence the open ping.
          disable_notification: true,
          ...(threadId != null ? { message_thread_id: threadId } : {}),
        }),
      {
        chat_id: chatId,
        verb: 'notifyDetachedFailure',
        ...(threadId != null ? { threadId } : {}),
      },
    )
  }
}

async function sweepBeforeSelfRestart(): Promise<void> {
  const agentDir = resolveAgentDirFromEnv()
  if (agentDir == null) return
  // #1122 PR3: pre-restart progress-card pin sweep removed with the card.
  // Status-pin: unpin every status pin we own before we hand control to the
  // restart, so a crash / interrupt / config-bounce never leaves a permanent
  // pin stuck at the top of the chat. Best-effort; the drop-on-unpin contract
  // clears the claim even if the API throws.
  try {
    await unpinAllStatusPins()
  } catch (err) {
    process.stderr.write(`telegram gateway: pre-restart status-pin sweep threw: ${(err as Error).message}\n`)
  }
  try {
    await sweepActiveReactions(
      agentDir,
      (chatId, messageId) => sendReaction(chatId, messageId, '👍' as ReactionTypeEmoji['emoji']),
      { log: (msg) => process.stderr.write(`telegram gateway: pre-restart reaction sweep — ${msg}\n`) },
    )
  } catch (err) {
    process.stderr.write(`telegram gateway: pre-restart reaction sweep threw: ${(err as Error).message}\n`)
  }
}

/**
 * Schedule a marker-safe, turn-deferred SELF-restart so a just-persisted
 * config change ACTUALLY takes effect. claude loads tools / MCP servers /
 * settings at process start, so a durable "Always allow" write is inert in
 * the running session until the next restart — the old "restart agent for
 * full effect" text asked the operator to do this by hand, and most never
 * did (so the grant didn't stick and the same prompt reappeared). This
 * completes the flow the operator already approved.
 *
 * CALLER-AGENT ONLY (an "Always allow" edits the calling agent's own
 * `agents.<self>.tools.allow`, a provably single-agent blast radius). The
 * restart fires when the CURRENT turn completes (via `pendingRestarts`),
 * never mid-turn — so the operator-approved action finishes first. If no
 * turn is in flight, it fires immediately after a short drain delay. A
 * marker is written first so the post-restart greeting lands in the chat
 * the operator tapped. Kill-switch: `SWITCHROOM_AUTORESTART_ON_GRANT=0`.
 *
 * Returns 'disabled' | 'deferred' | 'now'.
 */
function scheduleGrantRestart(
  agentName: string,
  chatId: string | number | undefined,
  threadId: number | undefined,
  reason: string,
): GrantRestartDecision {
  const decision = grantRestartDecision({
    killSwitch: process.env.SWITCHROOM_AUTORESTART_ON_GRANT,
    selfAgent: process.env.SWITCHROOM_AGENT_NAME,
    agentName,
    turnInFlight: turnInFlightForGate(),
  })
  if (decision === "disabled") return decision
  // Marker first → the post-restart greeting lands in the chat the operator
  // tapped, not the default operator DM.
  if (chatId != null) {
    writeRestartMarker({ chat_id: String(chatId), thread_id: threadId ?? null, ack_message_id: null, ts: Date.now() })
  }
  stampUserRestartReason(reason)
  if (decision === "deferred") {
    pendingRestarts.set(agentName, Date.now()) // fires at turn-complete (marker-safe)
  } else {
    // No turn to drain — restart now, after a short delay so this callback's
    // card edit flushes first.
    void sweepBeforeSelfRestart().finally(() => triggerSelfRestart(agentName, reason, 1500))
  }
  return decision
}

/**
 * Shape the `switchroom auth ...` CLI stdout into a Telegram-friendly
 * HTML block. Returns the body text AND the OAuth authorize URL (if
 * one was present in the output) so the caller can wire a tappable
 * InlineKeyboardButton in addition to the inline link.
 *
 * The URL-in-text is kept on its own line at the bottom as a fallback:
 * if the inline button ever fails to render (old client, unusual scope)
 * the user still has a copy-paste-able URL.
 */

async function runSwitchroomAuthCommand(ctx: Context, args: string[], label: string): Promise<void> {
  try {
    const output = switchroomExecCombined(args, 30000)
    const formatted = formatAuthOutputForTelegram(output)
    const keyboard = formatted.url ? buildAuthUrlKeyboard(formatted.url) : undefined
    await switchroomReply(ctx, formatted.text, { html: true, reply_markup: keyboard })
    // If this flow produced an OAuth URL, follow up with a ForceReply
    // prompt so Telegram's text-input bar shows a "Paste browser code"
    // placeholder. The user's next message (whether they 'reply' to
    // this explicitly or just type) is auto-captured by the existing
    // pendingReauthFlows intercept in the inbound-message handler.
    if (formatted.url) {
      // Channel B context rule: arm unconditionally — record that this chat
      // is awaiting an auth code paste so the inbound handler can treat the
      // next message as auth-flow-sensitive even if the pattern rule misses
      // it. Set BEFORE the ForceReply attempt so a switchroomReply throw
      // doesn't leave Channel B unarmed.
      const authChatId = String(ctx.chat!.id)
      awaitingAuthCodeAt.set(authChatId, Date.now())
      try {
        await switchroomReply(ctx, '📋 Paste the browser code here ↓', {
          reply_markup: { force_reply: true, input_field_placeholder: 'Paste browser code', selective: true },
        })
      } catch {
        // ForceReply is UX garnish — if it fails the flow still works
        // via the pending-intercept. Don't escalate.
      }
    }
  } catch (err: unknown) {
    const error = err as { status?: number; stderr?: string; message?: string }
    if (error.message?.includes('ENOENT')) { await switchroomReply(ctx, 'switchroom CLI not found.', { html: true }); return }
    if (error.message?.includes('ETIMEDOUT') || error.message?.includes('timed out')) { await switchroomReply(ctx, `${label}: timed out`); return }
    const detail = stripAnsi(error.stderr?.trim() || error.message || 'unknown error')
    await switchroomReply(ctx, `**${escapeHtmlForTg(label)} failed:**\n${preBlock(formatSwitchroomOutput(detail))}`, { html: true })
  }
}

function runVaultCli(args: string[], passphrase: string, stdinValue?: string): { ok: boolean; output: string } {
  // Suppress the #969 P3 deprecation warning on this per-spawn
  // invocation. The gateway forwarding the operator's passphrase to
  // the CLI (which in turn forwards it to the broker as the canonical
  // P1a passphrase-attestation) is intended; without this silencer the
  // warning would surface in error pre-blocks shown to the user.
  const env = {
    ...process.env,
    SWITCHROOM_VAULT_PASSPHRASE: passphrase,
    SWITCHROOM_NO_VAULT_DEPRECATION_WARNING: '1',
  }
  try {
    let result: string
    if (stdinValue !== undefined) {
      result = execFileSync(process.env.SWITCHROOM_CLI_PATH ?? 'switchroom', ['vault', ...args], { input: stdinValue, encoding: 'utf8', env, timeout: 10000 })
    } else {
      result = execFileSync(process.env.SWITCHROOM_CLI_PATH ?? 'switchroom', ['vault', ...args], { encoding: 'utf8', env, timeout: 10000 })
    }
    return { ok: true, output: result.trim() }
  } catch (err: unknown) {
    const e = err as { stdout?: string; stderr?: string; message?: string }
    return { ok: false, output: [e.stdout, e.stderr, e.message].filter(Boolean).join('\n').trim() }
  }
}

async function executeVaultOp(ctx: Context, chatId: string, op: 'list' | 'get' | 'set' | 'delete', key: string | undefined, passphrase: string, setValue: string | undefined): Promise<void> {
  if (op === 'list') {
    const r = runVaultCli(['list'], passphrase)
    if (!r.ok) { await switchroomReply(ctx, renderVaultOpFailure('list', r.output, undefined), { html: true }); return }
    const keys = r.output.split('\n').filter(Boolean)
    if (keys.length === 0) { await switchroomReply(ctx, 'Vault is empty.', { html: true }) }
    else { await switchroomReply(ctx, `**Vault keys (${keys.length}):**\n${keys.map(k => `• \`${k}\``).join('\n')}`, { html: true }) }
  } else if (op === 'get') {
    const r = runVaultCli(['get', key!], passphrase)
    if (!r.ok) { await switchroomReply(ctx, renderVaultOpFailure('get', r.output, key), { html: true }); return }
    await switchroomReply(ctx, `\`${key!}\` =\n\`${r.output}\``, { html: true })
  } else if (op === 'set') {
    if (setValue === undefined) {
      pendingVaultOps.set(chatId, { kind: 'value', op: 'set', key: key!, passphrase, startedAt: Date.now() })
      await switchroomReply(ctx, `Send the value for \`${key!}\`.`, { html: true })
      return
    }
    const r = runVaultCli(['set', key!], passphrase, setValue)
    if (!r.ok) { await switchroomReply(ctx, renderVaultOpFailure('set', r.output, key), { html: true }) }
    else { await switchroomReply(ctx, `✅ \`${key!}\` saved to vault.`, { html: true }) }
  } else if (op === 'delete') {
    const r = runVaultCli(['remove', key!], passphrase)
    if (!r.ok) { await switchroomReply(ctx, renderVaultOpFailure('delete', r.output, key), { html: true }) }
    else { await switchroomReply(ctx, `✅ \`${key!}\` removed from vault.`, { html: true }) }
  }
}

/**
 * Dispatch a short-running verb (agent_start, agent_stop, cross-agent
 * agent_restart) through hostd when available, else fall back to the
 * legacy in-container CLI shell-out.
 *
 * Why: on docker-mode hosts the agent container has no docker binary,
 * so the legacy `runSwitchroomCommand` path silently exits 127 for any
 * verb that touches compose (RFC C §1, #926). Hostd runs on the host
 * with the docker socket mounted, so the verb actually works.
 *
 * Result handling:
 *   - `not-configured` → fall back to {@link runSwitchroomCommand}.
 *     (Operator opted out; let the legacy path's existing error
 *     surfacing handle the exit-127 case.)
 *   - `completed` → reply with the stdout tail (mirrors the legacy
 *     path's formatted-output reply).
 *   - `started`   → reply with a brief "🔄 dispatched" ack. Verbs that
 *     return `started` (agent_restart) finish asynchronously on the
 *     daemon; the audit log is the canonical record.
 *   - `error` / `denied` → reply with the error tail inline. No
 *     fallback (RFC §7 hard-fail contract — operator opted in).
 */
async function dispatchShortVerbViaHostd(
  ctx: Context,
  req: HostdRequest,
  label: string,
  legacyArgs: string[],
): Promise<void> {
  const hostdResp = await tryHostdDispatch(getMyAgentName(), req)
  if (hostdResp === 'not-configured') {
    warnLegacySpawnIfHostdDisabled(req.op)
    await runSwitchroomCommand(ctx, legacyArgs, label)
    return
  }
  if (hostdResp.result === 'completed') {
    const body = hostdResp.stdout_tail?.trim() || `${label}: done (exit ${hostdResp.exit_code})`
    const formatted = formatSwitchroomOutput(stripAnsi(body))
    if (formatted) {
      await switchroomReply(ctx, preBlock(formatted), { html: true })
    } else {
      await switchroomReply(ctx, `${label}: done (no output)`)
    }
    return
  }
  if (hostdResp.result === 'started') {
    await switchroomReply(
      ctx,
      `🔄 **${escapeHtmlForTg(label)}** dispatched via hostd ` +
        `(request_id=\`${hostdResp.request_id}\`). ` +
        `Check audit log for completion.`,
      { html: true },
    )
    return
  }
  // error / denied — surface inline. RFC §7 hard-fail: no spawn fallback.
  const errBody =
    hostdResp.error ??
    hostdResp.stderr_tail ??
    hostdResp.stdout_tail ??
    '(no error tail returned)'
  await switchroomReply(
    ctx,
    `❌ **${escapeHtmlForTg(label)} failed via hostd** ` +
      `(result=${escapeHtmlForTg(hostdResp.result)}):\n` +
      preBlock(stripAnsi(errBody)),
    { html: true },
  )
}

async function runSwitchroomCommand(
  ctx: Context,
  args: string[],
  label: string,
  // PR5 — supergroup-mode classification threaded through to
  // switchroomReply. Default 'query' so existing callers (most
  // commands) preserve in-place reply behavior. /logs /audit
  // /upgradestatus /memory pass 'heavy' to route to admin alias.
  classification: 'query' | 'mutation' | 'heavy' = 'query',
  // Optional DISPLAY-ONLY transform applied to the stripped command output
  // before formatting (never mutates the underlying stored logs). /logs uses
  // this to render leading UTC ISO docker-log timestamps in local am/pm.
  transformOutput?: (raw: string) => string,
): Promise<void> {
  try {
    const stripped = stripAnsi(switchroomExec(args))
    const output = transformOutput ? transformOutput(stripped) : stripped
    const formatted = formatSwitchroomOutput(output)
    if (formatted) { await switchroomReply(ctx, preBlock(formatted), { html: true, classification }) }
    else { await switchroomReply(ctx, `${label}: done (no output)`, { classification }) }
  } catch (err: unknown) {
    const error = err as { status?: number; stderr?: string; message?: string }
    if (error.message?.includes('ENOENT')) { await switchroomReply(ctx, 'switchroom CLI not found.', { html: true, classification }); return }
    if (error.message?.includes('ETIMEDOUT') || error.message?.includes('timed out')) { await switchroomReply(ctx, `${label}: timed out`, { classification }); return }
    const detail = stripAnsi(error.stderr?.trim() || error.message || 'unknown error')
    await switchroomReply(ctx, `**${escapeHtmlForTg(label)} failed:**\n${preBlock(formatSwitchroomOutput(detail))}`, { html: true, classification })
  }
}

function switchroomExecJson<T = unknown>(args: string[]): T | null {
  try {
    const output = switchroomExec([...args, '--json'])
    return JSON.parse(stripAnsi(output)) as T
  } catch { return null }
}

interface AuthCodeJsonResult {
  completed: boolean
  tokenSaved: boolean
  tokenPath: string | null
  outcome: AuthCodeOutcome | null
  instructions: string[]
}

/**
 * Run `switchroom auth code <agent> <code> --json` with a 150 s timeout
 * (allows for the full 120 s poll budget + startup overhead).
 *
 * Returns the parsed `AuthCodeJsonResult`, or null on exec failure.
 * On exec failure, `errorText` holds a formatted error string for the caller.
 */
function execAuthCode(
  agent: string,
  code: string,
): { result: AuthCodeJsonResult; errorText: null } | { result: null; errorText: string } {
  try {
    const output = switchroomExec(['auth', 'code', agent, code, '--json'], 150_000)
    const parsed = JSON.parse(stripAnsi(output)) as AuthCodeJsonResult
    return { result: parsed, errorText: null }
  } catch (err: unknown) {
    const error = err as { stderr?: string; stdout?: string; message?: string }
    // `auth code` exits 0 even on timeout/failure (it prints instructions).
    // However if the process itself fails (ENOENT, killed, etc.) we land here.
    // Try to salvage a JSON body from stdout if present.
    const rawOut = error.stdout ?? ''
    if (rawOut.trim().startsWith('{')) {
      try {
        const parsed = JSON.parse(stripAnsi(rawOut)) as AuthCodeJsonResult
        return { result: parsed, errorText: null }
      } catch { /* fall through */ }
    }
    const detail = stripAnsi(error.stderr?.trim() || error.message || 'unknown error')
    return { result: null, errorText: detail }
  }
}

async function runSwitchroomCommandFormatted(ctx: Context, args: string[], label: string, formatter: () => string | null): Promise<void> {
  try {
    const formatted = formatter()
    if (formatted) { await switchroomReply(ctx, formatted, { html: true }); return }
    await runSwitchroomCommand(ctx, args, label)
  } catch (err: unknown) {
    const error = err as { stderr?: string; message?: string }
    const detail = stripAnsi(error.stderr?.trim() || error.message || 'unknown error')
    await switchroomReply(ctx, `**${escapeHtmlForTg(label)} failed:**\n${preBlock(formatSwitchroomOutput(detail))}`, { html: true })
  }
}

// ─── Admin-command gating middleware ─────────────────────────────────────
// When AGENT_ADMIN=false (default), admin slash commands (/agents, /logs,
// /grant, etc.) must NOT execute locally — this agent isn't admin-flagged
// and routing them through Claude burns tokens for no benefit. Reply with a
// concise "admin required" warning instead.
//
// Special case: `/restart` with no arg, or `/restart <my-agent-name>`, is
// allowed to fall through to the local bot.command('restart', …) handler so
// every agent can self-restart without admin privilege. `/restart <other>`
// is blocked just like any other admin verb.
//
// sec WS7-F2 (#1394): when AGENT_ADMIN=true this middleware is NO LONGER a
// no-op — a `block`-classified verb (fleet-admin / `/restart <other>`)
// requires OPERATOR-PRIVATE (a private chat from a strict
// `access.allowFrom` sender), because the per-command `isAuthorizedSender`
// gate treats an empty group `allowFrom` as "allow every member". Non-
// admin-verb traffic (`pass-through`, incl. `/restart`-self and all normal
// chat) is untouched and reaches `next()` exactly as before.

// ─── Bot commands ─────────────────────────────────────────────────────────

/**
 * Build the optional audit details surfaced on `/status` (Profile, Tools,
 * Skills, Limits, Channel, Memory, Version). Populated from switchroom.yaml
 * at request time so the values reflect the live config.
 *
 * Pre-#142 this content was baked into a SessionStart curl script and
 * pushed on every restart. Now it's pulled on demand via /status (#142
 * PR 3) — server-side render of the same row shape.
 *
 * Best-effort: any failure (yaml unreadable, agent missing, etc.) returns
 * undefined so /status falls back to its previous (auth + uptime + agent
 * name) shape rather than blocking the reply.
 */
/**
 * Issue #969 P2b — read recent broker-denied vault accesses for an
 * agent. Used by `/vault audit <agent>` to surface a one-tap
 * "always allow" button per unique denied key, so the operator can
 * fix a misconfigured cron without editing switchroom.yaml.
 *
 * Thin wrapper over the pure-functional parser in `./recent-denials.ts`
 * which handles the actual parse + filter + group + sort logic and is
 * unit-tested directly.
 */
function readRecentDenialsForAgent(
  agentName: string,
  windowMs: number,
  limit: number,
): RecentDenial[] {
  try {
    const auditPath = join(homedir(), '.switchroom', 'vault-audit.log')
    if (!existsSync(auditPath)) return []
    const raw = readFileSync(auditPath, 'utf8')
    return recentDenialsFromAuditLog(raw, { agentName, windowMs, limit })
  } catch {
    return []
  }
}

function buildAgentAudit(agentName: string): AgentAudit | undefined {
  try {
    const config = loadSwitchroomConfig()
    const agentConfig = config.agents?.[agentName]
    if (!agentConfig) return undefined

    // Tools allowlist — same shape as the deleted greeting:
    //   "all" / first 5 names + "+N more" / "none (default)".
    const allow = agentConfig.tools?.allow
    const tools = allow?.includes('all')
      ? 'all'
      : (allow?.slice(0, 5).join(', ') ?? 'none (default)')
        + ((allow?.length ?? 0) > 5 ? ` +${(allow?.length ?? 0) - 5} more` : '')

    const denyList = agentConfig.tools?.deny
    const toolsDeny = denyList?.length ? denyList.join(', ') : null

    // Skills cap at 6 names + "…+N more" so the row never wraps 4+
    // mobile lines (matches the deleted greeting's behavior).
    const skillsList = agentConfig.skills
    let skills: string | null = null
    if (skillsList?.length) {
      const max = 6
      skills = skillsList.length <= max
        ? skillsList.join(', ')
        : `${skillsList.slice(0, max).join(', ')}, …+${skillsList.length - max} more`
    }

    // Session limits — concatenated idle + max-turns, or "unlimited".
    const session: string[] = []
    if (agentConfig.session?.max_idle) session.push(`idle ${agentConfig.session.max_idle}`)
    if (agentConfig.session?.max_turns) session.push(`${agentConfig.session.max_turns} turns`)
    const limits = session.length ? session.join(', ') : 'unlimited (default)'

    const channel = agentConfig.channels?.telegram?.plugin ?? 'switchroom (default)'
    const memoryBank = agentConfig.memory?.collection ?? `${agentName} (default)`

    return {
      version: formatBootVersion(),
      tools,
      toolsDeny,
      skills,
      limits,
      channel,
      memoryBank,
    }
  } catch {
    // Silent failure — gateway runs in agent dirs without switchroom.yaml
    // path resolution always succeeding. /status falls back gracefully.
    return undefined
  }
}

// Build an AgentMetadata snapshot for the current agent by shelling out
// to `switchroom agent list --json` and `switchroom auth show --json`.
// Best-effort — any missing piece renders as a placeholder in the text
// templates rather than blocking the reply. RFC H retired the per-agent
// `auth status --json` shape; auth state is now derived from the
// broker's fleet-wide `ListStateData` payload via
// `buildAuthSummaryFromBroker`, with billingType pulled from the
// agent's `.claude.json` (the broker doesn't track plan tier).
// The live session-model override set by the `/model` picker (session-only)
// lives on `sessionModelSource` (setOverride/getOverride, declared beside the
// currentTurn globals). Held in gateway memory so it clears on restart, the
// same point at which claude's session reverts to the configured model —
// keeping `/status` honest without a persisted store. `resolve()` arbitrates
// freshness against the transcript-observed model (#2982 idle-switch window).

async function buildAgentMetadata(agentName: string): Promise<AgentMetadata> {
  type AgentListResp = {
    agents: Array<{
      name: string; status: string; uptime: string;
      extends?: string | null; template?: string | null;
      topic_name?: string | null; topic_emoji?: string | null;
      model?: string | null;
    }>
  }
  const list = switchroomExecJson<AgentListResp>(['agent', 'list'])
  const brokerState = switchroomExecJson<BrokerStateView>(['auth', 'show'])
  const a = list?.agents?.find(x => x.name === agentName) ?? null
  let claudeJson: ClaudeJsonView | null = null
  try {
    const agentDir = resolveAgentDirFromEnv()
    if (agentDir) {
      const raw = readFileSync(join(agentDir, '.claude', '.claude.json'), 'utf8')
      claudeJson = JSON.parse(raw) as ClaudeJsonView
    }
  } catch { /* leave null — billingType becomes null in the summary */ }
  const authSummary: AuthSummary | null = buildAuthSummaryFromBroker(
    brokerState,
    agentName,
    claudeJson,
  )
  return {
    agentName,
    model: a?.model ?? null,
    // The FRESHEST session-model observation wins (session-model-source.ts):
    // the transcript's `message.model` (ground truth for the last API call)
    // vs the #2982 /model override (the only truthful source in the idle-
    // after-switch window, before the next assistant line). Both rendered
    // through formatModelLabel for a consistent short form; an override value
    // that isn't model-shaped (an already-friendly "Opus 4.8" label) passes
    // through verbatim. Never sourced from config.
    sessionModel: (() => {
      const resolved = sessionModelSource.resolve()
      if (resolved == null) return null
      return formatModelLabel(resolved.model) ?? resolved.model
    })(),
    extendsProfile: (a?.extends ?? a?.template) ?? null,
    topicName: a?.topic_name ?? null,
    topicEmoji: a?.topic_emoji ?? null,
    uptime: a?.uptime ?? null,
    status: a?.status ?? null,
    auth: authSummary,
    audit: buildAgentAudit(agentName),
    live: await buildLiveProbeRows(agentName),
    sendGate: buildSendGateStatus(),
  }
}

/**
 * Build the `/status` send-gate block (#3084 PR 3, part3-design §6). Returns
 * `undefined` when the gate flag is OFF so `/status` renders exactly as it did
 * before the gate existed. Queued / shed totals come from the live counters;
 * open flood windows are read from the persisted sibling file (already pruned).
 */
function buildSendGateStatus(): AgentMetadata['sendGate'] {
  const s = sendGate.stats()
  if (!s.enabled) return undefined
  const openWindows = readFloodWindows(FLOOD_WINDOWS_PATH, Date.now()).map((w) => ({
    scopeKey: w.scopeKey,
    untilTs: w.untilTs,
  }))
  return {
    queued: s.global.queued,
    shed: s.global.shed,
    expired: s.global.expired,
    failedFast: s.global.failedFast,
    dropped: s.global.dropped,
    openWindows,
  }
}

/**
 * Run the boot-card probe set on demand for `/status`. Same probes,
 * different rendering contract: `/status` shows every row (silent-when-
 * healthy is for the boot card; the user explicitly asked for current
 * state here). Failures are swallowed per-probe via runAllProbes's
 * Promise.allSettled, and we filter out anything we couldn't render so
 * the reply doesn't break on a broken probe.
 */
async function buildLiveProbeRows(agentName: string): Promise<StatusProbeRow[]> {
  try {
    const { runAllProbes } = await import('./boot-card.js')
    const agentDir = resolveAgentDirFromEnv()
      ?? (process.env.TELEGRAM_STATE_DIR
        ? require('path').dirname(process.env.TELEGRAM_STATE_DIR)
        : '/tmp')
    const probes = await runAllProbes({
      agentName,
      agentSlug: agentName,
      version: formatBootVersion(),
      agentDir,
      gatewayInfo: { pid: process.pid, startedAtMs: GATEWAY_STARTED_AT_MS },
      tmuxSupervisor: process.env.SWITCHROOM_TMUX_SUPERVISOR === '1',
      dockerMode: process.env.SWITCHROOM_RUNTIME === 'docker',
      probeQuotaViaBroker: (t) => probeQuotaForBootCard(agentName, t),
    })
    const rows: StatusProbeRow[] = []
    // Render order matches the boot card's PROBE_KEYS so the two
    // surfaces tell the same story in the same order.
    const order = ['account', 'agent', 'gateway', 'quota', 'hindsight',
      'scheduler', 'broker', 'kernel', 'skills', 'connections'] as const
    for (const k of order) {
      const r = probes[k]
      if (!r) continue
      rows.push({ status: r.status, label: r.label, detail: r.detail })
    }
    return rows
  } catch (err: unknown) {
    process.stderr.write(
      `telegram gateway: /status: probe gathering failed: ${
        (err as Error)?.message ?? String(err)
      }\n`,
    )
    return []
  }
}

// RFC B §9: /approvals list|revoke is registered against the approval kernel.
// P0b (#2996): this references `bot`, so it moved to initGatewayBot() at boot —
// kept AHEAD of registerGatewayHandlers so /approvals stays before the admin-gate
// bot.use in the grammY stack (unchanged pre-P0b ordering; /approvals not gated).





// /inject — #725 Phase 2 slash-command bridge. Implementation in
// inject-handler.ts so it's unit-testable without booting the bot.
// Shared deps for the inject-backed commands. `/inject <verb>` uses the
// defaults; first-class /compact and /clear pass `open` (anyone in the chat —
// operator decision, single-tenant trust) + a `fixedVerb` so they don't need
// the `/inject` prefix.
function buildInjectDeps(opts?: { open?: boolean; fixedVerb?: string }): InjectDeps {
  return {
    isAuthorized: opts?.open ? () => true : isAuthorizedSender,
    inject: injectSlashCommandImpl,
    // accent is already inlined into the body by the handler via
    // buildAccentHeader; switchroomReply doesn't need to know about it.
    reply: async (ctx, text, replyOpts) => switchroomReply(ctx, text, { html: replyOpts?.html }),
    getAgentName: getMyAgentName,
    getArgs: opts?.fixedVerb != null ? () => opts.fixedVerb as string : getCommandArgs,
    escapeHtml: escapeHtmlForTg,
    preBlock,
    formatOutput: formatSwitchroomOutput,
  }
}


// /compact + /clear — first-class session-control commands, open to anyone in
// the chat. Both are in the INJECT_COMMANDS allowlist; they ride the same
// inject primitive as `/inject compact` / `/inject clear`.

// /model — model dashboard + switch for this agent's live session.
// Bare form: drives claude's own /model picker (open → parse → Esc,
// src/agents/model-picker.ts) to discover the live option list — no
// hardcoded model names — and renders it as an inline-keyboard menu
// with the current model + a brief quota line. A tap re-opens the
// picker fresh and applies session-only (`s`). Kill-switch
// SWITCHROOM_MODEL_MENU=0 reverts the bare form to the static v1
// text. The typed argument form rides the allowlisted inject
// primitive unchanged. Implementation in model-command.ts so it's
// unit-testable without booting the bot.
interface ModelDepsRestartContext {
  chatId: string
  threadId: number | undefined
}

function buildModelDeps(restartCtx?: ModelDepsRestartContext): ModelMenuDeps & ModelCommandDeps {
  const deps: ModelMenuDeps & ModelCommandDeps = {
    discover: (a) => discoverModels(a),
    discoverSrModels: async () => {
      // /model/info lives on the ROOT proxy (model-mapped surface), NOT the
      // Anthropic pass-through that ANTHROPIC_BASE_URL now points at
      // (<root>/anthropic). Prefer SWITCHROOM_LITELLM_BASE (the root emitted
      // by compose.ts); fall back to stripping a trailing /anthropic off
      // ANTHROPIC_BASE_URL so an agent booted from a pre-passthrough compose
      // (base_url == root) still resolves correctly.
      const base = process.env.SWITCHROOM_LITELLM_BASE
        ?? process.env.ANTHROPIC_BASE_URL?.replace(/\/anthropic\/?$/, '')
      const headers = process.env.ANTHROPIC_CUSTOM_HEADERS
      if (!base || !headers) return []
      const keyMatch = headers.match(/x-litellm-api-key:\s*Bearer\s*(\S+)/)
      if (!keyMatch) return []
      try {
        const res = await fetch(`${base.replace(/\/$/, '')}/model/info`, {
          headers: { Authorization: `Bearer ${keyMatch[1]}` },
          signal: AbortSignal.timeout(5000),
        })
        if (!res.ok) return []
        const data = (await res.json()) as { data?: Array<{ model_name: string }> }
        return (data.data ?? [])
          .map((m) => m.model_name)
          .filter((n) => n.startsWith('sr-'))
          .sort()
      } catch {
        return []
      }
    },
    isBusy: () => currentTurn !== null,
    getAgentName: getMyAgentName,
    getQuotaBrief: async () => {
      // Broker-routed probe first (authoritative), local headers as
      // fallback — same ladder as the boot card / legacy /usage.
      try {
        const probed = await probeQuotaForBootCard(getMyAgentName(), 4000)
        if (probed?.ok) return formatQuotaLine(probed.data)
      } catch { /* fall through */ }
      try {
        const agentDir = resolveAgentDirFromEnv()
        if (agentDir) {
          const local = await fetchQuota({ claudeConfigDir: join(agentDir, '.claude') })
          if (local.ok) return formatQuotaLine(local.data)
        }
      } catch { /* quota is garnish — never block the menu on it */ }
      return null
    },
    getConfiguredModel: () => {
      type AgentListResp = { agents: Array<{ name: string; model?: string | null }> }
      const data = switchroomExecJson<AgentListResp>(['agent', 'list'])
      return data?.agents?.find(a => a.name === getMyAgentName())?.model ?? null
    },
    // Feeds the switch-time #1978 assessment (thinkingEffortCaveat); see the
    // ModelCommandDeps.getConfiguredEffort doc for why doctor can't make it.
    getConfiguredEffort: () => getConfiguredEffortForPersist(),
    escapeHtml: escapeHtmlForTg,
    preBlock,
    /**
     * Graceful restart for sr-* → Claude model switch. Same mechanism as
     * the /restart command: writes a restart marker (so the post-restart
     * greeting lands in the originating chat), stamps the reason, and
     * dispatches via hostd (or legacy detached spawn as fallback).
     */
    scheduleRestart: async (reason: string) => {
      const name = getMyAgentName()
      // Debounce: mirror the /restart command's 15 s guard to prevent
      // double-dispatch on a rapid double-tap of /model <claude-alias>. This
      // path previously `return`ed silently — indistinguishable from a
      // successful dispatch — so a model switch caught in the window was a
      // silent no-op while the caller reported success. THROW a tagged error
      // so scheduleModelRelaunch can react (keep the in-flight restart's carrier,
      // tell the operator honestly) instead of falsely claiming the switch stuck.
      const existing = readRestartMarker()
      if (existing && Date.now() - existing.ts < 15_000) {
        const e = new Error('a restart is already in flight — try again in ~15s')
        ;(e as { code?: string }).code = 'restart_in_flight'
        throw e
      }
      if (restartCtx) {
        writeRestartMarker({
          chat_id: restartCtx.chatId,
          thread_id: restartCtx.threadId ?? null,
          ack_message_id: null,
          ts: Date.now(),
        })
      }
      stampUserRestartReason(reason)
      // Model-switch restarts are the APPLY-relaunch for a `.session-model`
      // carrier the caller wrote immediately above: start.sh consumes it on
      // the very next boot (this dispatch's boot), then reverts thereafter.
      // No keep/revert intent is needed — the carrier is consume-once.
      await sweepBeforeSelfRestart()
      const hostdResp = await tryHostdDispatch(name, {
        v: 1,
        op: 'agent_restart',
        request_id: hostdRequestId('gw-model-restart'),
        args: { name, force: true, reason },
      })
      if (hostdResp === 'not-configured') {
        warnLegacySpawnIfHostdDisabled('agent_restart')
        spawnSwitchroomDetached(
          ['agent', 'restart', name, '--force'],
          notifyDetachedFailure(
            restartCtx?.chatId ?? '',
            restartCtx?.threadId ?? null,
            `restart ${name}`,
          ),
        )
        return
      }
      // hostd is configured but returned an error/denied result. No restart
      // is coming, so the carrier the caller wrote must not linger to be
      // consumed by an unrelated later boot — scheduleModelRelaunch's catch
      // rolls it back on this throw.
      if (hostdResp.result !== 'started' && hostdResp.result !== 'completed') {
        clearRestartMarker()
        throw new Error(
          `hostd restart failed (result=${hostdResp.result}): ${hostdResp.error ?? '(no details)'}`,
        )
      }
    },
    /**
     * Switch TO a model that needs a relaunch (sr-* LiteLLM/OpenRouter ids,
     * which claude's native `/model` picker rejects, and the sr-to-claude
     * direction). Write the CONSUME-ONCE `.session-model` carrier (start.sh
     * applies it on the very next boot — this dispatch's apply-relaunch — and
     * deletes it, so it reverts on any subsequent restart), set the in-memory
     * session-model so /status stays honest across the restart window, then
     * run the SAME restart dispatch as scheduleRestart above.
     */
    scheduleModelRelaunch: async (model: string, reason: string) => {
      const agentDir = resolveAgentDirFromEnv()
      if (!agentDir) throw new Error('agent dir unresolvable — cannot write session-model file')
      const prevOverride = sessionModelSource.getOverride()
      const prevFileRaw = readSessionModelFileRaw(agentDir)
      writeSessionModelFile(
        agentDir,
        model,
        readConfiguredDefaultModel(agentDir) ??
          resolveMainModel(deps.getConfiguredModel() ?? undefined),
      )
      sessionModelSource.setOverride(model)
      // Diagnosability (rev 5): the applied-model is now always greppable at the
      // relaunch boundary — `grep 'gw /model relaunch scheduled'` — closing the
      // gap the debug worker flagged (the retired inject path logged nothing).
      process.stderr.write(
        `telegram gateway: gw /model relaunch scheduled agent=${getMyAgentName()} token=${model} reason=${JSON.stringify(reason)}\n`,
      )
      // A manual /model switch clears any pending premium-recovery marker so the
      // "available again" ping can't still fire after the operator switched away
      // themselves. Rev 5: this moves here (from the deleted recordTypedModelSwitch /
      // recordModelMenuSideEffects) so it fires for EVERY switch path uniformly —
      // both R5 sites collapse to this single call.
      clearPremiumRecoveryOnManualSwitch(model)
      try {
        await deps.scheduleRestart(reason)
      } catch (err) {
        // A restart already in flight OWNS the carrier we just wrote — its
        // boot will consume+apply our token, so the switch is queued, not
        // lost: keep the file + override and let the caller tell the operator
        // "~15s". Any OTHER dispatch failure means no restart is coming, so
        // roll BOTH back — a lingering carrier would lie to /status and be
        // consumed (mis-applied) by an unrelated later boot.
        if ((err as { code?: string })?.code !== 'restart_in_flight') {
          restoreSessionModelFileRaw(agentDir, prevFileRaw)
          sessionModelSource.setOverride(prevOverride)
        }
        throw err
      }
    },
    /**
     * `/model default` (rev 5): CLEAR the consume-once carrier + the in-memory
     * override, then relaunch so the LIVE session reverts to the configured
     * default. Mirrors scheduleModelRelaunch's rollback discipline (G1): on a
     * `restart_in_flight` throw keep the cleared state (the in-flight boot has no
     * carrier and reverts anyway); on any other dispatch failure restore the
     * prior carrier + override so a failed default-revert doesn't strand the
     * session in a half-cleared state.
     */
    scheduleModelDefaultRelaunch: async (reason: string) => {
      const agentDir = resolveAgentDirFromEnv()
      if (!agentDir) throw new Error('agent dir unresolvable — cannot clear session-model file')
      const prevOverride = sessionModelSource.getOverride()
      const prevFileRaw = readSessionModelFileRaw(agentDir)
      clearSessionModelFile(agentDir)
      sessionModelSource.setOverride(null)
      process.stderr.write(
        `telegram gateway: gw /model relaunch scheduled agent=${getMyAgentName()} token=(default) reason=${JSON.stringify(reason)}\n`,
      )
      clearPremiumRecoveryOnManualSwitch(null)
      try {
        await deps.scheduleRestart(reason)
      } catch (err) {
        if ((err as { code?: string })?.code !== 'restart_in_flight') {
          restoreSessionModelFileRaw(agentDir, prevFileRaw)
          sessionModelSource.setOverride(prevOverride)
        }
        throw err
      }
    },
  }
  return deps
}

function modelMenuReplyMarkup(reply: ModelMenuReply): InlineKeyboard | undefined {
  if (!reply.keyboard) return undefined
  const kb = new InlineKeyboard()
  for (const row of reply.keyboard) {
    for (const btn of row) kb.text(btn.text, btn.callback_data)
    kb.row()
  }
  return kb
}

// Rev 5 (deterministic switch): `recordTypedModelSwitch` and
// `recordModelMenuSideEffects` are RETIRED. Every switch now routes through
// `scheduleModelRelaunch` / `scheduleModelDefaultRelaunch` inside the handlers,
// which own the carrier + in-memory override writes and the premium-recovery
// clear. The sr-*→Claude special case is gone: because EVERY switch relaunches,
// the sr-* LiteLLM routing is always torn down cleanly by the boot, so there is
// no distinct transition to detect. The ACTUAL running model is reconciled at
// boot from `.active-session-model` (never from a scraped `selectedModel`).

// ─── Mid-turn ack-queue-apply-confirm for /model + /effort (#3017) ──────────
//
// See pending-session-command.ts for the contract. The busy gates ENQUEUE
// here + ACK; drainPendingSessionCommand() APPLIES the moment the agent idles
// (from the same model-idle gate that drains pendingRestarts, plus the reaper
// cap) and EDITS the ack card into the confirmation.

/**
 * Edit a queued command's ack card (chatId+messageId) into a new body,
 * dropping any inline keyboard. Best-effort — a deleted card just logs.
 * Mirrors redeliverBufferedInbound's edit-on-deliver via the shared retry
 * policy so flood-wait / not-found are handled by the standard wrapper.
 */
async function editPendingCommandCard(chatId: string, messageId: number, text: string): Promise<void> {
  try {
    await robustApiCall(
      () =>
        // allow-raw-bot-api: deferred command-card edit routed through robustApiCall (not in the THREAD_NOT_FOUND blast pattern)
        lockedBot.api.editMessageText(chatId, messageId, richMessage(hardenCardBreaks(text)), {
          reply_markup: { inline_keyboard: [] },
        }),
      { chat_id: chatId, verb: 'pending-cmd-card' },
    )
  } catch (err) {
    process.stderr.write(
      `telegram gateway: pending-command card edit failed chat=${chatId} msg=${messageId}: ${(err as Error)?.message ?? String(err)}\n`,
    )
  }
}

/**
 * Enqueue a mid-turn session command (same-kind last-write-wins; a /model and
 * a /effort coexist). If it displaces an earlier same-kind command, edit that
 * stale ack card into a "superseded" note so the operator's replaced choice is
 * never silently lost.
 */
function enqueueSessionCommand(cmd: PendingSessionCommand): void {
  const displaced = pendingSessionCommand.set(cmd)
  if (displaced) {
    void editPendingCommandCard(
      displaced.ackChatId,
      displaced.ackMessageId,
      pendingCmdSupersededText(displaced, cmd, escapeHtmlForTg),
    )
  }
  // #3018 finding 5 — enqueue/turn-end race: if the idle gate fired between
  // the busy check and this enqueue, no further turn-end will drain the slot
  // and the command would sit until the reaper cap. If the session is idle
  // NOW, kick the drain immediately (re-entrancy-guarded, no-op if a racing
  // drain already ran).
  if (!turnInFlightForGate()) void drainPendingSessionCommand()
}

/** Apply a queued typed/menu-alias model command at idle; return the reply body. */
async function applyQueuedModelCommand(cmd: PendingSessionCommand): Promise<string> {
  const deps = buildModelDeps({ chatId: cmd.chatId, threadId: cmd.threadId })
  if (cmd.origin === 'menu') {
    // Menu SELECT (mdl:s:<token>) — replay the callback handler, which now
    // relaunches through the carrier itself (rev 5: no side-effects helper, no
    // scrape). The relaunch writes its own restart marker so the post-boot card
    // lands in this chat.
    const outcome = await handleModelMenuCallback(cmd.arg, deps)
    return outcome.reply.text
  }
  // Typed (and alias/sr menu taps converted to typed at enqueue): run the real
  // handler, which relaunches through the carrier and owns all side effects.
  const reply = await handleModelCommand({ kind: 'set', model: cmd.arg }, deps)
  return reply.text
}

/** Apply a queued typed/menu effort command at idle; return the reply body. */
async function applyQueuedEffortCommand(cmd: PendingSessionCommand): Promise<string> {
  const deps = buildEffortDeps()
  if (cmd.origin === 'menu') {
    const outcome = await handleEffortMenuCallback(cmd.arg, deps)
    return outcome.reply.text
  }
  const parsed =
    cmd.arg === 'default'
      ? ({ kind: 'default' } as const)
      : ({ kind: 'set', level: cmd.arg as EffortLevel } as const)
  const reply = await handleEffortCommand(parsed, deps)
  return reply.text
}

/**
 * Re-enqueue a command the drain took but could not safely apply (a turn
 * raced in). If a NEWER same-kind command was enqueued while the drain was
 * mid-flight, the newer one wins (last-write-wins invariant) and this older
 * card is edited to superseded instead.
 */
function reEnqueueUnlessSuperseded(cmd: PendingSessionCommand): void {
  const newer = pendingSessionCommand.get(cmd.kind)
  if (newer != null) {
    void editPendingCommandCard(
      cmd.ackChatId,
      cmd.ackMessageId,
      pendingCmdSupersededText(cmd, newer, escapeHtmlForTg),
    )
    return
  }
  pendingSessionCommand.set(cmd)
}

/**
 * #3039 — execute a shutdown/restart resolution action's durable write:
 * carry a queued (typed) choice across the bounce via the boot carriers
 * (`.session-model` / `.session-effort`) instead of asking for a re-issue.
 * Returns the ack-card text to edit in (persisted vs re-issue fallback).
 */
function persistQueuedCommandForRestart(action: ShutdownResolutionAction): string {
  if (action.persist == null) return action.reissueText
  const agentDir = resolveAgentDirFromEnv()
  if (agentDir == null) return action.reissueText
  try {
    switch (action.persist) {
      case 'model': {
        // #3042 blocker 2a: this token was QUEUED, never confirmed by claude.
        // The carrier is written immediately before the bounce, so the next
        // boot IS its apply-relaunch: consume-once means a garbage token can
        // crash at most one boot before it reverts, but we still gate on
        // offline-trustable tokens (static Claude aliases, curated sr-* alias
        // targets) to avoid even that one crash-boot; anything else gets the
        // honest "couldn't verify — re-issue" card instead.
        if (!isOfflineTrustedModelToken(action.arg)) {
          return `↩️ Couldn’t verify \`${escapeHtmlForTg(action.cmd.targetLabel || action.arg)}\` as a known model without the live session — it was NOT saved. Re-issue \`/model ${escapeHtmlForTg(action.arg)}\` once the agent is back.`
        }
        const configured =
          readConfiguredDefaultModel(agentDir) ?? resolveMainModel(undefined)
        // Consume-once carrier: applied by the next boot, then reverts.
        writeSessionModelFile(agentDir, expandModelAlias(action.arg), configured)
        break
      }
      case 'clear-model':
        clearSessionModelFile(agentDir)
        break
      case 'effort':
        writeSessionEffortFile(agentDir, action.arg, getConfiguredEffortForPersist())
        break
      case 'clear-effort':
        clearSessionEffortFile(agentDir)
        break
    }
    return action.persistedText
  } catch (err) {
    process.stderr.write(
      `telegram gateway: queued-command persist-for-restart failed kind=${action.cmd.kind} arg=${action.arg}: ${(err as Error)?.message ?? String(err)}\n`,
    )
    return action.reissueText
  }
}

/**
 * The cascade-resolved thinking_effort, for `.session-effort`'s
 * configuredDefaultAtWrite. #3042 item 5: on a transient `agent list`
 * failure fall back to the scaffold default rather than null — persisting ''
 * would trip a bogus "configured default effort changed" clear+alert at the
 * next boot (start.sh bakes the same default when yaml is unset).
 */
function getConfiguredEffortForPersist(): string {
  try {
    type AgentListResp = { agents: Array<{ name: string; thinking_effort?: string | null }> }
    const data = switchroomExecJson<AgentListResp>(['agent', 'list'])
    return (
      data?.agents?.find(a => a.name === getMyAgentName())?.thinking_effort ??
      SWITCHROOM_DEFAULT_THINKING_EFFORT
    )
  } catch {
    return SWITCHROOM_DEFAULT_THINKING_EFFORT
  }
}

// Synchronous re-entrancy guard — the idle gate can fire several times per
// turn-end; the async apply must not double-dispatch before the first settles
// (mirrors compactDispatching).
let pendingCmdDraining = false

/**
 * Drain the queued session command(s) when the agent goes idle: apply each,
 * then edit its ack card into the confirmation (or a failure banner). Called
 * from the model-idle gate (turn complete), the post-enqueue idle kick, and
 * the reaper drain-cap. No-op when the slots are empty. If a restart is (or
 * becomes — a model apply can itself enqueue one) pending, the session is
 * going away — a Claude-model / effort session change would not survive, so
 * report that honestly rather than falsely confirming.
 */
async function drainPendingSessionCommand(): Promise<void> {
  if (pendingCmdDraining) return
  if (pendingSessionCommand.size === 0) return
  pendingCmdDraining = true
  try {
    // Iteration + loss-safety invariants live in drainTakenCommands
    // (pending-session-command.ts, unit-tested): a restart-pending command is
    // persisted to the boot carriers; an early stop (turn raced in / handler
    // busy-refusal) re-enqueues EVERY not-yet-applied taken command (#3042
    // blocker 1) instead of dropping the rest of the batch.
    await pendingCmdDrainTaken(pendingSessionCommand.takeAll(), {
      restartPending: () => pendingRestarts.size > 0,
      turnInFlight: () => turnInFlightForGate(),
      apply: cmd =>
        cmd.kind === 'model' ? applyQueuedModelCommand(cmd) : applyQueuedEffortCommand(cmd),
      isBusyRefusal: isBusyRefusalText,
      resolveForRestartText: cmd =>
        persistQueuedCommandForRestart(pendingCmdResolveForRestart(cmd, escapeHtmlForTg)),
      editCard: (cmd, text) => editPendingCommandCard(cmd.ackChatId, cmd.ackMessageId, text),
      reEnqueue: reEnqueueUnlessSuperseded,
      failureText: (cmd, err) =>
        `❌ Couldn’t apply the queued ${cmd.kind} switch to \`${escapeHtmlForTg(cmd.targetLabel)}\`: ${escapeHtmlForTg((err as Error)?.message ?? String(err))}`,
    })
  } finally {
    pendingCmdDraining = false
  }
}


// `/effort` — show or switch the reasoning effort for the live session.
// The effort sibling of `/model`: bare form renders a five-button menu
// (low/medium/high/xhigh/max, the live level ✅), a typed form
// `/effort <level>` sets it directly. Both ride the dedicated `applyEffort`
// driver (claude's own `/effort` REPL command, with the confirmation modal
// answered so the pane never wedges — NOT the bare inject primitive, which
// is blocklisted for `/effort` since #2471), session-scoped — boot re-pins
// the configured default via start.sh's `--effort`. Implementation in
// effort-command.ts so it's unit-testable without booting the bot.

// The live session-effort override, in memory only (#3186, session-scoped
// like /model rev 4). A confirmed live apply records here — NOT to the
// `.session-effort` carrier — so it lasts exactly until the next restart
// (start.sh's explicit `--effort <configured>` reverts it for free). Seeded
// at boot from `.active-session-effort` (the effort sibling of
// `.active-session-model`) so a queued-carrier apply-boot still shows the
// honest live level on the /effort menu.
let sessionEffortOverride: string | null = null

function buildEffortDeps(): EffortCommandDeps {
  return {
    // Session-scoped (#3186): a positively-confirmed live apply records the
    // level IN MEMORY only — no durable carrier. The `.session-effort`
    // carrier is written solely by persistQueuedCommandForRestart (a queued
    // mid-turn /effort carried across the bounce) and is consume-once at
    // boot. `/effort default` clears via clearSessionEffort below.
    applyEffort: async (agent, level) => {
      const result = await applyEffort(agent, level)
      if (result.ok) sessionEffortOverride = level
      return result
    },
    getAgentName: getMyAgentName,
    getConfiguredEffort: () => getConfiguredEffortForPersist(),
    clearSessionEffort: () => {
      sessionEffortOverride = null
      // Also drop any leftover queued-command carrier so the next boot can't
      // consume a stale level the user just cleared.
      const agentDir = resolveAgentDirFromEnv()
      if (agentDir) clearSessionEffortFile(agentDir)
    },
    getSessionEffort: () => sessionEffortOverride,
    escapeHtml: escapeHtmlForTg,
  }
}

function effortMenuReplyMarkup(reply: EffortMenuReply): InlineKeyboard | undefined {
  if (!reply.keyboard) return undefined
  const kb = new InlineKeyboard()
  for (const row of reply.keyboard) {
    for (const btn of row) kb.text(btn.text, btn.callback_data)
    kb.row()
  }
  return kb
}



// #3020: container stop lives on /agentstop (pairs with /agentstart above).
// It WAS /stop; that word now cancels the in-flight turn instead — the
// intuitive meaning for a chat-first operator.

// #3020: /stop — cancel the agent's in-flight turn (the typed sibling of the
// bare "stop" keyword and the empty-`!` interrupt; shared executeHaltNow).


// ─── /new and /reset ──────────────────────────────────────────────────────
// Start a fresh session: flush .handoff.md + .handoff-topic so the restarted
// claude session isn't primed with the prior conversation, then trigger a
// restart. MEMORY.md, workspace/, skills/ are preserved. A1/N1/C6 from the
// OpenClawification review pass all applied.
function flushAgentHandoff(agentDir: string): number {
  let removed = 0
  for (const fname of ['.handoff.md', '.handoff-topic']) {
    const p = join(agentDir, fname)
    try {
      if (existsSync(p)) { unlinkSync(p); removed++ }
    } catch (err) {
      process.stderr.write(`telegram gateway: flushAgentHandoff ${fname}: ${(err as Error).message}\n`)
    }
  }
  return removed
}

async function handleNewCommand(ctx: Context): Promise<void> {
  const kind = 'new' // /reset removed (was a pure alias); keep the string for messages
  if (!isAuthorizedSender(ctx)) return
  const name = (typeof ctx.match === "string" ? ctx.match : "").trim() || getMyAgentName()
  try { assertSafeAgentName(name) } catch { await switchroomReply(ctx, 'Invalid agent name.'); return }
  // N1: `all` passes isSelfTargetingCommand (for /restart), but /new and
  // /reset semantically require flushing each agent's handoff before
  // restarting it — only that agent's own gateway can do that. If we let
  // /new all through we'd flush ONLY this agent's handoff and restart every
  // agent, leaving the others with stale briefings.
  if (name === 'all') {
    await switchroomReply(
      ctx,
      `/${kind} only supports a single agent — “all” would leave other agents with stale handoff briefings. ` +
        `Run /${kind} from each agent’s own topic, or use \`switchroom agent restart all\` if you just want a plain restart without flushing sessions.`,
      { html: true },
    )
    return
  }
  // A1: Cross-agent /new is refused — this gateway can only flush its own
  // handoff. Silently wiping our handoff while restarting another agent is a
  // footgun.
  if (!isSelfTargetingCommand(name)) {
    await switchroomReply(
      ctx,
      `/${kind} only supports the current agent (**${escapeHtmlForTg(getMyAgentName())}**). ` +
        `To restart another agent with a fresh session, run /${kind} from its own topic, ` +
        `or use \`switchroom agent restart ${escapeHtmlForTg(name)}\`.`,
      { html: true },
    )
    return
  }
  // C6: debounce — /new and /reset are functionally self-restarts. Without
  // the same 15s marker guard /restart uses, a double-tap (because the ack
  // hasn't landed yet) would stack systemctl restarts.
  const existing = readRestartMarker()
  if (existing && Date.now() - existing.ts < 15_000) {
    await switchroomReply(
      ctx,
      `⏳ Restart of **${escapeHtmlForTg(name)}** already in progress (${Math.round((Date.now() - existing.ts) / 1000)}s ago) — ignoring duplicate /${kind}.`,
      { html: true },
    )
    return
  }
  // Flush handoff first — if we crash between here and the restart the
  // worst case is the next boot has no briefing, which is the intent anyway.
  const agentDir = resolveAgentDirFromEnv()
  const flushed = agentDir != null ? flushAgentHandoff(agentDir) : 0

  const chatId = String(ctx.chat!.id)
  const threadId = resolveThreadId(chatId, ctx.message?.message_thread_id)
  const ackText = buildNewSessionAckText(name, flushed > 0)
  let ackId: number | null = null
  // #1075: thread-id-bearing — fall back to main chat.
  try {
    const sent = await retryWithThreadFallback<{ message_id: number }>(
      robustApiCall,
      (tid) =>
        lockedBot.api.sendRichMessage(chatId, richMessage(ackText), {
          // /new /reset acknowledgement is a status notice — silence the
          // open ping (the post-restart greeting card is what matters).
          disable_notification: true,
          ...(tid != null ? { message_thread_id: tid } : {}),
        }),
      { threadId, chat_id: chatId, verb: 'new-or-reset.ack' },
    )
    ackId = sent.message_id
    if (HISTORY_ENABLED) {
      try { recordOutbound({ chat_id: chatId, thread_id: threadId ?? null, message_ids: [sent.message_id], texts: [ackText], attachment_kinds: [] }) } catch {}
    }
  } catch {}
  writeRestartMarker({ chat_id: chatId, thread_id: threadId ?? null, ack_message_id: ackId, ts: Date.now() })

  // Force-fresh-session marker: tell start.sh to skip --continue on next
  // boot so the user actually gets a new Claude session (and therefore a
  // SessionStart greeting). Flushing .handoff.md alone is not enough,
  // because start.sh auto-mode picks --continue whenever the JSONL
  // session file still exists under ~/.claude/projects/<slug>/. The
  // marker is consumed (removed) by start.sh on that one boot, so normal
  // resume behavior returns immediately after.
  if (agentDir != null) {
    try {
      writeFileSync(join(agentDir, '.force-fresh-session'), `${kind} at ${new Date().toISOString()}\n`, 'utf8')
    } catch (err) {
      process.stderr.write(`telegram gateway: failed to write force-fresh marker: ${err}\n`)
    }
  }

  // Stamp user attribution so the next greeting shows "Restarted  user:
  // /new" / "user: /reset" rather than the downstream CLI default.
  stampUserRestartReason(`user: /${kind} from chat`)
  // Session-scoped (rev 4): /new and /reset are restarts, so they revert any
  // live /model override to the configured default — no carrier to preserve.
  await sweepBeforeSelfRestart()
  const hostdResp = await tryHostdDispatch(getMyAgentName(), {
    v: 1,
    op: 'agent_restart',
    request_id: hostdRequestId(`gw-${kind}`),
    args: { name, force: true, reason: `user: /${kind} from chat` },
  })
  if (hostdResp === 'not-configured') {
    warnLegacySpawnIfHostdDisabled('agent_restart')
    spawnSwitchroomDetached(
      ['agent', 'restart', name, '--force'],
      notifyDetachedFailure(chatId, threadId ?? null, `${kind} ${name}`),
    )
    return
  }
  if (hostdResp.result === 'started' || hostdResp.result === 'completed') {
    return
  }
  clearRestartMarker()
  await switchroomReply(
    ctx,
    `❌ **${escapeHtmlForTg(kind)} ${escapeHtmlForTg(name)} failed via hostd** ` +
      `(result=${escapeHtmlForTg(hostdResp.result)}):\n` +
      preBlock(hostdResp.error ?? '(no error message)'),
    { html: true },
  )
}


// /update — host update from Telegram (#919). Default = dry-run plan
// (`switchroom update --check`); explicit `apply` triggers the real
// thing via spawnSwitchroomDetached so the gateway can be killed
// mid-flight by the recreate-containers step without orphaning the
// update. Admin-gated via ADMIN_COMMAND_NAMES.

// /upgradestatus — read-only snapshot of where this host stands (#927).
// Wraps `switchroom update --status` synchronously and posts the
// formatted output. NOT admin-gated: read-only fleet metadata is safe
// for any allowFrom user to see, and the answer "is something behind?"
// is the missing companion to /update's "trigger an update".
// (Telegram slash-commands forbid hyphens, hence /upgradestatus not
// /upgrade-status. The /upgrade alias just below redirects.)
// Alias with hyphen — Grammy doesn't allow hyphens in command names
// (Telegram's slash-command grammar excludes them) but operators are
// likely to type /upgrade-status; surface a polite redirect.

// /audit hostd — tail/filter the hostd audit log. Mirrors `/vault audit`
// in spirit (operator observability over a privileged subsystem from any
// admin DM). Admin-gated via ADMIN_COMMAND_NAMES. Reads the audit JSONL
// at ~/.switchroom/host-control-audit.log directly — no hostd RPC needed
// because the file is shared via the host bind mount on docker installs.

// ─── /approve, /deny, /pending ────────────────────────────────────────────
// Slash-command alternatives to the inline-button approval flow (useful for
// desktop-only sessions and power-users). Share pendingPermissions state
// with the button handler; emit the same `permission` IPC broadcast.
function isValidPermissionRequestId(id: string): boolean {
  return /^[a-z0-9-]{1,32}$/.test(id)
}

async function handlePermissionSlash(ctx: Context, behavior: 'allow' | 'deny'): Promise<void> {
  if (!isAuthorizedSender(ctx)) return
  const access = loadAccess()
  const senderId = String(ctx.from?.id ?? '')
  if (!access.allowFrom.includes(senderId)) {
    await switchroomReply(ctx, 'Not authorized to answer permission prompts.')
    return
  }
  const raw = (typeof ctx.match === "string" ? ctx.match : "").trim()
  let request_id = raw
  if (!request_id) {
    // Default to most-recently created pending permission. Map preserves
    // insertion order so Array.from(...).at(-1) gives us that.
    const entries = Array.from(pendingPermissions.keys())
    request_id = entries[entries.length - 1] ?? ''
  }
  if (!request_id) {
    await switchroomReply(ctx, 'No pending permission prompts right now.')
    return
  }
  // C2: sanity-check the id shape so we don't look up (or echo back)
  // arbitrary user input. Claude Code's request_ids are short alphanumeric
  // slugs; the button handler enforces /^[a-km-z]{5}$/. The slash path is
  // looser for forward compat but still rejects obvious junk.
  if (!isValidPermissionRequestId(request_id)) {
    await switchroomReply(ctx, `Invalid permission id. Expected lowercase alphanumeric / dashes up to 32 chars.`)
    return
  }
  const details = pendingPermissions.get(request_id)
  if (!details) {
    await switchroomReply(
      ctx,
      `No pending permission for id \`${request_id}\`. It may have already been answered or timed out.`,
      { html: true },
    )
    return
  }
  // Operator answered via slash ⇒ present; reset no-repeat suppression.
  clearPermissionTimeoutSuppression('operator answered via /approve|/deny')
  // #2862 — operator is present; re-offer any approvals that timed out meanwhile.
  maybePostMissedApprovalDigest('operator answered via /approve|/deny')
  // Forward to connected bridges — same IPC the button handler uses.
  dispatchPermissionVerdict({ type: 'permission', requestId: request_id, behavior })
  resumeReactionAfterVerdict()
  postPermissionResumeMessage({
    behavior,
    action: naturalAction(details.tool_name, details.input_preview),
  })
  pendingPermissions.delete(request_id)
  permCardStore.remove(request_id)
  reconcileBlockedApprovals()
  process.stderr.write(
    `[telegram gateway] slash-${behavior} request_id=${request_id} tool=${details.tool_name} by=${senderId}\n`,
  )
  const lbl = behavior === 'allow' ? '✅ Allowed' : '❌ Denied'
  const suffix = details.tool_name ? ` (\`${details.tool_name}\`)` : ''
  await switchroomReply(
    ctx,
    `${lbl}${suffix} via /${behavior} \`${request_id}\``,
    { html: true },
  )
}


// ─── Drive folder picker (RFC E §4.1) ───────────────────────────────────
// /folders — post a Telegram picker card listing this agent's top-level
// Drive folders. Tap [Allow] on a folder to grant the agent
// allow_always at doc:gdrive:folder/<id>/**; tap [Browse] to drill in.
//
// Authorisation: same dmCommandGate as the other operator slash
// commands — only allowFrom users can post-trigger.

const folderPickerCache = new FolderListCache()

function buildFolderPickerDeps(): FolderPickerHandlerDeps {
  const agentName = getMyAgentName()
  return {
    agentName,
    cache: folderPickerCache,
    fetchPage: async ({ parent_id, page_token }) => {
      const handle = await loadFromAuthBroker()
      if (handle === null) {
        throw new Error(
          `auth-broker unreachable for agent ${agentName} — is the broker container running?`,
        )
      }
      return fetchFolderPage({
        access_token: handle.access_token,
        ...(parent_id !== undefined ? { parent_id } : {}),
        ...(page_token !== undefined ? { page_token } : {}),
      })
    },
    approvalRequest: async (args) => {
      const r = await kernelApprovalRequest({
        agent_unit: args.agent_unit,
        scope: args.scope,
        action: args.action,
        approver_set: args.approver_set,
        ...(args.why !== null && args.why !== undefined ? { why: args.why } : {}),
        ...(args.ttl_ms !== null && args.ttl_ms !== undefined ? { ttl_ms: args.ttl_ms } : {}),
      })
      if (r === null || r.state === 'rate_limited') return null
      return { request_id: r.request_id }
    },
    approvalConsume: async (id) => {
      const r = await kernelApprovalConsume(id)
      return r !== null && r.consumed
    },
    approvalRecord: async (args) => kernelApprovalRecord(args),
  }
}


// /pending — list current pending permission prompts with their ids, so the
// user can target a specific one via /approve <id> or /deny <id>.
// Restricted to access.allowFrom DMs to match /approve and /deny — it
// wouldn't make sense to let a group member see which permissions are
// pending when they can't actually answer them.


// Persist-ops bundle for the legacy auto-fallback lockout file. The
// only remaining reader is `isAutoFallbackCooldownActive` (line ~2030)
// — used by the pending-restart drain cap to defer a forced restart
// stacking on top of an in-flight slot rotation. The legacy poller
// that USED to write this file was retired alongside this refactor;
// existing on-disk lockouts age out via DEFAULT_FALLBACK_COOLDOWN_MS.
const lockoutOps: LockoutPersistOps = {
  readFileSync: (p, enc) => readFileSync(p, enc),
  writeFileSync: (p, data, opts) => writeFileSync(p, data, opts),
  existsSync: (p) => existsSync(p),
  mkdirSync: (p, opts) => mkdirSync(p, opts),
  joinPath: (...parts) => join(...parts),
}

// Pinned slot-banner state (#421). One banner per gateway process,
// in the owner chat (access.allowFrom[0]). Per-topic forum support
// + multi-chat pinning are tracked as #421 follow-ups.
let pinnedBannerState: BannerState | null = null

async function refreshPinnedBanner(reason: string): Promise<void> {
  try {
    const ownerChatId = loadAccess().allowFrom[0]
    if (!ownerChatId) return
    const agentDir = resolveAgentDirFromEnv()
    if (!agentDir) return // No TELEGRAM_STATE_DIR — banner has no slot context.
    const agentName = getMyAgentName()
    const slot = currentActiveSlot(agentDir)
    pinnedBannerState = await refreshBanner({
      bot,
      ownerChatId,
      agentName,
      currentSlot: slot,
      defaultSlot: DEFAULT_SLOT,
      prevState: pinnedBannerState,
      onError: (phase, err) => {
        process.stderr.write(`telegram gateway: banner ${phase} failed (${reason}): ${err}\n`)
      },
      // Share the one per-process pin-rights negative cache with the status-pin
      // path and the stale-pin sweep (D5): the banner skips a chat already known
      // rights-less and records/clears its own pin-verb discoveries there.
      rightsCache: statusPinRightsCache,
      // Durable pin persistence into the SHARED status-pin store (distinct
      // `banner:` pinKey). persist-BEFORE-pin ordering: pending() lands before
      // the pinChatMessage call so a crash in that window is recoverable by the
      // one runStatusPinBootCleanup on next boot. Best-effort / gated no-op.
      persist: {
        pending: (chatId, messageId) =>
          persistBannerRow({ pinKey: BANNER_PIN_KEY, chatId, messageId, pending: true }),
        confirm: (chatId, messageId) =>
          persistBannerRow({ pinKey: BANNER_PIN_KEY, chatId, messageId }),
        clear: () => persistBannerRow(null),
      },
    })
  } catch (err) {
    process.stderr.write(`telegram gateway: banner refresh error (${reason}): ${err}\n`)
  }
}

/**
 * Re-entry guard + dedup window for `fireFleetAutoFallback`. The state
 * was lifted into `fleet-fallback-gate.ts` so it can be tested in
 * isolation (gateway.ts module state was unreachable from vitest). The
 * gate ALSO enforces the broker-reachability honesty contract: when the
 * broker is down, `wouldFire()` returns false so the model-unavailable
 * card stays honest instead of advertising a swap that would bail with
 * `reason=no-broker-client`.
 */
const FLEET_FALLBACK_DEDUP_MS = 30_000

/** Synchronous reachability check for the auth-broker UDS. Used by the
 *  fleet-fallback gate to keep the model-unavailable card honest: if the
 *  broker socket isn't bound, the dispatcher would bail with
 *  `reason=no-broker-client`, so `wouldFire()` should return false and
 *  the card should fall back to the manual `/auth use <label>` hint. */
function isAuthBrokerSocketReachable(): boolean {
  try {
    return existsSync(resolveAuthBrokerSocketPath())
  } catch {
    return false
  }
}

const fleetFallbackGate = createFleetFallbackGate({
  dedupMs: FLEET_FALLBACK_DEDUP_MS,
  brokerReachable: isAuthBrokerSocketReachable,
})

/**
 * #3031 PR 3 — per-chat registry of the most recent model-unavailable card
 * that promised an in-flight auto-failover. On a SUCCESSFUL swap the
 * announcement is folded into an EDIT of that card (single evolving card);
 * on every failure / no-op outcome the notice stays a separate message
 * (promise-honesty: the 2026-06-06→07 incident contract). See
 * fallback-card-collapse.ts for the decision seam.
 */
const modelUnavailableCardRegistry = createModelUnavailableCardRegistry()

/**
 * Resume-after-swap gate (auth-failover-stall fix). Owns the single-flight +
 * staleness decision for re-running the turn a mid-turn 429 killed. See
 * fleet-fallback-resume.ts. Wired into doFireFleetAutoFallback below: on a
 * 'switched' outcome we restart so the boot-resume path replays the dead turn
 * on the freshly-active account. 3h staleness mirrors the boot-resume
 * RESUME_MAX_AGE_MS failsafe (gateway boot path); single-flight stops a 429
 * storm from loop-restarting the agent.
 */
const fleetFallbackResumeGate = createFleetFallbackResumeGate({
  maxAgeMs: (() => {
    const v = Number(process.env.SWITCHROOM_RESUME_MAX_AGE_MS)
    return Number.isFinite(v) && v > 0 ? v : 10_800_000 // 3h, matches boot-resume
  })(),
})

/**
 * The start time (epoch-ms) of the most-recently-started active turn — the
 * staleness signal for the resume gate. `activeTurnStartedAt` is stamped on
 * inbound receipt (see its declaration), so the newest entry is the turn the
 * 429 just killed. Returns null when no turn is tracked (then the resume gate
 * defers staleness to the boot-resume 3h failsafe). */
function newestActiveTurnStartedAtMs(): number | null {
  let newest: number | null = null
  for (const ms of activeTurnStartedAt.values()) {
    if (newest == null || ms > newest) newest = ms
  }
  return newest
}

function wouldFireFleetAutoFallback(): boolean {
  return fleetFallbackGate.wouldFire()
}

/**
 * Fleet-wide auto-fallback dispatcher (RFC H follow-up).
 *
 * Wired from the model-unavailable card render path so a quota-out
 * event on ANY agent immediately triggers a fleet-wide swap (via
 * broker.setActive — same path /auth use takes), not the per-agent
 * legacy `runAutoFallbackCheck`. Pre-fix, the card path never called
 * any fallback machinery; the scheduled poller (60-min interval, only
 * fires on utilization headers) was the only trigger and missed
 * hard-rejection events.
 *
 * Concurrency: collapses concurrent triggers via the in-flight
 * promise above. Subsequent calls within `FLEET_FALLBACK_DEDUP_MS` of
 * a recent fire are dropped silently — the broadcast announcement is
 * the user-visible signal that the swap happened, no need to repeat.
 *
 * Fire-and-forget: never throws into the caller's flow. Posts the
 * causal-shape announcement to every chat in `loadAccess().allowFrom`
 * so the user sees the outcome inline with the original "Model
 * unavailable" card.
 */
async function fireFleetAutoFallback(
  triggerAgent: string,
  untilMs?: number,
  parsedResetAt?: Date,
  trigger?: 'rate-limit',
): Promise<void> {
  return fleetFallbackGate.fire(
    () => doFireFleetAutoFallback(triggerAgent, untilMs, parsedResetAt, trigger),
    (err) => {
      process.stderr.write(
        `telegram gateway: [fleet-fallback] error agent=${triggerAgent}: ${(err as Error)?.message ?? err}\n`,
      )
    },
  )
}

// ─── 429 throttle tier — side-effect wiring ─────────────────────────────────
// Decision + notice text live in throttle-tier.ts (pure); the SEQUENCING
// (broker mark → fleet-deduped notice → jittered retry nudge with the
// live-turn safety guards) lives in throttle-tier-wiring.ts so it is
// unit-testable with injected deps. This block only binds the real gateway
// dependencies.
const throttleTierRunner = createThrottleTierRunner({
  agentName: process.env.SWITCHROOM_AGENT_NAME ?? '',
  getBrokerClient: () =>
    getAuthBrokerClient(process.env.SWITCHROOM_AGENT_NAME ?? ''),
  listNoticeChats: () => loadAccess().allowFrom,
  sendNotice: (chat_id, markdown) => {
    // Status notice, not the user's answer — silence the ping (same posture
    // as the fleet-fallback announcement).
    void swallowingApiCall(
      // allow-raw-bot-api: wrapped in swallowingApiCall (retry policy)
      () => bot.api.sendRichMessage(chat_id, richMessage(markdown), { disable_notification: true }),
      { chat_id: String(chat_id), verb: 'throttle-tier:notify' },
    )
  },
  resumeDecide: (ts) => fleetFallbackResumeGate.decide(ts),
  newestActiveTurnStartedAtMs,
  turnInFlight: () => turnInFlightForGate(),
  deferRestartToTurnComplete: (agentName, reason) => {
    // Same lever the schedule_restart IPC uses: the restart drains at the
    // turn-complete gate (never SIGTERM-now under a live turn). Note the
    // pending-restart drain cap (PENDING_RESTART_DRAIN_CAP_MS) still bounds
    // a never-idling session — deliberate, matching scheduled restarts.
    process.stderr.write(
      `telegram gateway: [throttle-tier] restart deferred to turn-complete agent=${agentName} reason=${reason}\n`,
    )
    pendingRestarts.set(agentName, Date.now())
  },
  restartNow: (agentName, reason) => {
    triggerSelfRestart(agentName, reason)
  },
  log: (m) => process.stderr.write(`telegram gateway: ${m}\n`),
})

// ─── litellm-local 429 notice — side-effect wiring ──────────────────────────
// State machine + text + config parsing live in litellm-local-notice.ts
// (pure); the sequencing (classification guard → per-agent cooldown →
// broadcast + metric) lives in litellm-local-notice-wiring.ts so it is
// unit-testable with injected deps. This block only binds the real gateway
// dependencies. Deliberately NO broker surface: the litellm-local calm
// path's invariant is that account state is never touched.
const litellmLocalNoticeRunner = createLitellmLocalNoticeRunner({
  listNoticeChats: () => loadAccess().allowFrom,
  sendNotice: (chat_id, markdown) => {
    // Topic routing — this notice REPLACES the generic operator-event card
    // for the litellm-local classification, so it must land where that card
    // would have: supergroup-mode agents route system notifications into the
    // alerts/admin alias topic ('compact-watchdog' kind, same resolution as
    // the emitGatewayOperatorEvent broadcast loop), while DM recipients get
    // a thread-less send (topicForRecipient guards the #2096 "message
    // thread not found" misrouting class).
    const noticeTopic = resolveAgentOutboundTopic({ kind: 'compact-watchdog' })
    const noticeSupergroup = resolveAgentSupergroupChatId()
    const noticeThread = topicForRecipient({
      recipientChatId: chat_id,
      resolvedTopic: noticeTopic,
      supergroupChatId: noticeSupergroup,
    })
    // Status notice, not the user's answer — silence the ping (same posture
    // as the throttle-tier / fleet-fallback announcements).
    void swallowingApiCall(
      // allow-raw-bot-api: wrapped in swallowingApiCall (retry policy)
      () => bot.api.sendRichMessage(chat_id, richMessage(markdown), {
        disable_notification: true,
        ...(noticeThread != null ? { message_thread_id: noticeThread } : {}),
      }),
      { chat_id: String(chat_id), verb: 'litellm-local-notice:notify' },
    )
  },
  windowMs: () => parseLitellmNoticeWindowMs(loadAccess().litellmNoticeWindowMs),
  emitMetric: (event) => emitRuntimeMetric(event),
  log: (m) => process.stderr.write(`telegram gateway: ${m}\n`),
})

/**
 * Broadcast a fleet-fallback FAILURE notice to every authorized chat.
 *
 * Why this exists: the model-unavailable card renders "Auto-failover in
 * progress — see the announcement below" BEFORE the dispatcher's outcome
 * is known. When the dispatcher errors (broker down, listState throw,
 * markExhausted failure), the success announcement never lands and the
 * card's promise is broken — the 2026-06-06→07 incident sent 12 such
 * broken-promise cards while every fallback errored "set-active requires
 * admin". The admin-gating root cause is fixed (#2206), but ANY future
 * dispatcher error reproduces the broken promise. This notice closes the
 * loop deterministically: card promised an announcement → an
 * announcement ALWAYS arrives, success or failure.
 *
 * Disable with SWITCHROOM_FLEET_FALLBACK_FAILURE_NOTICE=0 (log-only,
 * pre-fix behaviour).
 */
let fallbackFailureNoticeState: FallbackFailureNoticeState = { lastSentAtMs: 0 }

/**
 * Bug 2 — per-gateway cooldown for the "All accounts blocked" card. The
 * all-blocked outcome is a no-op swap (doFireFleetAutoFallback returns false),
 * so the fleetFallbackGate dedup window never arms for it, and the ~60s
 * quota_wall_detected re-trigger would otherwise re-broadcast the identical card
 * every minute for the life of the wall. This bounds it to one card per window.
 * Reset on a successful swap so a fresh all-blocked after a recovery (a real new
 * transition) is not stale-suppressed.
 */
let fallbackAllBlockedNoticeState: FallbackAllBlockedNoticeState = { lastSentAtMs: 0 }

function broadcastFleetFallbackFailure(triggerAgent: string, reason: string): void {
  if (process.env.SWITCHROOM_FLEET_FALLBACK_FAILURE_NOTICE === '0') return
  // Notice-level cooldown (30 min, per gateway). The fleetFallbackGate's
  // dedup window only arms on SUCCESSFUL swaps, so it bounds nothing
  // here — and the card-less quota_wall_detected trigger re-fires every
  // ~60s during a wall. Without this, a persistent broker outage would
  // stream failure notices for days. See evaluateFallbackFailureNotice.
  const verdict = evaluateFallbackFailureNotice(fallbackFailureNoticeState, Date.now())
  if (!verdict.send) {
    process.stderr.write(
      `telegram gateway: [fleet-fallback] failure notice suppressed (cooldown) agent=${triggerAgent}: ${reason}\n`,
    )
    return
  }
  fallbackFailureNoticeState = verdict.next
  const access = loadAccess()
  if (access.allowFrom.length === 0) return
  const html = renderFallbackFailureNotice(triggerAgent, reason)
  for (const chat_id of access.allowFrom) {
    void swallowingApiCall(
      // allow-raw-bot-api: wrapped in swallowingApiCall (retry policy)
      () => bot.api.sendRichMessage(chat_id, richMessage(html), {}),
      { chat_id, verb: 'fleet-fallback:failure-notify' },
    )
  }
}

/**
 * Broadcast a status notice to every authorized chat (system notice posture:
 * silenced ping, wrapped send). Shared by the tier-downgrade notices below.
 */
function broadcastTierNotice(markdown: string): void {
  const access = loadAccess()
  if (access.allowFrom.length === 0) return
  for (const chat_id of access.allowFrom) {
    void swallowingApiCall(
      // allow-raw-bot-api: wrapped in swallowingApiCall (retry policy)
      () => bot.api.sendRichMessage(chat_id, richMessage(markdown), { disable_notification: true }),
      { chat_id: String(chat_id), verb: 'tier-downgrade:notify' },
    )
  }
}

/**
 * MODEL-TIER downgrade failover (second recovery tier). Consulted ONLY from the
 * `all-blocked` branch of doFireFleetAutoFallback — i.e. AFTER account-swap has
 * been tried and found no account still serving the walled premium model
 * (precedence A: account-swap first). When a PREMIUM /model override is active
 * (distinct from the configured default), downgrade to the configured default
 * and resume the dead turn via a self-restart, rather than let the turn stall.
 *
 *   - NO automatic return to the premium model. The /model override is
 *     session-scoped and in-memory only (recordTypedModelSwitch writes no
 *     carrier), so it dies on the downgrade SIGTERM. The consume-once
 *     `.session-model` carrier written here targets the CONFIGURED DEFAULT:
 *     start.sh applies+deletes it on the resume boot, and every later restart
 *     also boots the default. The premium tier is never restored on its own —
 *     the user must re-issue `/model <premium>`, which the notice says plainly.
 *   - Effort is NATIVE: no `.session-effort` carrier is written, so the restart
 *     sheds any live /effort override and the downgraded default boots at the
 *     configured `thinking_effort` (#1978 / thinking-effort-risk.ts).
 *   - Loop-bounded by the NATURAL on-default guard: after the downgrade boot the
 *     session runs the configured default (override gone), so a re-entry returns
 *     `skip` ('on-default') and never re-downgrades — even if the default is
 *     itself walled (then the normal all-blocked card fires, no loop). Pacing
 *     reuses the fleetFallbackResumeGate single-flight + 3h staleness.
 *
 * Returns:
 *   'downgraded'      — carrier written, latch armed, restart fired; caller must
 *                       NOT also emit the all-blocked give-up card (we are
 *                       recovering, not giving up).
 *   'restart-pending' — a resume restart was ALREADY armed in this process (a
 *                       concurrent turn's downgrade or account-swap); that
 *                       restart replays the interrupted turn, so caller must NOT
 *                       emit a give-up card (avoids the contradictory "could not
 *                       be recovered" race).
 *   'skip'            — not applicable (on the configured default, unresolved
 *                       default, or the turn is too stale to resume); caller
 *                       falls through to the all-blocked card.
 */
function maybeTierDowngrade(triggerAgent: string): 'downgraded' | 'restart-pending' | 'skip' {
  // Thin adapter: the order-sensitive glue lives in runTierDowngrade
  // (tier-downgrade-wiring.ts) behind injected deps so it is unit-testable
  // without importing the gateway. This wires the real seams.
  return runTierDowngrade(triggerAgent, {
    getAgentDir: () => resolveAgentDirFromEnv() ?? null,
    getConfiguredDefault: () => {
      const dir = resolveAgentDirFromEnv()
      if (!dir) return null
      return resolveMainModel(readConfiguredDefaultModel(dir) ?? undefined)
    },
    getSessionOverride: () => sessionModelSource.getOverride(),
    resolve: (t) => resolveMainModel(t),
    // PEEK the resume gate WITHOUT arming (single-flight within this process +
    // 3h staleness), the same gate the account-swap resume path uses.
    peekResumeGate: () => fleetFallbackResumeGate.peek(newestActiveTurnStartedAtMs()),
    writeCarrier: (dir, toModel, cfg) => writeSessionModelFile(dir, toModel, cfg),
    armResumeGate: () => fleetFallbackResumeGate.arm(),
    // Records the DROPPED premium token + the notice's allowFrom chats; start.sh
    // never consumes `.premium-recovery`, so it survives the self-restart.
    writeRecoveryMarker: (dir, premiumModel) => {
      const chats = loadAccess().allowFrom.map((c) => String(c))
      if (chats.length > 0) writePremiumRecoveryFile(dir, premiumModel, chats)
    },
    broadcastNotice: (md) => broadcastTierNotice(md),
    selfRestart: (agent) => triggerSelfRestart(agent, 'tier-downgrade-resume'),
    selfAgent: (t) => process.env.SWITCHROOM_AGENT_NAME ?? t,
    log: (msg) => process.stderr.write(`telegram gateway: ${msg}\n`),
  })
}

/**
 * "Premium model recovered" ping (tier-downgrade companion). Consulted from the
 * gateway's existing `runQuotaWatch` tick (every 15 min, on the cheap
 * `list-state` IPC read it already does — NO new poller, NO broker change).
 * When a `.premium-recovery` marker is pending (a downgrade dropped a premium
 * `/model` selection fleet-wide) AND the broker's live-authoritative per-account
 * eligibility shows the premium tier servable again — at least one account
 * neither `exhausted` nor `premium_walled` — fire EXACTLY ONE ping to the
 * recorded chats with a one-tap "switch back" button, then consume the marker.
 *
 * DETERMINISTIC: `exhausted` / `premium_walled` are the broker's own verdicts
 * (`isAccountExhausted` / `isAccountPremiumWalled` → `isModelTierWalled`, a pure
 * timestamp compare). No model judgement, no clock of our own.
 *
 * AT-MOST-ONCE: a fleet-wide `claim-notification` gates against a bounce or a
 * concurrent tick, and the marker is cleared BEFORE the send (never-storm). The
 * button routes through the SAME session-scoped `/model` apply path as the
 * model menu (`mdl:alias:<premium>` → handleModelMenuCallback +
 * recordModelMenuSideEffects) — it does not bypass it.
 */
async function maybePremiumRecoveryPing(
  brokerClient: NonNullable<Awaited<ReturnType<typeof getAuthBrokerClient>>>,
  accounts: ReadonlyArray<{ exhausted: boolean; premium_walled?: boolean }>,
): Promise<void> {
  // Thin adapter: the order-sensitive never-storm glue lives in
  // runPremiumRecoveryPing (premium-recovery-wiring.ts) behind injected deps so
  // it is unit-testable without importing the gateway. This wires the real seams
  // (marker FS, fleet claim, send) — behaviour is preserved exactly.
  return runPremiumRecoveryPing({
    getAgentDir: () => resolveAgentDirFromEnv() ?? null,
    readMarker: (dir) => readPremiumRecoveryFile(dir),
    clearMarker: (dir) => clearPremiumRecoveryFile(dir),
    getAgent: () => getMyAgentName(),
    // The pure recovery predicate, bound to THIS tick's live per-account
    // eligibility (the broker's own verdicts; `premium_walled` may be absent).
    decide: () =>
      decidePremiumRecovery({
        hasMarker: true,
        accounts: accounts.map((a) => ({
          exhausted: a.exhausted,
          premiumWalled: a.premium_walled === true,
        })),
      }).fire,
    // Fail-open (claimQuotaNotification returns true on any broker error) — a
    // convenience ping degrades to at-least-once, never lost.
    claimNotification: (key) => claimQuotaNotification(brokerClient, key),
    fallbackChats: () => loadAccess().allowFrom.map((c) => String(c)),
    sendToChat: (chat_id, ping, keyboard) => {
      void swallowingApiCall(
        // allow-raw-bot-api: wrapped in swallowingApiCall (retry policy)
        () =>
          bot.api.sendRichMessage(chat_id, richMessage(ping.text), {
            disable_notification: true,
            reply_markup: keyboard,
          }),
        { chat_id: String(chat_id), verb: 'premium-recovery:notify' },
      )
    },
    log: (msg) => process.stderr.write(`telegram gateway: ${msg}\n`),
  })
}

/**
 * Clear a pending premium-recovery marker when the user MANUALLY re-selects the
 * dropped premium model before the recovery ping fires — no stale "available
 * again" ping after they've already switched back. Called from every `/model`
 * apply chokepoint (typed + menu/callback). Matches on the canonicalized token
 * so an alias vs resolved-id spelling of the same model still clears it.
 */
function clearPremiumRecoveryOnManualSwitch(appliedToken: string | null | undefined): void {
  if (appliedToken == null || appliedToken.length === 0) return
  const agentDir = resolveAgentDirFromEnv()
  if (!agentDir) return
  const marker = readPremiumRecoveryFile(agentDir)
  if (marker == null) return
  if (resolveMainModel(appliedToken) === resolveMainModel(marker.premiumModel)) {
    clearPremiumRecoveryFile(agentDir)
    process.stderr.write(
      `telegram gateway: [premium-recovery] marker cleared — user manually re-issued /model ${marker.premiumModel}\n`,
    )
  }
}

/** Returns true iff the dispatcher actually performed a swap (and the
 *  user-visible announcement was broadcast). False on no-op /
 *  error / idempotent-skip — caller uses this to decide whether to
 *  arm the post-fire suppression window. */
async function doFireFleetAutoFallback(
  triggerAgent: string,
  untilMs?: number,
  parsedResetAt?: Date,
  trigger?: 'rate-limit',
): Promise<boolean> {
  try {
    const client = await getAuthBrokerClient(triggerAgent)
    if (!client) {
      process.stderr.write(
        `telegram gateway: [fleet-fallback] skipped agent=${triggerAgent} reason=no-broker-client\n`,
      )
      // The model-unavailable card may have promised an announcement —
      // keep the promise even though nothing could run.
      broadcastFleetFallbackFailure(triggerAgent, 'auth-broker unreachable (no client).')
      return false
    }
    const state = await client.listState()
    // Probe live quota via the broker (#1336). Pre-fix this read
    // credentials.json off the agent HOME, which is never populated
    // post-RFC-H — every account looked "no credentials" and the
    // fallback logic rolled blindly. Broker-routed probes use the
    // canonical stored tokens.
    const probeResp = state.accounts.length > 0
      ? await client.probeQuota(state.accounts.map((a) => a.label)).catch(() => ({ results: [] }))
      : { results: [] }
    const quotas = state.accounts.map((a) => {
      const hit = probeResp.results.find((r) => r.label === a.label)
      return hit?.result ?? { ok: false as const, reason: 'broker returned no result for account' }
    })
    const tz = process.env.SWITCHROOM_TIMEZONE ?? process.env.TZ ?? 'UTC'
    const outcome = await runFleetAutoFallback({
      state,
      quotas,
      // Non-admin swap: mark-exhausted derives the account from THIS agent's
      // own identity and rolls the fleet to the next fallback. Replaces the
      // admin-gated client.setActive(), which 403'd ("set-active requires
      // admin") for every non-admin agent — i.e. the whole production fleet —
      // so auto-fallback only ever worked when an admin agent happened to be
      // the one that 429'd. The manual /auth button stays on set-active (the
      // operator is explicitly choosing, and is admin); only this automatic
      // path moves to the non-admin verb.
      failover: async () => {
        // BOTH paths now pass a resolved `untilMs` via resolveExhaustUntil
        // (never undefined): the rate-limit-MENU path threads the parsed weekly
        // reset, and the 429 inference path threads parseResetTime's value or
        // the +7d floor when it's a weekly wall it can't parse. So a
        // weekly-capped account is never re-probed (and re-wedged) within the
        // broker's ~5h default.
        const r = await client.markExhausted(untilMs)
        return { rolledTo: r.rolledTo ?? null, rolled: r.rolled }
      },
      triggerAgent,
      tz,
      // Enriched card (429 throttle tier): the RAW reset parsed from the
      // error prose, so the announcement names when the old account frees
      // even when its live probe returned nothing.
      parsedResetAt,
      // Throttle-tier escalation: a terminal transient 429 with a long
      // parsed reset NEGATES the usage-limit reading, so the old account's
      // utilization probe typically classifies healthy — the idempotency
      // guard would self-cancel the swap ("probed healthy / Stale event?").
      // Trust the terminal parsed-reset signal over the utilization probe.
      rateLimitTrigger: trigger === 'rate-limit',
    })
    process.stderr.write(
      `telegram gateway: [fleet-fallback] outcome=${outcome.kind} agent=${triggerAgent}` +
        (outcome.kind === 'switched' ? ` old=${outcome.oldLabel} new=${outcome.newLabel}` : '') +
        '\n',
    )
    // Bug 2 — the all-blocked card is a no-op outcome, so the gate's dedup
    // window never arms for it and the ~60s quota_wall_detected re-trigger would
    // re-broadcast the identical card every minute. Gate it behind a per-gateway
    // cooldown; a successful swap resets the window so a later (genuinely new)
    // all-blocked still emits promptly.
    if (outcome.kind === 'switched') {
      fallbackAllBlockedNoticeState = { lastSentAtMs: 0 }
    } else if (outcome.kind === 'all-blocked') {
      // ── Second recovery tier: MODEL-TIER downgrade (precedence A) ──────────
      // Account-swap just came back all-blocked (no account still serves the
      // walled model). Before giving up, if a PREMIUM /model override is active,
      // downgrade to the configured default and resume the dead turn rather than
      // stall. Only reachable here — a `switched` outcome never enters this
      // branch, so a model throttled on one account is always recovered by
      // account-swap first, never by a downgrade. Loop-bounded by the natural
      // on-default guard; effort revert is native (see maybeTierDowngrade).
      const tier = maybeTierDowngrade(triggerAgent)
      if (tier === 'downgraded' || tier === 'restart-pending') {
        // Either this turn armed a downgrade restart, or a concurrent turn
        // already armed a resume restart. Do NOT emit the all-blocked give-up
        // card — a restart is coming that replays the interrupted turn.
        return false
      }
      const verdict = evaluateAllBlockedNotice(fallbackAllBlockedNoticeState, Date.now())
      if (!verdict.send) {
        process.stderr.write(
          `telegram gateway: [fleet-fallback] all-blocked card suppressed (cooldown) agent=${triggerAgent}\n`,
        )
        return false
      }
      fallbackAllBlockedNoticeState = verdict.next
    }
    // Post the announcement to every authorized chat. Mirrors the
    // operator-event broadcast pattern (line ~2290) — DM-only opts
    // (no message_thread_id) so THREAD_NOT_FOUND can't fire here;
    // wrap in swallowingApiCall anyway per the codebase rule.
    const access = loadAccess()
    if (access.allowFrom.length === 0) return outcome.kind === 'switched'
    // Account-switch / all-blocked announcement is a system status notice,
    // not the user's answer — silence the open ping.
    const opts = { disable_notification: true }
    for (const chat_id of access.allowFrom) {
      // #3031 PR 3 — collapse: on a SUCCESSFUL swap, fold the announcement
      // into an EDIT of the model-unavailable card this gateway just sent to
      // this chat (single evolving card). One-shot `take` clears the record
      // either way. Every non-switched outcome that REACHES this loop — and
      // any edit failure — falls through to the pre-fix separate send.
      // Known PRE-EXISTING hole, unchanged by the collapse (#3035 review,
      // finding 2): the all-blocked cooldown early-return above exits before
      // this loop, so a cooldown-suppressed all-blocked REPEAT delivers
      // neither edit nor message even when a promising card exists. The
      // first all-blocked card of a window does arrive and answers the
      // promise; only the repeats inside the 30-min window are silent.
      const card = modelUnavailableCardRegistry.take(String(chat_id), Date.now())
      if (decideAnnouncementDelivery(outcome.kind, card) === 'edit' && card) {
        try {
          // allow-raw-bot-api: guarded edit; failure falls through to the wrapped send below
          await bot.api.editMessageText(
            chat_id,
            card.messageId,
            richMessage(foldAnnouncementIntoCard(card.text, outcome.announcement)),
            {},
          )
          continue
        } catch (err) {
          process.stderr.write(
            `telegram gateway: [fleet-fallback] card edit failed chat=${chat_id} — sending announcement separately: ${(err as Error)?.message ?? err}\n`,
          )
        }
      }
      void swallowingApiCall(
        // allow-raw-bot-api: wrapped in swallowingApiCall (retry policy)
        () => bot.api.sendRichMessage(chat_id, richMessage(outcome.announcement), opts),
        { chat_id, verb: 'fleet-fallback:notify' },
      )
    }
    // ── Resume the dead turn (auth-failover-stall fix) ──────────────────────
    // A mid-turn 429 killed a turn; the swap above moved the fleet to a healthy
    // account, but that only takes effect on the NEXT claude invocation. Re-run
    // the dead turn via triggerSelfRestart: the boot-resume path (gateway boot,
    // findLatestTurnIfInterrupted → buildResumeInterruptedInbound) replays the
    // LATEST interrupted turn on the freshly-active account. We restart rather
    // than redeliver because the failed inbound was already DELIVERED (the turn
    // started, then the model 429'd) so it is NOT in pendingInboundBuffer —
    // redeliverBufferedInbound would find nothing. Guards live in
    // fleetFallbackResumeGate: single-flight (a 429 storm cannot loop-restart)
    // + 3h staleness (an ancient interrupted turn is not resurrected). Only
    // reached on 'switched'; all-blocked / no-op outcomes never get here, so the
    // all-blocked cooldown path above is preserved.
    if (outcome.kind === 'switched') {
      const verdict = fleetFallbackResumeGate.decide(newestActiveTurnStartedAtMs())
      if (verdict === 'resume') {
        const selfAgent = process.env.SWITCHROOM_AGENT_NAME ?? triggerAgent
        process.stderr.write(
          `telegram gateway: [fleet-fallback] resuming dead turn via self-restart ` +
          `agent=${selfAgent} (swap ${outcome.oldLabel}→${outcome.newLabel})\n`,
        )
        triggerSelfRestart(selfAgent, 'fleet-fallback-resume')
      } else {
        process.stderr.write(
          `telegram gateway: [fleet-fallback] resume suppressed (${verdict}) agent=${triggerAgent}\n`,
        )
      }
    }
    return outcome.kind === 'switched'
  } catch (err) {
    process.stderr.write(
      `telegram gateway: [fleet-fallback] error agent=${triggerAgent}: ${(err as Error)?.message ?? err}\n`,
    )
    // Keep the card's "see the announcement below" promise on the error
    // path — the 06-06→07 incident sent 12 cards whose promised
    // announcement never arrived because this catch was log-only.
    broadcastFleetFallbackFailure(triggerAgent, (err as Error)?.message ?? String(err))
    return false
  }
}

/**
 * Credit-exhaustion watcher loop body (#348). Reads the agent's
 * `.claude.json` for `cachedExtraUsageDisabledReason`, evaluates the
 * transition against the last-notified state, and emits a Telegram
 * message via the existing access.allowFrom path when the state
 * crosses a fatal-billing boundary.
 *
 * Idempotent: if the state hasn't changed since the last check, no
 * message is sent. State persists across gateway restarts via
 * `<stateDir>/credits-watch.json` so a restart inside an out-of-credits
 * window doesn't re-spam the user.
 */
async function runCreditWatch(): Promise<void> {
  const agentDir = resolveAgentDirFromEnv()
  if (!agentDir) return // No TELEGRAM_STATE_DIR — no agent context to watch.
  const agentName = getMyAgentName()
  const claudeConfigDir = join(agentDir, '.claude')
  const stateDir = STATE_DIR
  const reason = readClaudeJsonOverage(claudeConfigDir)
  const prev = loadCreditState(stateDir)
  const decision = evaluateCreditState({
    agentName,
    currentReason: reason,
    prev,
    now: Date.now(),
    // Subscription-only: empty by default → extra-usage-off never alarms.
    // Opt back in via SWITCHROOM_CREDITS_WATCH_FATAL_REASONS. See credits-watch.ts.
    fatalReasons: resolveCreditWatchFatalReasons(process.env),
  })
  if (decision.kind === 'skip') {
    return
  }
  // Notify path. Send to all configured allowFrom chats — the
  // assumption mirrors auto-fallback's notification routing.
  const access = loadAccess()
  for (const chat_id of access.allowFrom) {
    // Credit-watch notify — best-effort. Wrap via swallowingApiCall so
    // flood-wait / deleted-chat / not-found surface as a stderr log
    // rather than a thrown exception that aborts the loop and leaves
    // half the allowFrom chats unnotified. Matches the wrapping
    // contract enforced by scripts/check-bot-api-wrapping.sh (#1075).
    await swallowingApiCall(
      () =>
        bot.api.sendRichMessage(chat_id, richMessage(decision.message), {
          // Credit/quota warning is a system status notice — silence the
          // open ping (the user isn't waiting to tap anything).
          disable_notification: true,
        }),
      { chat_id, verb: 'credit-watch.notify' },
    )
  }
  // Persist state regardless of whether send succeeded — losing a
  // notify is bad, but re-spamming on every poll tick is worse.
  try {
    saveCreditState(stateDir, decision.newState)
  } catch (err) {
    process.stderr.write(`telegram gateway: credit-watch state persist failed: ${err}\n`)
  }
}

/**
 * Quota threshold-tier push loop body (#E4). Reads the broker's in-memory
 * cached utilization (populated by previous probeQuota calls from /auth,
 * auto-fallback, and boot cards) via `listState.accounts[].last_quota`.
 * Classifies each account via classifyHealth, and fires one Telegram message
 * per healthy ↔ throttling transition (edge-triggered, not level-triggered).
 * Does NOT fire on healthy → blocked or blocked → healthy — credits-watch.ts
 * owns those.
 *
 * Probe discipline:
 *   - Steady-state polls: ONE broker `listState` IPC call only (no network).
 *   - Accounts with no cached snapshot (null last_quota): skipped silently
 *     (classifyHealth returns 'unknown'). Cache populates from /auth, boot
 *     card, and auto-fallback probes in normal use.
 *   - State transition detected: ONE targeted `probeQuota` call for ONLY the
 *     crossing account, immediately before sending the notification, to get
 *     fresh numbers for the message body. All other steady-state accounts
 *     are not probed.
 *
 * This replaces the previous implementation that called probeQuota for ALL
 * accounts unconditionally on every 15-minute poll (~768 live Anthropic
 * network calls/day for an 8-account fleet). The corrected version makes
 * 0 network calls on steady-state polls and at most 1 call per crossing
 * event (which is also when we need to notify the user anyway).
 *
 * State persists across restarts via `<stateDir>/quota-watch.json`.
 * Mirrors runCreditWatch's structure and notification routing.
 */

/**
 * Ask the broker for the fleet-wide dedup claim on one notification key.
 * FAIL-OPEN on any error: a broker that predates the `claim-notification`
 * op (skewed rollout) rejects at the protocol layer, and a transient IPC
 * failure must degrade to duplicated notifications, never dropped ones.
 */
async function claimQuotaNotification(
  brokerClient: NonNullable<Awaited<ReturnType<typeof getAuthBrokerClient>>>,
  key: string,
): Promise<boolean> {
  try {
    const res = await brokerClient.claimNotification(key, QUOTA_WATCH_CLAIM_WINDOW_MS)
    return res.granted
  } catch (err) {
    process.stderr.write(`telegram gateway: quota-watch: claim failed (fail-open): ${err}\n`)
    return true
  }
}

async function runQuotaWatch(opts: { bootTick?: boolean } = {}): Promise<void> {
  const agentName = getMyAgentName()
  const stateDir = STATE_DIR
  const bootTick = opts.bootTick ?? false
  // Hardening knobs (2026-06-09 incident: fleet bounce released stale
  // recovery latches on all 11 agents at once → 26 duplicate sends).
  // See QuotaWatchTuning in quota-watch.ts for the env contract.
  const tuning = resolveQuotaWatchTuning(process.env)

  // Read broker state. The listState response now includes last_quota
  // per account — the broker's in-memory cache from previous probeQuota
  // calls. This is a local IPC call: no network, no Anthropic contact.
  const brokerClient = await getAuthBrokerClient(agentName)
  if (!brokerClient) {
    process.stderr.write('telegram gateway: quota-watch: broker client unavailable — skipping\n')
    return
  }

  let listStateData: Awaited<ReturnType<typeof brokerClient.listState>>
  try {
    listStateData = await brokerClient.listState()
  } catch (err) {
    process.stderr.write(`telegram gateway: quota-watch: listState failed: ${err}\n`)
    return
  }

  if (!listStateData.accounts || listStateData.accounts.length === 0) {
    return // No accounts — nothing to watch.
  }

  // Premium-model recovery ping (tier-downgrade companion). Reuses THIS tick's
  // list-state read (no extra IPC): if a downgrade left a `.premium-recovery`
  // marker and the broker now shows the premium tier servable again, ping once
  // with a one-tap switch-back button. At-most-once + fleet-claim-deduped.
  await maybePremiumRecoveryPing(brokerClient, listStateData.accounts).catch((err) => {
    process.stderr.write(
      `telegram gateway: [premium-recovery] ping check failed (non-fatal): ${(err as Error)?.message ?? err}\n`,
    )
  })

  // Build AccountSnapshot[] from cached broker state only — no live probe.
  // Accounts with null last_quota produce quota=null snapshots; classifyHealth
  // returns 'unknown'; evaluateQuotaWatchAccount skips — no false alarms.
  const snapshots = buildSnapshotsFromCachedState(listStateData)

  // Load persisted per-account state.
  let watchState = loadQuotaWatchState(stateDir)
  const now = Date.now()
  const access = loadAccess()

  // Fleet-wide all-exhausted check FIRST — must run before the per-account
  // early-return below. When every account is exhausted, the per-account loop
  // produces only 'blocked' skips → pendingTransitions empty → early return;
  // so this fleet-level alert (the one the trigger-based all-blocked card
  // misses during quiet periods / for the consumer+cron paths) would never
  // fire if placed after. Authoritative source: broker `exhausted` flags.
  {
    const fleetPrev = watchState[FLEET_ALL_EXHAUSTED_KEY] ?? emptyAccountState()
    const fleetDecision = evaluateFleetAllExhausted({
      accounts: listStateData.accounts,
      prev: fleetPrev,
      now,
      // #2478: the same staleness ceiling the per-account loop uses. Gates the
      // `entered` alert behind live corroboration so a probe blackout's stale
      // marks can't false-fire 🔴 All accounts exhausted.
      tuning,
    })
    if (fleetDecision.kind === 'notify') {
      for (const chat_id of access.allowFrom) {
        // Fleet-level dedup: all 11 gateways detect this same edge within
        // one poll cycle — only the broker-claim winner sends per chat.
        if (tuning.fleetDedup) {
          const granted = await claimQuotaNotification(
            brokerClient,
            buildQuotaClaimKey(FLEET_ALL_EXHAUSTED_KEY, fleetDecision.transition, chat_id),
          )
          if (!granted) {
            process.stderr.write(
              `telegram gateway: quota-watch: fleet-all-exhausted claim denied chat=${chat_id} — another agent notified\n`,
            )
            continue
          }
        }
        await swallowingApiCall(
          () =>
            bot.api.sendRichMessage(chat_id, richMessage(fleetDecision.message), {
              // Quota status notice — silence the open ping.
              disable_notification: true,
            }),
          { chat_id, verb: 'quota-watch.fleet-all-exhausted' },
        )
      }
      // Persist immediately — the per-account early-return path below would
      // otherwise drop this flag change (edge-trigger would re-fire next poll).
      watchState = patchQuotaWatchState(watchState, FLEET_ALL_EXHAUSTED_KEY, fleetDecision.newState)
      try {
        saveQuotaWatchState(stateDir, watchState)
      } catch (err) {
        process.stderr.write(`telegram gateway: quota-watch: fleet-state save failed: ${err}\n`)
      }
      process.stderr.write(
        `telegram gateway: quota-watch: fleet all-exhausted ${fleetDecision.transition}\n`,
      )
    }
  }

  // #3031 PR 3 — broker-initiated proactive roll announcement. The broker's
  // fleetQuotaProbeTick roll previously emitted stdout + audit only (zero
  // operator Telegram visibility); it now records `last_fleet_roll` in
  // list-state. Edge-triggered on the roll's `at` timestamp; deduped across
  // the multi-gateway fan-in via the same broker claim-notification verb the
  // per-account pushes use — one card per roll per chat, fleet-wide.
  {
    const rollPrev = watchState[FLEET_ROLL_ANNOUNCE_KEY] ?? emptyAccountState()
    const rollDecision = evaluateFleetRollAnnounce({
      roll: listStateData.last_fleet_roll ?? null,
      prev: rollPrev,
      now,
    })
    if (rollDecision.kind === 'notify') {
      for (const chat_id of access.allowFrom) {
        if (tuning.fleetDedup) {
          const granted = await claimQuotaNotification(
            brokerClient,
            buildQuotaClaimKey(
              FLEET_ROLL_ANNOUNCE_KEY,
              String(listStateData.last_fleet_roll!.at),
              chat_id,
            ),
          )
          if (!granted) {
            process.stderr.write(
              `telegram gateway: quota-watch: fleet-roll claim denied chat=${chat_id} — another agent notified\n`,
            )
            continue
          }
        }
        await swallowingApiCall(
          () =>
            bot.api.sendRichMessage(chat_id, richMessage(rollDecision.message), {
              // Reassuring status notice, not the user's answer — silent.
              disable_notification: true,
            }),
          { chat_id, verb: 'quota-watch.fleet-roll' },
        )
      }
      // Persist immediately — mirrors the all-exhausted block's rationale:
      // a per-account early return below must not drop the latch advance.
      watchState = patchQuotaWatchState(watchState, FLEET_ROLL_ANNOUNCE_KEY, rollDecision.newState)
      try {
        saveQuotaWatchState(stateDir, watchState)
      } catch (err) {
        process.stderr.write(`telegram gateway: quota-watch: fleet-roll state save failed: ${err}\n`)
      }
      process.stderr.write(
        `telegram gateway: quota-watch: announced broker fleet roll ` +
          `${listStateData.last_fleet_roll!.from} → ${listStateData.last_fleet_roll!.to}\n`,
      )
    }
  }

  // First pass: evaluate all accounts against cached state. Collect
  // labels that need a live probe (i.e. accounts with a detected transition
  // that we're about to notify about). We probe those to get fresh
  // utilization numbers for the notification body — not for classification.
  const pendingTransitions: Array<{
    accountLabel: string
    snapIndex: number
    decision: ReturnType<typeof evaluateQuotaWatchAccount>
  }> = []

  const labelToSnapIndex = new Map<string, number>(
    snapshots.map((s, i) => [s.label, i]),
  )

  // Reconciled transitions: state advances (latch clears) but nothing is
  // sent — boot-tick and late recoveries (see QuotaWatchDecision docs).
  let reconciledCount = 0
  let mutatedState = watchState

  // #3031 PR 3 — thread the last broker roll so a 🟡 throttling push for the
  // just-rolled-off account is latched silently (the roll card covered it).
  const lastRoll = listStateData.last_fleet_roll ?? null

  for (const snap of snapshots) {
    const prev = watchState[snap.label] ?? emptyAccountState()
    const decision = evaluateQuotaWatchAccount({ agentName, snap, prev, now, bootTick, tuning, lastRoll })
    if (decision.kind === 'reconcile') {
      mutatedState = patchQuotaWatchState(mutatedState, decision.accountLabel, decision.newAccountState)
      reconciledCount++
      process.stderr.write(
        `telegram gateway: quota-watch: reconciled ${decision.transition} for account=${decision.accountLabel} (${decision.reason}) — no notification\n`,
      )
    } else if (decision.kind !== 'skip') {
      pendingTransitions.push({
        accountLabel: snap.label,
        snapIndex: labelToSnapIndex.get(snap.label) ?? -1,
        decision,
      })
    }
  }

  if (pendingTransitions.length === 0) {
    // Steady-state: no notifications, no probes. Persist only if a
    // reconcile advanced the latch (otherwise no state write at all).
    if (reconciledCount > 0) {
      try {
        saveQuotaWatchState(stateDir, mutatedState)
      } catch (err) {
        process.stderr.write(`telegram gateway: quota-watch state persist failed: ${err}\n`)
      }
    }
    return
  }

  // Transition detected: probe ONLY the crossing accounts to get fresh
  // numbers for the notification message bodies. One batched RPC for all
  // crossing accounts (typically 1, rarely 2+).
  const crossingLabels = pendingTransitions.map(t => t.accountLabel)
  // #2495 BLOCKER fix — store the FULL entry (result + `served` tag), not just
  // `entry.result`. The corroboration gate below needs `served` to tell a true
  // live probe apart from a failed-probe cache fallback (which is `ok:true`
  // but `served:"cache"` — vacuous corroboration).
  let freshProbeMap = new Map<string, Awaited<ReturnType<typeof brokerClient.probeQuota>>['results'][number]>()
  try {
    // #2495 Change 3 — forceLive bypasses the broker's probe-on-open TTL so the
    // DECISION to alarm is corroborated by a TRUE live probe, never a cache hit.
    // Only the transition-to-alarm pays for this; steady-state polls stay on the
    // cheap cached listState read (no probe). Honors the existing fleet/consumer
    // probe knobs upstream — this re-evaluation never fires without a detected
    // transition.
    const probeData = await brokerClient.probeQuota(crossingLabels, 8000, true)
    for (const entry of probeData.results) {
      freshProbeMap.set(entry.label, entry)
    }
  } catch (err) {
    process.stderr.write(`telegram gateway: quota-watch: probe for crossing accounts failed: ${err}\n`)
    // A quota notification must never carry numbers we could not verify
    // live. Leave the crossing accounts' state untouched — the
    // transition re-evaluates (and re-probes) on the next 15-min tick.
    // Persist any reconciles already applied, then bail.
    if (reconciledCount > 0) {
      try {
        saveQuotaWatchState(stateDir, mutatedState)
      } catch (saveErr) {
        process.stderr.write(`telegram gateway: quota-watch state persist failed: ${saveErr}\n`)
      }
    }
    process.stderr.write(
      `telegram gateway: quota-watch: deferring ${pendingTransitions.length} notification(s) until probe succeeds\n`,
    )
    return
  }

  // Build final notifications, enriching the snapshot with fresh probe
  // data where available.
  const notifications: Array<{ message: string; accountLabel: string; transition: string }> = []

  for (const { accountLabel, snapIndex, decision } of pendingTransitions) {
    // Re-evaluate with fresh probe data to get an accurate message body.
    // If the fresh probe succeeded, replace the snap's quota with live data.
    const freshEntry = freshProbeMap.get(accountLabel)
    let enrichedDecision = decision
    // pendingTransitions only ever holds notify decisions (pushed under
    // `decision.kind !== 'skip'` / `!== 'reconcile'`). Narrow explicitly so
    // `decision.transition` type-checks below; this continue never fires
    // at runtime.
    if (decision.kind !== 'notify') continue
    // #2495 BLOCKER fix — only a GENUINE live probe corroborates the alarm. A
    // forceLive entry that is `ok:true` but `served:"cache"` (the broker's
    // failed-probe cache fallback) is NOT corroboration: the upstream probe
    // failed, so we have no live confirmation that the throttling crossing is
    // real right now. Treat it exactly like a probe failure → fall through to
    // the defer branch below (state untouched, re-evaluated next tick). This
    // also guarantees the "Live-probe corroborated (#2495)" footnote is only
    // ever stamped on a real live probe.
    if (isLiveCorroboration(freshEntry) && freshEntry!.result.ok && snapIndex >= 0) {
      // Live numbers replace the cache — and capturedAtMs is cleared so the
      // staleness gate never misfires on data we JUST probed.
      const enrichedSnap = { ...snapshots[snapIndex]!, quota: freshEntry!.result.data, capturedAtMs: undefined }
      const prev = watchState[accountLabel] ?? emptyAccountState()
      const re = evaluateQuotaWatchAccount({ agentName, snap: enrichedSnap, prev, now, bootTick, tuning, lastRoll })
      // If the fresh probe still shows the same transition, use the
      // enriched message. If it no longer shows a transition (e.g. the
      // account recovered in the 100ms between listState and probe),
      // fall through to skip this notification.
      if (re.kind === 'notify' && re.transition === decision.transition) {
        enrichedDecision = re
      } else if (re.kind === 'reconcile') {
        // Fresh data confirms the transition but it isn't news (boot-tick /
        // late recovery) — advance the latch silently.
        mutatedState = patchQuotaWatchState(mutatedState, accountLabel, re.newAccountState)
        reconciledCount++
        process.stderr.write(
          `telegram gateway: quota-watch: reconciled ${re.transition} for account=${accountLabel} (${re.reason}) — no notification\n`,
        )
        continue
      } else if (re.kind === 'skip') {
        // State normalised by the time of the probe — don't notify.
        continue
      }
    } else {
      // No verified fresh data for this account (per-account probe failure
      // or label missing from the batch result). Same rule as the batch
      // throw above: never send unverified numbers. State untouched —
      // re-evaluated (and re-probed) next tick.
      process.stderr.write(
        `telegram gateway: quota-watch: probe unavailable for account=${accountLabel} — deferring notification\n`,
      )
      continue
    }

    if (enrichedDecision.kind !== 'notify') continue
    notifications.push({
      message: enrichedDecision.message,
      accountLabel,
      transition: enrichedDecision.transition,
    })
    mutatedState = patchQuotaWatchState(mutatedState, accountLabel, enrichedDecision.newAccountState)
  }

  if (notifications.length === 0) {
    // All transitions resolved/deferred by the time of the live probe.
    // Reconciles may still have advanced the latch — persist those.
    if (reconciledCount > 0) {
      try {
        saveQuotaWatchState(stateDir, mutatedState)
      } catch (err) {
        process.stderr.write(`telegram gateway: quota-watch state persist failed: ${err}\n`)
      }
    }
    return
  }

  // Send all notifications (one message per crossing account).
  for (const { message, accountLabel, transition } of notifications) {
    for (const chat_id of access.allowFrom) {
      // Fleet-level dedup: every agent gateway independently detects the
      // same account transition within one poll cycle. The broker claim
      // grants exactly one sender per (account, transition, chat) per
      // window — the other ten agents advance their local state silently.
      // Fail-open on claim error (see claimQuotaNotification).
      if (tuning.fleetDedup) {
        const granted = await claimQuotaNotification(
          brokerClient,
          buildQuotaClaimKey(accountLabel, transition, chat_id),
        )
        if (!granted) {
          process.stderr.write(
            `telegram gateway: quota-watch: claim denied account=${accountLabel} chat=${chat_id} — another agent notified\n`,
          )
          continue
        }
      }
      // Quota-watch notify — best-effort. Wrap via swallowingApiCall so
      // flood-wait / deleted-chat / not-found surface as a stderr log
      // rather than a thrown exception that aborts the loop and leaves
      // half the allowFrom chats unnotified. Matches the wrapping
      // contract enforced by scripts/check-bot-api-wrapping.sh (#1075).
      await swallowingApiCall(
        () =>
          bot.api.sendRichMessage(chat_id, richMessage(message), {
            // Quota throttling status notice — silence the open ping.
            disable_notification: true,
          }),
        { chat_id, verb: 'quota-watch.notify' },
      )
    }
    process.stderr.write(`telegram gateway: quota-watch: notified transition for account=${accountLabel}\n`)
  }

  // Persist updated state regardless of whether sends succeeded.
  try {
    saveQuotaWatchState(stateDir, mutatedState)
  } catch (err) {
    process.stderr.write(`telegram gateway: quota-watch state persist failed: ${err}\n`)
  }
}

/**
 * Edit a Microsoft connect card from the BACKGROUND device-code poll
 * (no `ctx` — we hold the chat+message id). Wrapped in robustApiCall;
 * swallows failures (a deleted card / closed topic must not crash the
 * poll). RFC #1873 Phase 2.
 */
async function editMicrosoftConnectCard(
  chatId: number | string,
  messageId: number,
  html: string,
): Promise<void> {
  await robustApiCall(
    // allow-raw-bot-api: background connect-card edit by message id (no thread_id; not the reply chunk loop)
    () => bot.api.editMessageText(chatId, messageId, richMessage(html), {
      link_preview_options: { is_disabled: true },
    }),
    { chat_id: String(chatId), verb: 'microsoftConnectCard' },
  ).catch(() => {})
}

/**
 * Background half of `/connect microsoft`: poll Microsoft for consent,
 * register the account with the broker, then edit the card to the
 * outcome. Fire-and-forget from the command handler.
 */
async function finalizeMicrosoftConnect(key: string): Promise<void> {
  const flow = pendingMicrosoftConnectFlows.get(key)
  if (!flow) return
  const agentName = getMyAgentName()
  const result = await runMicrosoftConnectPoll(flow)
  // A `/connect cancel` (command or button) between consent and write
  // already edited the card and dropped the entry — don't clobber it.
  if (result.kind === 'cancelled' || !pendingMicrosoftConnectFlows.has(key)) {
    pendingMicrosoftConnectFlows.delete(key)
    return
  }
  pendingMicrosoftConnectFlows.delete(key)

  let html: string
  if (result.kind === 'connected') {
    html =
      `✅ **Connected** \`${result.account}\` ` +
      `(${result.accountType}).\n\n` +
      `To let **${escapeHtmlForTg(agentName)}** use it, run on the host:\n` +
      `\`switchroom auth microsoft enable ${escapeHtmlForTg(result.account)} ${escapeHtmlForTg(agentName)}\`\n` +
      `then restart ${escapeHtmlForTg(agentName)}.`
  } else if (result.kind === 'no-refresh-token') {
    html =
      `⚠ Microsoft returned no refresh token (the account would expire in ~1h), ` +
      `so it was not registered. Try \`/connect microsoft\` again, or ` +
      `connect from the host CLI.`
  } else {
    html =
      `❌ **Connect failed:** ${escapeHtmlForTg(result.message)}\n\n` +
      `_Work/school accounts can't use the phone flow at /common — connect those ` +
      `from the host: \`switchroom auth microsoft account add <email>\`._`
  }
  await editMicrosoftConnectCard(flow.cardChatId, flow.cardMessageId, html)
}

/**
 * `/connect microsoft` — Telegram-native device-code connect for a
 * Microsoft account (RFC #1873 Phase 2). The user signs in on their
 * phone; we register the account with the auth-broker (shipped default
 * app unless the operator BYO'd one). Admin-gated like `/auth add`.
 * `/connect cancel` aborts a pending flow. Google stays host-CLI.
 */


// Boot-card auth-row loader (issue #708, RFC H rewire). Queries the
// broker for `list-state` and hands the raw shape to the boot card,
// which delegates rendering to `renderAuthLine`. Returns null on any
// failure so the boot card silently omits the section.
async function loadAccountsForBootCard(agent: string): Promise<ListStateData | null> {
  try {
    const client = await getAuthBrokerClient(agent)
    if (!client) return null
    return await client.listState()
  } catch (err) {
    process.stderr.write(`telegram gateway: boot-card auth probe failed: ${(err as Error)?.message ?? String(err)}\n`)
    return null
  }
}

/**
 * Canonical boot-card quota probe (#1336): resolve this agent's
 * effective account, then have the broker probe Anthropic server-side.
 * Returns null on any failure (broker unreachable, no active account)
 * so `probeQuota` falls back to a direct probe. Mirrors
 * `loadAccountsForBootCard`'s broker-client + swallow-to-null shape,
 * and the override→account→active resolution used by auth-line.ts.
 */
async function probeQuotaForBootCard(
  agent: string,
  timeoutMs?: number,
): Promise<QuotaResult | null> {
  try {
    const client = await getAuthBrokerClient(agent)
    if (!client) return null
    const state = await client.listState()
    const entry = state.agents.find((a) => a.name === agent)
    const label = entry?.override ?? entry?.account ?? state.active
    if (!label) return null
    const { results } = await client.probeQuota([label], timeoutMs)
    return results.find((r) => r.label === label)?.result ?? null
  } catch (err) {
    process.stderr.write(`telegram gateway: boot-card quota probe failed: ${(err as Error)?.message ?? String(err)}\n`)
    return null
  }
}

/**
 * Read the pending auth session's target slot from the agent's
 * `.setup-token.session.json` meta file. Returns null when no session
 * is pending.
 */
function readPendingSessionSlot(agent: string): string | null {
  try {
    const agentDir = resolveAgentDirForName(agent)
    if (!agentDir) return null
    const metaPath = join(agentDir, '.claude', '.setup-token.session.json')
    const raw = readFileSync(metaPath, 'utf-8')
    const meta = JSON.parse(raw) as { slot?: string }
    return meta.slot ?? 'default'
  } catch {
    return null
  }
}

/**
 * Resolve the agent directory for a given name. Tries the local
 * SWITCHROOM_CONFIG-driven lookup first, falls back to scanning
 * known agent-root paths. Used by dashboard path probing without
 * blowing up when configs are split across roots (klanker setup).
 */
function resolveAgentDirForName(agent: string): string | null {
  try {
    // If this gateway is scoped to a specific agent, prefer that.
    if (agent === getMyAgentName()) {
      return resolveAgentDirFromEnv()
    }
  } catch { /* ignore */ }
  // Common split-root layout for klanker.
  const candidates = [
    join(process.env.HOME ?? '/root', `.switchroom-${agent}/agents/${agent}`),
    join(process.env.HOME ?? '/root', `.switchroom/agents/${agent}`),
  ]
  for (const c of candidates) {
    try { readFileSync(join(c, '.claude', 'settings.json'), 'utf-8'); return c } catch { /* try next */ }
  }
  return null
}

